#[test]
fn contact_fallback_never_replaces_a_certified_pole() {
    use crate::tests::decided;
    let curve = RationalBezier2::try_new(
        vec![
            Point2::from_values(0, 0),
            Point2::from_values(1, 1),
            Point2::from_values(2, 0),
        ],
        vec![Real::one(), -Real::one(), Real::one()],
    )
    .unwrap();
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let polynomial = decided(
            BezierParameterPolynomial::try_new_power_basis(
                vec![Real::from(-1), Real::from(2)],
                &policy,
            )
            .unwrap(),
        );
        let interval =
            decided(BezierParameterInterval::try_new(Real::zero(), Real::one(), &policy).unwrap());
        let parameter =
            decided(BezierAlgebraicParameter2::try_isolate(polynomial, interval, &policy).unwrap());
        assert!(matches!(
            rational_point_evidence_at_parameter(
                &curve,
                &BezierParameter2::Algebraic(parameter),
                &policy
            ),
            Ok(Classification::Uncertain(UncertaintyReason::Boundary))
        ));
    }
}

use crate::BezierAlgebraicImageStatus;

fn bivariate_bilinear_factorizations(
    polynomial: &BivariatePolynomial,
) -> Vec<(BivariatePolynomial, BivariatePolynomial)> {
    bivariate_bilinear_factorizations_bounded(polynomial, usize::MAX, usize::MAX)
}

#[test]
fn independent_oblique_chords_support_constrained_fillet_families() {
    use crate::{Curve2, CurveFillet2, CurveFilletContact2, CurvePath2};

    let q = |n: i64, d: i64| (Real::from(n) / Real::from(d)).unwrap();
    let a = q(1, 2).sqrt().unwrap();
    let b = Real::from(3) * q(1, 6).sqrt().unwrap();
    // Rotate and scale the rational U-shaped fixture. The first line
    // runs from (a,0) to (0,b), with a²+b²=2; its two retained endpoints
    // deliberately belong to independent selected fields.
    let p = |x: i64, y: i64| {
        Point2::new(
            -&a * q(x, 3) - &b * q(y, 3),
            &b + &b * q(x, 3) - &a * q(y, 3),
        )
    };
    let radius = &a * q(2, 3);
    let witness = CurvePath2::try_new(vec![
        LineSeg2::try_new(p(-3, 0), p(-2, 0)).unwrap().into(),
        CircularArc2::try_from_center(p(-2, 0), p(-2, 2), p(-2, 1), false)
            .unwrap()
            .into(),
        LineSeg2::try_new(p(-2, 2), p(-3, 2)).unwrap().into(),
    ])
    .unwrap();
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let closed_region = |path: &CurvePath2| {
            let mut curves = path.curves().to_vec();
            let Classification::Decided(closing) =
                BezierAlgebraicChord2::try_new(path.end(), path.start(), &policy).unwrap()
            else {
                panic!("the independent oblique fillet path must close exactly");
            };
            curves.push(closing.into());
            CurveRegion2::try_from_boundary_paths(
                &[CurvePath2::try_new(curves).unwrap()],
                crate::FillRule::EvenOdd,
                &policy,
            )
            .unwrap()
            .value
        };
        let expected = closed_region(&witness);
        let offset_distance = &radius * q(1, 100);
        let expected_offset = expected
            .offset(offset_distance.clone(), &OffsetCornerStyle2::Bevel, &policy)
            .unwrap();
        assert_eq!(expected_offset.certainty, CurveCertainty::Certified);
        let chord = dense_chord_normal_chord(
            2,
            vec![Real::zero(), Real::one()],
            vec![Real::zero()],
            6,
            vec![Real::zero()],
            vec![Real::zero(), Real::from(3)],
            &policy,
            "independent oblique fillet source",
        );
        assert!(chord.exact_line().is_none());
        assert!(chord.strict_provenance_support_line(&policy).is_none());
        let spline = Curve2::try_nurbs(
            2,
            vec![p(0, 0), p(0, 1), p(0, 2), p(-1, 2), p(-3, 2)],
            vec![Real::one(); 5],
            [0, 0, 0, 1, 1, 2, 2, 2]
                .into_iter()
                .map(Real::from)
                .collect(),
            &policy,
        )
        .unwrap()
        .value;
        for (retained, first) in [
            (
                false,
                Curve2::from(LineSeg2::try_new(p(-3, 0), p(0, 0)).unwrap()),
            ),
            (true, Curve2::from(chord)),
        ] {
            let source = CurvePath2::try_new(vec![first, spline.clone()]).unwrap();
            for reversed in [false, true] {
                let path = if reversed {
                    source.reversed(&policy).unwrap().value
                } else {
                    source.clone()
                };
                let spline_axis = usize::from(!reversed);
                for mode in [CurveCornerMode2::TrimOnly, CurveCornerMode2::TrimOrExtend] {
                    match path.fillet_vertex(1, &CurveFillet2::new(radius.clone()), mode, &policy) {
                        Err(crate::ExactCurveError::Invalid {
                            cause: CurveError::FilletConstraintRequired,
                            ..
                        }) => (),
                        Err(error) => panic!(
                            "oblique radius-only family: {error}; retained={retained}, reversed={reversed}, mode={mode:?}"
                        ),
                        Ok(_) => panic!("a continuous oblique family requires a constraint"),
                    }
                    for selection in 0..5 {
                        let mut request = CurveFillet2::new(radius.clone());
                        match selection {
                            0 => request.center = Some(p(-2, 1).into()),
                            1 => {
                                request.contacts[spline_axis] =
                                    Some(CurveFilletContact2::Point(p(-2, 2).into()))
                            }
                            2 => {
                                let parameter = Real::from(3).sqrt().unwrap();
                                request.contacts[spline_axis] =
                                    Some(CurveFilletContact2::Parameter(
                                        (if reversed {
                                            Real::from(2) - parameter
                                        } else {
                                            parameter
                                        })
                                        .into(),
                                    ));
                            }
                            3 => {
                                request.contacts[1 - spline_axis] =
                                    Some(CurveFilletContact2::Point(p(-2, 0).into()))
                            }
                            _ => {
                                let parameter =
                                    match path.curves()[1 - spline_axis].retained_fragment() {
                                        Some(BezierSplitFragment2::AlgebraicChord(chord)) => {
                                            CurveParameter2::from_algebraic_chord(
                                                chord
                                                    .parameter_at_certified_support_point(
                                                        p(-2, 0).into(),
                                                        &policy,
                                                    )
                                                    .unwrap(),
                                            )
                                        }
                                        _ => (if reversed { q(2, 3) } else { q(1, 3) }).into(),
                                    };
                                request.contacts[1 - spline_axis] =
                                    Some(CurveFilletContact2::Parameter(parameter));
                            }
                        }
                        let selected = path.fillet_vertex(1, &request, mode, &policy)
                            .unwrap_or_else(|error| panic!(
                                "oblique constrained fillet: {error}; retained={retained}, reversed={reversed}, mode={mode:?}, selection={selection}"
                            ));
                        assert_eq!(selected.certainty, CurveCertainty::Certified);
                        assert_eq!(selected.value.candidate_count(), 1);
                        let edited = &selected.value.solutions()[0];
                        let contacts: [CurvePoint2; 2] = [p(-2, 0).into(), p(-2, 2).into()];
                        for (actual, expected) in [
                            (edited.start(), path.start()),
                            (edited.end(), path.end()),
                            (
                                edited.curves().first().unwrap().end(),
                                contacts[usize::from(reversed)].clone(),
                            ),
                            (
                                edited.curves().last().unwrap().start(),
                                contacts[spline_axis].clone(),
                            ),
                        ] {
                            assert_eq!(
                                actual.same_point(&expected, &policy),
                                Classification::Decided(true)
                            );
                        }
                        for pair in edited.curves().windows(2) {
                            assert_eq!(
                                pair[0].end().same_point(&pair[1].start(), &policy),
                                Classification::Decided(true)
                            );
                        }
                        let region = closed_region(edited);
                        let difference = region.boolean_regions(&expected, &policy)
                            .unwrap_or_else(|error| panic!(
                                "oblique fillet Boolean: {error}; retained={retained}, reversed={reversed}, mode={mode:?}, selection={selection}"
                            ));
                        assert_eq!(difference.certainty, CurveCertainty::Certified);
                        assert!(difference.value.xor().is_empty());
                        if selection == 0 {
                            let offset = region.offset(offset_distance.clone(), &OffsetCornerStyle2::Bevel, &policy)
                                .unwrap_or_else(|error| panic!(
                                    "oblique fillet offset: {error}; retained={retained}, reversed={reversed}, mode={mode:?}"
                                ));
                            assert_eq!(offset.certainty, CurveCertainty::Certified);
                            let difference = offset
                                .value
                                .boolean_regions(&expected_offset.value, &policy)
                                .unwrap_or_else(|error| panic!(
                                    "oblique fillet offset Boolean: {error}; retained={retained}, reversed={reversed}, mode={mode:?}"
                                ));
                            assert_eq!(difference.certainty, CurveCertainty::Certified);
                            assert!(difference.value.xor().is_empty());
                            assert!(!offset.value.is_empty());
                        }
                    }
                }
            }
        }
    }
}

#[test]
fn retained_incident_domains_admit_exterior_affine_endpoints() {
    let half = (Real::one() / Real::from(2)).unwrap();
    let parallel = RationalBezier2::try_new(
        vec![Point2::from_values(0, 0), Point2::from_values(1, 0)],
        vec![-Real::one(), Real::one()],
    )
    .unwrap()
    .parallel_left(Real::one())
    .unwrap();
    let line = LineSeg2::try_new(Point2::from_values(0, 0), Point2::from_values(1, 0)).unwrap();
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let (selected, _, alpha) = selected_fiber_quartile_parameters(&policy);
        let point = dense_chord_normal_point(
            2,
            vec![Real::zero(), half.clone()],
            vec![Real::zero()],
            &policy,
            "exterior incident endpoint field",
        );
        let Classification::Decided(recursive) =
            affine_line_parameter_at_incident_point(&line, &point, &policy).unwrap()
        else {
            panic!("the independent selected point must retain its affine parameter");
        };
        assert!(recursive.as_recursive_projective().is_some());
        for base in [CurveParameter2::from_selected_fiber(selected), recursive] {
            for shift in [-2, 2] {
                let Classification::Decided(endpoint) = base
                    .affine_image_unbounded(&Real::one(), &Real::from(shift), &policy)
                    .unwrap()
                else {
                    panic!("the retained endpoint must translate exactly");
                };
                let exact = Real::from(shift) + &alpha * &half;
                for direction in [
                    BezierParameterRayDirection2::Decreasing,
                    BezierParameterRayDirection2::Increasing,
                ] {
                    let result = crate::policy::resolve_certified_value(&policy, |attempt| {
                        parallel.incident_domain_from_parameter(&endpoint, direction, attempt)
                    });
                    assert_eq!(result.certainty, crate::CurveCertainty::Certified);
                    let Classification::Decided(incident) = result.value.unwrap() else {
                        panic!("the exterior endpoint must retain its regular incident domain");
                    };
                    assert!(incident.endpoint() == &endpoint);
                    assert!(incident.bridge().is_some());
                    let toward_pole =
                        (shift > 0) == (direction == BezierParameterRayDirection2::Decreasing);
                    assert_eq!(incident.barrier().is_some(), toward_pole);
                    if let Some(barrier) = incident.barrier() {
                        assert_eq!(
                            barrier
                                .cmp_by_refinement(&BezierParameter2::Exact(half.clone()), &policy)
                                .unwrap(),
                            Classification::Decided(std::cmp::Ordering::Equal),
                        );
                    }
                    for candidate in [-4, -2, -1, 0, 1, 2, 3, 4]
                        .map(Real::from)
                        .into_iter()
                        .chain([half.clone()])
                    {
                        let expected_order =
                            if direction == BezierParameterRayDirection2::Increasing {
                                std::cmp::Ordering::Greater
                            } else {
                                std::cmp::Ordering::Less
                            };
                        let expected = compare_reals(&candidate, &exact, &policy)
                            == Some(expected_order)
                            && (!toward_pole
                                || compare_reals(&candidate, &half, &policy)
                                    == Some(expected_order.reverse()));
                        assert_eq!(
                            incident
                                .contains_extension_parameter(&candidate.into(), &policy)
                                .unwrap(),
                            Classification::Decided(expected),
                        );
                    }
                }
            }
        }
    }
}

#[test]
fn independent_oblique_offset_coordinates_replay_exact_equalities_and_separation() {
    let q = |n: i64, d: i64| (Real::from(n) / Real::from(d)).unwrap();
    let a = q(1, 2).sqrt().unwrap();
    let b = Real::from(3) * q(1, 6).sqrt().unwrap();
    let tiny = (0..10).fold(q(1, 2), |value, _| &value * &value);
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let chord = dense_chord_normal_chord(
            2,
            vec![Real::zero(), Real::one()],
            vec![Real::zero()],
            6,
            vec![Real::zero()],
            vec![Real::zero(), Real::from(3)],
            &policy,
            "independent oblique offset coordinate fields",
        );
        let endpoints = [
            Point2::new(a.clone(), Real::zero()),
            Point2::new(Real::zero(), b.clone()),
        ];
        for reversed in [false, true] {
            let source = if reversed {
                chord.reversed()
            } else {
                chord.clone()
            };
            let sign = Real::from(if reversed { -1 } else { 1 });
            let shift_x = -(&sign * Real::from(3).sqrt().unwrap() * q(1, 8));
            let shift_y = -(&sign * q(1, 8));
            let offset = source.parallel_left_retained(q(1, 4), &policy).unwrap();
            for (index, point) in [offset.start(), offset.end()].into_iter().enumerate() {
                let expected = endpoints[if reversed { 1 - index } else { index }]
                    .translated(shift_x.clone(), shift_y.clone());
                for (axis, coordinate) in [(Axis2::X, expected.x()), (Axis2::Y, expected.y())] {
                    for (target, expected) in [
                        (coordinate.clone(), std::cmp::Ordering::Equal),
                        (coordinate + &tiny, std::cmp::Ordering::Less),
                        (coordinate - &tiny, std::cmp::Ordering::Greater),
                    ] {
                        // Exact endpoint equality and separation below the
                        // approximate terminal must both reuse the retained
                        // normal sheet and independent source fields.
                        let result = crate::policy::resolve_certified_value(&policy, |attempt| {
                            BezierAlgebraicChord2::point_axis_order_to_real(
                                point, axis, &target, attempt,
                            )
                        });
                        assert_eq!(result.certainty, crate::CurveCertainty::Certified);
                        assert_eq!(result.value.unwrap(), Classification::Decided(expected));
                    }
                }
            }
        }
    }
}

#[test]
fn independent_chord_linear_forms_replay_exact_coefficient_relations() {
    let q = |n: i64, d: i64| (Real::from(n) / Real::from(d)).unwrap();
    let a = q(1, 2).sqrt().unwrap();
    let b = Real::from(3) * q(1, 6).sqrt().unwrap();
    let tiny = (0..10).fold(q(1, 2), |value, _| &value * &value);
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let chord = dense_chord_normal_chord(
            2,
            vec![Real::zero(), Real::one()],
            vec![Real::zero()],
            6,
            vec![Real::zero()],
            vec![Real::zero(), Real::from(3)],
            &policy,
            "independent chord direction fields",
        );
        let clipped = chord
            .chord_between_certified_ordered_support_points(
                chord.start().clone(),
                Point2::new(&a * q(1, 2), &b * q(1, 2)).into(),
                &policy,
            )
            .unwrap();
        let parallel = clipped.parallel_left_retained(q(1, 4), &policy).unwrap();
        for source in [chord, clipped, parallel] {
            assert!(source.certified_unit_tangent().is_none());
            for reversed in [false, true] {
                let chord = if reversed {
                    source.reversed()
                } else {
                    source.clone()
                };
                for (x, y, expected) in [
                    (b.clone(), a.clone(), RealSign::Zero),
                    (Real::from(3).sqrt().unwrap(), Real::one(), RealSign::Zero),
                    (b.clone(), &a + &tiny, RealSign::Positive),
                    (b.clone(), &a - &tiny, RealSign::Negative),
                ] {
                    // The two exact zeros use different coefficient fields.
                    // Perturbations below 2^-512 must retain their nonzero
                    // signs, including after trimming, offset and reversal.
                    assert_eq!(
                        chord.tangent_linear_form_sign(&x, &y, &policy).unwrap(),
                        Classification::Decided(if reversed {
                            product_sign(expected, RealSign::Negative)
                        } else {
                            expected
                        }),
                    );
                }
            }
        }
    }
}

#[test]
fn repeated_point_similarities_keep_one_original_selected_field() {
    let affine = |entries: [i8; 6]| {
        let [a, b, d, e, tx, ty] = entries.map(Real::from);
        Similarity2::try_from_real_affine(a, b, d, e, tx, ty).unwrap()
    };
    let translation = affine([1, 0, 0, 1, 3, -2]);
    let reflection = affine([0, 2, 2, 0, 0, 0]);
    let half = (Real::one() / Real::from(2)).unwrap();
    let inverse = Similarity2::try_from_real_affine(
        Real::zero(),
        half.clone(),
        half,
        Real::zero(),
        Real::from(-3),
        Real::from(2),
    )
    .unwrap();
    let expected_maps = [
        translation.clone(),
        affine([0, 2, 2, 0, -4, 6]),
        affine([1, 0, 0, 1, 0, 0]),
    ];
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let point = |x: Vec<Real>, y: Vec<Real>| {
            dense_chord_normal_point(2, x, y, &policy, "similarity cycle witness")
        };
        let source = point(vec![Real::zero(), Real::one()], vec![Real::one()]);
        let expected_points = [
            point(vec![Real::from(3), Real::one()], vec![Real::from(-1)]),
            point(vec![Real::from(-2)], vec![Real::from(6), Real::from(2)]),
            point(vec![Real::zero(), Real::one()], vec![Real::one()]),
        ];
        let mut current = source.clone();
        // T, R, and (R T)^-1 form an exact cycle. Intermediate images
        // distinguish the noncommuting order and reverse orientation.
        for cycle in 0..64 {
            for (phase, transform) in [&translation, &reflection, &inverse]
                .into_iter()
                .enumerate()
            {
                let image = BezierSimilarityPoint2::new(current, transform.clone(), &policy);
                assert!(
                    image.data.source.shares_storage(&source),
                    "compatible transforms must retain one shared selected field"
                );
                assert!(image.data.transform == expected_maps[phase]);
                if cycle == 0 || cycle == 63 {
                    let Classification::Decided(Some(evidence)) =
                        image.predicate_point_evidence(&policy).unwrap()
                    else {
                        panic!("the original selected field must replay every image");
                    };
                    assert_eq!(
                        evidence.same_point(&expected_points[phase], &policy),
                        Classification::Decided(true)
                    );
                }
                current = CurvePoint2::from(image);
                assert!(current.coordinates().is_none());
            }
        }
    }
}

#[test]
fn point_similarity_composition_preserves_retained_policy_barriers() {
    let translation = Similarity2::try_from_real_affine(
        Real::one(),
        Real::zero(),
        Real::zero(),
        Real::one(),
        Real::one(),
        Real::zero(),
    )
    .unwrap();
    let source = dense_chord_normal_point(
        2,
        vec![Real::zero(), Real::one()],
        vec![Real::one()],
        &CurveContext::STRICT,
        "similarity policy witness",
    );
    let approximate = CurvePoint2::from(BezierSimilarityPoint2::new(
        source.clone(),
        translation.clone(),
        &CurveContext::APPROXIMATE_512,
    ));
    let strict = BezierSimilarityPoint2::new(
        approximate.clone(),
        translation.clone(),
        &CurveContext::STRICT,
    );
    assert!(strict.data.source.shares_storage(&approximate));
    assert!(
        strict
            .predicate_point_evidence(&CurveContext::STRICT)
            .is_err()
    );
    assert!(matches!(
        strict.conservative_bounds_refined(0, &CurveContext::STRICT),
        Classification::Uncertain(_)
    ));

    let permitted = BezierSimilarityPoint2::new(
        CurvePoint2::from(strict),
        translation,
        &CurveContext::APPROXIMATE_512,
    );
    assert!(permitted.data.source.shares_storage(&source));
    assert!(matches!(
        permitted.predicate_point_evidence(&CurveContext::APPROXIMATE_512),
        Ok(Classification::Decided(Some(_)))
    ));
    assert!(
        permitted
            .predicate_point_evidence(&CurveContext::STRICT)
            .is_err()
    );
    assert!(matches!(
        permitted.conservative_bounds_refined(0, &CurveContext::STRICT),
        Classification::Uncertain(_)
    ));
}

#[test]
fn bivariate_products_accept_empty_zero_coefficients() {
    let nonzero = BivariatePolynomial::new(vec![
        vec![Real::from(2), Real::from(-3)],
        vec![],
        vec![Real::one()],
    ]);
    let zeros = [vec![], vec![vec![]], vec![vec![], vec![]]].map(BivariatePolynomial::new);
    for zero in &zeros {
        for other in zeros.iter().chain([&nonzero]) {
            for (first, second) in [(zero, other), (other, zero)] {
                assert!(bivariate_multiply(first, second).coefficients.is_empty());
                assert!(
                    try_bivariate_multiply(first, second)
                        .expect("zero products need no coefficient allocation")
                        .coefficients
                        .is_empty()
                );
            }
        }
        for factor in [&[][..], &[Real::from(-1), Real::from(2)][..]] {
            assert!(
                bivariate_multiply_first_parameter(zero, factor)
                    .coefficients
                    .is_empty()
            );
        }
    }
    assert!(
        bivariate_multiply_first_parameter(&nonzero, &[])
            .coefficients
            .is_empty()
    );
}

#[test]
fn domain_component_normal_constraints_follow_swapped_operands() {
    let q = |n: i64, d: i64| (Real::from(n) / Real::from(d)).unwrap();
    // The two center traces share a line with s = 2t. Independent
    // original-normal predicates distinguish their parameter axes.
    let firsts = [0, 1].map(|distance| {
        let y = Real::from(1 - distance);
        QuadraticBezier2::new(
            Point2::new(Real::zero(), y.clone()),
            Point2::new(q(1, 2), y.clone()),
            Point2::new(Real::one(), y),
        )
        .parallel_left(Real::from(distance))
        .unwrap()
    });
    let second = QuadraticBezier2::new(
        Point2::from_values(0, 0),
        Point2::new(q(1, 4), Real::zero()),
        Point2::new(q(1, 2), Real::zero()),
    )
    .parallel_left(Real::one())
    .unwrap();
    let source = QuadraticBezier2::new(
        Point2::from_values(0, 0),
        Point2::new(q(3, 16), Real::zero()),
        Point2::new(q(3, 8), q(9, 64)),
    )
    .parallel_left(Real::zero())
    .unwrap();
    let originals = [
        source.with_distance(q(41, 64)),
        source.with_distance(q(5, 8)),
    ];
    let ranges = [q(5, 9), q(10, 9)].map(|middle| {
        CurveParameterRange2::new_validated(
            CurveParameter2::from(&middle - q(1, 10_000)),
            CurveParameter2::from(&middle + q(1, 10_000)),
        )
    });
    for first in &firsts {
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            for swapped in [false, true] {
                let order = if swapped { [1, 0] } else { [0, 1] };
                let axes = [
                    CurveResultantParameter::First,
                    CurveResultantParameter::Second,
                ];
                for allowed in [false, true] {
                    let signs = if allowed {
                        [RealSign::Negative, RealSign::Positive]
                    } else {
                        [RealSign::Positive, RealSign::Negative]
                    };
                    let constraints = std::array::from_fn(|axis| {
                        originals[order[axis]].derivative_scale_constraint(
                            axes[axis],
                            signs[order[axis]],
                            None,
                        )
                    });
                    let supports = [first, &second];
                    // Both nonzero center traces have exact rational images.
                    // Reusing those images must preserve the original normals'
                    // distinct parameter axes and reject the opposite sheets.
                    for query in [
                        ParameterComponentQuery2::FirstComponent(Some(&constraints)),
                        ParameterComponentQuery2::AllComponents(Some(&constraints)),
                    ] {
                        let Classification::Decided(result) = supports[order[0]]
                            .parallel_intersections_in_domain(
                                supports[order[1]],
                                order.map(|index| CurveParameterDomain2::new(&ranges[index], None)),
                                query,
                                &policy,
                            )
                            .unwrap()
                        else {
                            panic!("normal constraints must retain their original parameter axes");
                        };
                        let (intersections, components) = result.into_parts();
                        assert!(intersections.is_complete());
                        assert_eq!(!components.is_empty(), allowed);
                        if !allowed {
                            assert!(intersections.is_empty());
                        }
                    }
                }
            }
        }
    }
}

#[test]
fn original_parallel_normal_constraints_clip_finite_and_incident_components() {
    let q = |n: i64, d: i64| (Real::from(n) / Real::from(d)).unwrap();
    let source = QuadraticBezier2::new(
        Point2::from_values(0, 0),
        Point2::new(q(3, 16), Real::zero()),
        Point2::new(q(3, 8), q(9, 64)),
    )
    .parallel_left(Real::zero())
    .unwrap();
    let sqrt_two = Real::from(2_i8).sqrt().unwrap();
    let sqrt_three = Real::from(3_i8).sqrt().unwrap();
    let sum = &sqrt_two + &sqrt_three;
    let radical_zero =
        &sum * &sum - (Real::from(5_i8) + Real::from(2_i8) * Real::from(6_i8).sqrt().unwrap());
    for distance in [Real::zero(), radical_zero] {
        let stationary_identity = QuadraticBezier2::new(
            Point2::from_values(0, 0),
            Point2::from_values(0, 0),
            Point2::from_values(1, 0),
        )
        .parallel_left(distance)
        .unwrap();
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            assert_eq!(
                real_sign(stationary_identity.distance(), &policy),
                Some(RealSign::Zero)
            );
            for expected in [RealSign::Positive, RealSign::Negative] {
                let constraint = stationary_identity.derivative_scale_constraint(
                    CurveResultantParameter::First,
                    expected,
                    None,
                );
                assert_eq!(
                    constraint
                        .polynomials()
                        .unwrap()
                        .selected_at(
                            &BezierParameter2::Exact(Real::zero()),
                            &BezierParameter2::Exact(Real::zero()),
                            &policy,
                        )
                        .unwrap(),
                    Classification::Decided(expected == RealSign::Positive),
                );
            }
        }
    }
    let constraints = [
        source.with_distance(q(41, 64)).derivative_scale_constraint(
            CurveResultantParameter::First,
            RealSign::Negative,
            None,
        ),
        source.with_distance(q(5, 8)).derivative_scale_constraint(
            CurveResultantParameter::Second,
            RealSign::Positive,
            None,
        ),
    ];
    let diagonal =
        BivariatePolynomial::new(vec![vec![Real::zero(), Real::one()], vec![-Real::one()]]);
    let positive = BivariatePolynomial::new(vec![vec![Real::one()]]);
    let allowed = CurveParameterRange2::new_validated(
        CurveParameter2::from(q(5, 9) - q(1, 10_000)),
        CurveParameter2::from(q(5, 9) + q(1, 10_000)),
    );
    let excluded = CurveParameterRange2::new_validated(Real::zero().into(), q(1, 4).into());
    let unit = CurveParameterRange2::unit();
    let zero = Real::zero();
    let quarter = q(1, 4);
    let ray = |direction| BezierParameterRay2 {
        anchor: if direction == BezierParameterRayDirection2::Increasing {
            &quarter
        } else {
            &zero
        },
        direction,
        barrier: None,
    };
    let finite = |range| CurveParameterDomain2::new(range, None);
    let exterior = |direction| CurveParameterDomain2::new(&excluded, Some(ray(direction)));
    let config = CurveIntersectionResultantConfig {
        min_precision: PARALLEL_INTERSECTION_RESULTANT_PRECISION,
        max_resultant_degree: MAX_PARALLEL_INTERSECTION_RESULTANT_DEGREE,
    };
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        for (domains, expected) in [
            ([finite(&allowed), finite(&allowed)], true),
            ([finite(&excluded), finite(&excluded)], false),
            ([finite(&unit), finite(&unit)], true),
            (
                [exterior(BezierParameterRayDirection2::Increasing); 2],
                true,
            ),
            (
                [
                    exterior(BezierParameterRayDirection2::Decreasing),
                    exterior(BezierParameterRayDirection2::Increasing),
                ],
                false,
            ),
        ] {
            let Classification::Decided(selection) = select_parameter_component_in_domain(
                &diagonal,
                &ParameterComponentSelector2::Positive(&positive, None),
                domains,
                ParameterComponentQuery2::FirstComponent(Some(&constraints)),
                &policy,
                config,
            )
            .unwrap() else {
                panic!("the rational normal-sheet component must classify");
            };
            assert_eq!(selection.has_components(), expected);
        }
    }
}

use super::*;
use crate::bezier_region::CurveBoundaryInteriorSide2;
use crate::rational_bezier::RationalQuadraticCircle2;
use crate::{
    BezierParallelFragment2, BezierSplitFragment2, BezierSubcurve2, CircularArc2, CurveCertainty,
    CurveCornerMode2, CurveCornerSolutions2, CurveRegion2, CurveRegionBoundaryLoop2,
    CurveRegionLoopRole, FillRule, OffsetCornerStyle2,
};

fn region_parameter(parameter: BezierParameter2) -> CurveParameter2 {
    CurveParameter2::from(parameter)
}

#[test]
fn formula_roots_compare_in_their_existing_native_coefficient_field() {
    let q = |n, d| (Real::from(n) / Real::from(d)).unwrap();
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let native = |coefficients: Vec<Real>, lower, upper| {
            let Classification::Decided(polynomial) =
                BezierParameterPolynomial::try_new_power_basis(coefficients, &policy).unwrap()
            else {
                panic!("the cubic has rational coefficients")
            };
            let Classification::Decided(interval) =
                BezierParameterInterval::try_new(lower, upper, &policy).unwrap()
            else {
                panic!("the selected cubic root has a rational bracket")
            };
            let Classification::Decided(parameter) =
                BezierAlgebraicParameter2::try_isolate(polynomial, interval, &policy).unwrap()
            else {
                panic!("the cubic has one root in its selected bracket")
            };
            BezierParameter2::Algebraic(parameter)
        };
        let lower = native(
            vec![(-1).into(), 0.into(), 0.into(), 4.into()],
            q(6, 10),
            q(65, 100),
        );
        let upper = native(
            vec![(-1).into(), (-2).into(), 0.into(), 8.into()],
            q(65, 100),
            q(7, 10),
        );
        let one = DenseTensorPolynomial::try_new(vec![1, 1], vec![Real::one()]).unwrap();
        let field = BezierRecursiveQuadraticField2::base(
            [&lower, &upper]
                .map(bezier_parameter_root_representation)
                .into(),
            one.clone(),
            one,
        )
        .unwrap();
        let roots = [&lower, &upper].map(|parameter| {
            field
                .retained_parameter_value(&parameter.clone().into(), &policy)
                .unwrap()
                .expect("both roots are existing coefficient generators")
        });
        // Independently selected cubics are the two roots of this quadratic.
        // Its formula introduces sqrt((upper-lower)^2); the selected sheet
        // must recover the original roots without projecting them anew.
        let coefficients = [
            roots[0].multiply(&roots[1]).unwrap(),
            roots[0]
                .add(&roots[1])
                .unwrap()
                .scale(&-Real::one())
                .unwrap(),
            field.constant(Real::one()).unwrap(),
        ];
        let formulas =
            recursive_quadratic_polynomial_projective_roots(&field, &coefficients, None, &policy)
                .unwrap()
                .expect("the quadratic has two ordered exact roots");
        assert_eq!(formulas.len(), 2);
        for (index, formula) in formulas.into_iter().enumerate() {
            let Classification::Decided(parameter) =
                BezierRecursiveProjectiveParameter2::new(formula, &policy).unwrap()
            else {
                panic!("each exact root has finite bounds")
            };
            for (other_index, native) in [&lower, &upper].into_iter().enumerate() {
                assert_eq!(
                    parameter.cmp_bezier_parameter(native, &policy).unwrap(),
                    Classification::Decided(index.cmp(&other_index)),
                );
                assert!(parameter.data.projection.parameter.get().is_none());
            }
        }
    }
}

#[test]
fn chord_parallel_monotonicity_rejects_opposed_endpoint_signs() {
    let q = |n, d| (Real::from(n) / Real::from(d)).unwrap();
    // P(t)=(t,t²), D=(1,1): cross(D,P'(t))=2t-1.
    let source = QuadraticBezier2::new(
        Point2::from_values(0, 0),
        Point2::new(q(1, 2), Real::zero()),
        Point2::from_values(1, 1),
    );
    let mut parallels = vec![source.parallel_left(Real::zero()).unwrap()];
    for gauge in [1, -3] {
        parallels.push(
            RationalBezier2::try_new(
                source.control_points().into_iter().cloned().collect(),
                vec![Real::from(gauge); 3],
            )
            .unwrap()
            .parallel_left(Real::zero())
            .unwrap(),
        );
    }
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let Classification::Decided(chord) = BezierAlgebraicChord2::try_new(
            CurvePoint2::from(Point2::from_values(0, 0)),
            CurvePoint2::from(Point2::from_values(1, 1)),
            &policy,
        )
        .unwrap() else {
            panic!("the exact diagonal chord must construct");
        };
        for (chord, orientation) in [
            (chord.clone(), RealSign::Positive),
            (chord.reversed(), RealSign::Negative),
        ] {
            for parallel in &parallels {
                for (lower, upper, sign) in [
                    (Real::zero(), Real::one(), None),
                    (Real::zero(), q(1, 4), Some(RealSign::Negative)),
                    (q(3, 4), Real::one(), Some(RealSign::Positive)),
                    // A zero at a closed endpoint still allows strict
                    // monotonicity throughout the open retained interval.
                    (Real::zero(), q(1, 2), Some(RealSign::Negative)),
                    (q(1, 2), Real::one(), Some(RealSign::Positive)),
                ] {
                    let range = CurveParameterRange2::new_validated(
                        BezierParameter2::Exact(lower).into(),
                        BezierParameter2::Exact(upper).into(),
                    );
                    let expected = match sign {
                        Some(sign) => Classification::Decided(product_sign(sign, orientation)),
                        None => Classification::Uncertain(UncertaintyReason::Boundary),
                    };
                    assert_eq!(
                        chord
                            .parallel_tangent_cross_sign_on_region_range(parallel, &range, &policy)
                            .unwrap(),
                        expected,
                    );
                }
            }
        }
    }
}

#[test]
fn chord_parallel_monotonicity_covers_the_retained_parameter_range() {
    let q = |n, d| (Real::from(n) / Real::from(d)).unwrap();
    // P(t)=(t,15t/4-2t²+t³/3), D=(1,0). The cross polynomial
    // (t-3/2)(t-5/2) is positive on [0,1] and at both ends of
    // [1,3], but has two interior roots in that extended range.
    let source = CubicBezier2::new(
        Point2::from_values(0, 0),
        Point2::new(q(1, 3), q(5, 4)),
        Point2::new(q(2, 3), q(11, 6)),
        Point2::new(Real::one(), q(25, 12)),
    );
    let mut parallels = vec![source.parallel_left(Real::zero()).unwrap()];
    for gauge in [1, -3] {
        parallels.push(
            RationalBezier2::try_new(
                source.control_points().into_iter().cloned().collect(),
                vec![Real::from(gauge); 4],
            )
            .unwrap()
            .parallel_left(Real::zero())
            .unwrap(),
        );
    }
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let Classification::Decided(chord) = BezierAlgebraicChord2::try_new(
            CurvePoint2::from(Point2::from_values(0, 0)),
            CurvePoint2::from(Point2::from_values(1, 0)),
            &policy,
        )
        .unwrap() else {
            panic!("the exact horizontal chord must construct");
        };
        for (chord, orientation) in [
            (chord.clone(), RealSign::Positive),
            (chord.reversed(), RealSign::Negative),
        ] {
            for parallel in &parallels {
                for (lower, upper, expected) in [
                    (Real::one(), Real::from(3), None),
                    (Real::zero(), Real::one(), Some(RealSign::Positive)),
                    (Real::from(3), Real::from(4), Some(RealSign::Positive)),
                    (q(7, 4), q(9, 4), Some(RealSign::Negative)),
                    // Roots at the two endpoints do not invalidate a
                    // strict sign in the open retained interval.
                    (q(3, 2), q(5, 2), Some(RealSign::Negative)),
                ] {
                    for (start, end) in [(lower.clone(), upper.clone()), (upper, lower)] {
                        let range = CurveParameterRange2::new_validated(
                            BezierParameter2::Exact(start).into(),
                            BezierParameter2::Exact(end).into(),
                        );
                        let result = chord
                            .parallel_tangent_cross_sign_on_region_range(parallel, &range, &policy)
                            .unwrap();
                        match expected {
                            None => assert!(
                                matches!(result, Classification::Uncertain(_)),
                                "two interior tangent roots forbid a monotonicity certificate: {result:?}",
                            ),
                            Some(sign) => assert_eq!(
                                result,
                                Classification::Decided(product_sign(sign, orientation)),
                            ),
                        }
                    }
                }
            }
        }
    }
}

#[test]
fn chord_pair_bounds_refine_native_fibers_before_global_projection() {
    use crate::classify::LineSide::{Left, Right};

    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let height = (Real::from(3_i8) / Real::from(2_i8)).unwrap();
    // alpha^65=1/2, u³=alpha, P(u)=(2u²,u). The chord from
    // P(u) to P(u)+(1,1) meets y=3/2 at (2u²-u+3/2,3/2).
    // Its raw [0,1] singleton makes the interval determinant touch zero;
    // native refinement suffices without the degree-195 global image.
    let u = half
        .clone()
        .pow((Real::one() / Real::from(195)).unwrap())
        .unwrap();
    let expected = Point2::new(Real::from(2_i8) * &u * &u - &u + &height, height.clone());
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let seed = high_degree_quadratic_selected_fiber_parameter_for_test(half.clone(), &policy);
        let selected = BezierAlgebraicSelectedFiberAuthority2::new(
            BivariatePolynomial::new(vec![
                vec![Real::zero(), Real::zero(), Real::zero(), Real::one()],
                vec![Real::from(-1_i8)],
            ]),
            seed.data.authority.data.retained_parameter.clone(),
            &policy,
        )
        .parameter(IsolatedRootInterval {
            lower: Real::zero(),
            upper: Real::one(),
            exact_root: None,
            distinct_root_count: 1,
        });
        let parallel = QuadraticBezier2::new(
            Point2::from_values(0, 0),
            Point2::new(Real::zero(), half.clone()),
            Point2::from_values(2, 1),
        )
        .parallel_left(Real::zero())
        .unwrap();
        let start = CurvePoint2::from(BezierAnalyticParallelPoint2::new_selected_fiber(
            parallel,
            selected.clone(),
            &policy,
        ));
        let Classification::Decided(end) =
            BezierAlgebraicChord2::translated_endpoint(&start, &Real::one(), &Real::one(), &policy)
                .unwrap()
        else {
            panic!("the selected endpoint must translate exactly");
        };
        let first = BezierAlgebraicChord2::from_certified_monotone_axis_endpoints(
            start,
            end,
            Axis2::X,
            true,
            &policy,
        );
        let second = BezierAlgebraicChord2::from_certified_axis_aligned_endpoints(
            Point2::new(Real::zero(), height.clone()).into(),
            Point2::new(Real::from(4_i8), height.clone()).into(),
            BezierAlgebraicChordAxisDirection2::PositiveX,
            &policy,
        );
        let intersection = BezierAlgebraicChordPairPoint2::new(
            first,
            second,
            [Right, Left],
            [Left, Right],
            RealSign::Negative,
            &policy,
        );
        let point = CurvePoint2::from(intersection.clone());
        assert!(matches!(
            algebraic_chord_endpoint_local_bounds_refined(&point, 0, &policy),
            Classification::Uncertain(_),
        ));
        for steps in [0, 8, 32] {
            let Classification::Decided(bounds) = policy.bounded_exact_predicate_pass(|| {
                algebraic_chord_endpoint_bounds_refined(&point, steps, &policy)
            }) else {
                panic!("the finite intersection must retain native bounds");
            };
            assert_eq!(
                bounds.contains_point(&expected, &CurveContext::STRICT),
                Classification::Decided(true),
            );
        }
        assert!(selected.data.representations.bezier.get().is_none());
        assert!(selected.data.representations.projective.get().is_none());
        assert!(intersection.data.recursive_point.get().is_none());
    }
}

#[test]
fn conic_owned_endpoint_reuses_local_evidence_on_finite_ranges() {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let selected =
            high_degree_quadratic_selected_fiber_parameter_for_test(half.clone(), &policy);
        for gauge in [1, -3] {
            let source = RationalBezier2::try_new(
                vec![
                    Point2::from_values(0, 0),
                    Point2::new(Real::zero(), half.clone()),
                    Point2::from_values(2, 1),
                ],
                vec![Real::from(gauge); 3],
            )
            .unwrap();
            for source in [source.clone(), source.elevated_to_degree(4).unwrap()] {
                for (owned, dx, dy) in [
                    (CurveParameter2::from_selected_fiber(selected.clone()), 1, 2),
                    (BezierParameter2::Exact(Real::from(2_i8)).into(), 1, 2),
                    // At t=1/2, (2,1) is the tangent. Its double endpoint
                    // contact is still the complete finite intersection.
                    (BezierParameter2::Exact(half.clone()).into(), 2, 1),
                ] {
                    let Classification::Decided(point) =
                        rational_point_evidence_at_region_parameter(&source, &owned, &policy)
                            .unwrap()
                    else {
                        panic!("the exact conic endpoint must remain representable");
                    };
                    let Classification::Decided(end) = BezierAlgebraicChord2::translated_endpoint(
                        &point,
                        &Real::from(dx),
                        &Real::from(dy),
                        &policy,
                    )
                    .unwrap() else {
                        panic!("the chord endpoint must translate");
                    };
                    let Classification::Decided(chord) =
                        BezierAlgebraicChord2::try_new(point, end, &policy).unwrap()
                    else {
                        panic!("the incident chord must construct");
                    };
                    for chord in [chord.clone(), chord.reversed()] {
                        for (start, end) in [
                            (BezierParameter2::Exact(Real::zero()).into(), owned.clone()),
                            (owned.clone(), BezierParameter2::Exact(Real::zero()).into()),
                        ] {
                            let range = CurveParameterRange2::new_validated(start, end);
                            let complete = chord.rational_endpoint_contact_is_complete(
                                &source, &range, &owned, &policy,
                            );
                            assert!(
                                complete,
                                "conic certificate declined: policy={policy:?}, degree={}, selected={}, direction=({dx},{dy}), owned_at_start={}",
                                source.degree(),
                                owned.as_selected_fiber().is_some(),
                                range.start() == &owned,
                            );
                            let Classification::Decided(
                                BezierAlgebraicChordRationalIntersections2::Contacts(contacts),
                            ) = chord
                                .rational_intersections(&source, &range, Some(&owned), &policy)
                                .unwrap()
                            else {
                                panic!("the owned endpoint must discharge the complete range");
                            };
                            assert!(contacts.is_empty());
                        }
                    }
                }
            }
        }
        assert!(selected.data.representations.bezier.get().is_none());
        assert!(selected.data.representations.projective.get().is_none());
    }
}

#[test]
fn conic_owned_endpoint_preserves_a_second_interior_contact() {
    let q = |n, d| (Real::from(n) / Real::from(d)).unwrap();
    let owned = CurveParameter2::from(BezierParameter2::Exact(q(3, 8)));
    // P(t)=(2t²,t). The line through P(3/8) in direction (1,1)
    // also meets P(1/8), strictly inside the retained source range.
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        for gauge in [1, -3] {
            let source = RationalBezier2::try_new(
                vec![
                    Point2::from_values(0, 0),
                    Point2::new(Real::zero(), q(1, 2)),
                    Point2::from_values(2, 1),
                ],
                vec![Real::from(gauge); 3],
            )
            .unwrap();
            let Classification::Decided(chord) = BezierAlgebraicChord2::try_new(
                Point2::new(q(9, 32), q(3, 8)).into(),
                Point2::new(q(-23, 32), q(-5, 8)).into(),
                &policy,
            )
            .unwrap() else {
                panic!("the crossing chord must construct");
            };
            for chord in [chord.clone(), chord.reversed()] {
                for (start, end) in [
                    (BezierParameter2::Exact(Real::zero()).into(), owned.clone()),
                    (owned.clone(), BezierParameter2::Exact(Real::zero()).into()),
                ] {
                    let range = CurveParameterRange2::new_validated(start, end);
                    assert!(
                        !chord.rational_endpoint_contact_is_complete(
                            &source, &range, &owned, &policy,
                        )
                    );
                    let Classification::Decided(
                        BezierAlgebraicChordRationalIntersections2::Contacts(contacts),
                    ) = chord
                        .rational_intersections(&source, &range, Some(&owned), &policy)
                        .unwrap()
                    else {
                        panic!("the complete conic contact set must remain decided");
                    };
                    let [contact] = contacts.as_slice() else {
                        panic!("the unowned interior contact must remain");
                    };
                    assert_eq!(
                        contact
                            .other_parameter()
                            .cmp_by_refinement(&BezierParameter2::Exact(q(1, 8)).into(), &policy)
                            .unwrap(),
                        Classification::Decided(std::cmp::Ordering::Equal),
                    );
                }
            }
        }
    }
}

#[test]
fn conic_owned_endpoint_degree_guard_preserves_cubic_crossings() {
    let q = |n, d| (Real::from(n) / Real::from(d)).unwrap();
    // X=t, Y=(t-1/10)(t-1/5)(t-1), W=(t+1/100)^3.
    // The side at zero agrees with the side immediately below one,
    // and y'(t)>0 throughout [1/2,1], despite two further contacts.
    let e = q(1, 100);
    let e2 = &e * &e;
    let e3 = &e2 * &e;
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        for gauge in [1, -3] {
            let controls = [
                (Real::zero(), q(-1, 50), e3.clone()),
                (q(1, 3), q(13, 150), &e3 + &e2),
                (q(2, 3), q(-6, 25), &e3 + Real::from(2_i8) * &e2 + &e),
                (
                    Real::one(),
                    Real::zero(),
                    &e3 + Real::from(3_i8) * (&e2 + &e) + Real::one(),
                ),
            ]
            .into_iter()
            .map(|(x, y, w)| {
                crate::HomogeneousControl2::new(
                    x * Real::from(gauge),
                    y * Real::from(gauge),
                    w * Real::from(gauge),
                )
            })
            .collect();
            let Classification::Decided(source) =
                RationalBezier2::from_homogeneous_controls(controls, &policy).unwrap()
            else {
                panic!("the pole-free cubic must construct");
            };
            let Classification::Decided(chord) = BezierAlgebraicChord2::try_new(
                source.end().clone().into(),
                Point2::from_values(100, 0).into(),
                &policy,
            )
            .unwrap() else {
                panic!("the horizontal crossing chord must construct");
            };
            let owned = CurveParameter2::from(BezierParameter2::Exact(Real::one()));
            let range = CurveParameterRange2::unit();
            let parallel = source.parallel_left(Real::zero()).unwrap();
            let terminal = CurveParameterRange2::new_validated(
                BezierParameter2::Exact(q(1, 2)).into(),
                owned.clone(),
            );
            for (chord, derivative, side) in [
                (
                    chord.clone(),
                    RealSign::Positive,
                    crate::classify::LineSide::Right,
                ),
                (
                    chord.reversed(),
                    RealSign::Negative,
                    crate::classify::LineSide::Left,
                ),
            ] {
                assert_eq!(
                    chord
                        .parallel_tangent_cross_sign_on_region_range(&parallel, &terminal, &policy,)
                        .unwrap(),
                    Classification::Decided(derivative),
                );
                assert_eq!(
                    chord
                        .strict_oriented_side_by_local_interval_refinement(
                            &source.start().clone().into(),
                            &policy,
                        )
                        .unwrap(),
                    Classification::Decided(side),
                );
                assert!(
                    !chord.rational_endpoint_contact_is_complete(&source, &range, &owned, &policy,)
                );
                let Classification::Decided(BezierAlgebraicChordRationalIntersections2::Contacts(
                    contacts,
                )) = chord
                    .rational_intersections(&source, &range, Some(&owned), &policy)
                    .unwrap()
                else {
                    panic!("the complete cubic contact set must remain decided");
                };
                assert_eq!(contacts.len(), 2);
                for parameter in [q(1, 10), q(1, 5)] {
                    let expected = BezierParameter2::Exact(parameter).into();
                    assert!(contacts.iter().any(|contact| {
                        contact
                            .other_parameter()
                            .cmp_by_refinement(&expected, &policy)
                            .unwrap()
                            == Classification::Decided(std::cmp::Ordering::Equal)
                    }));
                }
            }
        }
    }
}

#[test]
fn conic_owned_endpoint_still_requires_a_pole_free_range() {
    let q = |n, d| (Real::from(n) / Real::from(d)).unwrap();
    // X=t, Y=(t-1/4)(t-2), W=t-3/4. The pole at 3/4
    // masks an additional root from the endpoint-side argument on [0,2].
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let Classification::Decided(source) = RationalBezier2::from_homogeneous_controls(
            vec![
                crate::HomogeneousControl2::new(Real::zero(), q(1, 2), q(-3, 4)),
                crate::HomogeneousControl2::new(q(1, 2), q(-5, 8), q(-1, 4)),
                crate::HomogeneousControl2::new(Real::one(), q(-3, 4), q(1, 4)),
            ],
            &policy,
        )
        .unwrap() else {
            panic!("finite authored endpoints may enclose a projective pole");
        };
        let Classification::Decided(chord) = BezierAlgebraicChord2::try_new(
            Point2::new(q(8, 5), Real::zero()).into(),
            Point2::from_values(100, 0).into(),
            &policy,
        )
        .unwrap() else {
            panic!("the horizontal chord must construct");
        };
        let owned = CurveParameter2::from(BezierParameter2::Exact(Real::from(2_i8)));
        let range = CurveParameterRange2::new_validated(
            BezierParameter2::Exact(Real::zero()).into(),
            owned.clone(),
        );
        assert!(matches!(
            chord
                .rational_intersections(&source, &range, Some(&owned), &policy)
                .unwrap(),
            Classification::Uncertain(UncertaintyReason::Boundary),
        ));
    }
}

#[test]
fn chord_rational_contact_ownership_preserves_selected_fiber_parameters() {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let beta = half.clone().sqrt().unwrap();
    let radius = beta.clone().sqrt().unwrap();
    let BezierParameter2::Algebraic(retained) =
        algebraic_parameter(vec![-half.clone(), Real::zero(), Real::one()])
    else {
        panic!("the selected base must retain its algebraic root");
    };
    // P(t)=(t,(2t-1)²) meets y=beta at two distinct parameters.
    // Each owned contact is selected directly in Q(beta), without first
    // projecting its parameter to an independent univariate root.
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let authority = BezierAlgebraicSelectedFiberAuthority2::new(
            BivariatePolynomial::new(vec![
                vec![Real::one(), Real::from(-4_i8), Real::from(4_i8)],
                vec![Real::from(-1_i8)],
            ]),
            retained.clone(),
            &policy,
        );
        let Classification::Decided(chord) = BezierAlgebraicChord2::try_new(
            Point2::new(Real::zero(), beta.clone()).into(),
            Point2::new(Real::one(), beta.clone()).into(),
            &policy,
        )
        .unwrap() else {
            panic!("the exact horizontal chord must construct");
        };
        for gauge in [1, -3] {
            let curve = RationalBezier2::try_new(
                vec![
                    Point2::from_values(0, 1),
                    Point2::new(half.clone(), Real::from(-1_i8)),
                    Point2::from_values(1, 1),
                ],
                vec![Real::from(gauge); 3],
            )
            .unwrap();
            for chord in [chord.clone(), chord.reversed()] {
                for (lower, upper, remaining) in [
                    (Real::zero(), half.clone(), &half * (Real::one() + &radius)),
                    (half.clone(), Real::one(), &half * (Real::one() - &radius)),
                ] {
                    let owned = CurveParameter2::from_selected_fiber(authority.parameter(
                        IsolatedRootInterval {
                            lower,
                            upper,
                            exact_root: None,
                            distinct_root_count: 1,
                        },
                    ));
                    assert!(owned.as_bezier_parameter().is_none());
                    let Classification::Decided(
                        BezierAlgebraicChordRationalIntersections2::Contacts(contacts),
                    ) = chord
                        .rational_intersections(
                            &curve,
                            &CurveParameterRange2::unit(),
                            Some(&owned),
                            &policy,
                        )
                        .unwrap()
                    else {
                        panic!("selected contact ownership must remain decided");
                    };
                    let [contact] = contacts.as_slice() else {
                        panic!("exactly the unowned contact must remain");
                    };
                    assert_eq!(
                        policy
                            .strict_predicate_pass(|| contact.other_parameter().cmp_by_refinement(
                                &BezierParameter2::Exact(remaining).into(),
                                &policy
                            ))
                            .unwrap(),
                        Classification::Decided(std::cmp::Ordering::Equal),
                    );
                }
            }
        }
    }
}

#[test]
fn vector_tangent_predicates_replay_general_parameter_authorities() {
    use RealSign::{Negative, Positive, Zero};

    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let source = QuadraticBezier2::new(
        Point2::from_values(0, 0),
        Point2::new(half.clone(), Real::zero()),
        Point2::from_values(1, 1),
    );
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        // alpha^65=1/2 and 4 beta^2=alpha select 0<beta<1/2.
        // P'(beta)=(1,2beta), or (-1,-2(1-beta)) after reversal.
        // These interval facts independently determine every sign below.
        let selected =
            high_degree_quadratic_selected_fiber_parameter_for_test(half.clone(), &policy);
        let cold_parameter = CurveParameter2::from_selected_fiber(selected.clone());
        assert_eq!(
            source
                .parallel_left(Real::zero())
                .unwrap()
                .vector_tangent_cross_and_dot_signs(
                    &cold_parameter,
                    &Real::one(),
                    &Real::one(),
                    &policy,
                )
                .unwrap(),
            Classification::Decided((Negative, Positive)),
        );
        assert!(selected.data.representations.bezier.get().is_none());
        let recursive = selected
            .recursive_projective_parameter(&policy)
            .unwrap()
            .expect("the quadratic fiber retains its base field");
        let parameters = [
            cold_parameter,
            CurveParameter2::from_recursive_projective(recursive),
        ];
        for reversed in [false, true] {
            for distance in [-10_i8, 0, 10] {
                let parallel = source.parallel_left(Real::from(distance)).unwrap();
                let parallel = if reversed {
                    parallel.reversed()
                } else {
                    parallel
                };
                // On 0<t<1 the source curvature is at least 2/(5sqrt(5)).
                // Thus distance +10 reverses the derivative; -10 and 0 do not.
                let orient = |sign| match (distance > 0, sign) {
                    (true, Positive) => Negative,
                    (true, Negative) => Positive,
                    (_, sign) => sign,
                };
                for parameter in &parameters {
                    for (x, y, forward, backward) in [
                        (1_i8, 0_i8, (Positive, Positive), (Negative, Negative)),
                        (0, 1, (Negative, Positive), (Positive, Negative)),
                        (1, 1, (Negative, Positive), (Negative, Negative)),
                        (1, -1, (Positive, Positive), (Negative, Positive)),
                        (-1, 0, (Negative, Negative), (Positive, Positive)),
                        (0, 0, (Zero, Zero), (Zero, Zero)),
                    ] {
                        let (cross, dot) = if reversed { backward } else { forward };
                        assert_eq!(
                            parallel
                                .vector_tangent_cross_and_dot_signs(
                                    parameter,
                                    &Real::from(x),
                                    &Real::from(y),
                                    &policy,
                                )
                                .unwrap(),
                            Classification::Decided((orient(cross), orient(dot))),
                            "vector=({x},{y}), reversed={reversed}, distance={distance}",
                        );
                    }
                    for (cross_scale, dot_scale, forward, backward) in [
                        (1_i8, 0_i8, Positive, Negative),
                        (0, 1, Positive, Negative),
                        (1, 1, Positive, Negative),
                        (1, -1, Negative, Negative),
                        (-1, 1, Positive, Positive),
                        (0, 0, Zero, Zero),
                    ] {
                        assert_eq!(
                            parallel
                                .vector_source_tangent_cross_dot_linear_combination_sign(
                                    parameter,
                                    &Real::one(),
                                    &Real::zero(),
                                    &Real::from(cross_scale),
                                    &Real::from(dot_scale),
                                    &policy,
                                )
                                .unwrap(),
                            Classification::Decided(if reversed { backward } else { forward }),
                            "source relation must not include the parallel derivative scale",
                        );
                    }
                }
            }
        }
        assert!(selected.data.representations.bezier.get().is_none());
    }
}

#[test]
fn regularized_vector_tangent_owns_selected_stationary_endpoints() {
    use RealSign::{Negative, Positive, Zero};

    let source = CubicBezier2::new(
        Point2::from_values(0, 0),
        Point2::from_values(0, 0),
        Point2::from_values(0, 0),
        Point2::from_values(1, 0),
    );
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        let seed = high_degree_quadratic_selected_fiber_parameter_for_test(half, &policy);
        for reversed in [false, true] {
            let endpoint = Real::from(if reversed { 1_i8 } else { 0_i8 });
            let selected = BezierAlgebraicSelectedFiberAuthority2::new(
                BivariatePolynomial::new(vec![vec![-&endpoint, Real::one()]]),
                seed.data.authority.data.retained_parameter.clone(),
                &policy,
            )
            .parameter(IsolatedRootInterval {
                lower: &endpoint - Real::one(),
                upper: &endpoint + Real::one(),
                exact_root: Some(endpoint),
                distinct_root_count: 1,
            });
            let parameter = CurveParameter2::from_selected_fiber(selected.clone());
            let parallel = source.parallel_left(Real::one()).unwrap();
            let parallel = if reversed {
                parallel.reversed()
            } else {
                parallel
            };
            // P(t)=(t^3,0) has zero derivative at t=0. Cancelling its
            // stationary factor leaves the one-sided traversal tangent.
            assert_eq!(
                parallel
                    .vector_tangent_cross_and_dot_signs_on_regular_range(
                        &parameter,
                        &Real::zero(),
                        &Real::one(),
                        &CurveParameterRange2::unit(),
                        &policy,
                    )
                    .unwrap(),
                Classification::Decided((if reversed { Positive } else { Negative }, Zero)),
            );
            assert!(selected.data.representations.bezier.get().is_none());
        }
    }
}

#[test]
fn bounded_point_import_preserves_a_cached_local_field() {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let parallel = QuadraticBezier2::new(
        Point2::from_values(0, 0),
        Point2::new(half.clone(), Real::zero()),
        Point2::from_values(1, 0),
    )
    .parallel_left(Real::zero())
    .unwrap();
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        // alpha^65=1/2 and 4*u²=alpha. A later query may also know the
        // native global equation u^130=2^-131, but importing P(u)=(u,0)
        // must preserve the smaller local field and its coordinate identity.
        let selected =
            high_degree_quadratic_selected_fiber_parameter_for_test(half.clone(), &policy);
        let local = selected
            .recursive_projective_parameter(&policy)
            .unwrap()
            .expect("the quadratic fiber has a local field");
        let mut coefficients = vec![Real::zero(); 131];
        coefficients[0] = -Real::from(2_i8).powi_i64(-131).unwrap();
        coefficients[130] = Real::one();
        let polynomial =
            match BezierParameterPolynomial::try_new_power_basis(coefficients, &policy).unwrap() {
                Classification::Decided(polynomial) => polynomial,
                Classification::Uncertain(reason) => panic!("global equation: {reason:?}"),
            };
        let interval =
            match BezierParameterInterval::try_new(Real::zero(), half.clone(), &policy).unwrap() {
                Classification::Decided(interval) => interval,
                Classification::Uncertain(reason) => panic!("global interval: {reason:?}"),
            };
        selected.retain_certified_parameter(BezierParameter2::Algebraic(
            BezierAlgebraicParameter2::from_certified_singleton(polynomial, interval),
        ));
        let point =
            BezierAnalyticParallelPoint2::new_selected_fiber(parallel.clone(), selected, &policy);
        let Classification::Decided(Some(point)) = policy
            .bounded_exact_predicate_pass(|| point.recursive_projective_point(&policy))
            .unwrap()
        else {
            panic!("the already retained local field must remain reusable");
        };
        let scalar = local
            .projective_scalar()
            .expect("a quadratic fiber retains its projective value");
        let residual = point
            .x
            .multiply(&scalar.denominator)
            .and_then(|x| {
                scalar
                    .numerator
                    .multiply(&point.denominator)
                    .and_then(|expected| x.subtract(&expected))
            })
            .expect("the coordinate identity must not need another field import");
        assert_eq!(
            residual.sign(&CurveContext::STRICT).unwrap(),
            Classification::Decided(RealSign::Zero)
        );
        assert_eq!(
            point.y.sign(&CurveContext::STRICT).unwrap(),
            Classification::Decided(RealSign::Zero)
        );
    }
}

#[test]
fn bounded_point_import_reuses_certified_native_fiber_parameters() {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let expected_parameter = half.clone().sqrt().unwrap();
    let source = QuadraticBezier2::new(
        Point2::from_values(0, 0),
        Point2::new(Real::zero(), half.clone()),
        Point2::from_values(2, 1),
    );
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let seed = high_degree_quadratic_selected_fiber_parameter_for_test(half.clone(), &policy);
        let native = BezierAlgebraicParameter2::from_certified_singleton(
            match BezierParameterPolynomial::try_new_power_basis(
                vec![Real::from(-1_i8), Real::zero(), Real::from(2_i8)],
                &policy,
            )
            .unwrap()
            {
                Classification::Decided(polynomial) => polynomial,
                Classification::Uncertain(reason) => panic!("native polynomial: {reason:?}"),
            },
            match BezierParameterInterval::try_new(half.clone(), Real::one(), &policy).unwrap() {
                Classification::Decided(interval) => interval,
                Classification::Uncertain(reason) => panic!("native interval: {reason:?}"),
            },
        );
        for representation in 0..3 {
            for distance in [Real::zero(), half.clone()] {
                let selected = BezierAlgebraicSelectedFiberAuthority2::new(
                    BivariatePolynomial::new(vec![vec![-half.clone(), Real::zero(), Real::one()]]),
                    seed.data.authority.data.retained_parameter.clone(),
                    &policy,
                )
                .parameter(IsolatedRootInterval {
                    lower: half.clone(),
                    upper: Real::one(),
                    exact_root: (representation == 0).then(|| expected_parameter.clone()),
                    distinct_root_count: 1,
                });
                if representation != 0 {
                    selected.retain_certified_parameter(if representation == 1 {
                        BezierParameter2::Exact(expected_parameter.clone())
                    } else {
                        BezierParameter2::Algebraic(native.clone())
                    });
                }
                let parallel = source.parallel_left(distance).unwrap();
                let expected = match parallel.point_at(&expected_parameter, &policy).unwrap() {
                    Classification::Decided(point) => point,
                    Classification::Uncertain(reason) => panic!("expected point: {reason:?}"),
                };
                let point = BezierAnalyticParallelPoint2::new_selected_fiber(
                    parallel,
                    selected.clone(),
                    &policy,
                );
                let Classification::Decided(Some(imported)) = policy
                    .bounded_exact_predicate_pass(|| point.recursive_projective_point(&policy))
                    .unwrap()
                else {
                    panic!("a certified native fiber parameter must import under a bounded budget");
                };
                for (coordinate, expected) in
                    [(&imported.x, expected.x()), (&imported.y, expected.y())]
                {
                    assert_eq!(
                        coordinate
                            .subtract(&imported.denominator.scale(expected).unwrap())
                            .unwrap()
                            .sign(&CurveContext::STRICT)
                            .unwrap(),
                        Classification::Decided(RealSign::Zero),
                    );
                }
                assert!(selected.data.representations.projective.get().is_none());
                assert_eq!(
                    selected.data.representations.bezier.get().is_some(),
                    representation != 0
                );
                let Classification::Decided(Some(replayed)) =
                    point.clone().recursive_projective_point(&policy).unwrap()
                else {
                    panic!("a cloned point must retain its certified recursive field");
                };
                assert!(
                    imported
                        .denominator
                        .field()
                        .same_field(&replayed.denominator.field())
                );
            }
        }
    }
}

#[test]
fn selected_fiber_points_reuse_projective_roots_without_global_promotion() {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let sqrt_two = Real::from(2_i8).sqrt().unwrap();
    let parallel = QuadraticBezier2::new(
        Point2::from_values(0, 0),
        Point2::new(Real::zero(), half.clone()),
        Point2::from_values(2, 1),
    )
    .parallel_left(Real::zero())
    .unwrap();
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let seed = high_degree_quadratic_selected_fiber_parameter_for_test(half.clone(), &policy);
        for gauge in [Real::one(), Real::from(-3_i8)] {
            for (quadratic, lower, upper, sign) in [
                (true, -half.clone(), Real::zero(), RealSign::Negative),
                (true, Real::zero(), half.clone(), RealSign::Positive),
                (false, Real::zero(), Real::one(), RealSign::Positive),
            ] {
                let coefficients = if quadratic {
                    vec![Real::zero(), Real::zero(), &gauge * Real::from(4_i8)]
                } else {
                    vec![Real::zero(), &gauge * &sqrt_two]
                };
                let selected = BezierAlgebraicSelectedFiberAuthority2::new(
                    BivariatePolynomial::new(vec![coefficients, vec![-gauge.clone()]]),
                    seed.data.authority.data.retained_parameter.clone(),
                    &policy,
                )
                .parameter(IsolatedRootInterval {
                    lower,
                    upper,
                    exact_root: None,
                    distinct_root_count: 1,
                });
                let point = BezierAnalyticParallelPoint2::new_selected_fiber(
                    parallel.clone(),
                    selected.clone(),
                    &policy,
                );
                let Classification::Decided(Some(point)) = policy
                    .bounded_exact_predicate_pass(|| point.recursive_projective_point(&policy))
                    .unwrap()
                else {
                    panic!("a low-degree fiber point must import in its retained field");
                };
                assert!(selected.data.representations.bezier.get().is_none());
                let first = selected
                    .recursive_projective_parameter(&policy)
                    .unwrap()
                    .expect("the selected projective root must be cached");
                let Classification::Decided(refined) = selected.refined(4, &policy).unwrap() else {
                    panic!("the selected singleton must refine");
                };
                let second = refined
                    .recursive_projective_parameter(&policy)
                    .unwrap()
                    .expect("refinement must preserve the cached representation");
                assert!(Arc::ptr_eq(&first.data, &second.data));
                assert!(Arc::ptr_eq(
                    &selected.data.representations,
                    &refined.data.representations,
                ));
                assert!(refined.data.representations.bezier.get().is_none());

                let field = point.denominator.field();
                let (base, extensions) = field.base_and_extension_path();
                assert_eq!(base.sources.len(), 1);
                assert_eq!(base.sources[0].polynomial_coefficients.len(), 66);
                assert_eq!(extensions.len(), usize::from(quadratic));
                let alpha = recursive_quadratic_rational_value(
                    &base,
                    DenseTensorPolynomial::from_axis_polynomial(1, 0, &[Real::zero(), Real::one()])
                        .unwrap(),
                )
                .and_then(|value| field.lift(&value))
                .unwrap();
                // The source is P(t)=(2t²,t). These two independent
                // equations and the selected sign determine its point.
                let parabola = point
                    .x
                    .multiply(&point.denominator)
                    .and_then(|value| value.subtract(&point.y.square()?.scale(&Real::from(2_i8))?))
                    .unwrap();
                let fiber_value = if quadratic {
                    point
                        .y
                        .square()
                        .and_then(|value| value.scale(&Real::from(4_i8)))
                } else {
                    point
                        .y
                        .multiply(&point.denominator)
                        .and_then(|value| value.scale(&sqrt_two))
                }
                .and_then(|value| value.subtract(&alpha.multiply(&point.denominator.square()?)?))
                .unwrap();
                assert_eq!(
                    parabola.sign(&policy).unwrap(),
                    Classification::Decided(RealSign::Zero)
                );
                assert_eq!(
                    fiber_value.sign(&policy).unwrap(),
                    Classification::Decided(RealSign::Zero)
                );
                assert_eq!(
                    point.denominator.sign(&policy).unwrap(),
                    Classification::Decided(RealSign::Positive)
                );
                assert_eq!(
                    point.y.sign(&policy).unwrap(),
                    Classification::Decided(sign)
                );
            }
        }
    }
}

#[test]
fn nonquadratic_selected_fiber_keeps_its_defining_authority() {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let seed = high_degree_quadratic_selected_fiber_parameter_for_test(half.clone(), &policy);
        let incidence = BivariatePolynomial::new(vec![
            vec![Real::zero(), Real::zero(), Real::zero(), Real::one()],
            vec![Real::from(-1_i8)],
        ]);
        let selected = BezierAlgebraicSelectedFiberAuthority2::new(
            incidence.clone(),
            seed.data.authority.data.retained_parameter.clone(),
            &policy,
        )
        .parameter(IsolatedRootInterval {
            lower: half.clone(),
            upper: Real::one(),
            exact_root: None,
            distinct_root_count: 1,
        });
        assert!(
            selected
                .recursive_projective_parameter(&policy)
                .unwrap()
                .is_none()
        );
        assert!(selected.data.representations.bezier.get().is_none());
        assert!(selected.data.representations.projective.get().is_none());
        assert_eq!(
            policy
                .strict_predicate_pass(|| selected.predicate_sign(&incidence, &policy))
                .unwrap(),
            Classification::Decided(RealSign::Zero),
        );
    }
}

fn clip_aligned_overlap_for_test(
    first: &BezierParameterRange2,
    second: &BezierParameterRange2,
    reversed: bool,
    first_limit: &CurveParameterRange2,
    second_limit: &CurveParameterRange2,
    policy: &CurveContext,
) -> CurveResult<Option<(CurveParameterRange2, CurveParameterRange2)>> {
    let source = if reversed {
        crate::rational_bezier_general::RationalBezierOverlapParameterCorrespondence2::UnitComplement
    } else {
        crate::rational_bezier_general::RationalBezierOverlapParameterCorrespondence2::Identity
    };
    match source.clipped_ranges(first, second, first_limit, second_limit, policy)? {
        Classification::Decided(ranges) => Ok(ranges),
        Classification::Uncertain(reason) => panic!("test overlap restriction: {reason:?}"),
    }
}

#[test]
fn fiber_specialization_retains_native_quadratic_root_certificates() {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let alpha = half.clone().sqrt().unwrap();
    let delta = (&alpha + &half * &half).sqrt().unwrap();
    for root in [-&half - &delta, -&half + &delta] {
        let width = (Real::from(2_i8) / Real::from(7_i8)).unwrap();
        let parameter = Real::average_pair(&(&root - &width), &(&root + &width));
        let rows: Vec<Vec<Real>> = [Real::one(), Real::pi(), -Real::pi()]
            .into_iter()
            .map(|scale| vec![-&alpha * &scale, scale.clone(), scale])
            .collect();
        let bivariate = BivariatePolynomial::new(rows.clone());
        let dense =
            DenseTensorPolynomial::try_new(vec![3, 3], rows.into_iter().flatten().collect())
                .unwrap();
        let second_fiber = bivariate_specialize_second(&bivariate, &parameter);
        let last_axis = dense_specialize_last_axis(&dense, &parameter).unwrap();
        assert_eq!(last_axis.dimensions(), &[3, 1]);
        for (lane, values) in [
            ("bivariate second fiber", second_fiber.as_slice()),
            ("dense last axis", last_axis.coefficients()),
        ] {
            assert_eq!(values.len(), 3);
            for (row, value) in values.iter().enumerate() {
                assert_eq!(
                    value.zero_status(),
                    ZeroKnowledge::Zero,
                    "{lane}, coefficient row {row}",
                );
            }
        }
    }
}

#[test]
fn fiber_specialization_preserves_axis_order_and_ragged_zero_rows() {
    let rows = vec![
        vec![],
        vec![3.into()],
        vec![2.into(), (-1).into(), 4.into()],
    ];
    let bivariate = BivariatePolynomial::new(rows);
    let dense = DenseTensorPolynomial::try_new(
        vec![2, 3, 4],
        (0..24).map(|index| Real::from(index - 11)).collect(),
    )
    .unwrap();
    for (numerator, denominator) in [(-3, 2), (0, 1), (1, 1), (7, 3)] {
        let parameter = (Real::from(numerator) / Real::from(denominator)).unwrap();
        assert_eq!(
            bivariate_specialize_second(&bivariate, &parameter),
            vec![
                Real::zero(),
                Real::from(3_i8),
                Real::from(2_i8) - &parameter + Real::from(4_i8) * &parameter * &parameter,
            ],
        );
        let specialized = dense_specialize_last_axis(&dense, &parameter).unwrap();
        assert_eq!(specialized.dimensions(), &[2, 3, 1]);
        for (fiber, value) in dense
            .coefficients()
            .as_chunks::<4>()
            .0
            .iter()
            .zip(specialized.coefficients())
        {
            let expected =
                fiber
                    .iter()
                    .enumerate()
                    .fold(Real::zero(), |sum, (power, coefficient)| {
                        sum + if power == 0 {
                            coefficient.clone()
                        } else {
                            coefficient * parameter.clone().powi_i64(power as i64).unwrap()
                        }
                    });
            assert_eq!(value, &expected);
        }
    }
}

#[test]
fn recursive_scalar_comparison_replays_exact_equality_before_approximation() {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let other = algebraic_parameter(vec![-half.clone(), Real::zero(), Real::one()]);
    assert!(matches!(other, BezierParameter2::Algebraic(_)));
    let one = DenseTensorPolynomial::try_new(vec![], vec![Real::one()]).unwrap();
    let field = BezierRecursiveQuadraticField2::base(vec![], one.clone(), one).unwrap();
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let Classification::Decided(parameter) = BezierRecursiveProjectiveParameter2::new(
            BezierRecursiveQuadraticProjectiveScalar2 {
                numerator: field.constant(half.clone().sqrt().unwrap()).unwrap(),
                denominator: field.constant(Real::one()).unwrap(),
            },
            &policy,
        )
        .unwrap() else {
            panic!("the native radical has an exact finite enclosure");
        };
        let result = crate::policy::resolve_certified_value(&policy, |policy| {
            parameter.cmp_bezier_parameter(&other, policy)
        });
        assert_eq!(result.certainty, crate::CurveCertainty::Certified);
        assert_eq!(
            result.value.unwrap(),
            Classification::Decided(std::cmp::Ordering::Equal)
        );
        let BezierParameter2::Algebraic(owner) = &other else {
            unreachable!("the fixture retains an algebraic owner")
        };
        let selected = CurveParameter2::from_selected_fiber(
            BezierAlgebraicSelectedFiberAuthority2::from_bezier_parameter(
                owner.clone(),
                other.clone(),
                &policy,
            ),
        );
        let recursive = CurveParameter2::from_recursive_projective(parameter);
        for (first, second) in [(&selected, &recursive), (&recursive, &selected)] {
            let result = crate::policy::resolve_certified_value(&policy, |attempt| {
                first.cmp_by_refinement(second, attempt)
            });
            assert_eq!(result.certainty, CurveCertainty::Certified);
            assert_eq!(
                result.value.unwrap(),
                Classification::Decided(std::cmp::Ordering::Equal)
            );
            assert!(matches!(
                CurveParameterRange2::new_validated(first.clone(), second.clone())
                    .strict_interior_scalar(&policy),
                Err(CurveError::InvalidBezierRange)
            ));
        }
    }
}

#[test]
fn recursive_local_root_orders_against_close_coefficient_generators() {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let native = algebraic_parameter(vec![-half, Real::zero(), Real::one()]);
    let source = bezier_parameter_root_representation(&native);
    let one = DenseTensorPolynomial::try_new(vec![1, 1], vec![Real::one()]).unwrap();
    let base = BezierRecursiveQuadraticField2::base(vec![source.clone(), source], one.clone(), one)
        .unwrap();
    let field = base
        .extension(base.constant(Real::from(3_i8)).unwrap())
        .unwrap();
    let BezierRecursiveQuadraticField2::Base(base_data) = &base else {
        unreachable!("the fixture begins with a dense base");
    };
    // Use the second copy of the generator in the polynomial; importing
    // its native parameter selects the first. Their exact identity must
    // survive without rebuilding or merging the coefficient field.
    let alpha = field
        .lift(
            &recursive_quadratic_rational_value(
                base_data,
                DenseTensorPolynomial::from_axis_polynomial(2, 1, &[Real::zero(), Real::one()])
                    .unwrap(),
            )
            .unwrap(),
        )
        .unwrap();
    let tiny = Real::from(2_i8).powi_i64(-80).unwrap();
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        for gauge in [Real::one(), Real::from(-7_i8)] {
            let eighth = (Real::one() / Real::from(8_i8)).unwrap();
            for (shift, expected, inside) in [
                (-tiny.clone(), std::cmp::Ordering::Less, true),
                (Real::zero(), std::cmp::Ordering::Equal, true),
                (tiny.clone(), std::cmp::Ordering::Greater, true),
                (-eighth.clone(), std::cmp::Ordering::Less, false),
                (eighth, std::cmp::Ordering::Greater, false),
            ] {
                // The local root alpha + shift shares its broad isolator
                // with alpha. Its defining linear relation can order the
                // two directly even when ordinary bounds cannot separate.
                let constant = alpha
                    .add(&field.constant(shift).unwrap())
                    .unwrap()
                    .scale(&-gauge.clone())
                    .unwrap();
                let polynomial = vec![constant, field.constant(gauge.clone()).unwrap()];
                let roots = recursive_quadratic_polynomial_local_parameters(
                    &field,
                    &polynomial,
                    [&Real::zero(), &Real::one()],
                    &policy,
                )
                .unwrap()
                .expect("the shifted generator remains a simple local root");
                let [root] = roots.as_slice() else {
                    panic!("the linear relation has exactly one root");
                };
                let selected = root.as_recursive_projective().unwrap();
                let lower_order = represented_order_to_real(
                    &bezier_parameter_root_representation(&native),
                    &selected.data.lower,
                    &CurveContext::STRICT,
                );
                let upper_order = represented_order_to_real(
                    &bezier_parameter_root_representation(&native),
                    &selected.data.upper,
                    &CurveContext::STRICT,
                );
                assert_eq!(
                    lower_order == Classification::Decided(std::cmp::Ordering::Greater)
                        && upper_order == Classification::Decided(std::cmp::Ordering::Less),
                    inside,
                );
                #[cfg(feature = "dispatch-trace")]
                hyperreal::dispatch_trace::reset();
                let compare = || {
                    crate::policy::resolve_certified_value(&policy, |attempt| {
                        root.cmp_by_refinement(&native.clone().into(), attempt)
                    })
                };
                #[cfg(feature = "dispatch-trace")]
                let result = hyperreal::dispatch_trace::with_recording(compare);
                #[cfg(not(feature = "dispatch-trace"))]
                let result = compare();
                assert_eq!(result.certainty, crate::CurveCertainty::Certified);
                assert_eq!(result.value.unwrap(), Classification::Decided(expected));
                assert!(selected.data.projection.parameter.get().is_none());
                #[cfg(feature = "dispatch-trace")]
                {
                    let trace = hyperreal::dispatch_trace::take_trace();
                    assert!(
                        trace.path_count(
                            "hypercurve",
                            "recursive-parameter-comparison",
                            if expected == std::cmp::Ordering::Equal {
                                "retained-generator-identity"
                            } else {
                                "retained-generator-order"
                            },
                        ) > 0
                    );
                    assert_eq!(
                        trace.path_count(
                            "hypercurve",
                            "recursive-polynomial-sign",
                            "retained-field-remainder",
                        ),
                        0,
                        "a generator comparison needs no polynomial reduction"
                    );
                }
            }
        }
    }
}

#[test]
fn retained_parameter_import_keeps_original_axes_and_tower() {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let third = (Real::one() / Real::from(3_i8)).unwrap();
    let parameter =
        algebraic_parameter(vec![-half.clone(), Real::zero(), Real::zero(), Real::one()]);
    let foreign = algebraic_parameter(vec![-third, Real::zero(), Real::zero(), Real::one()]);
    assert!(parameter.scalar().is_none());
    assert!(foreign.scalar().is_none());
    let source = bezier_parameter_root_representation(&parameter);
    let one = DenseTensorPolynomial::try_new(vec![1, 1], vec![Real::one()]).unwrap();
    let base = BezierRecursiveQuadraticField2::base(vec![source.clone(), source], one.clone(), one)
        .unwrap();
    let tower = base
        .extension(base.constant(Real::from(7_i8)).unwrap())
        .unwrap();
    let contact = CurveParameter2::from(parameter.clone());
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        for field in [&base, &tower] {
            let value = policy
                .bounded_exact_predicate_pass(|| field.retained_parameter_value(&contact, &policy))
                .unwrap()
                .expect("an original selected axis is already in the field");
            assert!(field.same_field(&value.field()));
            assert_eq!(
                value
                    .square()
                    .unwrap()
                    .multiply(&value)
                    .unwrap()
                    .subtract(&field.constant(half.clone()).unwrap())
                    .unwrap()
                    .sign(&CurveContext::STRICT)
                    .unwrap(),
                Classification::Decided(RealSign::Zero)
            );
            assert_eq!(
                value.sign(&CurveContext::STRICT).unwrap(),
                Classification::Decided(RealSign::Positive)
            );
            // Deduplicating two original axes leaves room for a foreign
            // source without changing the union length. It is still not
            // an existing generator and must decline this optional import.
            assert!(
                field
                    .retained_parameter_value(&foreign.clone().into(), &policy)
                    .unwrap()
                    .is_none()
            );
            assert_eq!(field.base_and_extension_path().0.sources.len(), 2);
        }
    }
    assert!(parameter.scalar().is_none());
    assert!(foreign.scalar().is_none());
    assert_eq!(contact.as_bezier_parameter(), Some(&parameter));
}

#[test]
fn exterior_chord_contact_deflation_preserves_other_contacts() {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let source =
        RationalBezier2::try_from_subcurve(&BezierSubcurve2::Quadratic(QuadraticBezier2::new(
            Point2::from_values(0, 0),
            Point2::new(half.clone(), Real::zero()),
            Point2::from_values(1, 1),
        )))
        .unwrap();
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        for native in [
            algebraic_parameter(vec![-half.clone(), Real::zero(), Real::one()]),
            BezierParameter2::Exact(Real::zero()),
            BezierParameter2::Exact(Real::one()),
        ] {
            let contact = CurveParameter2::from(native.clone());
            let point = match &native {
                BezierParameter2::Algebraic(root) => CurvePoint2::from(crate::tests::decided(
                    source.point_at_algebraic_parameter(root, &policy).unwrap(),
                )),
                BezierParameter2::Exact(value) => {
                    CurvePoint2::from(Point2::new(value.clone(), value * value))
                }
            };
            let Classification::Decided(chord) =
                BezierAlgebraicChord2::try_new(point, Point2::from_values(2, 4).into(), &policy)
                    .unwrap()
            else {
                panic!("the parabola secant has distinct exact endpoints");
            };
            for reversed in [false, true] {
                let chord = if reversed {
                    chord.reversed()
                } else {
                    chord.clone()
                };
                let (start, end) = if reversed { (3, -1) } else { (-1, 3) };
                let Classification::Decided(range) = CurveParameterRange2::try_new(
                    Real::from(start).into(),
                    Real::from(end).into(),
                    &policy,
                )
                .unwrap() else {
                    panic!("the finite exterior range is exact");
                };
                #[cfg(feature = "dispatch-trace")]
                hyperreal::dispatch_trace::reset();
                let evaluate = || {
                    chord.recursive_projective_rational_intersections(
                        &source,
                        &range,
                        Some(&contact),
                        &policy,
                    )
                };
                #[cfg(feature = "dispatch-trace")]
                let result = hyperreal::dispatch_trace::with_recording(evaluate);
                #[cfg(not(feature = "dispatch-trace"))]
                let result = evaluate();
                let Classification::Decided(Some(
                    BezierAlgebraicChordRationalIntersections2::Contacts(contacts),
                )) = result.unwrap()
                else {
                    panic!("the exterior secant retains every other contact");
                };
                assert_eq!(contacts.len(), 1);
                assert_eq!(
                    contacts[0]
                        .other_parameter()
                        .cmp_by_refinement(&Real::from(2_i8).into(), &policy,)
                        .unwrap(),
                    Classification::Decided(std::cmp::Ordering::Equal)
                );
                let expected_endpoint = if reversed {
                    chord.start_parameter()
                } else {
                    chord.end_parameter()
                };
                assert_eq!(
                    contacts[0]
                        .chord_parameter()
                        .cmp_by_refinement(&expected_endpoint, &policy)
                        .unwrap(),
                    Classification::Decided(std::cmp::Ordering::Equal)
                );
                assert_ne!(contacts[0].tangent_cross_sign(), RealSign::Zero);
                #[cfg(feature = "dispatch-trace")]
                if matches!(native, BezierParameter2::Algebraic(_)) {
                    let trace = hyperreal::dispatch_trace::take_trace();
                    assert!(
                        trace.path_count(
                            "hypercurve",
                            "algebraic-chord-rational-kernel",
                            "retained-contact-factor",
                        ) > 0
                    );
                }
            }
        }
    }
}

#[test]
fn recursive_quadratic_endpoint_roots_keep_the_original_field() {
    let one = DenseTensorPolynomial::try_new(vec![], vec![Real::one()]).unwrap();
    let field = BezierRecursiveQuadraticField2::base(vec![], one.clone(), one).unwrap();
    for scale in [Real::one(), Real::from(2_i8).sqrt().unwrap(), -Real::pi()] {
        let coefficients =
            [Real::zero(), -scale.clone(), scale].map(|value| field.constant(value).unwrap());
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let roots = recursive_quadratic_polynomial_projective_roots(
                &field,
                &coefficients,
                None,
                &policy,
            )
            .unwrap()
            .expect("the two distinct endpoint roots are complete");
            assert_eq!(roots.len(), 2);
            for (index, root) in roots.iter().enumerate() {
                assert!(field.same_field(&root.numerator.field()));
                assert!(field.same_field(&root.denominator.field()));
                assert_eq!(
                    root.numerator.exact_real_value_with_retained_witnesses(),
                    Some(Real::from(index as i8))
                );
                assert_eq!(
                    root.denominator.exact_real_value_with_retained_witnesses(),
                    Some(Real::one())
                );
            }
        }
    }
}

#[test]
fn certified_circle_chord_endpoint_factor_preserves_roots_and_field() {
    let q = |n, d| (Real::from(n) / Real::from(d)).unwrap();
    let one = DenseTensorPolynomial::try_new(vec![], vec![Real::one()]).unwrap();
    let base = BezierRecursiveQuadraticField2::base(vec![], one.clone(), one).unwrap();
    let field = base
        .extension(base.constant(Real::from(2_i8)).unwrap())
        .unwrap();
    let projective = |point: &Point2| BezierRecursiveQuadraticProjectivePoint2 {
        x: field.constant(point.x().clone()).unwrap(),
        y: field.constant(point.y().clone()).unwrap(),
        denominator: field.constant(Real::one()).unwrap(),
    };
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let anchor = match BezierAlgebraicChord2::try_new(
            CurvePoint2::from(Point2::from_values(0, -1)),
            CurvePoint2::from(Point2::from_values(1, -1)),
            &policy,
        )
        .unwrap()
        {
            Classification::Decided(chord) => chord,
            _ => panic!("the horizontal anchor is exact"),
        };
        let circle = match BezierAlgebraicCuspSemicircle2::from_retained_center_and_chord_normal(
            CurvePoint2::from(Point2::from_values(0, 0)),
            anchor,
            Real::one(),
            true,
            &policy,
        )
        .unwrap()
        {
            Classification::Decided(Some(circle)) => circle,
            _ => panic!("the right unit semicircle is exact"),
        };
        let authority = BezierRecursiveCircleFrame2 {
            field: field.clone(),
            center: projective(&Point2::from_values(0, 0)),
            support_center: projective(&Point2::from_values(0, -1)),
            normal_denominator: Real::one(),
        };
        for tangent in [false, true] {
            for reversed in [false, true] {
                let (mut start, mut end) = if tangent {
                    (Point2::from_values(1, 0), Point2::from_values(1, 1))
                } else {
                    // x=3/5 meets the unit circle at y=+/-4/5.
                    (
                        Point2::new(q(3, 5), q(4, 5)),
                        Point2::new(q(3, 5), q(-6, 5)),
                    )
                };
                if reversed {
                    std::mem::swap(&mut start, &mut end);
                }
                let chord = match BezierAlgebraicChord2::try_new(
                    CurvePoint2::from(start.clone()),
                    CurvePoint2::from(end.clone()),
                    &policy,
                )
                .unwrap()
                {
                    Classification::Decided(chord) => chord,
                    _ => panic!("the exact secant or tangent is finite"),
                };
                let result = crate::policy::resolve_certified_value(&policy, |policy| {
                    circle.recursive_projective_chord_intersections(
                        &chord,
                        authority.clone(),
                        projective(&start),
                        projective(&end),
                        true,
                        Some(if reversed {
                            BezierCertifiedFiniteChordEndpointIncidence2::End
                        } else {
                            BezierCertifiedFiniteChordEndpointIncidence2::Start
                        }),
                        policy,
                    )
                });
                assert_eq!(result.certainty, crate::CurveCertainty::Certified);
                let Classification::Decided(Some(
                    BezierAlgebraicCuspSemicircleChordIntersections2::Contacts {
                        contacts,
                        parameter_map,
                    },
                )) = result.value.unwrap()
                else {
                    panic!("the certified endpoint and every other finite root must survive");
                };
                let BezierAlgebraicCuspSemicircleChordParameterMapSystem2::RecursiveQuadraticLine(
                    system,
                ) = &parameter_map.data.system
                else {
                    panic!("the contacts retain their field");
                };
                let expected = if tangent {
                    vec![(Real::from(i8::from(reversed)), RealSign::Zero)]
                } else if reversed {
                    vec![
                        (q(1, 5), RealSign::Negative),
                        (Real::one(), RealSign::Positive),
                    ]
                } else {
                    vec![
                        (Real::zero(), RealSign::Negative),
                        (q(4, 5), RealSign::Positive),
                    ]
                };
                assert_eq!(contacts.len(), expected.len());
                assert_eq!(system.contacts.len(), expected.len());
                for ((contact, retained), (parameter, cross)) in
                    contacts.iter().zip(&system.contacts).zip(expected)
                {
                    assert_eq!(contact.tangent_cross_sign, cross);
                    assert_eq!(
                        retained
                            .parameter
                            .order_to_real(&parameter, &policy)
                            .unwrap(),
                        Classification::Decided(std::cmp::Ordering::Equal)
                    );
                    let scalar = retained.parameter.projective_scalar().unwrap();
                    assert!(field.same_field(&scalar.numerator.field()));
                    assert!(field.same_field(&scalar.denominator.field()));
                    assert!(field.same_field(&retained.point.denominator.field()));
                }
            }
        }
    }
}

#[test]
fn recursive_projective_bounds_reuse_positive_denominator_certificate() {
    let one = DenseTensorPolynomial::try_new(vec![], vec![Real::one()]).unwrap();
    let field = BezierRecursiveQuadraticField2::base(vec![], one.clone(), one).unwrap();
    let sine = Real::e().sin();
    let cosine = Real::e().cos();
    // sin(e)^2 + cos(e)^2 = 1 proves this denominator is 2^-3000.
    // This nonlinear identity remains outside the bounded affine scalar
    // normal form, so coordinate bounds must reuse the construction proof.
    let scale =
        &sine * &sine + &cosine * &cosine - Real::one() + Real::from(2_i8).powi_i64(-3000).unwrap();
    assert_eq!(scale.zero_status(), ZeroKnowledge::Unknown);
    let point = BezierRecursiveQuadraticProjectivePoint2 {
        x: field.constant(&scale * Real::from(3_i8)).unwrap(),
        y: field.constant(-scale.clone()).unwrap(),
        denominator: field.constant(scale).unwrap(),
    };
    assert_eq!(
        point
            .denominator
            .exact_real_value_with_retained_witnesses()
            .unwrap()
            .zero_status(),
        ZeroKnowledge::Unknown,
    );
    #[cfg(feature = "dispatch-trace")]
    hyperreal::dispatch_trace::reset();
    let bounds = || point.bounds_refined(0);
    #[cfg(feature = "dispatch-trace")]
    let bounds = hyperreal::dispatch_trace::with_recording(bounds);
    #[cfg(not(feature = "dispatch-trace"))]
    let bounds = bounds();
    let Classification::Decided(bounds) = bounds else {
        panic!("the retained nonzero proof must permit native coordinate bounds");
    };
    let expected = Point2::from_values(3, -1);
    let max_width = Real::from(2_i8).powi_i64(-60).unwrap();
    for (lower, value, upper) in [
        (bounds.min().x(), expected.x(), bounds.max().x()),
        (bounds.min().y(), expected.y(), bounds.max().y()),
    ] {
        assert!(lower <= value && value <= upper);
        assert!(upper - lower <= max_width);
    }
    #[cfg(feature = "dispatch-trace")]
    assert_eq!(
        hyperreal::dispatch_trace::take_trace().path_count(
            "hypercurve",
            "recursive-projective-bounds",
            "retained-scalar",
        ),
        1,
    );
}

#[test]
fn recursive_projective_bounds_enclose_scaled_nested_radicals() {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let source = bezier_parameter_root_representation(&algebraic_parameter(vec![
        -half.clone(),
        Real::zero(),
        Real::one(),
    ]));
    let one = DenseTensorPolynomial::try_new(vec![1], vec![Real::one()]).unwrap();
    let field = BezierRecursiveQuadraticField2::base(vec![source], one.clone(), one).unwrap();
    let BezierRecursiveQuadraticField2::Base(base) = &field else {
        unreachable!();
    };
    assert!(base.source_real_witnesses[0].is_some());
    let coordinate = recursive_quadratic_rational_value(
        base,
        DenseTensorPolynomial::try_new(vec![2], vec![Real::zero(), Real::one()]).unwrap(),
    )
    .unwrap();
    let radicand = coordinate
        .add(&field.constant(Real::from(3_i8)).unwrap())
        .unwrap();
    let extension = field.extension(radicand).unwrap();
    let x = extension
        .element(coordinate.clone(), field.constant(Real::one()).unwrap())
        .unwrap();
    let y = extension
        .element(coordinate, field.constant(Real::from(-1_i8)).unwrap())
        .unwrap();
    let denominator = extension.constant(Real::from(2_i8)).unwrap();
    let selected = half.sqrt().unwrap();
    let root = (&selected + Real::from(3_i8)).sqrt().unwrap();
    let expected_x = ((&selected + &root) / Real::from(2_i8)).unwrap();
    let expected_y = ((selected - root) / Real::from(2_i8)).unwrap();

    for scale in [
        -Real::from(2_i8).powi_i64(600).unwrap(),
        Real::from(-1_i8),
        Real::zero(),
        Real::from(2_i8).powi_i64(-600).unwrap(),
        Real::one(),
        Real::from(2_i8).powi_i64(600).unwrap(),
    ] {
        let point = BezierRecursiveQuadraticProjectivePoint2 {
            x: x.scale(&scale).unwrap(),
            y: y.scale(&scale).unwrap(),
            denominator: denominator.clone(),
        };
        let expected = [&expected_x * &scale, &expected_y * scale];
        let mut previous_widths: Option<[HyperRational; 2]> = None;
        for steps in [0_usize, 64, 256, 1024] {
            let Classification::Decided(bounds) = point.bounds_refined(steps) else {
                panic!("retained nested witnesses must enclose both coordinates");
            };
            let intervals = [
                [bounds.min().x(), bounds.max().x()],
                [bounds.min().y(), bounds.max().y()],
            ];
            let widths = std::array::from_fn(|axis| {
                // Native precision applies before the rational scale.
                // Compare against the exact coordinate, not another
                // representation's potentially wider dyadic certificate.
                assert!(
                    intervals[axis][0] <= &expected[axis],
                    "axis {axis}, steps {steps}"
                );
                assert!(
                    &expected[axis] <= intervals[axis][1],
                    "axis {axis}, steps {steps}"
                );
                let lower = intervals[axis][0].exact_rational_ref().unwrap();
                let upper = intervals[axis][1].exact_rational_ref().unwrap();
                upper - lower
            });
            if let Some(previous) = previous_widths {
                assert!(widths[0] <= previous[0] && widths[1] <= previous[1]);
            }
            previous_widths = Some(widths);
        }
    }
}

#[test]
fn recursive_projective_bounds_keep_unwitnessed_source_fallback() {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let source = bezier_parameter_root_representation(&algebraic_parameter(vec![
        -half.clone(),
        Real::zero(),
        Real::zero(),
        Real::one(),
    ]));
    let one = DenseTensorPolynomial::try_new(vec![1], vec![Real::one()]).unwrap();
    let field = BezierRecursiveQuadraticField2::base(vec![source], one.clone(), one).unwrap();
    let BezierRecursiveQuadraticField2::Base(base) = &field else {
        unreachable!();
    };
    assert!(base.source_real_witnesses[0].is_none());
    let point = BezierRecursiveQuadraticProjectivePoint2 {
        x: recursive_quadratic_rational_value(
            base,
            DenseTensorPolynomial::try_new(vec![2], vec![Real::zero(), Real::one()]).unwrap(),
        )
        .unwrap(),
        y: field.constant(Real::from(-1_i8)).unwrap(),
        denominator: field.constant(Real::one()).unwrap(),
    };
    assert!(point.x.exact_real_value_with_retained_witnesses().is_none());
    for steps in [0, 4, 8, 32] {
        let Classification::Decided(bounds) = point.bounds_refined(steps) else {
            panic!("a missing scalar witness must retain selected-root refinement");
        };
        assert!(bounds.min().x() >= &Real::zero());
        assert!(bounds.max().x() <= &Real::one());
        assert!(bounds.min().x().clone().powi_i64(3).unwrap() <= half);
        assert!(bounds.max().x().clone().powi_i64(3).unwrap() >= half);
        assert_eq!(bounds.min().y(), &Real::from(-1_i8));
        assert_eq!(bounds.max().y(), &Real::from(-1_i8));
    }
    let zero_denominator = BezierRecursiveQuadraticProjectivePoint2 {
        x: field.constant(Real::one()).unwrap(),
        y: field.constant(Real::zero()).unwrap(),
        denominator: field.constant(Real::zero()).unwrap(),
    };
    assert!(matches!(
        zero_denominator.bounds_refined(0),
        Classification::Uncertain(_)
    ));
}

#[test]
fn recursive_scalar_native_replay_preserves_selected_source_authority() {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let source = bezier_parameter_root_representation(&algebraic_parameter(vec![
        -half,
        Real::zero(),
        Real::one(),
    ]));
    let value = Real::one()
        + Real::from(2_i8).sqrt().unwrap()
        + Real::from(3_i8).sqrt().unwrap()
        + Real::from(6_i8).sqrt().unwrap();
    let expected = ((&value + value.clone().sqrt().unwrap()) / Real::from(2_i8)).unwrap();
    for sources in [vec![], vec![source]] {
        let rank = sources.len();
        let constant =
            |value| DenseTensorPolynomial::try_new(vec![1; rank], vec![Real::from(value)]).unwrap();
        let field =
            BezierRecursiveQuadraticField2::base(sources, constant(2_i8), constant(3_i8)).unwrap();
        let BezierRecursiveQuadraticField2::Base(base) = &field else {
            unreachable!();
        };
        let value = BezierRecursiveQuadraticValue2::from_base(
            base.clone(),
            DenseTwoSquareRootExpression {
                rational: constant(1_i8),
                first: constant(1_i8),
                second: constant(1_i8),
                product: constant(1_i8),
            },
        )
        .unwrap();
        let extension = field.extension(value.clone()).unwrap();
        let scalar = BezierRecursiveQuadraticProjectiveScalar2 {
            numerator: extension
                .element(value, field.constant(Real::one()).unwrap())
                .unwrap(),
            denominator: extension.constant(Real::from(2_i8)).unwrap(),
        };
        assert!(
            scalar
                .numerator
                .exact_real_value_with_retained_witnesses()
                .is_some()
        );
        if rank == 0 {
            assert_eq!(scalar.exact_real_value(), Some(expected.clone()));
        } else {
            // Even an unused, witnessed axis retains its selected-root
            // publication path. Native coefficient replay is not license
            // to replace that parameter authority with an opaque scalar.
            assert!(scalar.exact_real_value().is_none());
        }
    }
}

#[test]
fn recursive_projective_content_normalization_preserves_selected_fields() {
    fn assert_witnesses_scaled(
        source: &BezierRecursiveQuadraticValue2,
        normalized: &BezierRecursiveQuadraticValue2,
        scale: &Real,
    ) {
        let cached = |value: &BezierRecursiveQuadraticValue2| match value.data.as_ref() {
            BezierRecursiveQuadraticValueData2::Base { real_witness, .. }
            | BezierRecursiveQuadraticValueData2::Extension { real_witness, .. } => {
                real_witness.get().cloned()
            }
        };
        match (cached(source), cached(normalized)) {
            (Some(source), Some(normalized)) => {
                assert_eq!(
                    (normalized - source * scale).zero_status(),
                    ZeroKnowledge::Zero
                );
            }
            (None, None) => {}
            (source, normalized) => {
                panic!(
                    "normalization must retain witness availability: {source:?} -> {normalized:?}"
                );
            }
        }
        if let (
            BezierRecursiveQuadraticValueData2::Extension {
                retained, radical, ..
            },
            BezierRecursiveQuadraticValueData2::Extension {
                retained: normalized_retained,
                radical: normalized_radical,
                ..
            },
        ) = (source.data.as_ref(), normalized.data.as_ref())
        {
            assert_witnesses_scaled(retained, normalized_retained, scale);
            assert_witnesses_scaled(radical, normalized_radical, scale);
        }
    }

    let source = bezier_parameter_root_representation(&algebraic_parameter(vec![
        (Real::from(-1_i8) / Real::from(2_i8)).unwrap(),
        Real::zero(),
        Real::one(),
    ]));
    let constant = |value| DenseTensorPolynomial::try_new(vec![1], vec![value]).unwrap();
    let field = BezierRecursiveQuadraticField2::base(
        vec![source],
        constant(Real::from(2_i8)),
        constant(Real::from(3_i8)),
    )
    .unwrap();
    let BezierRecursiveQuadraticField2::Base(base) = &field else {
        unreachable!();
    };
    let value = recursive_quadratic_pair_value(
        base,
        DenseTensorPolynomial::try_new(vec![2], vec![Real::from(2_i8), Real::one()]).unwrap(),
        constant(Real::one()),
        1,
    )
    .unwrap();
    let extension = field.extension(value.clone()).unwrap();
    let x = extension
        .element(value, field.constant(Real::one()).unwrap())
        .unwrap();
    let y = extension.constant(Real::from(-3_i8)).unwrap();
    let denominator = extension.constant(Real::one()).unwrap();
    let large = Real::from(2_i8).powi_i64(1024).unwrap() + Real::from(17_i8);
    for (scale, orientation) in [
        (large.clone(), Real::one()),
        ((Real::one() / &large).unwrap(), Real::one()),
        (-large.clone(), Real::from(-1_i8)),
    ] {
        for (count, warm) in [1, 3, 8, 17]
            .into_iter()
            .flat_map(|count| [(count, false), (count, true)])
        {
            let expected = [&x, &y, &denominator].into_iter().cycle().take(count);
            let mut normalized: Vec<_> = expected
                .clone()
                .map(|value| value.scale(&scale).unwrap())
                .collect();
            if warm {
                // A mixed tuple retains known witnesses without forcing
                // unused projections for its other values or descendants.
                for value in normalized.iter().step_by(2) {
                    assert!(value.exact_real_value_with_retained_witnesses().is_some());
                }
            }
            let original = normalized.clone();
            BezierRecursiveQuadraticValue2::normalize_positive_scale(&mut normalized);
            let positive_scale = (&orientation / &scale).unwrap();
            for (source, normalized) in original.iter().zip(&normalized) {
                assert_witnesses_scaled(source, normalized, &positive_scale);
            }
            for (actual, expected) in normalized.iter().zip(expected) {
                assert!(actual.field().same_field(&extension));
                assert!(actual.is_stored_equivalent_to(&expected.scale(&orientation).unwrap()));
            }
            let mut repeated = normalized.clone();
            BezierRecursiveQuadraticValue2::normalize_positive_scale(&mut repeated);
            for (first, second) in normalized.iter().zip(&repeated) {
                assert!(Arc::ptr_eq(&first.data, &second.data));
            }
        }
    }

    let wide_x = x.scale(&large).unwrap();
    let wide_denominator = denominator.scale(&large).unwrap();
    let mut shared = [wide_x.clone(), wide_x.clone(), wide_denominator];
    BezierRecursiveQuadraticValue2::normalize_positive_scale(&mut shared);
    assert!(Arc::ptr_eq(&shared[0].data, &shared[1].data));
    let opaque = extension.constant(Real::pi()).unwrap();
    let mut unnormalized = [wide_x.clone(), denominator.clone(), opaque.clone()];
    BezierRecursiveQuadraticValue2::normalize_positive_scale(&mut unnormalized);
    for (actual, expected) in unnormalized.iter().zip([&wide_x, &denominator, &opaque]) {
        assert!(Arc::ptr_eq(&actual.data, &expected.data));
    }
}

#[test]
fn recursive_scalar_publication_accepts_general_exact_witnesses() {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let source = bezier_parameter_root_representation(&algebraic_parameter(vec![
        -half.clone(),
        Real::zero(),
        Real::one(),
    ]));
    let constant = |value| DenseTensorPolynomial::try_new(vec![1], vec![value]).unwrap();
    let field = BezierRecursiveQuadraticField2::base(
        vec![source.clone()],
        constant(Real::from(3_i8)),
        constant(Real::one()),
    )
    .unwrap();
    let BezierRecursiveQuadraticField2::Base(base) = &field else {
        unreachable!();
    };
    let scalar = BezierRecursiveQuadraticProjectiveScalar2 {
        numerator: recursive_quadratic_pair_value(
            base,
            DenseTensorPolynomial::try_new(vec![2], vec![Real::pi(), Real::one()]).unwrap(),
            constant(Real::one()),
            1,
        )
        .unwrap(),
        denominator: field.constant(Real::one()).unwrap(),
    };
    assert!(scalar.exact_real_value().is_none());
    let Classification::Decided(root) = scalar.represented_value(&CurveContext::STRICT).unwrap()
    else {
        panic!("proved exact scalar witnesses must publish selected root evidence");
    };
    let expected = Real::pi() + half.sqrt().unwrap() + Real::from(3_i8).sqrt().unwrap();
    let witness = root.exact_point_witness().unwrap();
    assert_eq!(
        (witness - &expected).zero_status(),
        hyperreal::ZeroKnowledge::Zero,
    );
    assert_eq!(root.polynomial_coefficients.len(), 2);
    assert!(
        root.polynomial_coefficients[0]
            .exact_rational_ref()
            .is_none()
    );
    assert_eq!(base.sources, vec![source]);
    assert_eq!(
        hypersolve::validate_algebraic_root_representation(
            &root,
            hypersolve::PredicatePolicy::STRICT,
        )
        .status,
        hypersolve::AlgebraicRootValidationStatus::Valid,
    );
}

#[test]
fn recursive_bounds_refine_each_shared_source_once() {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let selected = high_degree_quadratic_selected_fiber_parameter_for_test(
        half.clone(),
        &CurveContext::STRICT,
    );
    let source = certified_parameter_representation(
        &selected.data.authority.data.retained_parameter,
        &CurveContext::STRICT,
    );
    let one = DenseTensorPolynomial::from_axis_polynomial(1, 0, &[Real::one()]).unwrap();
    let mut field =
        BezierRecursiveQuadraticField2::base(vec![source.clone()], one.clone(), one).unwrap();
    let BezierRecursiveQuadraticField2::Base(base) = &field else {
        unreachable!();
    };
    assert!(base.source_real_witnesses[0].is_none());
    let mut value = recursive_quadratic_rational_value(
        base,
        DenseTensorPolynomial::from_axis_polynomial(1, 0, &[Real::zero(), Real::one()]).unwrap(),
    )
    .unwrap();
    // The independent scalar oracle knows alpha=(1/2)^(1/65). The field
    // retains only its certified polynomial root. Every later value
    // reuses its predecessor both directly and under a positive radical.
    let mut expected = half.pow((Real::one() / Real::from(65)).unwrap()).unwrap();
    for depth in 1..=4 {
        let shift = Real::from(depth + 1);
        let radicand = value.add(&field.constant(shift.clone()).unwrap()).unwrap();
        let unit = field.constant(Real::one()).unwrap();
        field = field.extension(radicand).unwrap();
        value = field.element(value, unit).unwrap();
        expected = &expected + (&expected + shift).sqrt().unwrap();
        for steps in [4, 16, 64] {
            #[cfg(feature = "dispatch-trace")]
            hyperreal::dispatch_trace::reset();
            let evaluate = || value.interval_with_coefficient_precision(steps, Some(-128));
            #[cfg(feature = "dispatch-trace")]
            let interval = hyperreal::dispatch_trace::with_recording(evaluate);
            #[cfg(not(feature = "dispatch-trace"))]
            let interval = evaluate();
            let interval = interval.expect("the positive tower must retain finite bounds");
            #[cfg(feature = "dispatch-trace")]
            assert_eq!(
                hyperreal::dispatch_trace::take_trace().path_count(
                    "hypercurve",
                    "bezier-parameter-refinement",
                    "advance",
                ),
                u64::from(depth == 1),
                "depth={depth}, steps={steps}",
            );
            assert_eq!(
                compare_reals(&interval.lower, &expected, &CurveContext::STRICT),
                Some(std::cmp::Ordering::Less),
            );
            assert_eq!(
                compare_reals(&interval.upper, &expected, &CurveContext::STRICT),
                Some(std::cmp::Ordering::Greater),
            );
            // Each positive radical adds less than one to the derivative
            // with respect to its argument. Four levels amplify the
            // root width by less than 16; allow the certified square-root
            // rounding as well, without relying on an internal box shape.
            let maximum_width = Real::from(2_i8).powi_i64(5 - steps as i64).unwrap();
            assert_eq!(
                compare_reals(
                    &(interval.upper - interval.lower),
                    &maximum_width,
                    &CurveContext::STRICT,
                ),
                Some(std::cmp::Ordering::Less),
            );
            assert!(field.base_and_extension_path().0.sources == vec![source.clone()]);
        }
    }
    let (base, _) = field.base_and_extension_path();
    let refined = base.source_box(0);
    assert_eq!(refined, base.source_box(16));
    assert_eq!(refined, base.source_box(64));
    assert_eq!(
        refined[0].polynomial_coefficients,
        source.polynomial_coefficients,
    );
    assert_eq!(refined[0].symbol, source.symbol);
    assert_eq!(refined[0].constraint_index, source.constraint_index);
    assert_eq!(refined[0].interval_index, source.interval_index);
    assert_eq!(
        hypersolve::validate_algebraic_root_representation(
            &refined[0],
            hypersolve::PredicatePolicy::STRICT,
        )
        .status,
        hypersolve::AlgebraicRootValidationStatus::Valid,
    );
}

#[test]
fn recursive_source_refinement_keeps_its_equation_after_an_exact_midpoint() {
    let policy = CurveContext::STRICT;
    // This rational root lies beyond the compact witness proposal's
    // denominator range. Bisection discovers it in the native isolator.
    let expected = (Real::from(65_i8) / Real::from(128_i16)).unwrap();
    let selected = high_degree_quadratic_selected_fiber_parameter_for_test(
        expected.clone().powi_i64(65).unwrap(),
        &policy,
    );
    let source = certified_parameter_representation(
        &selected.data.authority.data.retained_parameter,
        &policy,
    );
    let one = DenseTensorPolynomial::from_axis_polynomial(1, 0, &[Real::one()]).unwrap();
    let field =
        BezierRecursiveQuadraticField2::base(vec![source.clone()], one.clone(), one).unwrap();
    let (base, _) = field.base_and_extension_path();
    assert!(base.source_real_witnesses[0].is_none());
    let refined = base.source_box(7);
    assert_eq!(refined[0].interval.exact_root, Some(expected));
    assert_eq!(refined[0].polynomial_coefficients.len(), 66);
    assert_eq!(
        refined[0].polynomial_coefficients,
        source.polynomial_coefficients,
    );
    assert_eq!(refined[0].constraint_index, source.constraint_index);
    assert_eq!(refined[0].symbol, source.symbol);
    assert_eq!(refined[0].interval_index, source.interval_index);
    assert_eq!(refined, base.source_box(0));
    assert_eq!(refined, base.source_box(32));
    assert_eq!(base.sources, vec![source]);
    assert_eq!(
        hypersolve::validate_algebraic_root_representation(
            &refined[0],
            hypersolve::PredicatePolicy::STRICT,
        )
        .status,
        hypersolve::AlgebraicRootValidationStatus::Valid,
    );
}

#[test]
fn recursive_sign_replays_correlated_real_witness_before_deep_intervals() {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let tiny = Real::from(2_i8).powi_i64(-256).unwrap();
    let source = bezier_parameter_root_representation(&algebraic_parameter(vec![
        -half.clone(),
        Real::zero(),
        Real::one(),
    ]));
    let constant = |value| DenseTensorPolynomial::try_new(vec![1], vec![value]).unwrap();
    let field =
        BezierRecursiveQuadraticField2::base(vec![source], constant(half), constant(Real::one()))
            .unwrap();
    let BezierRecursiveQuadraticField2::Base(base) = &field else {
        unreachable!()
    };
    assert!(base.source_real_witnesses[0].is_some());
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        for bounded in [false, true] {
            for (offset, expected) in [
                (tiny.clone(), RealSign::Positive),
                (-tiny.clone(), RealSign::Negative),
            ] {
                // alpha - sqrt(1/2) +/- 2^-256 has a compact exact sign.
                // Independent interval images lose that cancellation.
                let value = recursive_quadratic_pair_value(
                    base,
                    DenseTensorPolynomial::try_new(vec![2], vec![offset, Real::one()]).unwrap(),
                    constant(Real::one()),
                    -1,
                )
                .unwrap();
                assert!(value.bounded_interval_sign(0..=16).is_none());
                #[cfg(feature = "dispatch-trace")]
                hyperreal::dispatch_trace::reset();
                let evaluate = || {
                    crate::policy::resolve_certified_value(&policy, |attempt| {
                        if bounded {
                            attempt.bounded_exact_predicate_pass(|| value.sign(attempt))
                        } else {
                            value.sign(attempt)
                        }
                    })
                };
                #[cfg(feature = "dispatch-trace")]
                let result = hyperreal::dispatch_trace::with_recording(evaluate);
                #[cfg(not(feature = "dispatch-trace"))]
                let result = evaluate();
                assert_eq!(result.certainty, CurveCertainty::Certified);
                assert_eq!(result.value.unwrap(), Classification::Decided(expected));
                #[cfg(feature = "dispatch-trace")]
                assert!(
                    hyperreal::dispatch_trace::take_trace().path_count(
                        "hypercurve",
                        "recursive-quadratic-sign",
                        "compact-real-witness",
                    ) > 0
                );
            }
        }
    }
}

#[test]
fn recursive_real_witnesses_do_not_require_unused_selected_generators() {
    let parameter = algebraic_parameter(vec![
        Real::from(-1),
        Real::one(),
        Real::zero(),
        Real::zero(),
        Real::zero(),
        Real::one(),
    ]);
    let source = bezier_parameter_root_representation(&parameter);
    let one = DenseTensorPolynomial::from_axis_polynomial(1, 0, &[Real::one()]).unwrap();
    let coordinate =
        DenseTensorPolynomial::from_axis_polynomial(1, 0, &[Real::zero(), Real::one()]).unwrap();
    let field = BezierRecursiveQuadraticField2::base(vec![source.clone()], coordinate.clone(), one)
        .unwrap();
    let BezierRecursiveQuadraticField2::Base(base) = &field else {
        unreachable!()
    };
    assert!(base.source_real_witnesses[0].is_none());
    let active = recursive_quadratic_rational_value(base, coordinate).unwrap();
    assert!(active.exact_real_value_with_retained_witnesses().is_none());
    assert_eq!(
        active.sign(&CurveContext::STRICT).unwrap(),
        Classification::Decided(RealSign::Positive)
    );
    let extension = field.extension(active).unwrap();
    for field in [field, extension] {
        let value = field.constant(Real::pi()).unwrap();
        let cached = |value: &BezierRecursiveQuadraticValue2| match value.data.as_ref() {
            BezierRecursiveQuadraticValueData2::Base { real_witness, .. }
            | BezierRecursiveQuadraticValueData2::Extension { real_witness, .. } => {
                real_witness.get().cloned()
            }
        };
        assert!(cached(&value).is_none());
        assert_eq!(
            value.exact_real_value_with_retained_witnesses(),
            Some(Real::pi())
        );
        assert_eq!(cached(&value.clone()), Some(Real::pi()));
        let scalar = BezierRecursiveQuadraticProjectiveScalar2 {
            numerator: value,
            denominator: field.constant(Real::one()).unwrap(),
        };
        let Classification::Decided(root) =
            scalar.represented_value(&CurveContext::STRICT).unwrap()
        else {
            panic!("an unused selected axis must not prevent exact scalar publication");
        };
        assert_eq!(root.exact_point_witness(), Some(&Real::pi()));
        assert_eq!(
            hypersolve::validate_algebraic_root_representation(
                &root,
                hypersolve::PredicatePolicy::STRICT,
            )
            .status,
            hypersolve::AlgebraicRootValidationStatus::Valid
        );
        assert_eq!(
            field.base_and_extension_path().0.sources,
            vec![source.clone()]
        );
    }
}

#[test]
fn retained_real_witnesses_collapse_recursive_source_box_coefficients() {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let source_parameter = algebraic_parameter(vec![-half, Real::zero(), Real::one()]);
    let source = bezier_parameter_root_representation(&source_parameter);
    let one = DenseTensorPolynomial::from_axis_polynomial(1, 0, &[Real::one()])
        .expect("the recursive base must retain its unit");
    let two = DenseTensorPolynomial::from_axis_polynomial(1, 0, &[Real::from(2_i8)])
        .expect("the recursive base must retain its positive radicand");
    let coordinate =
        DenseTensorPolynomial::from_axis_polynomial(1, 0, &[Real::zero(), Real::one()])
            .expect("the recursive base must retain its selected coordinate");
    let field = BezierRecursiveQuadraticField2::base(vec![source.clone()], two, one.clone())
        .expect("the recursive base must construct");
    let BezierRecursiveQuadraticField2::Base(base) = field else {
        unreachable!("a recursive base begins at its base")
    };
    assert!(base.source_real_witnesses[0].is_some());
    let value = recursive_quadratic_pair_value(&base, coordinate, one, 1)
        .expect("the selected coordinate and positive root must embed");
    let exact = value
        .exact_real_value_with_retained_witnesses()
        .expect("the retained witnesses must evaluate the recursive value");
    let interval = value
        .interval_over_source_box_with_witnesses(&[source], Some(-64), true)
        .expect("the retained witnesses must enclose the recursive value");

    assert_eq!(interval.lower, exact);
    assert_eq!(interval.upper, exact);
}

#[test]
fn unused_positive_radicals_do_not_block_recursive_enclosures() {
    // 0 < 2^-600 < 1, so 1-cos(2^-600) is strictly positive, but
    // the ordinary scalar sign budget cannot separate it from zero.
    let tiny = Real::one() - Real::from(2_i8).powi_i64(-600).unwrap().cos();
    assert_eq!(tiny.zero_status(), ZeroKnowledge::Unknown);
    let unresolved = RealInterval {
        lower: tiny.clone(),
        upper: tiny.clone(),
    };
    assert!(unresolved.nonnegative_square_root(None).is_none());
    let scalar = |value| DenseTensorPolynomial::try_new(vec![], vec![value]).unwrap();
    let zero = scalar(Real::zero());
    let one = scalar(Real::one());
    for active in [None, Some(0), Some(1)] {
        let expression = DenseTwoSquareRootExpression {
            rational: one.clone(),
            first: if active == Some(0) {
                scalar(Real::from(2_i8))
            } else {
                zero.clone()
            },
            second: if active == Some(1) {
                scalar(Real::from(2_i8))
            } else {
                zero.clone()
            },
            product: zero.clone(),
        };
        let radicands = [0, 1].map(|index| {
            scalar(if active == Some(index) {
                Real::from(9_i8)
            } else {
                tiny.clone()
            })
        });
        let interval =
            dense_two_positive_square_root_interval(&expression, &radicands[0], &radicands[1], &[])
                .expect("only the used positive generators need enclosures");
        let expected = Real::from(if active.is_some() { 7_i8 } else { 1_i8 });
        assert!(interval.lower == expected && interval.upper == expected);
    }
    let base = BezierRecursiveQuadraticField2::base(vec![], one.clone(), one).unwrap();
    let field = base
        .extension(base.constant(tiny.clone()).unwrap())
        .unwrap();
    let value = field.constant(Real::from(7_i8)).unwrap();
    let interval = value.interval_with_coefficient_precision(0, None).unwrap();
    assert!(interval.lower == Real::from(7_i8) && interval.upper == Real::from(7_i8));
    let value = field
        .element(
            base.constant(Real::from(7_i8)).unwrap(),
            base.constant(tiny).unwrap(),
        )
        .unwrap();
    assert!(
        value.interval_with_coefficient_precision(0, None).is_none(),
        "an unresolved coefficient is not an exact zero coefficient"
    );
}

#[test]
fn coefficient_precision_uses_certified_dyadic_bounds_for_signed_surds() {
    let coefficient = Real::from(2_i8).sqrt().unwrap();
    assert_eq!(coefficient.immediate_sign(), Some(RealSign::Positive));
    assert!(coefficient.exact_rational_normal_form().is_none());
    let polynomial = DenseTensorPolynomial::try_new(vec![1], vec![coefficient.clone()]).unwrap();
    let interval =
        dense_tensor_interval_with_coefficient_precision(&polynomial, &[], Some(-64)).unwrap();

    assert!(interval.lower.exact_rational_normal_form().is_some());
    assert!(interval.upper.exact_rational_normal_form().is_some());
    assert_ne!(
        compare_reals(&interval.lower, &coefficient, &CurveContext::STRICT),
        Some(std::cmp::Ordering::Greater),
    );
    assert_ne!(
        compare_reals(&interval.upper, &coefficient, &CurveContext::STRICT),
        Some(std::cmp::Ordering::Less),
    );
    assert_eq!(
        dense_strict_interval_sign(&interval),
        Some(RealSign::Positive)
    );

    // A dyadic coefficient enclosure alone is insufficient when an axis
    // carries a nondyadic chart bound or an exact surd witness. Check the
    // independent polynomial 1 + x + x^2 on both signed point axes and a
    // nontrivial interval where it is strictly increasing.
    let polynomial =
        DenseTensorPolynomial::try_new(vec![3, 1], vec![Real::one(), Real::one(), Real::one()])
            .unwrap();
    let third = (Real::one() / Real::from(3_i8)).unwrap();
    let enclose = |interval: &RealInterval, lower: &Real, upper: &Real| {
        assert!(interval.lower.exact_rational_ref().unwrap().is_dyadic());
        assert!(interval.upper.exact_rational_ref().unwrap().is_dyadic());
        assert!(matches!(
            compare_reals(&interval.lower, lower, &CurveContext::STRICT),
            Some(std::cmp::Ordering::Less | std::cmp::Ordering::Equal)
        ));
        assert!(matches!(
            compare_reals(&interval.upper, upper, &CurveContext::STRICT),
            Some(std::cmp::Ordering::Greater | std::cmp::Ordering::Equal)
        ));
    };
    let expected = |value: &Real| Real::one() + value + value * value;
    for value in [third.clone(), -third.clone(), coefficient] {
        let source = bezier_parameter_root_representation(&BezierParameter2::Exact(value.clone()));
        let witnesses = [Some(value.clone())];
        for source_witnesses in [None, Some(witnesses.as_slice())] {
            let interval = dense_tensor_interval_with_coefficient_precision_and_source_witnesses(
                &polynomial,
                std::slice::from_ref(&source),
                source_witnesses,
                Some(-64),
            )
            .unwrap();
            enclose(&interval, &expected(&value), &expected(&value));
            let exact = dense_tensor_interval_with_coefficient_precision_and_source_witnesses(
                &polynomial,
                std::slice::from_ref(&source),
                source_witnesses,
                None,
            )
            .unwrap();
            assert!(
                exact.lower == exact.upper,
                "unrounded point axes stay exact points"
            );
            if value.exact_rational_ref().is_some() {
                assert!(exact.lower == expected(&value));
            } else {
                // Real equality compares symbolic construction. Horner's
                // (sqrt(2)+1)*sqrt(2)+1 need not have the same structure as
                // the independent enclosure oracle sqrt(2)+3 above.
                assert!(exact.lower.exact_rational_ref().is_none());
            }
        }
    }
    let mut source = bezier_parameter_root_representation(&BezierParameter2::Exact(
        (Real::one() / Real::from(2_i8)).unwrap(),
    ));
    source.interval.lower = third.clone();
    source.interval.upper = Real::from(2_i8) * third;
    let interval = dense_tensor_interval_with_coefficient_precision(
        &polynomial,
        std::slice::from_ref(&source),
        Some(-64),
    )
    .unwrap();
    enclose(
        &interval,
        &expected(&source.interval.lower),
        &expected(&source.interval.upper),
    );
    // The generator enclosure must remain dyadic even when the square
    // root itself has a rational scale with an odd denominator.
    for squared in [
        (Real::one() / Real::from(9_i8)).unwrap(),
        (Real::from(2_i8) / Real::from(9_i8)).unwrap(),
    ] {
        let expected = squared.clone().sqrt().unwrap();
        let interval = RealInterval {
            lower: squared.clone(),
            upper: squared,
        }
        .nonnegative_square_root(Some(-64))
        .unwrap();
        enclose(&interval, &expected, &expected);
    }
}

#[test]
fn selected_zero_distance_source_axis_order_stays_in_its_correlated_field() {
    let source = QuadraticBezier2::from_line_segment(
        LineSeg2::try_new(Point2::from_values(0, 0), Point2::from_values(1, 0)).unwrap(),
    );
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let selected = degree_nine_selected_fiber_parameter_for_test(
            (Real::one() / Real::from(2_i8)).unwrap(),
            1,
            &policy,
        );
        let ordinary =
            BezierParameter2::Algebraic(selected.data.authority.data.retained_parameter.clone());
        let parallel = BezierParallel2::from_source(
            BezierParallelSource2::Quadratic(source.clone()),
            Real::zero(),
        );
        let selected_point = CurvePoint2::from(BezierAnalyticParallelPoint2::new_selected_fiber(
            parallel.clone(),
            selected,
            &policy,
        ));
        let ordinary_point = CurvePoint2::from(BezierAnalyticParallelPoint2::new(
            parallel, ordinary, &policy,
        ));

        #[cfg(feature = "dispatch-trace")]
        hyperreal::dispatch_trace::reset();
        let compare_x = || {
            algebraic_chord_point_coordinate_order(
                &selected_point,
                &ordinary_point,
                Axis2::X,
                &policy,
            )
        };
        #[cfg(feature = "dispatch-trace")]
        let x_order = hyperreal::dispatch_trace::with_recording(compare_x);
        #[cfg(not(feature = "dispatch-trace"))]
        let x_order = compare_x();
        #[cfg(feature = "dispatch-trace")]
        let trace = hyperreal::dispatch_trace::take_trace();
        assert_eq!(
            x_order.unwrap(),
            Classification::Decided(std::cmp::Ordering::Greater),
        );
        assert_eq!(
            algebraic_chord_point_coordinate_order(
                &selected_point,
                &ordinary_point,
                Axis2::Y,
                &policy,
            )
            .unwrap(),
            Classification::Decided(std::cmp::Ordering::Equal),
        );
        #[cfg(feature = "dispatch-trace")]
        assert!(
            trace.path_count(
                "hypercurve",
                "algebraic-chord-point-axis-order",
                "same-zero-distance-selected-source",
            ) > 0,
            "the selected/ordinary comparison must retain its correlated field: {trace:?}",
        );
    }
}

#[test]
fn quadratic_affine_root_signs_cover_exact_branch_configurations() {
    use RealSign::{Negative, Positive, Zero};

    assert_eq!(
        quadratic_affine_root_signs(Negative, Positive, Positive, Positive),
        None
    );
    assert_eq!(
        quadratic_affine_root_signs(Zero, Zero, Negative, Zero),
        Some([Negative; 2])
    );
    assert_eq!(
        quadratic_affine_root_signs(Positive, Positive, Negative, Zero),
        Some([Negative; 2])
    );
    assert_eq!(
        quadratic_affine_root_signs(Positive, Positive, Positive, Zero),
        Some([Positive; 2])
    );
    assert_eq!(
        quadratic_affine_root_signs(Positive, Negative, Zero, Positive),
        Some([Negative, Positive])
    );
    assert_eq!(
        quadratic_affine_root_signs(Positive, Negative, Zero, Negative),
        Some([Positive, Negative])
    );
    assert_eq!(
        quadratic_affine_root_signs(Positive, Zero, Negative, Positive),
        Some([Negative, Zero])
    );
    assert_eq!(
        quadratic_affine_root_signs(Positive, Zero, Positive, Positive),
        Some([Zero, Positive])
    );
    assert_eq!(
        quadratic_affine_root_signs(Positive, Zero, Negative, Negative),
        Some([Zero, Negative])
    );
    assert_eq!(
        quadratic_affine_root_signs(Positive, Zero, Positive, Negative),
        Some([Positive, Zero])
    );
    assert_eq!(
        quadratic_affine_root_signs(Positive, Zero, Zero, Zero),
        Some([Zero; 2])
    );
}

#[test]
fn recursive_circle_contact_tangent_sign_follows_root_branch() {
    use RealSign::{Negative, Positive, Zero};

    assert_eq!(
        recursive_circle_contact_tangent_cross_sign(-1, Positive),
        Positive
    );
    assert_eq!(
        recursive_circle_contact_tangent_cross_sign(0, Positive),
        Zero
    );
    assert_eq!(
        recursive_circle_contact_tangent_cross_sign(1, Positive),
        Negative
    );
    assert_eq!(
        recursive_circle_contact_tangent_cross_sign(-1, Negative),
        Negative
    );
    assert_eq!(
        recursive_circle_contact_tangent_cross_sign(1, Negative),
        Positive
    );
}

#[test]
fn retained_chord_rejects_collinear_winding_rays_outside_its_finite_extent() {
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let Classification::Decided(chord) = BezierAlgebraicChord2::try_new(
            CurvePoint2::from(Point2::from_values(-2, 0)),
            CurvePoint2::from(Point2::from_values(-1, 0)),
            &policy,
        )
        .unwrap() else {
            panic!("an exact nonzero chord must construct");
        };
        let origin = Point2::from_values(0, 0);
        for direction_x in [-Real::one(), Real::one()] {
            assert_eq!(
                chord
                    .forward_ray_winding_delta(&origin, &direction_x, &Real::zero(), &policy,)
                    .unwrap(),
                Classification::Uncertain(UncertaintyReason::Predicate),
            );
        }
        assert_eq!(
            chord
                .forward_ray_winding_delta(&origin, &Real::zero(), &Real::one(), &policy,)
                .unwrap(),
            Classification::Decided(0),
        );
    }
}

#[test]
fn exact_radial_chord_replays_a_retained_circle_endpoint_contact() {
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let arc = CircularArc2::try_from_center(
            Point2::from_values(2, 0),
            Point2::from_values(0, 2),
            Point2::from_values(0, 0),
            false,
        )
        .unwrap();
        let Classification::Decided(decomposition) = arc
            .rational_bezier_decomposition_with_policy(&policy)
            .unwrap()
        else {
            panic!("an exact quarter circle must decompose");
        };
        let [span] = decomposition.spans() else {
            panic!("an exact quarter circle must have one rational span");
        };
        let source = RationalBezier2::from(span.curve().clone());
        let Classification::Decided(chord) = BezierAlgebraicChord2::try_new(
            CurvePoint2::from(Point2::from_values(0, 0)),
            CurvePoint2::from(Point2::from_values(0, 2)),
            &policy,
        )
        .unwrap() else {
            panic!("an exact radial chord must construct");
        };
        let support_witness =
            LineSeg2::try_new(Point2::from_values(0, 0), Point2::from_values(0, 1))
                .expect("valid short support witness");
        let Classification::Decided(BezierAlgebraicChordRationalIntersections2::Contacts(
            witness_contacts,
        )) = chord
            .exact_line_retained_circle_intersections(&support_witness, &source, None, &policy)
            .unwrap()
            .expect("the retained circle path applies")
        else {
            panic!("a short support witness must retain its external circle contact");
        };
        assert_eq!(witness_contacts.len(), 1);
        assert!(matches!(
            witness_contacts[0].point(),
            CurvePoint2(CurvePointData2::Exact(point))
                if point == &Point2::from_values(0, 2)
        ));
        let Classification::Decided(BezierAlgebraicChordRationalIntersections2::Contacts(contacts)) =
            chord
                .rational_intersections(&source, &CurveParameterRange2::unit(), None, &policy)
                .unwrap()
        else {
            panic!("the radial chord contact must be decided");
        };
        let [contact] = contacts.as_slice() else {
            panic!("the finite radial chord must retain one circle contact");
        };
        assert_eq!(contact.tangent_cross_sign(), RealSign::Positive);
        assert_eq!(
            contact
                .chord_parameter()
                .cmp_by_refinement(&chord.end_parameter(), &policy)
                .unwrap(),
            Classification::Decided(std::cmp::Ordering::Equal),
        );
        assert_eq!(contact.other_parameter().scalar(), Some(&Real::one()));
        assert!(matches!(
            contact.point(),
            CurvePoint2(CurvePointData2::Exact(point))
                if point == &Point2::from_values(0, 2)
        ));

        let excluded = CurveParameter2::from(BezierParameter2::Exact(Real::one()));
        let Classification::Decided(BezierAlgebraicChordRationalIntersections2::Contacts(
            excluded_contacts,
        )) = chord
            .rational_intersections(
                &source,
                &CurveParameterRange2::unit(),
                Some(&excluded),
                &policy,
            )
            .unwrap()
        else {
            panic!("excluding the authored endpoint must remain decided");
        };
        assert!(excluded_contacts.is_empty());
    }
}

#[test]
fn nonuniform_rational_cusp_parallel_intersects_round_join_quarter() {
    let third = (Real::one() / Real::from(3_i8)).unwrap();
    let two_thirds = &third * Real::from(2_i8);
    let quarter = (Real::one() / Real::from(4_i8)).unwrap();
    let source = RationalBezier2::try_new(
        vec![
            Point2::from_values(1, -1),
            Point2::new(-third.clone(), Real::one()),
            Point2::new(-third, -Real::one()),
            Point2::from_values(1, 1),
        ],
        vec![
            Real::from(8_i8),
            Real::from(4_i8),
            Real::from(2_i8),
            Real::one(),
        ],
    )
    .unwrap();
    let parallel =
        BezierParallel2::from_source(BezierParallelSource2::Rational(source), quarter.clone());
    let range = BezierParameterRange2::new_validated(
        BezierParameter2::Exact(two_thirds.clone()),
        BezierParameter2::Exact(Real::one()),
    );
    let center = Point2::from_values(0, 0);
    let arc = CircularArc2::try_from_center(
        Point2::new(-quarter.clone(), Real::zero()),
        Point2::new(Real::zero(), quarter.clone()),
        center.clone(),
        true,
    )
    .unwrap();
    let Classification::Decided(decomposition) = arc
        .rational_bezier_decomposition_with_policy(&CurveContext::STRICT)
        .unwrap()
    else {
        panic!("an exact quarter circle must decompose");
    };
    let [span] = decomposition.spans() else {
        panic!("a quarter circle must have one rational-quadratic span");
    };
    let base = span.curve().clone();
    let circle = Arc::new(crate::rational_bezier::RationalQuadraticCircle2 {
        center,
        radius_squared: &quarter * &quarter,
        tangent_contacts: Some(Arc::from([
            crate::rational_bezier::RationalQuadraticCircleTangentContact2::Parallel(
                crate::rational_bezier::RationalQuadraticParallelCircleContact2 {
                    parallel: parallel.clone(),
                    parameter: two_thirds.clone(),
                    point: Point2::new(Real::zero(), quarter),
                    eliminant_root_multiplicity: 3,
                },
            ),
        ])),
    });
    let curve: RationalBezier2 = base
        .clone()
        .with_retained_conic_provenance(
            base.retained_implicit_quadratic_conic().cloned(),
            Some(circle),
        )
        .into();

    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let result = parallel
            .intersections_on_regular_range(
                &curve,
                &CurveParameterRange2::from_bezier_range(range.clone()),
                &policy,
            )
            .unwrap();
        let Classification::Decided(result) = result else {
            panic!("the retained cusp/quarter-circle intersection must decide");
        };
        assert!(
            result.is_complete(),
            "the retained cusp/quarter-circle intersection must complete"
        );
        assert!(!result.contacts().is_empty());

        // The same rational circle can arrive as a zero-distance parallel
        // after a retained cut. It must keep the exact rational route,
        // while the nonuniform source keeps its one-sided cusp frame.
        let rational_parallel = BezierParallel2::from_source(
            BezierParallelSource2::Rational(curve.clone()),
            Real::zero(),
        );
        let unit = BezierParameterRange2::from_exact(Real::zero(), Real::one());
        for swapped in [false, true] {
            let pair = if swapped {
                rational_parallel.parallel_intersections_on_regular_ranges(
                    &parallel,
                    &CurveParameterRange2::from_bezier_range(unit.clone()),
                    &CurveParameterRange2::from_bezier_range(range.clone()),
                    &policy,
                )
            } else {
                parallel.parallel_intersections_on_regular_ranges(
                    &rational_parallel,
                    &CurveParameterRange2::from_bezier_range(range.clone()),
                    &CurveParameterRange2::from_bezier_range(unit.clone()),
                    &policy,
                )
            }
            .unwrap();
            let Classification::Decided(pair) = pair else {
                panic!("zero-distance rational authority must retain the cusp branch")
            };
            assert!(pair.is_complete());
            assert_eq!(pair.contacts().len(), result.contacts().len());
            assert!(pair.contacts().iter().any(|contact| {
                let (source, circle) = if swapped {
                    (contact.second_parameter(), contact.first_parameter())
                } else {
                    (contact.first_parameter(), contact.second_parameter())
                };
                source.scalar() == Some(&two_thirds) && circle.scalar() == Some(&Real::one())
            }));
        }
    }
}

#[test]
fn finite_domain_admits_one_sided_source_cusp_contacts() {
    let third = (Real::one() / Real::from(3_i8)).unwrap();
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let source = CubicBezier2::new(
        Point2::from_values(1, -1),
        Point2::new(-third.clone(), Real::one()),
        Point2::new(-third, -Real::one()),
        Point2::from_values(1, 1),
    );
    let parallel = source
        .parallel_left(-(Real::one() / Real::from(4_i8)).unwrap())
        .unwrap();
    let before = CurveParameterRange2::from_bezier_range(BezierParameterRange2::new_validated(
        BezierParameter2::Exact(Real::zero()),
        BezierParameter2::Exact(half.clone()),
    ));
    let after = CurveParameterRange2::from_bezier_range(BezierParameterRange2::new_validated(
        BezierParameter2::Exact(half.clone()),
        BezierParameter2::Exact(Real::one()),
    ));
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let regular = match parallel
            .parallel_intersections_on_regular_ranges(&parallel, &before, &after, &policy)
            .unwrap()
        {
            Classification::Decided(result) => result,
            Classification::Uncertain(reason) => {
                panic!("one-sided regular sheets remained uncertain: {reason:?}")
            }
        };
        let domain = match parallel
            .parallel_intersections_in_domain(
                &parallel,
                [
                    CurveParameterDomain2::new(&before, None),
                    CurveParameterDomain2::new(&after, None),
                ],
                ParameterComponentQuery2::RetainFinite,
                &policy,
            )
            .unwrap()
        {
            Classification::Decided(result) => result,
            Classification::Uncertain(reason) => {
                panic!("one-sided domain contacts remained uncertain: {reason:?}")
            }
        };
        let (domain, retained_components) = domain.into_parts();
        let positive_dimensional = !retained_components.is_empty();
        assert!(!positive_dimensional);
        assert!(
            domain.is_complete(),
            "finite domain evidence was incomplete or inconsistent"
        );
        assert_eq!(domain.contacts().len(), regular.contacts().len());
        assert!(
            domain.contacts().iter().any(|contact| {
                overlap_parameter_is_in_range(
                    contact.first_parameter(),
                    &BezierParameterRange2::new_validated(
                        BezierParameter2::Exact(Real::zero()),
                        BezierParameter2::Exact(half.clone()),
                    ),
                    true,
                    &policy,
                ) == Ok(Classification::Decided(true))
                    && overlap_parameter_is_in_range(
                        contact.second_parameter(),
                        &BezierParameterRange2::new_validated(
                            BezierParameter2::Exact(half.clone()),
                            BezierParameter2::Exact(Real::one()),
                        ),
                        true,
                        &policy,
                    ) == Ok(Classification::Decided(true))
            }),
            "finite domain evidence was incomplete or inconsistent"
        );
        let limit = match parallel
            .regular_source_point_and_tangent_support(
                &parallel,
                &CurveParameter2::from(half.clone()),
                &before,
                RealSign::Positive,
                &policy,
            )
            .unwrap()
        {
            Classification::Decided(limit) => limit,
            Classification::Uncertain(reason) => {
                panic!("one-sided cusp limit remained uncertain: {reason:?}")
            }
        };
        assert!(
            limit.1.start().same_point(limit.1.end(), &policy) != Classification::Decided(true)
        );
        let interior =
            CurveParameterRange2::from_bezier_range(BezierParameterRange2::new_validated(
                BezierParameter2::Exact((Real::one() / Real::from(4_i8)).unwrap()),
                BezierParameter2::Exact((Real::from(3_i8) / Real::from(4_i8)).unwrap()),
            ));
        let interior_cusp = parallel
            .parallel_intersections_in_domain(
                &parallel,
                [
                    CurveParameterDomain2::new(&interior, None),
                    CurveParameterDomain2::new(&interior, None),
                ],
                ParameterComponentQuery2::RetainFinite,
                &policy,
            )
            .unwrap();
        assert!(
            matches!(
                interior_cusp,
                Classification::Uncertain(UncertaintyReason::Boundary)
            ),
            "an open interior source cusp is not a one-sided frame"
        );

        // Component queries retain separate parameter intervals instead
        // of attaching one frame to the whole range. Both regular sheets
        // survive, while their undefined shared source parameter does not.
        let components = match parallel
            .parallel_intersections_in_domain(
                &parallel,
                [CurveParameterDomain2::new(&interior, None); 2],
                ParameterComponentQuery2::AllComponents(None),
                &policy,
            )
            .unwrap()
        {
            Classification::Decided(result) => result,
            Classification::Uncertain(reason) => {
                panic!("the separate pointwise components must decide: {reason:?}")
            }
        };
        let (intersections, components) = components.into_parts();
        assert!(intersections.is_complete());
        assert!(!components.is_empty());
        for numerator in [3_i8, 4, 5] {
            let parameter =
                CurveParameter2::from((Real::from(numerator) / Real::from(8_i8)).unwrap());
            let mut owners = 0;
            for component in &components {
                match component
                    .constrain([Some(&parameter), None], &policy)
                    .unwrap()
                {
                    Classification::Decided(CurveParameterComponentSelection2::Empty) => {}
                    Classification::Decided(CurveParameterComponentSelection2::Selected(pair)) => {
                        owners += 1;
                        for selected in pair {
                            assert_eq!(
                                selected.same_value(&parameter, &policy).unwrap(),
                                Classification::Decided(true),
                            );
                        }
                    }
                    _ => panic!("one exact contact must decide each component's owner"),
                }
            }
            assert_eq!(owners, usize::from(numerator != 4));
        }
    }
}

#[test]
fn odd_source_cusp_branches_do_not_saturate_a_false_source_diagonal() {
    // P(u)=((2u-1)^2,(2u-1)^3) has opposite one-sided normal sheets at
    // u=1/2. The two retained branches come from the same parallel object,
    // but its ordinary source diagonal is not a component of the
    // branch-oriented pair system. The branches meet only at isolated
    // off-diagonal parameters.
    let third = (Real::one() / Real::from(3_i8)).unwrap();
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let source = CubicBezier2::new(
        Point2::from_values(1, -1),
        Point2::new(-third.clone(), Real::one()),
        Point2::new(-third, -Real::one()),
        Point2::from_values(1, 1),
    );
    let parallel = source
        .parallel_left(-(Real::one() / Real::from(4_i8)).unwrap())
        .unwrap();
    let before = BezierParameterRange2::new_validated(
        BezierParameter2::Exact(Real::zero()),
        BezierParameter2::Exact(half.clone()),
    );
    let after = BezierParameterRange2::new_validated(
        BezierParameter2::Exact(half),
        BezierParameter2::Exact(Real::one()),
    );

    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let result = match parallel
            .parallel_intersections_on_regular_ranges(
                &parallel,
                &CurveParameterRange2::from_bezier_range(before.clone()),
                &CurveParameterRange2::from_bezier_range(after.clone()),
                &policy,
            )
            .unwrap()
        {
            Classification::Decided(result) => result,
            Classification::Uncertain(reason) => {
                panic!("opposite source sheets remained uncertain: {reason:?}")
            }
        };
        assert!(
            result.is_complete(),
            "regular pair evidence was incomplete or inconsistent"
        );
        assert!(
            result.overlaps().is_empty(),
            "regular pair evidence was incomplete or inconsistent"
        );
        assert!(
            result.contacts().iter().any(|contact| {
                overlap_parameter_is_in_range(contact.first_parameter(), &before, true, &policy)
                    == Ok(Classification::Decided(true))
                    && overlap_parameter_is_in_range(
                        contact.second_parameter(),
                        &after,
                        true,
                        &policy,
                    ) == Ok(Classification::Decided(true))
            }),
            "regular pair evidence was incomplete or inconsistent"
        );
    }
}

#[test]
fn rational_parallel_endpoint_uses_transverse_tangent_before_exterior_germs() {
    let policy = CurveContext::STRICT;
    let source = RationalBezier2::try_new(
        vec![
            Point2::from_values(0, 0),
            Point2::from_values(2, 3),
            Point2::from_values(4, 0),
        ],
        vec![Real::one(), Real::from(2_i8), Real::one()],
    )
    .unwrap();
    let parallel = BezierParallel2::from_source(
        BezierParallelSource2::Rational(source),
        (Real::one() / Real::from(10_i8)).unwrap(),
    );
    let endpoint = match parallel.point_at(&Real::one(), &policy).unwrap() {
        Classification::Decided(point) => point,
        Classification::Uncertain(reason) => panic!("parallel endpoint: {reason:?}"),
    };
    let normal_line = LineSeg2::try_new(
        endpoint.clone(),
        endpoint.translated(Real::from(3_i8), Real::from(2_i8)),
    )
    .unwrap();
    let Classification::Decided(parallel) = crate::Curve2::try_analytic_parallel(
        parallel,
        BezierParameterRange2::from_exact(Real::zero(), Real::one()),
        &policy,
    )
    .unwrap() else {
        panic!("the regular parallel is admitted");
    };
    let evidence = parallel
        .intersect_curve(&crate::Curve2::from(normal_line), &policy)
        .unwrap()
        .value;
    assert!(evidence.is_complete());
    let contact = evidence
        .contacts()
        .iter()
        .find(|contact| contact.first().local_parameter().scalar() == Some(&Real::one()))
        .expect("the exact endpoint contact must be retained");
    assert!(contact.is_certified_transverse());
}

fn algebraic_parameters(coefficients: Vec<Real>) -> Vec<BezierParameter2> {
    let polynomial =
        match BezierParameterPolynomial::try_new_power_basis(coefficients, &CurveContext::STRICT)
            .unwrap()
        {
            Classification::Decided(polynomial) => polynomial,
            Classification::Uncertain(reason) => panic!("parameter polynomial: {reason:?}"),
        };
    let parameters = match polynomial
        .isolate_unit_interval_roots(&CurveContext::STRICT)
        .unwrap()
    {
        Classification::Decided(parameters) => parameters,
        Classification::Uncertain(reason) => panic!("parameter isolation: {reason:?}"),
    };
    assert!(
        parameters
            .iter()
            .all(|parameter| matches!(parameter, BezierParameter2::Algebraic(_)))
    );
    parameters
}

fn algebraic_parameter(coefficients: Vec<Real>) -> BezierParameter2 {
    let parameters = algebraic_parameters(coefficients);
    let [parameter] = parameters.as_slice() else {
        panic!("expected one unit-interval algebraic parameter");
    };
    parameter.clone()
}

fn general_analytic_circle_overlap(
    policy: &CurveContext,
) -> (
    BezierAlgebraicCuspSemicircle2,
    BezierParallel2,
    BezierAlgebraicCuspSemicircleMappedOverlap2,
) {
    let semicircle = synthetic_reducible_cusp_semicircle((3, 4), ((2, 3), (4, 5)), policy);
    let source = RationalBezier2::from(
        RationalQuadraticBezier2::try_new(
            Point2::new(Real::from(2_i8), Real::zero()),
            Point2::new(Real::from(2_i8), Real::from(2_i8)),
            Point2::new(Real::zero(), Real::from(2_i8)),
            Real::one(),
            Real::one(),
            Real::from(2_i8),
        )
        .unwrap(),
    );
    let parallel = source.parallel_left(Real::one()).unwrap();
    assert!(parallel.data.certified_ph_offset.set(None).is_ok());
    let Classification::Decided(BezierAlgebraicCuspSemicircleParallelIntersections2::Mapped {
        overlaps,
        contacts: unexpected_contacts,
    }) = semicircle
        .parallel_intersections(&parallel, &CurveParameterRange2::unit(), None, policy)
        .unwrap()
    else {
        panic!("the analytic quarter must overlap the selected circle");
    };
    assert!(unexpected_contacts.is_empty(), "unexpected contacts");
    let [overlap] = overlaps.as_slice() else {
        panic!("the analytic quarter must retain one overlap cell");
    };
    (semicircle, parallel, overlap.clone())
}

#[test]
fn mapped_overlap_retains_distinct_selected_inverse_keys_and_rebuilds_expired_values() {
    let BezierParameter2::Algebraic(retained_parameter) = algebraic_parameter(vec![
        (Real::from(-1_i8) / Real::from(2_i8)).unwrap(),
        Real::zero(),
        Real::one(),
    ]) else {
        panic!("the selected base parameter must be algebraic");
    };
    let values = [
        (Real::one() / Real::from(3_i8)).unwrap(),
        (Real::from(2_i8) / Real::from(3_i8)).unwrap(),
    ];

    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let (_, _, overlap) = general_analytic_circle_overlap(&policy);
        let selected = values.clone().map(|value| {
            CurveParameter2::from_selected_fiber(exact_selected_fiber_parameter_for_test(
                retained_parameter.clone(),
                value,
                &policy,
            ))
        });

        {
            let source = values.clone().map(|value| {
                let Classification::Decided(parameter) = overlap
                    .cusp_parameter_for_other(
                        &region_parameter(BezierParameter2::Exact(value)),
                        &policy,
                    )
                    .unwrap()
                else {
                    panic!("an interior analytic cut must remain mapped");
                };
                parameter
            });
            for (target, source) in selected.iter().zip(&source) {
                overlap.retain_inverse_authority(
                    &Classification::Decided(target.clone()),
                    source,
                    &policy,
                );
            }
            for (target, source) in selected.iter().zip(&source) {
                let Classification::Decided(replayed) =
                    overlap.cusp_parameter_for_other(target, &policy).unwrap()
                else {
                    panic!("a retained selected-fiber inverse must replay");
                };
                assert!(replayed.shares_exact_evidence(source));
            }
        }

        for (target, value) in selected.iter().zip(&values) {
            let rebuilt = crate::policy::resolve_certified_operation(&policy, |attempt| {
                overlap.cusp_parameter_for_other(target, attempt)
            })
            .unwrap();
            assert_eq!(rebuilt.certainty, CurveCertainty::Certified);
            let Classification::Decided(rebuilt) = rebuilt.value else {
                panic!("an expired selected-fiber inverse must rebuild exactly");
            };
            let Classification::Decided(expected) = overlap
                .cusp_parameter_for_other(
                    &region_parameter(BezierParameter2::Exact(value.clone())),
                    &policy,
                )
                .unwrap()
            else {
                panic!("the corresponding ordinary cut must remain mapped");
            };
            assert_eq!(
                rebuilt.scalar_value(&policy).unwrap(),
                expected.scalar_value(&policy).unwrap(),
            );
        }
    }
}

fn selected_fiber_rational_quarter(
    exact_center: bool,
    policy: &CurveContext,
) -> (BezierAlgebraicCuspSemicircle2, RationalBezier2) {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let support = QuadraticBezier2::new(
        Point2::from_values(0, 0),
        Point2::new(half.clone(), Real::zero()),
        Point2::from_values(if exact_center { 1 } else { 2 }, 0),
    )
    .parallel_left(Real::zero())
    .unwrap();
    let quarter = RationalBezier2::from(
        RationalQuadraticBezier2::try_new(
            Point2::new(half.clone(), Real::one()),
            Point2::new(-half.clone(), Real::one()),
            Point2::new(-half.clone(), Real::zero()),
            Real::one(),
            Real::one(),
            Real::from(2_i8),
        )
        .unwrap(),
    );
    let Classification::Decided(polynomial) = BezierParameterPolynomial::try_new_power_basis(
        if exact_center {
            vec![-half.clone(), Real::one()]
        } else {
            vec![-half.clone(), Real::one(), Real::one()]
        },
        policy,
    )
    .unwrap() else {
        panic!("the selected-center polynomial must construct");
    };
    let Classification::Decided(interval) =
        BezierParameterInterval::try_new(Real::zero(), Real::one(), policy).unwrap()
    else {
        panic!("the selected-center interval must construct");
    };
    let Classification::Decided(center_parameter) =
        BezierAlgebraicParameter2::try_isolate(polynomial, interval, policy).unwrap()
    else {
        panic!("the selected center must isolate");
    };
    if exact_center {
        assert_eq!(
            BezierParameter2::Algebraic(center_parameter.clone())
                .refined_isolating_interval(64, &CurveContext::STRICT),
            BezierParameter2::Exact(half),
        );
    }
    let Classification::Decided(Some(circle)) =
        BezierAlgebraicCuspSemicircle2::from_selected_parallel_normal(
            support,
            BezierParameter2::Algebraic(center_parameter).into(),
            Real::one(),
            false,
            policy,
        )
        .unwrap()
    else {
        panic!("the algebraic selected circle must construct");
    };
    (circle, quarter)
}

fn selected_fiber_rational_quarter_overlap(
    policy: &CurveContext,
) -> (
    BezierAlgebraicCuspSemicircle2,
    RationalBezier2,
    BezierAlgebraicCuspSemicircleSelectedFiberRationalOverlap2,
) {
    let (circle, quarter) = selected_fiber_rational_quarter(false, policy);
    let Classification::Decided(
        BezierAlgebraicCuspSemicircleRationalIntersections2::SelectedFiber {
            overlaps,
            contacts: unexpected_contacts,
        },
    ) = circle
        .rational_intersections(&quarter, &crate::CurveParameterRange2::unit(), policy)
        .unwrap()
    else {
        panic!("the rational quarter must remain in the selected fiber");
    };
    assert!(unexpected_contacts.is_empty(), "unexpected contacts");
    let [overlap] = overlaps.as_slice() else {
        panic!("the selected rational quarter must retain one overlap");
    };
    (circle, quarter, overlap.clone())
}

#[test]
fn translated_selected_contact_import_omits_the_unused_center() {
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let (_, quarter, overlap) = selected_fiber_rational_quarter_overlap(&policy);
        let point = overlap
            .map
            .contact(
                overlap.other_end.clone(),
                BezierAlgebraicCuspSemicircleContactLocation2::Interior,
                RealSign::Zero,
            )
            .point_evidence();
        let CurvePoint2(CurvePointData2::AlgebraicCuspChordDerived(point)) = point else {
            panic!("the selected contact must retain its mapped source");
        };
        for (tx, ty) in [(Real::zero(), Real::zero()), (Real::pi(), Real::from(-2))] {
            let translated = point.translated(&tx, &ty);
            let imported = policy
                .bounded_exact_predicate_pass(|| translated.recursive_projective_point(&policy))
                .unwrap();
            let Classification::Decided(Some(imported)) = imported else {
                panic!("a translated source must import without joining its unused center");
            };
            let (base, extensions) = imported.denominator.field().base_and_extension_path();
            assert_eq!(base.sources.len(), 1);
            assert!(extensions.is_empty());
            assert_eq!(base.sources[0].exact_point_witness(), Some(&Real::one()));
            for (coordinate, expected) in [
                (&imported.x, quarter.end().x() + &tx),
                (&imported.y, quarter.end().y() + &ty),
            ] {
                let residual = coordinate
                    .subtract(&imported.denominator.scale(&expected).unwrap())
                    .unwrap();
                assert_eq!(
                    residual.sign(&CurveContext::STRICT).unwrap(),
                    Classification::Decided(RealSign::Zero),
                );
            }
        }
    }
}

fn check_selected_fiber_rational_overlap(exact_center: bool) {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let third = (Real::one() / Real::from(3_i8)).unwrap();
    for (policy, consume_terminal) in [
        (CurveContext::APPROXIMATE_512, false),
        (CurveContext::STRICT, false),
        (CurveContext::APPROXIMATE_512, true),
    ] {
        let (circle, quarter) = selected_fiber_rational_quarter(exact_center, &policy);
        for circle in [circle.clone(), circle.reversed()] {
            for reverse_source in [false, true] {
                let quarter = if reverse_source {
                    quarter.reversed()
                } else {
                    quarter.clone()
                };
                let outcome = crate::policy::resolve_certified_value(&policy, |attempt| {
                    if consume_terminal {
                        let sine = Real::e().sin();
                        let cosine = Real::e().cos();
                        let zero = &sine * &sine + &cosine * &cosine - Real::one();
                        assert_eq!(real_sign(&zero, attempt), Some(RealSign::Zero));
                    }
                    circle
                        .rational_intersections(
                            &quarter,
                            &crate::CurveParameterRange2::unit(),
                            attempt,
                        )
                        .unwrap()
                });
                assert_eq!(
                    outcome.certainty,
                    if consume_terminal {
                        CurveCertainty::Approximate512Consumed
                    } else {
                        CurveCertainty::Certified
                    },
                );
                let Classification::Decided(
                    BezierAlgebraicCuspSemicircleRationalIntersections2::SelectedFiber {
                        overlaps,
                        contacts: unexpected_contacts,
                    },
                ) = outcome.value
                else {
                    panic!("the selected quarter must publish its complete overlap");
                };
                assert!(unexpected_contacts.is_empty(), "unexpected contacts");
                let [overlap] = overlaps.as_slice() else {
                    panic!("the regular quarter must retain one overlap cell");
                };
                assert_eq!(
                    overlap.orientation(),
                    if circle.is_clockwise() == reverse_source {
                        CurveOverlapOrientation2::Same
                    } else {
                        CurveOverlapOrientation2::Reversed
                    },
                );
                let interior = BezierAlgebraicSelectedFiberAuthority2::exact_parameter(
                    overlap
                        .other_start
                        .data
                        .authority
                        .data
                        .retained_parameter
                        .clone(),
                    half.clone(),
                    &policy,
                );
                let mut endpoints = [
                    (Real::zero(), Point2::new(half.clone(), Real::one())),
                    (half.clone(), Point2::new(-half.clone(), Real::zero())),
                ];
                if reverse_source {
                    endpoints.reverse();
                }
                for (parameter, (angle, point)) in [
                    (overlap.other_start_parameter(), endpoints[0].clone()),
                    (overlap.other_end_parameter(), endpoints[1].clone()),
                    (
                        interior,
                        (
                            third.clone(),
                            Point2::new(
                                (Real::from(-3_i8) / Real::from(10_i8)).unwrap(),
                                (Real::from(3_i8) / Real::from(5_i8)).unwrap(),
                            ),
                        ),
                    ),
                ] {
                    let angle = if circle.is_clockwise() {
                        Real::one() - angle
                    } else {
                        angle
                    };
                    for replay_policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
                        let replay = overlap.cusp_parameter_for_other(&parameter, &replay_policy);
                        if consume_terminal && replay_policy == CurveContext::STRICT {
                            assert!(matches!(replay, Err(CurveError::Topology(_))));
                            assert!(matches!(
                                overlap.point_evidence_for_other(&parameter, &replay_policy),
                                Err(CurveError::Topology(_)),
                            ));
                            continue;
                        }
                        let Classification::Decided(mapped) = replay.unwrap() else {
                            panic!("the selected quarter correspondence must replay");
                        };
                        if consume_terminal {
                            assert!(
                                !mapped
                                    .shares_parametric_source_point(&mapped, &replay_policy)
                                    .unwrap(),
                                "approximate incidence cannot establish a certified shared-source identity"
                            );
                        }
                        assert_eq!(
                            mapped.order_to_real(&angle, &replay_policy).unwrap(),
                            Classification::Decided(std::cmp::Ordering::Equal),
                        );
                        let Classification::Decided(inverse) = overlap
                            .other_parameter_for_cusp(&mapped, &replay_policy)
                            .unwrap()
                        else {
                            panic!("the selected quarter inverse must replay");
                        };
                        assert_eq!(
                            inverse
                                .cmp_by_refinement(&parameter, &replay_policy)
                                .unwrap(),
                            Classification::Decided(std::cmp::Ordering::Equal),
                        );
                        let Classification::Decided(evidence) = overlap
                            .point_evidence_for_other(&parameter, &replay_policy)
                            .unwrap()
                        else {
                            panic!("the selected quarter point must replay");
                        };
                        assert_eq!(
                            evidence.same_point(&CurvePoint2::from(point.clone()), &replay_policy,),
                            Classification::Decided(true),
                        );
                    }
                }
            }
        }
    }
}

#[test]
fn selected_fiber_rational_overlap_keeps_exact_center() {
    check_selected_fiber_rational_overlap(true);
}

#[test]
fn selected_fiber_rational_overlap_replays_certified_policy() {
    check_selected_fiber_rational_overlap(false);
}

#[test]
fn selected_fiber_circle_overlap_does_not_prove_source_parameter_identity() {
    let quarter = (Real::one() / Real::from(4_i8)).unwrap();
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let (_, _, overlap) = selected_fiber_rational_quarter_overlap(&policy);
        let retained = overlap
            .other_start
            .data
            .authority
            .data
            .retained_parameter
            .clone();
        let first = BezierAlgebraicSelectedFiberAuthority2::new(
            BivariatePolynomial::new(vec![vec![-quarter.clone(), Real::one()]]),
            retained.clone(),
            &policy,
        )
        .parameter(IsolatedRootInterval {
            lower: Real::zero(),
            upper: Real::one(),
            exact_root: None,
            distinct_root_count: 1,
        });
        let second = BezierAlgebraicSelectedFiberAuthority2::exact_parameter(
            retained,
            half.clone(),
            &policy,
        );
        let Classification::Decided(first) =
            overlap.cusp_parameter_for_other(&first, &policy).unwrap()
        else {
            panic!("the first interior overlap point must map");
        };
        let Classification::Decided(second) =
            overlap.cusp_parameter_for_other(&second, &policy).unwrap()
        else {
            panic!("the second interior overlap point must map");
        };
        // Both points lie on the same source and circle, and 1/2 is
        // strictly inside the first singleton (0,1). On an overlap that
        // geometric incidence does not prove it solves u-1/4=0.
        assert!(
            !first
                .shares_parametric_source_point(&second, &policy)
                .unwrap()
        );
        assert!(
            !second
                .shares_parametric_source_point(&first, &policy)
                .unwrap()
        );
        assert_eq!(
            first.cmp_by_refinement(&second, &policy).unwrap(),
            Classification::Decided(std::cmp::Ordering::Less)
        );
        assert_eq!(
            second.cmp_by_refinement(&first, &policy).unwrap(),
            Classification::Decided(std::cmp::Ordering::Greater)
        );
    }
}

#[test]
fn selected_fiber_rational_component_publishes_its_isolated_endpoint() {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let opposite_quarter = RationalBezier2::from(
        RationalQuadraticBezier2::try_new(
            Point2::new(half.clone(), Real::one()),
            Point2::new(&half + Real::one(), Real::one()),
            Point2::new(&half + Real::one(), Real::zero()),
            Real::one(),
            Real::one(),
            Real::from(2_i8),
        )
        .unwrap(),
    );
    for exact_center in [false, true] {
        for (policy, consume_terminal) in [
            (CurveContext::STRICT, false),
            (CurveContext::APPROXIMATE_512, false),
            (CurveContext::APPROXIMATE_512, true),
        ] {
            let (circle, _) = selected_fiber_rational_quarter(exact_center, &policy);
            for circle in [circle.clone(), circle.reversed()] {
                for reverse_source in [false, true] {
                    let source = if reverse_source {
                        opposite_quarter.reversed()
                    } else {
                        opposite_quarter.clone()
                    };
                    let outcome = crate::policy::resolve_certified_value(&policy, |attempt| {
                        if consume_terminal {
                            let sine = Real::e().sin();
                            let cosine = Real::e().cos();
                            let zero = &sine * &sine + &cosine * &cosine - Real::one();
                            assert_eq!(real_sign(&zero, attempt), Some(RealSign::Zero));
                        }
                        circle
                            .rational_intersections(
                                &source,
                                &crate::CurveParameterRange2::unit(),
                                attempt,
                            )
                            .unwrap()
                    });
                    assert_eq!(
                        outcome.certainty,
                        if consume_terminal {
                            CurveCertainty::Approximate512Consumed
                        } else {
                            CurveCertainty::Certified
                        }
                    );
                    let Classification::Decided(
                        BezierAlgebraicCuspSemicircleRationalIntersections2::SelectedFiber {
                            contacts,
                            overlaps: unexpected_overlaps,
                        },
                    ) = outcome.value
                    else {
                        panic!("the opposite quarter must retain its lone shared endpoint");
                    };
                    assert!(unexpected_overlaps.is_empty(), "unexpected overlaps");
                    let [contact] = contacts.as_slice() else {
                        panic!("the opposite quarter must have exactly one contact");
                    };
                    assert_eq!(
                        contact.location(),
                        if circle.is_clockwise() {
                            BezierAlgebraicCuspSemicircleContactLocation2::End
                        } else {
                            BezierAlgebraicCuspSemicircleContactLocation2::Start
                        }
                    );
                    assert_eq!(contact.tangent_cross_sign(), RealSign::Zero);
                    for replay_policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
                        for (axis, value) in [(Axis2::X, half.clone()), (Axis2::Y, Real::one())] {
                            let order = contact.point_coordinate_order_to_real(
                                axis,
                                &value,
                                &replay_policy,
                            );
                            if consume_terminal && replay_policy == CurveContext::STRICT {
                                assert!(matches!(order, Err(CurveError::Topology(_))));
                            } else {
                                assert_eq!(
                                    order.unwrap(),
                                    Classification::Decided(std::cmp::Ordering::Equal)
                                );
                            }
                        }
                        if !consume_terminal || replay_policy == CurveContext::APPROXIMATE_512 {
                            assert_eq!(
                                contact.tangent_dot_sign(&replay_policy).unwrap(),
                                Classification::Decided(
                                    if circle.is_clockwise() == reverse_source {
                                        RealSign::Negative
                                    } else {
                                        RealSign::Positive
                                    }
                                )
                            );
                        }
                    }
                }
            }
        }
    }
}

#[test]
fn selected_fiber_rational_component_rejects_the_conjugate_circle() {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    for exact_center in [false, true] {
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let (base, _) = selected_fiber_rational_quarter(exact_center, &policy);
            let frame = base.data.frame.parallel_normal().unwrap();
            for distance in [Real::one(), Real::from(2_i8)] {
                let Classification::Decided(Some(circle)) =
                    BezierAlgebraicCuspSemicircle2::from_selected_parallel_normal(
                        frame.center_support.with_distance(distance.clone()),
                        frame.center_parameter.clone(),
                        Real::one(),
                        false,
                        &policy,
                    )
                    .unwrap()
                else {
                    panic!("the positively offset selected circle must construct");
                };
                // The authored/conjugate centers are (1/2, +/-distance).
                // For distance=1 they share only (1/2, 0); for 2 they are disjoint.
                for authored_sheet in [false, true] {
                    let source_y = if authored_sheet {
                        distance.clone()
                    } else {
                        -distance.clone()
                    };
                    let quarter = RationalBezier2::from(
                        RationalQuadraticBezier2::try_new(
                            Point2::new(half.clone(), &source_y + Real::one()),
                            Point2::new(-half.clone(), &source_y + Real::one()),
                            Point2::new(-half.clone(), source_y),
                            Real::one(),
                            Real::one(),
                            Real::from(2_i8),
                        )
                        .unwrap(),
                    );
                    for circle in [circle.clone(), circle.reversed()] {
                        for source in [quarter.clone(), quarter.reversed()] {
                            let outcome =
                                crate::policy::resolve_certified_value(&policy, |attempt| {
                                    circle
                                        .rational_intersections(
                                            &source,
                                            &crate::CurveParameterRange2::unit(),
                                            attempt,
                                        )
                                        .unwrap()
                                });
                            assert_eq!(outcome.certainty, CurveCertainty::Certified);
                            if authored_sheet {
                                let Classification::Decided(
                            BezierAlgebraicCuspSemicircleRationalIntersections2::SelectedFiber { overlaps, contacts: unexpected_contacts },
                        ) = outcome.value else {
                            panic!("the authored circle must retain its quarter overlap");
                        };
                                assert!(unexpected_contacts.is_empty(), "unexpected contacts");
                                assert_eq!(overlaps.len(), 1);
                                assert_eq!(
                                    overlaps[0]
                                        .cusp_start
                                        .cmp_by_refinement(&overlaps[0].cusp_end, &policy)
                                        .unwrap(),
                                    Classification::Decided(std::cmp::Ordering::Less)
                                );
                                continue;
                            }
                            let Classification::Decided(
                        BezierAlgebraicCuspSemicircleRationalIntersections2::SelectedFiber { contacts, overlaps: unexpected_overlaps },
                    ) = outcome.value else {
                        panic!("the conjugate component must not publish an overlap");
                    };
                            assert!(unexpected_overlaps.is_empty(), "unexpected overlaps");
                            if distance == Real::from(2_i8) {
                                assert!(contacts.is_empty());
                                continue;
                            }
                            let [contact] = contacts.as_slice() else {
                                panic!("the conjugate circle must have exactly one true contact");
                            };
                            assert_eq!(contact.tangent_cross_sign(), RealSign::Zero);
                            for (axis, value) in
                                [(Axis2::X, half.clone()), (Axis2::Y, Real::zero())]
                            {
                                assert_eq!(
                                    contact
                                        .point_coordinate_order_to_real(axis, &value, &policy)
                                        .unwrap(),
                                    Classification::Decided(std::cmp::Ordering::Equal)
                                );
                            }
                        }
                    }
                }
            }
        }
    }
}

#[test]
fn selected_fiber_angle_query_observes_its_requested_policy() {
    let (_, _, overlap) = selected_fiber_rational_quarter_overlap(&CurveContext::STRICT);
    let parameter = overlap.cusp_end_parameter();
    assert!(matches!(
        parameter,
        BezierAlgebraicCuspSemicircleParameter2::Mapped(_)
    ));
    let sine = Real::e().sin();
    let cosine = Real::e().cos();
    let zero = &sine * &sine + &cosine * &cosine - Real::one();
    let outcome =
        crate::policy::resolve_certified_value(&CurveContext::APPROXIMATE_512, |attempt| {
            parameter.order_to_real(&zero, attempt).unwrap()
        });
    assert_eq!(outcome.certainty, CurveCertainty::Approximate512Consumed);
    assert_eq!(
        outcome.value,
        Classification::Decided(std::cmp::Ordering::Greater)
    );
    assert_eq!(
        parameter
            .order_to_real(&Real::zero(), &CurveContext::STRICT)
            .unwrap(),
        Classification::Decided(std::cmp::Ordering::Greater),
    );
}

