#[test]
fn dense_chord_normal_rejects_disjoint_and_finitely_clipped_chords() {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let circle = dense_chord_normal_unit_semicircle(&policy);
        let disjoint = dense_chord_normal_chord(
            17,
            vec![Real::from(-2_i8)],
            vec![Real::zero()],
            19,
            vec![Real::zero()],
            vec![Real::from(2_i8)],
            &policy,
            "dense disjoint target",
        );
        let clipped = dense_chord_normal_chord(
            23,
            vec![-half.clone()],
            vec![Real::zero()],
            29,
            vec![Real::zero()],
            vec![Real::zero()],
            &policy,
            "dense clipped target",
        );
        for chord in [disjoint, clipped.clone()] {
            assert!(chord.exact_line().is_none());
            assert!(chord.strict_retained_support_line(&policy).is_none());
            assert!(matches!(
                circle
                    .chord_normal_projective_chord_system(&chord, &policy)
                    .unwrap(),
                Classification::Decided(Some(_))
            ));
            for carrier in [chord.clone(), chord.reversed()] {
                assert!(matches!(
                    circle.chord_intersections(&carrier, &policy).unwrap(),
                    Classification::Decided(contacts) if contacts.is_empty()
                ));
            }
        }
        for carrier in [clipped.clone(), clipped.reversed()] {
            let result = circle
                .chord_support_intersections(&carrier, &policy)
                .unwrap();
            let Classification::Decided(contacts) = result else {
                panic!("the dense affine target must retain its circle contacts: {result:?}");
            };
            assert!(!contacts.is_empty());
            for contact in &contacts {
                let start = contact
                    .chord_parameter
                    .cmp_by_refinement(&carrier.start_parameter(), &policy)
                    .unwrap();
                let end = contact
                    .chord_parameter
                    .cmp_by_refinement(&carrier.end_parameter(), &policy)
                    .unwrap();
                assert!(
                    matches!(
                        (start, end),
                        (
                            Classification::Decided(std::cmp::Ordering::Less),
                            Classification::Decided(std::cmp::Ordering::Less)
                        ) | (
                            Classification::Decided(std::cmp::Ordering::Greater),
                            Classification::Decided(std::cmp::Ordering::Greater)
                        )
                    ),
                    "an affine-only dense contact must be on one exterior ray: start={start:?}, end={end:?}, contact={contact:?}",
                );
            }
        }
    }
}

#[test]
fn dense_chord_normal_retains_rational_contacts_and_circle_components() {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let secant = RationalBezier2::try_new(
        vec![
            Point2::new(half.clone(), Real::from(-2_i8)),
            Point2::new(half, Real::from(2_i8)),
        ],
        vec![Real::one(), Real::one()],
    )
    .unwrap();
    let quarter_circle = RationalBezier2::from(
        RationalQuadraticBezier2::try_new(
            Point2::from_values(1, 0),
            Point2::from_values(1, 1),
            Point2::from_values(0, 1),
            Real::one(),
            Real::one(),
            Real::from(2_i8),
        )
        .unwrap(),
    );
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let circle = dense_chord_normal_unit_semicircle(&policy);
        let Classification::Decided((
            BezierAlgebraicCuspSemicircleRationalIntersections2::Mapped {
                contacts,
                overlaps: unexpected_overlaps,
            },
            Some(parameter_map),
        )) = circle
            .rational_intersections_with_parameter_map(
                &secant,
                &crate::CurveParameterRange2::unit(),
                &policy,
            )
            .unwrap()
        else {
            panic!("the dense rational secant must complete");
        };
        assert!(unexpected_overlaps.is_empty(), "unexpected overlaps");
        assert_eq!(contacts.len(), 2);
        assert!(matches!(
            &parameter_map.data.system,
            BezierAlgebraicCuspSemicircleRationalParameterMapSystem2::ChordNormalProjective { .. }
        ));
        for contact in &contacts {
            assert_eq!(
                contact.location,
                BezierAlgebraicCuspSemicircleContactLocation2::Interior,
            );
            assert_ne!(contact.tangent_cross_sign, RealSign::Zero);
            let cusp_parameter = parameter_map.contact_parameter(contact);
            let Classification::Decided(Some(point)) = cusp_parameter
                .coincident_point_evidence(&circle, &policy)
                .unwrap()
            else {
                panic!("the dense rational map must replay its contact point");
            };
            assert_eq!(
                point.same_point(&contact.point, &policy),
                Classification::Decided(true),
            );
        }
        assert!(matches!(
            circle
                .chord_normal_projective_rational_system(
                    &quarter_circle,
                    &crate::CurveParameterRange2::unit(),
                    &policy
                )
                .unwrap(),
            Classification::Decided(Some(_))
        ));
        for (target, orientation) in [
            (quarter_circle.clone(), CurveOverlapOrientation2::Reversed),
            (quarter_circle.reversed(), CurveOverlapOrientation2::Same),
        ] {
            let Classification::Decided(
                BezierAlgebraicCuspSemicircleRationalIntersections2::Mapped {
                    overlaps,
                    contacts: unexpected_contacts,
                },
            ) = circle
                .rational_intersections(&target, &crate::CurveParameterRange2::unit(), &policy)
                .unwrap()
            else {
                panic!("the dense supporting-circle component must complete");
            };
            assert!(unexpected_contacts.is_empty(), "unexpected contacts");
            let [overlap] = overlaps.as_slice() else {
                panic!("the selected quarter must retain one monotone overlap cell");
            };
            assert_eq!(overlap.orientation(), orientation);
            assert!(matches!(
                overlap
                    .cusp_start_parameter()
                    .parameter_bracket(16, &policy),
                Ok(Classification::Decided(_))
            ));
            assert!(matches!(
                overlap.cusp_end_parameter().parameter_bracket(16, &policy),
                Ok(Classification::Decided(_))
            ));
        }
    }
}

#[test]
fn dense_tuple_sign_binds_exact_points_and_preserves_the_selected_root() {
    let mut source = bezier_parameter_root_representation(&algebraic_parameter(vec![
        -(Real::one() / Real::from(2)).unwrap(),
        Real::zero(),
        Real::zero(),
        Real::one(),
    ]));
    source.constraint_index = 23;
    source.symbol = hypersolve::SymbolId(29);
    assert!(source.exact_point_witness().is_none());
    for known_axis in 0..2 {
        for (scale, expected) in [(1, RealSign::Positive), (-1, RealSign::Negative)] {
            let point = Real::from(scale) * Real::from(2).sqrt().unwrap();
            assert!(point.exact_rational_ref().is_none());
            let mut sources = vec![source.clone(); 2];
            sources[known_axis] = AlgebraicRootRepresentation::from_exact_value(&point);
            // Q(k,x)=(k^2-2)x^2+kx-1, with x=cbrt(1/2).
            // For k=+sqrt(2), x>3/4 and k>4/3 prove Q>0;
            // for k=-sqrt(2), Q<0. No approximate oracle is needed.
            let mut coefficients = vec![Real::zero(); 9];
            coefficients[0] = -Real::one();
            coefficients[4] = Real::one();
            coefficients[8] = Real::one();
            coefficients[if known_axis == 0 { 2 } else { 6 }] = Real::from(-2);
            let polynomial = DenseTensorPolynomial::try_new(vec![3, 3], coefficients).unwrap();
            for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
                assert_eq!(
                    dense_polynomial_tuple_sign(&polynomial, &sources, &policy).unwrap(),
                    Classification::Decided(expected),
                );
            }
        }
    }
}

