#[test]
fn independently_encoded_scaled_rotated_recursive_circles_intersect_exactly() {
    let fifth = (Real::one() / Real::from(5_i8)).unwrap();
    let scale_rotate = Similarity2::try_from_real_affine(
        Real::from(8_i8) * &fifth,
        Real::from(-6_i8) * &fifth,
        Real::from(6_i8) * &fifth,
        Real::from(8_i8) * fifth,
        Real::zero(),
        Real::zero(),
    )
    .unwrap();
    assert_eq!(
        compare_reals(
            scale_rotate.scale(),
            &Real::from(2_i8),
            &CurveContext::STRICT,
        ),
        Some(std::cmp::Ordering::Equal),
    );
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let first = recursively_pair_radial_half(&policy);
        let transformed = recursively_pair_radial_half(&policy)
            .transform_similarity(&scale_rotate)
            .unwrap();
        let Classification::Decided(frame) = transformed
            .represented_selected_radial_frame(&policy)
            .unwrap()
        else {
            panic!("the scaled recursive frame must materialize exactly");
        };
        assert_eq!(
            compare_reals(&frame.signed_radius, &Real::one(), &CurveContext::STRICT,),
            Some(std::cmp::Ordering::Equal),
        );
        let Classification::Decided([unit_norm, unit_cross]) = Classification::from(
            represented_vector_dot_cross(&frame.unit_radial, &frame.unit_radial),
        ) else {
            panic!("the scaled recursive frame must retain its unit radial correlation");
        };
        let Classification::Decided(unit_norm_residual) = Classification::from(
            represented_affine_coordinate(&[(&unit_norm, &Real::one())], &Real::from(-1_i8)),
        ) else {
            panic!("the transformed unit norm must remain representable");
        };
        assert_eq!(
            represented_strict_sign(&unit_norm_residual),
            Some(RealSign::Zero)
        );
        assert_eq!(represented_strict_sign(&unit_cross), Some(RealSign::Zero));

        let second = transformed.complementary_half();
        for (left, right) in [(&first, &second), (&second, &first)] {
            let result = left.pair_intersections(right, &policy).unwrap();
            let Classification::Decided(
                BezierAlgebraicCuspSemicirclePairIntersections2::Contacts {
                    contacts,
                    parameter_map,
                },
            ) = result
            else {
                panic!("the scaled recursive pair must complete exactly: {result:?}");
            };
            assert_eq!(contacts.len(), 2);
            for contact in &contacts {
                assert_eq!(
                    contact.first_location,
                    BezierAlgebraicCuspSemicircleContactLocation2::Interior,
                );
                assert_eq!(
                    contact.second_location,
                    BezierAlgebraicCuspSemicircleContactLocation2::Interior,
                );
                assert_eq!(
                    parameter_map.tangent_dot_sign(contact, &policy).unwrap(),
                    Classification::Decided(RealSign::Negative),
                );
                let Classification::Decided([x, y]) = parameter_map
                    .represented_selected_radial_contact_point(contact)
                    .unwrap()
                else {
                    panic!("the scaled recursive contact must retain exact coordinates");
                };
                assert_eq!(
                    compare_reals(&x.interval.lower, &Real::zero(), &CurveContext::STRICT),
                    Some(std::cmp::Ordering::Greater),
                );
                assert_eq!(
                    compare_reals(&y.interval.upper, &Real::zero(), &CurveContext::STRICT),
                    Some(std::cmp::Ordering::Less),
                );
                for parameter in [
                    parameter_map.first_contact_parameter(contact),
                    parameter_map.second_contact_parameter(contact),
                ] {
                    assert_eq!(
                        parameter.order_to_real(&Real::zero(), &policy).unwrap(),
                        Classification::Decided(std::cmp::Ordering::Greater),
                    );
                    assert_eq!(
                        parameter.order_to_real(&Real::one(), &policy).unwrap(),
                        Classification::Decided(std::cmp::Ordering::Less),
                    );
                }
            }
        }
    }
}

#[test]
fn differently_factored_selected_roots_share_frame_axes_and_translation() {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let BezierParameter2::Algebraic(parameter) =
        algebraic_parameter(vec![-half, Real::zero(), Real::zero(), Real::one()])
    else {
        unreachable!("the cubic fixture retains an algebraic parameter")
    };
    let root = parameter_representation(&parameter, &CurveContext::STRICT);
    let mut factored = root.clone();
    factored.polynomial_coefficients = polynomial_multiply(
        &root.polynomial_coefficients,
        &[Real::one(), Real::zero(), Real::one()],
    );
    factored.validation =
        validate_algebraic_root_representation(&factored, hypersolve::PredicatePolicy::STRICT);
    assert!(factored.is_valid());
    assert_ne!(
        root.polynomial_coefficients.len(),
        factored.polynomial_coefficients.len(),
    );
    assert!(represented_roots_strictly_equal(&root, &factored));

    let zero = AlgebraicRootRepresentation::from_exact_value(&Real::zero());
    let one = AlgebraicRootRepresentation::from_exact_value(&Real::one());
    let first = BezierRepresentedSelectedRadialCircleFrame2 {
        center: [root.clone(), zero.clone()],
        unit_radial: [one.clone(), zero.clone()],
        signed_radius: Real::one(),
    };
    let second = BezierRepresentedSelectedRadialCircleFrame2 {
        center: [factored.clone(), zero.clone()],
        unit_radial: [one, zero],
        signed_radius: Real::one(),
    };
    let translation =
        BezierAlgebraicCuspSemicircle2::represented_certified_frame_translation(&first, &second)
            .expect("equal differently factored centers must certify translation");
    assert!(translation.iter().all(|coordinate| {
        compare_reals(coordinate, &Real::zero(), &CurveContext::STRICT)
            == Some(std::cmp::Ordering::Equal)
    }));

    let (sources, coordinates) = represented_affine_tensor_basis(&[root, factored]).unwrap();
    assert_eq!(sources.len(), 1);
    assert_eq!(coordinates[0], coordinates[1]);
}

