#[test]
fn common_scalar_gap_refines_mixed_native_parameters_without_projection() {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let radical = half.clone().sqrt().unwrap();
    let one = DenseTensorPolynomial::try_new(vec![], vec![Real::one()]).unwrap();
    let field = BezierRecursiveQuadraticField2::base(vec![], one.clone(), one).unwrap();
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let selected = degree_nine_selected_fiber_parameter_for_test(half.clone(), 32_768, &policy);
        assert!(matches!(
            selected.promoted_bezier_parameter(&policy).unwrap(),
            Classification::Uncertain(_)
        ));
        let recursive = |value| {
            let Classification::Decided(parameter) =
                BezierRecursiveProjectiveParameter2::new_with_certified_bounds(
                    BezierRecursiveQuadraticProjectiveScalar2 {
                        numerator: field.constant(value).unwrap(),
                        denominator: field.constant(Real::one()).unwrap(),
                    },
                    Some((Real::zero(), Real::one())),
                    &policy,
                )
                .unwrap()
            else {
                panic!("both complementary radicals have certified unit enclosures");
            };
            CurveParameter2::from_recursive_projective(parameter)
        };
        let selected_parameter = CurveParameter2::from_selected_fiber(selected.clone());
        let recursive_parameter = recursive(radical.clone());
        let recursive_complement = recursive(Real::one() - &radical);
        let Classification::Decided(polynomial) = BezierParameterPolynomial::try_new_power_basis(
            vec![-half.clone(), Real::zero(), Real::one()],
            &policy,
        )
        .unwrap() else {
            panic!("the ordinary quadratic must construct");
        };
        let Classification::Decided(interval) =
            BezierParameterInterval::try_new(Real::zero(), Real::one(), &policy).unwrap()
        else {
            panic!("the unit isolator must construct");
        };
        let Classification::Decided(ordinary) =
            BezierAlgebraicParameter2::try_isolate(polynomial, interval, &policy).unwrap()
        else {
            panic!("the positive quadratic root must isolate");
        };
        let ordinary = CurveParameter2::from(BezierParameter2::Algebraic(ordinary));
        for (index, (first, second)) in [
            (selected_parameter.clone(), recursive_parameter.clone()),
            (
                recursive_complement.clone(),
                selected_parameter.unit_complement().unwrap(),
            ),
            (selected_parameter.clone(), ordinary.clone()),
            (
                ordinary.unit_complement().unwrap(),
                selected_parameter.unit_complement().unwrap(),
            ),
            (recursive_complement, recursive_parameter),
        ]
        .into_iter()
        .enumerate()
        {
            let (_, first_upper) = first.finite_envelope_bounds().unwrap();
            let (second_lower, _) = second.finite_envelope_bounds().unwrap();
            assert_ne!(
                compare_reals(first_upper, second_lower, &CurveContext::STRICT),
                Some(std::cmp::Ordering::Less),
                "case {index}: the retained enclosures must require native refinement"
            );
            for range in [
                None,
                Some(CurveParameterRange2::new_validated(
                    first.clone(),
                    second.clone(),
                )),
                Some(CurveParameterRange2::new_validated(
                    second.clone(),
                    first.clone(),
                )),
            ] {
                let work = || {
                    crate::policy::resolve_certified_operation(&policy, |attempt| match &range {
                        Some(range) => range.strict_interior_scalar(attempt),
                        None => first.strict_scalar_between_ordered(&second, attempt),
                    })
                };
                #[cfg(feature = "dispatch-trace")]
                hyperreal::dispatch_trace::reset();
                #[cfg(feature = "dispatch-trace")]
                let outcome = hyperreal::dispatch_trace::with_recording(work).unwrap();
                #[cfg(not(feature = "dispatch-trace"))]
                let outcome = work().unwrap();
                #[cfg(feature = "dispatch-trace")]
                assert_eq!(
                    hyperreal::dispatch_trace::take_trace().path_count(
                        "hypercurve",
                        "selected-scalar-promotion",
                        "complete-projection",
                    ),
                    0,
                    "case {index}: native scalar separation must avoid global projection"
                );
                assert_eq!(outcome.certainty, CurveCertainty::Certified);
                let Classification::Decided(sample) = outcome.value else {
                    panic!("finite native parameters must expose their strict interior");
                };
                let sample = CurveParameter2::from(BezierParameter2::Exact(sample));
                assert_eq!(
                    first.cmp_by_refinement(&sample, &policy).unwrap(),
                    Classification::Decided(std::cmp::Ordering::Less)
                );
                assert_eq!(
                    second.cmp_by_refinement(&sample, &policy).unwrap(),
                    Classification::Decided(std::cmp::Ordering::Greater)
                );
            }
        }
        assert!(
            selected.data.representations.bezier.get().is_none(),
            "an interior sample must leave the degree-135 endpoint in its selected fiber"
        );
    }
}

#[test]
fn selected_fiber_distinct_fields_order_before_bounded_global_projection() {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let third = (Real::one() / Real::from(3_i8)).unwrap();
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let first = degree_nine_selected_fiber_parameter_for_test(half.clone(), 32_768, &policy);
        let second = degree_nine_selected_fiber_parameter_for_test(third.clone(), 64, &policy);
        for parameter in [&first, &second] {
            assert!(
                matches!(
                    parameter.promoted_bezier_parameter(&policy).unwrap(),
                    Classification::Uncertain(_)
                ),
                "the fixture must remain outside both bounded global projections",
            );
        }
        assert_eq!(
            first.cmp_by_refinement(&second, &policy).unwrap(),
            Classification::Decided(std::cmp::Ordering::Less),
        );
        let Classification::Decided(separator) = first
            .strict_scalar_between_ordered(&second, &policy)
            .unwrap()
        else {
            panic!("disjoint local isolators must expose an exact rational separator");
        };
        assert_eq!(
            first.order_to_real(&separator, &policy).unwrap(),
            Classification::Decided(std::cmp::Ordering::Less),
        );
        assert_eq!(
            second.order_to_real(&separator, &policy).unwrap(),
            Classification::Decided(std::cmp::Ordering::Greater),
        );
    }
}

#[test]
fn selected_fiber_distinct_field_equality_uses_only_the_512_bit_terminal() {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let one_over_1024 = (Real::one() / Real::from(1_024_i16)).unwrap();

    let strict_first =
        degree_nine_selected_fiber_parameter_for_test(half.clone(), 32_768, &CurveContext::STRICT);
    let strict_second = degree_nine_selected_fiber_parameter_for_test(
        one_over_1024.clone(),
        16_384,
        &CurveContext::STRICT,
    );
    assert!(matches!(
        strict_first
            .cmp_by_refinement(&strict_second, &CurveContext::STRICT)
            .unwrap(),
        Classification::Uncertain(_)
    ));

    let policy = CurveContext::APPROXIMATE_512;
    let approximate_first = degree_nine_selected_fiber_parameter_for_test(half, 32_768, &policy);
    let approximate_second =
        degree_nine_selected_fiber_parameter_for_test(one_over_1024, 16_384, &policy);
    let outcome = crate::policy::resolve_certified_operation(&policy, |attempt| {
        approximate_first.cmp_by_refinement(&approximate_second, attempt)
    })
    .unwrap();
    assert_eq!(
        outcome.value,
        Classification::Decided(std::cmp::Ordering::Equal),
    );
    assert_eq!(
        outcome.certainty,
        crate::CurveCertainty::Approximate512Consumed,
    );
}

#[test]
fn selected_fiber_offset_coalesces_boolean_only_cuts_through_one_parallel_kernel() {
    let source_curve = QuadraticBezier2::new(
        Point2::from_values(0, 0),
        Point2::from_values(1, 0),
        Point2::from_values(2, 0),
    );
    let rational =
        RationalBezier2::try_from_subcurve(&BezierSubcurve2::Quadratic(source_curve.clone()))
            .unwrap();
    let analytic = source_curve.parallel_left(Real::zero()).unwrap();
    let sources = [
        (
            crate::bezier_split::BezierSelectedFiberSource2::Rational(rational.clone()),
            BezierParallel2::from_source(BezierParallelSource2::Rational(rational), Real::zero()),
        ),
        (
            crate::bezier_split::BezierSelectedFiberSource2::AnalyticParallel(analytic.clone()),
            analytic,
        ),
    ];
    let line_fragment = |start: Point2, end: Point2| BezierSplitFragment2::Materialized {
        start: BezierParameter2::Exact(Real::zero()),
        end: BezierParameter2::Exact(Real::one()),
        curve: BezierSubcurve2::Quadratic(QuadraticBezier2::from_line_segment(
            LineSeg2::try_new(start, end).unwrap(),
        )),
    };

    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let (first_cut, second_cut, retained_root) = selected_fiber_quartile_parameters(&policy);
        let first_value = (&retained_root / Real::from(2_i8)).unwrap();
        let second_value = ((&retained_root + Real::one()) / Real::from(2_i8)).unwrap();
        let parameters = [
            crate::CurveParameter2::from(BezierParameter2::Exact(Real::zero())),
            crate::CurveParameter2::from_selected_fiber(first_cut),
            crate::CurveParameter2::from_selected_fiber(second_cut),
            crate::CurveParameter2::from(BezierParameter2::Exact(Real::one())),
        ];
        let points = [
            Point2::from_values(0, 0),
            Point2::new(&first_value * Real::from(2_i8), Real::zero()),
            Point2::new(&second_value * Real::from(2_i8), Real::zero()),
            Point2::from_values(2, 0),
        ];

        for (source, parallel) in sources.iter().cloned() {
            let mut split_fragments = parameters
                .windows(2)
                .zip(points.windows(2))
                .map(|(range, endpoints)| {
                    BezierSplitFragment2::SelectedFiber(
                        crate::bezier_split::BezierSelectedFiberFragment2::new(
                            source.clone(),
                            crate::CurveParameterRange2::new_validated(
                                range[0].clone(),
                                range[1].clone(),
                            ),
                            CurvePoint2::from(endpoints[0].clone()),
                            CurvePoint2::from(endpoints[1].clone()),
                        ),
                    )
                })
                .collect::<Vec<_>>();
            split_fragments.extend([
                line_fragment(Point2::from_values(2, 0), Point2::from_values(2, 2)),
                line_fragment(Point2::from_values(2, 2), Point2::from_values(0, 2)),
                line_fragment(Point2::from_values(0, 2), Point2::from_values(0, 0)),
            ]);
            split_fragments.rotate_left(1);
            let split_region = CurveRegion2::try_new_with_loop_topology(
                vec![CurveRegionBoundaryLoop2::new(split_fragments, &policy).unwrap()],
                vec![CurveRegionLoopRole::Material],
                vec![FillRule::NonZero],
                vec![CurveBoundaryInteriorSide2::Left],
            )
            .unwrap();

            let unsplit = BezierSplitFragment2::AnalyticParallel(
                BezierParallelFragment2::from_certified_range(
                    parallel,
                    BezierParameterRange2::new_validated(
                        BezierParameter2::Exact(Real::zero()),
                        BezierParameter2::Exact(Real::one()),
                    ),
                    false,
                ),
            );
            let unsplit_region = CurveRegion2::try_new_with_loop_topology(
                vec![
                    CurveRegionBoundaryLoop2::new(
                        vec![
                            unsplit,
                            line_fragment(Point2::from_values(2, 0), Point2::from_values(2, 2)),
                            line_fragment(Point2::from_values(2, 2), Point2::from_values(0, 2)),
                            line_fragment(Point2::from_values(0, 2), Point2::from_values(0, 0)),
                        ],
                        &policy,
                    )
                    .unwrap(),
                ],
                vec![CurveRegionLoopRole::Material],
                vec![FillRule::NonZero],
                vec![CurveBoundaryInteriorSide2::Left],
            )
            .unwrap();

            let distance = (Real::one() / Real::from(10_i8)).unwrap();
            let split_offset = split_region
                .offset(distance.clone(), &OffsetCornerStyle2::Round, &policy)
                .expect("selected Boolean-only cuts must offset through the retained carrier");
            let unsplit_offset = unsplit_region
                .offset(distance, &OffsetCornerStyle2::Round, &policy)
                .expect("the equivalent unsplit retained carrier must offset");
            assert_eq!(split_offset.certainty, CurveCertainty::Certified);
            assert_eq!(split_offset.certainty, unsplit_offset.certainty);
            for point in [
                Point2::from_values(1, 1),
                Point2::from_values(3, 1),
                Point2::from_values(-1, 1),
                Point2::from_values(1, 3),
                Point2::from_values(1, -1),
            ] {
                assert_eq!(
                    split_offset
                        .value
                        .classify_point(&point.clone().into(), &policy)
                        .unwrap()
                        .value,
                    unsplit_offset
                        .value
                        .classify_point(&point.clone().into(), &policy)
                        .unwrap()
                        .value,
                );
            }
            assert!(
                split_offset
                    .value
                    .boundary_loops()
                    .iter()
                    .flat_map(CurveRegionBoundaryLoop2::fragments)
                    .all(|fragment| !matches!(fragment, BezierSplitFragment2::SelectedFiber(_)))
            );
        }
    }
}

#[test]
fn selected_parallel_normal_circle_retains_strict_replay_after_exact_approximate_request() {
    let source = QuadraticBezier2::new(
        Point2::from_values(0, 0),
        Point2::from_values(1, 0),
        Point2::from_values(2, 1),
    );
    let center_support = source.parallel_left(Real::one()).unwrap();
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let Classification::Decided(Some(circle)) =
        BezierAlgebraicCuspSemicircle2::from_selected_parallel_normal(
            center_support.clone(),
            BezierParameter2::Exact(half.clone()).into(),
            Real::one(),
            false,
            &CurveContext::APPROXIMATE_512,
        )
        .unwrap()
    else {
        panic!("the approximate-policy selected frame must construct");
    };
    assert_eq!(
        circle
            .data
            .frame
            .parallel_normal()
            .expect("the selected circle retains its parallel-normal frame")
            .policy,
        CurveContext::STRICT,
    );
    assert!(matches!(
        circle.point_evidence_at(&half, &CurveContext::STRICT),
        Ok(Classification::Decided(_)),
    ));
}

#[test]
fn selected_parallel_normal_circle_uses_direct_exact_winding() {
    let support = QuadraticBezier2::from_line_segment(
        LineSeg2::try_new(Point2::from_values(0, 0), Point2::from_values(2, 0)).unwrap(),
    )
    .parallel_left(Real::zero())
    .unwrap();
    let half = (Real::one() / Real::from(2_i8)).unwrap();

    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let Classification::Decided(Some(circle)) =
            BezierAlgebraicCuspSemicircle2::from_selected_parallel_normal(
                support.clone(),
                BezierParameter2::Exact(half.clone()).into(),
                Real::one(),
                false,
                &policy,
            )
            .unwrap()
        else {
            panic!("a regular selected line frame must construct");
        };
        let fragment = BezierAlgebraicCuspSemicircleFragment2::full(circle, &policy);
        assert_eq!(
            fragment
                .contains_point(&Point2::from_values(0, 0).into(), &policy)
                .unwrap(),
            Classification::Decided(true),
        );
        assert_eq!(
            fragment
                .contains_point(&Point2::from_values(2, 0).into(), &policy)
                .unwrap(),
            Classification::Decided(false),
        );
        assert_eq!(
            fragment
                .contains_point(&Point2::from_values(1, 0).into(), &policy)
                .unwrap(),
            Classification::Decided(false),
        );
        assert_eq!(
            fragment
                .forward_ray_winding_delta(
                    &Point2::from_values(-2, 0),
                    &Real::one(),
                    &Real::zero(),
                    &policy,
                )
                .unwrap(),
            Classification::Decided(-1),
        );
        assert_eq!(
            fragment
                .forward_ray_winding_delta(
                    &Point2::from_values(2, 0),
                    &Real::one(),
                    &Real::zero(),
                    &policy,
                )
                .unwrap(),
            Classification::Decided(0),
        );
        assert_eq!(
            fragment
                .forward_ray_winding_delta(
                    &Point2::from_values(0, 0),
                    &Real::one(),
                    &Real::zero(),
                    &policy,
                )
                .unwrap(),
            Classification::Uncertain(UncertaintyReason::Boundary),
        );
        assert_eq!(
            fragment
                .reversed()
                .forward_ray_winding_delta(
                    &Point2::from_values(-2, 0),
                    &Real::one(),
                    &Real::zero(),
                    &policy,
                )
                .unwrap(),
            Classification::Decided(1),
        );
    }
}

#[test]
fn selected_parallel_contact_map_orders_the_exact_angular_parameter() {
    let anchor = QuadraticBezier2::from_line_segment(
        LineSeg2::try_new(Point2::from_values(0, 0), Point2::from_values(2, 0)).unwrap(),
    )
    .parallel_left(Real::zero())
    .unwrap();
    let contact = QuadraticBezier2::from_line_segment(
        LineSeg2::try_new(Point2::from_values(0, -1), Point2::from_values(0, 1)).unwrap(),
    )
    .parallel_left(Real::zero())
    .unwrap();
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let quarter = (Real::one() / Real::from(4_i8)).unwrap();
    let three_quarters = &half + &quarter;

    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let Classification::Decided(Some(circle)) =
            BezierAlgebraicCuspSemicircle2::from_selected_parallel_normal(
                anchor.clone(),
                BezierParameter2::Exact(half.clone()).into(),
                Real::one(),
                false,
                &policy,
            )
            .unwrap()
        else {
            panic!("the selected line-normal frame must construct");
        };
        let Classification::Decided(parameter) = circle
            .certified_selected_parallel_contact_parameter(
                contact.clone(),
                CurveParameter2::from(half.clone()),
                BezierAlgebraicCuspSemicircleContactLocation2::Interior,
                RealSign::Positive,
                RealSign::Positive,
                RealSign::Zero,
                &policy,
            )
            .unwrap()
        else {
            panic!("the quarter-turn contact must retain an angular map");
        };
        assert!(parameter.validate_policy(&CurveContext::STRICT).is_ok());
        assert_eq!(
            parameter.order_to_real(&quarter, &policy).unwrap(),
            Classification::Decided(std::cmp::Ordering::Greater),
        );
        assert_eq!(
            parameter.order_to_real(&half, &policy).unwrap(),
            Classification::Decided(std::cmp::Ordering::Equal),
        );
        assert_eq!(
            parameter.order_to_real(&three_quarters, &policy).unwrap(),
            Classification::Decided(std::cmp::Ordering::Less),
        );
        let Classification::Decided(Some(contact_point)) = parameter
            .coincident_point_evidence(&circle, &policy)
            .unwrap()
        else {
            panic!("the angular map must replay its analytic contact point");
        };
        let Classification::Decided(circle_point) =
            circle.point_evidence_at(&half, &policy).unwrap()
        else {
            panic!("the represented quarter-turn circle point must be exact");
        };
        for point in [&contact_point, &circle_point] {
            let Classification::Decided(bounds) =
                algebraic_chord_endpoint_bounds_refined(point, 0, &policy)
            else {
                panic!("the represented line-frame contact must have exact bounds");
            };
            assert_eq!(bounds.min(), &Point2::from_values(0, 0));
            assert_eq!(bounds.max(), &Point2::from_values(0, 0));
        }
        let Classification::Decided(bracket) = parameter.parameter_bracket(8, &policy).unwrap()
        else {
            panic!("the exact angular contact must refine to a bracket");
        };
        let (start, end) = cusp_semicircle_parameter_bracket_bounds(&bracket);
        assert!(compare_reals(start, &half, &policy) != Some(std::cmp::Ordering::Greater));
        assert!(compare_reals(end, &half, &policy) != Some(std::cmp::Ordering::Less));
    }
}

#[test]
fn local_parallel_endpoint_clipping_reuses_a_coefficient_root() {
    let q = |n, d| (Real::from(n) / Real::from(d)).unwrap();
    let half = q(1, 2);
    let polynomial = vec![-half.clone(), Real::zero(), Real::one()];
    let parallel = QuadraticBezier2::new(
        Point2::from_values(0, 0),
        Point2::new(half.clone(), Real::zero()),
        Point2::from_values(1, 1),
    )
    .parallel_left(q(1, 4))
    .unwrap();
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let Classification::Decided(defining) =
            BezierParameterPolynomial::try_new_power_basis(polynomial.clone(), &policy).unwrap()
        else {
            panic!("the quadratic has exact rational coefficients")
        };
        let Classification::Decided(interval) =
            BezierParameterInterval::try_new(half.clone(), Real::one(), &policy).unwrap()
        else {
            panic!("the positive root has a strict finite bracket")
        };
        let Classification::Decided(native) =
            BezierAlgebraicParameter2::try_isolate(defining, interval, &policy).unwrap()
        else {
            panic!("the positive quadratic root isolates uniquely")
        };
        let native = BezierParameter2::Algebraic(native);
        let one = DenseTensorPolynomial::from_axis_polynomial(1, 0, &[Real::one()]).unwrap();
        let field = BezierRecursiveQuadraticField2::base(
            vec![bezier_parameter_root_representation(&native)],
            one.clone(),
            one,
        )
        .unwrap();
        let coefficients = recursive_quadratic_real_polynomial(&field, &polynomial).unwrap();
        let BezierRecursiveQuadraticField2::Base(base) = &field else {
            unreachable!();
        };
        let generator = recursive_quadratic_rational_value(
            base,
            DenseTensorPolynomial::from_axis_polynomial(1, 0, &[Real::zero(), Real::one()])
                .unwrap(),
        )
        .unwrap();
        // Formula roots have no polynomial-root authority of their own.
        // Their retained field still proves the native defining equation;
        // selected intervals distinguish the conjugate and nearby values.
        for (sign, shift, expected) in [
            (-1, Real::zero(), std::cmp::Ordering::Less),
            (1, -q(1, 8), std::cmp::Ordering::Less),
            (1, Real::zero(), std::cmp::Ordering::Equal),
            (1, q(1, 8), std::cmp::Ordering::Greater),
        ] {
            let scalar = BezierRecursiveQuadraticProjectiveScalar2 {
                numerator: generator
                    .scale(&Real::from(sign))
                    .unwrap()
                    .add(&field.constant(shift).unwrap())
                    .unwrap(),
                denominator: field.constant(Real::one()).unwrap(),
            };
            let Classification::Decided(direct) =
                BezierRecursiveProjectiveParameter2::new(scalar, &policy).unwrap()
            else {
                panic!("the retained formula root must have finite bounds")
            };
            assert!(direct.projective_scalar().is_some());
            let order = policy
                .bounded_exact_predicate_pass(|| direct.cmp_bezier_parameter(&native, &policy))
                .unwrap();
            assert_eq!(order, Classification::Decided(expected));
            assert!(direct.data.projection.parameter.get().is_none());
        }
        let difference = [
            generator.scale(&-Real::one()).unwrap(),
            field.constant(Real::one()).unwrap(),
        ];
        let roots = recursive_quadratic_polynomial_local_parameters(
            &field,
            &coefficients,
            [&-Real::one(), &Real::one()],
            &policy,
        )
        .unwrap()
        .expect("both conjugates isolate in the retained field");
        assert_eq!(roots.len(), 2);
        let endpoint = BezierAnalyticParallelPoint2::new(parallel.clone(), native.clone(), &policy);
        let endpoint_point = CurvePoint2::from(endpoint.clone());
        let Classification::Decided(displaced) = BezierAlgebraicChord2::translated_endpoint(
            &endpoint_point,
            &Real::one(),
            &Real::zero(),
            &policy,
        )
        .unwrap() else {
            panic!("unit translation preserves the exact endpoint")
        };
        let Classification::Decided(chord) =
            BezierAlgebraicChord2::try_new_from_certified_distinct_endpoints(
                endpoint_point,
                displaced,
                &policy,
            )
            .unwrap()
        else {
            panic!("unit translation proves distinct horizontal endpoints")
        };
        for (index, root) in roots.iter().enumerate() {
            #[cfg(feature = "dispatch-trace")]
            hyperreal::dispatch_trace::reset();
            let sign = || {
                root.as_recursive_projective()
                    .unwrap()
                    .recursive_polynomial_sign(&difference, &policy)
                    .unwrap()
            };
            #[cfg(feature = "dispatch-trace")]
            let sign = hyperreal::dispatch_trace::with_recording(sign);
            #[cfg(not(feature = "dispatch-trace"))]
            let sign = sign();
            assert!(
                sign == Classification::Decided(if index == 0 {
                    RealSign::Negative
                } else {
                    RealSign::Zero
                })
            );
            #[cfg(feature = "dispatch-trace")]
            {
                let trace = hyperreal::dispatch_trace::take_trace();
                assert_eq!(
                    trace.path_count(
                        "hypercurve",
                        "recursive-polynomial-sign",
                        "defining-at-real",
                    ),
                    0,
                    "coefficient-root identity must precede redundant local refinement"
                );
            }
            let point =
                BezierAnalyticParallelPoint2::new_with_region_parameter_and_tangent_distance(
                    parallel.clone(),
                    root,
                    Real::zero(),
                    &policy,
                )
                .unwrap();
            let identity = policy
                .bounded_exact_predicate_pass(|| {
                    point.shared_parameter_point_equality(&endpoint, &policy)
                })
                .unwrap();
            assert_eq!(
                identity,
                Classification::Decided((index == 1).then_some(true))
            );
            if index == 1 {
                for (chord, at_end) in [(chord.clone(), false), (chord.reversed(), true)] {
                    let outcome = crate::policy::resolve_certified_operation(&policy, |attempt| {
                        attempt.bounded_exact_predicate_pass(|| {
                            chord.parameter_at_certified_support_point_by_local_evidence(
                                CurvePoint2::from(point.clone()),
                                attempt,
                            )
                        })
                    })
                    .unwrap();
                    assert_eq!(outcome.certainty, CurveCertainty::Certified);
                    assert!(
                        matches!(outcome.value, Classification::Decided(Some(parameter))
                        if matches!(parameter.data, BezierAlgebraicChordParameterStorage2::Endpoint { at_end: actual, .. } if actual == at_end))
                    );
                    let Classification::Decided(Some(system)) = chord
                        .recursive_projective_parallel_system_with_frame(
                            &parallel, None, true, &policy,
                        )
                        .unwrap()
                    else {
                        panic!("the chord retains a complete incidence field");
                    };
                    let Classification::Decided(
                        BezierAlgebraicChordParallelIntersections2::Contacts(contacts),
                    ) = chord
                        .recursive_projective_parallel_contacts(
                            &parallel,
                            &system,
                            vec![root.clone()],
                            BezierRecursiveParallelCandidateEvidence2::Replay,
                            None,
                            None,
                            true,
                            &policy,
                        )
                        .unwrap()
                    else {
                        panic!("the owned scalar must replay its actual incidence");
                    };
                    let [contact] = contacts.as_slice() else {
                        panic!("the supplied positive root is one endpoint contact");
                    };
                    assert_eq!(
                        contact.parallel_parameter().as_bezier_parameter(),
                        Some(&native)
                    );
                    assert!(matches!(contact.chord_parameter().data,
                        BezierAlgebraicChordParameterStorage2::Endpoint { at_end: actual, .. }
                            if actual == at_end));
                    assert!(contact.point().shares_storage(if at_end {
                        chord.end()
                    } else {
                        chord.start()
                    }));
                }
            }
            assert!(
                root.as_recursive_projective()
                    .unwrap()
                    .data
                    .projection
                    .parameter
                    .get()
                    .is_none()
            );
        }
    }
}

#[test]
fn recursive_local_isolation_reuses_exact_signs_below_interval_precision() {
    let scalar = |value| DenseTensorPolynomial::try_new(vec![], vec![value]).unwrap();
    let base =
        BezierRecursiveQuadraticField2::base(vec![], scalar(Real::one()), scalar(Real::one()))
            .unwrap();
    let field = base
        .extension(base.constant(Real::from(2_i8)).unwrap())
        .unwrap();
    let tiny = Real::from(2_i8).powi_i64(-600).unwrap();
    let value = field
        .element(
            base.constant(Real::zero()).unwrap(),
            base.constant(tiny.clone()).unwrap(),
        )
        .unwrap();
    let expected = tiny * Real::from(2_i8).sqrt().unwrap();
    // Every scheduled dyadic enclosure contains zero. The retained exact
    // witness still proves positivity, including under APPROXIMATE_512.
    assert!(value.bounded_interval_sign(0..=512).is_none());
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        for gauge in [
            Real::one(),
            (Real::from(-7_i8) / Real::from(97_i8)).unwrap(),
            -Real::pi(),
        ] {
            // g * (t - 2^-600 * sqrt(2)) has precisely this one positive
            // root. A negative gauge must preserve the same selection;
            // the pi gauge also prevents rational-content normalization
            // from removing the tiny coefficient before sign replay.
            let polynomial = vec![
                value.scale(&-gauge.clone()).unwrap(),
                field.constant(gauge).unwrap(),
            ];
            let roots = recursive_quadratic_polynomial_local_parameters(
                &field,
                &polynomial,
                [&Real::zero(), &Real::one()],
                &policy,
            )
            .unwrap()
            .expect("the exact tiny sign must retain local isolation");
            let [root] = roots.as_slice() else {
                panic!("the affine polynomial has exactly one unit root");
            };
            assert!(
                root.same_value(&expected.clone().into(), &policy).unwrap()
                    == Classification::Decided(true)
            );
            assert!(
                root.cmp_by_refinement(&Real::zero().into(), &policy)
                    .unwrap()
                    == Classification::Decided(std::cmp::Ordering::Greater)
            );
            assert!(
                root.as_recursive_projective()
                    .unwrap()
                    .data
                    .projection
                    .parameter
                    .get()
                    .is_none()
            );
        }
    }
}

#[test]
fn recursive_parameter_projection_preserves_roots_through_refinement_and_charts() {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let one = DenseTensorPolynomial::try_new(vec![], vec![Real::one()]).unwrap();
    let field = BezierRecursiveQuadraticField2::base(vec![], one.clone(), one).unwrap();
    let large = Real::from(2_i8).powi_i64(1024).unwrap() + Real::from(17_i8);
    let reciprocal = (Real::one() / &large).unwrap();
    let gauges = [
        Real::one(),
        large.clone(),
        -large,
        reciprocal.clone(),
        -reciprocal,
    ];
    for (policy, gauge) in [CurveContext::STRICT, CurveContext::APPROXIMATE_512]
        .into_iter()
        .flat_map(|policy| gauges.iter().map(move |gauge| (policy, gauge)))
    {
        let polynomial = recursive_quadratic_real_polynomial(
            &field,
            &[-&half * gauge, Real::zero(), gauge.clone()],
        )
        .unwrap();
        let roots = recursive_quadratic_polynomial_local_parameters(
            &field,
            &polynomial,
            [&-Real::one(), &Real::one()],
            &policy,
        )
        .unwrap()
        .expect("both simple conjugates isolate locally");
        assert_eq!(roots.len(), 2);
        for (root, expected) in roots
            .iter()
            .zip([std::cmp::Ordering::Less, std::cmp::Ordering::Greater])
        {
            let root = root
                .as_recursive_projective()
                .expect("the irrational root remains local");
            // This chart predates native projection. A later demand
            // must retain its map back to the same original selection.
            let prior_complement = root.unit_complement();
            #[cfg(feature = "dispatch-trace")]
            hyperreal::dispatch_trace::reset();
            let replay = || {
                root.recursive_polynomial_sign(&polynomial, &policy)
                    .unwrap()
            };
            #[cfg(feature = "dispatch-trace")]
            let zero = hyperreal::dispatch_trace::with_recording(replay);
            #[cfg(not(feature = "dispatch-trace"))]
            let zero = replay();
            assert!(zero == Classification::Decided(RealSign::Zero));
            #[cfg(feature = "dispatch-trace")]
            assert_eq!(
                hyperreal::dispatch_trace::take_trace().path_count(
                    "hypercurve",
                    "recursive-polynomial-sign",
                    "defining-at-real",
                ),
                0,
                "a known defining relation must not reconstruct its endpoint signs"
            );
            let Classification::Decided(refined) = root.refined(8, &policy).unwrap() else {
                panic!("wide rational gauges must preserve local refinement")
            };
            assert!(
                refined
                    .polynomial_sign(&[Real::zero(), Real::one()], &policy)
                    .unwrap()
                    == Classification::Decided(match expected {
                        std::cmp::Ordering::Less => RealSign::Negative,
                        std::cmp::Ordering::Greater => RealSign::Positive,
                        std::cmp::Ordering::Equal => unreachable!(),
                    })
            );
            assert!(root.data.projection.parameter.get().is_none());
            assert!(refined.data.projection.parameter.get().is_none());
            assert!(prior_complement.data.projection.parameter.get().is_none());
            let Classification::Decided(native) =
                root.promoted_bezier_parameter_complete(&policy).unwrap()
            else {
                panic!("the quadratic projection must be exact")
            };
            assert!(
                native
                    .cmp_by_refinement(&BezierParameter2::Exact(Real::zero()), &policy)
                    .unwrap()
                    == Classification::Decided(expected)
            );
            let Classification::Decided(projected_complement) = prior_complement
                .promoted_bezier_parameter_complete(&policy)
                .unwrap()
            else {
                panic!("the preexisting chart must replay its native source")
            };
            if let (BezierParameter2::Algebraic(source), BezierParameter2::Algebraic(image)) =
                (&native, &projected_complement)
            {
                assert!(
                    image.projective_map_from(source)
                        == Some(([Real::one(), -Real::one()], [Real::one(), Real::zero()])),
                    "projection must retain the exact chart, not only its image polynomial"
                );
            }
            let mut restored = root.clone();
            for _ in 0..4 {
                for (numerator, denominator) in [
                    ([Real::one(), Real::one()], [Real::from(-2_i8), Real::one()]),
                    ([Real::one(), Real::from(2_i8)], [-Real::one(), Real::one()]),
                ] {
                    let Classification::Decided(mapped) = restored
                        .projective_image_unbounded(&numerator, &denominator, &policy)
                        .unwrap()
                    else {
                        panic!("both inverse charts are regular at the selected root")
                    };
                    restored = mapped;
                }
                assert!(
                    Arc::ptr_eq(&restored.data, &root.data),
                    "composed inverse charts must recover the original root authority"
                );
            }
            let Classification::Decided(tighter_complement) =
                prior_complement.refined(8, &policy).unwrap()
            else {
                panic!("the transformed simple root must refine")
            };
            let restored = tighter_complement.unit_complement();
            assert!(
                restored.cmp_by_refinement(root, &policy).unwrap()
                    == Classification::Decided(std::cmp::Ordering::Equal)
            );
            assert!(
                compare_reals(
                    &(&restored.data.upper - &restored.data.lower),
                    &(&root.data.upper - &root.data.lower),
                    &CurveContext::STRICT,
                ) == Some(std::cmp::Ordering::Less),
                "inverse composition must preserve intervening refinement progress"
            );
            for steps in [0, 4, 12] {
                let Classification::Decided(refined) = root.refined(steps, &policy).unwrap() else {
                    panic!("the simple local root must refine")
                };
                let Classification::Decided(projected) =
                    refined.promoted_bezier_parameter_complete(&policy).unwrap()
                else {
                    panic!("refinement preserves the exact projection")
                };
                assert!(
                    projected.cmp_by_refinement(&native, &policy).unwrap()
                        == Classification::Decided(std::cmp::Ordering::Equal)
                );
                let complement = refined.unit_complement();
                let Classification::Decided(projected_complement) = complement
                    .promoted_bezier_parameter_complete(&policy)
                    .unwrap()
                else {
                    panic!("the changed chart must project its own selected value")
                };
                assert!(
                    projected_complement
                        .cmp_by_refinement(&native.unit_complement(), &policy)
                        .unwrap()
                        == Classification::Decided(std::cmp::Ordering::Equal)
                );
                assert!(
                    projected_complement
                        .cmp_by_refinement(&native, &policy)
                        .unwrap()
                        == Classification::Decided(expected.reverse())
                );
            }
        }
    }
}

#[test]
fn retained_parallel_contact_keeps_local_root_through_angular_and_point_queries() {
    let q = |n, d| (Real::from(n) / Real::from(d)).unwrap();
    let half = q(1, 2);
    // P(t)=(0,t^2-1/2) meets the unit circle centered at (1,0)
    // tangentially at t=sqrt(1/2). Its source tangent points upward,
    // so the contact is the exact midpoint of the left half-circle.
    let contact = QuadraticBezier2::new(
        Point2::new(Real::zero(), -half.clone()),
        Point2::new(Real::zero(), -half.clone()),
        Point2::new(Real::zero(), half.clone()),
    )
    .parallel_left(Real::zero())
    .unwrap();
    let anchor = QuadraticBezier2::from_line_segment(
        LineSeg2::try_new(Point2::from_values(0, 0), Point2::from_values(2, 0)).unwrap(),
    )
    .parallel_left(Real::zero())
    .unwrap();
    let one = DenseTensorPolynomial::from_axis_polynomial(1, 0, &[Real::one()]).unwrap();
    let field = BezierRecursiveQuadraticField2::base(
        vec![AlgebraicRootRepresentation::from_exact_value(&Real::zero())],
        one.clone(),
        one,
    )
    .unwrap();
    let polynomial =
        recursive_quadratic_real_polynomial(&field, &[-half.clone(), Real::zero(), Real::one()])
            .unwrap();
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let roots = recursive_quadratic_polynomial_local_parameters(
            &field,
            &polynomial,
            [&half, &Real::one()],
            &policy,
        )
        .unwrap()
        .expect("the positive simple root has a local isolator");
        assert_eq!(roots.len(), 1);
        let selected = roots[0]
            .as_recursive_projective()
            .expect("the irrational root remains local");
        // The same parameter may return from a later circle solve as
        // a selected fiber. F=(u-alpha-shift)(u+1)^2 has one root in
        // [1/2,1], while the repeated foreign root -1 stays outside.
        // Mixed ordering must preserve equality and both nearby sides.
        let BezierParameter2::Algebraic(alpha) =
            algebraic_parameter(vec![-half.clone(), Real::zero(), Real::one()])
        else {
            unreachable!()
        };
        for (shift, expected) in [
            (q(-1, 1024), std::cmp::Ordering::Less),
            (Real::zero(), std::cmp::Ordering::Equal),
            (q(1, 1024), std::cmp::Ordering::Greater),
        ] {
            let square = [Real::one(), Real::from(2_i8), Real::one()];
            let fiber = BezierAlgebraicSelectedFiberAuthority2::new(
                BivariatePolynomial::new(vec![
                    polynomial_multiply(&[-shift, Real::one()], &square),
                    polynomial_scale(&square, &Real::from(-1_i8)),
                ]),
                alpha.clone(),
                &policy,
            )
            .parameter(IsolatedRootInterval {
                lower: half.clone(),
                upper: Real::one(),
                exact_root: None,
                distinct_root_count: 1,
            });
            let fiber = CurveParameter2::from_selected_fiber(fiber);
            for (first, second, expected) in [
                (&fiber, &roots[0], expected),
                (&roots[0], &fiber, expected.reverse()),
            ] {
                let outcome = crate::policy::resolve_certified_value(&policy, |attempt| {
                    first.cmp_by_refinement(second, attempt).unwrap()
                });
                assert_eq!(outcome.certainty, CurveCertainty::Certified);
                assert_eq!(outcome.value, Classification::Decided(expected));
            }
        }
        let Classification::Decided(Some(local_frame)) =
            BezierAlgebraicCuspSemicircle2::from_selected_parallel_normal(
                contact.clone(),
                roots[0].clone(),
                Real::one(),
                false,
                &policy,
            )
            .unwrap()
        else {
            panic!("the normal frame itself must retain a local root")
        };
        // Optional scalar charts compose back to the original selected
        // root. The circle and every retained support stay in that source
        // chart, so tangent reattachment needs no separate map.
        let Classification::Decided(mapped) = roots[0]
            .affine_image_unbounded(&half, &Real::zero(), &policy)
            .unwrap()
        else {
            panic!("the local scalar chart must construct")
        };
        let Classification::Decided(restored) = mapped
            .affine_image_unbounded(&Real::from(2_i8), &Real::zero(), &policy)
            .unwrap()
        else {
            panic!("the inverse scalar chart must construct")
        };
        assert!(Arc::ptr_eq(
            &selected.data,
            &restored.as_recursive_projective().unwrap().data,
        ));
        let retained_frame_parameter = local_frame.selected_frame_parameter().unwrap();
        assert!(Arc::ptr_eq(
            &selected.data,
            &retained_frame_parameter
                .as_recursive_projective()
                .unwrap()
                .data
        ));
        let Classification::Decided(center) = local_frame.center_point_evidence(&policy).unwrap()
        else {
            panic!("the local normal-frame center must be an exact point")
        };
        assert_eq!(
            center.same_point(&Point2::from_values(0, 0).into(), &policy),
            Classification::Decided(true)
        );
        for (parameter, expected) in [
            (Real::zero(), Point2::from_values(-1, 0)),
            (Real::one(), Point2::from_values(1, 0)),
        ] {
            let Classification::Decided(point) =
                local_frame.point_evidence_at(&parameter, &policy).unwrap()
            else {
                panic!("the local normal-frame endpoint must retain its exact source")
            };
            assert_eq!(
                point.same_point(&expected.into(), &policy),
                Classification::Decided(true)
            );
        }
        let Classification::Decided(chord) = BezierAlgebraicChord2::try_new(
            Point2::from_values(0, 0).into(),
            Point2::from_values(2, 0).into(),
            &policy,
        )
        .unwrap() else {
            panic!("the horizontal anchor must construct")
        };
        let circles = [
            BezierAlgebraicCuspSemicircle2::from_selected_parallel_normal(
                anchor.clone(),
                BezierParameter2::Exact(half.clone()).into(),
                Real::one(),
                false,
                &policy,
            )
            .unwrap(),
            BezierAlgebraicCuspSemicircle2::from_retained_center_and_chord_normal(
                Point2::from_values(1, 0).into(),
                chord,
                Real::one(),
                false,
                &policy,
            )
            .unwrap(),
        ];
        for circle in circles {
            let Classification::Decided(Some(circle)) = circle else {
                panic!("both exact normal frames must construct")
            };
            let outcome = crate::policy::resolve_certified_value(&policy, |attempt| {
                circle
                    .certified_selected_parallel_contact_parameter(
                        contact.clone(),
                        roots[0].clone(),
                        BezierAlgebraicCuspSemicircleContactLocation2::Interior,
                        RealSign::Positive,
                        RealSign::Positive,
                        RealSign::Zero,
                        attempt,
                    )
                    .unwrap()
            });
            assert_eq!(outcome.certainty, CurveCertainty::Certified);
            let Classification::Decided(parameter) = outcome.value else {
                panic!("the local tangent contact must retain its circle parameter")
            };
            let BezierAlgebraicCuspSemicircleParameter2::Mapped(mapped) = &parameter else {
                panic!("the tangent contact must keep its selected map")
            };
            let BezierAlgebraicCuspSemicircleMappedParameterData2::SelectedParallelContact {
                parameter: retained,
                ..
            } = mapped.as_ref()
            else {
                panic!("the original contact authority must survive")
            };
            assert!(Arc::ptr_eq(
                &selected.data,
                &retained.as_recursive_projective().unwrap().data
            ));
            for (boundary, expected) in [
                (Real::zero(), std::cmp::Ordering::Greater),
                (q(1, 4), std::cmp::Ordering::Greater),
                (half.clone(), std::cmp::Ordering::Equal),
                (q(3, 4), std::cmp::Ordering::Less),
                (Real::one(), std::cmp::Ordering::Less),
            ] {
                assert_eq!(
                    parameter.order_to_real(&boundary, &policy).unwrap(),
                    Classification::Decided(expected)
                );
            }
            let Classification::Decided(Some(point)) = parameter
                .coincident_point_evidence(&circle, &policy)
                .unwrap()
            else {
                panic!("the local contact must publish its analytic point")
            };
            assert_eq!(
                point.same_point(&Point2::from_values(0, 0).into(), &policy),
                Classification::Decided(true)
            );
            assert_eq!(
                mapped
                    .selected_parallel_contact_source_tangent_dot_sign(
                        &contact,
                        &BezierParameter2::Exact(half.clone()),
                        &policy,
                    )
                    .unwrap(),
                Classification::Decided(None)
            );
        }
    }
}

#[test]
fn selected_parallel_normal_circle_intersects_rational_curves_exactly() {
    let source = QuadraticBezier2::new(
        Point2::from_values(0, 0),
        Point2::from_values(1, 0),
        Point2::from_values(2, 1),
    );
    let center_support = source.parallel_left(Real::one()).unwrap();
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let quarter = (Real::one() / Real::from(4_i8)).unwrap();
    let root_five = Real::from(5_i8).sqrt().unwrap();
    let inverse_speed = (Real::one() / root_five).unwrap();
    let center_x = Real::one() - &inverse_speed;
    let center_y = &quarter + Real::from(2_i8) * &inverse_speed;
    let cutter = RationalBezier2::try_new(
        vec![
            Point2::new(&center_x - Real::from(2_i8), center_y.clone()),
            Point2::new(&center_x + Real::from(2_i8), center_y.clone()),
        ],
        vec![Real::one(), Real::one()],
    )
    .unwrap();

    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let Classification::Decided(Some(circle)) =
            BezierAlgebraicCuspSemicircle2::from_selected_parallel_normal(
                center_support.clone(),
                BezierParameter2::Exact(half.clone()).into(),
                Real::one(),
                false,
                &policy,
            )
            .unwrap()
        else {
            panic!("the non-PH selected circle must construct");
        };
        let Classification::Decided((
            BezierAlgebraicCuspSemicircleRationalIntersections2::Mapped {
                contacts,
                overlaps: unexpected_overlaps,
            },
            Some(parameter_map),
        )) = circle
            .rational_intersections_with_parameter_map(
                &cutter,
                &crate::CurveParameterRange2::unit(),
                &policy,
            )
            .unwrap()
        else {
            panic!("the general selected circle must retain its rational contact");
        };
        assert!(unexpected_overlaps.is_empty(), "unexpected overlaps");
        assert_eq!(contacts.len(), 1);
        let contact = &contacts[0];
        assert_eq!(
            contact
                .other_parameter
                .same_value(
                    &region_parameter(BezierParameter2::Exact(quarter.clone())),
                    &policy,
                )
                .unwrap(),
            Classification::Decided(true),
        );
        assert_eq!(
            contact.location,
            BezierAlgebraicCuspSemicircleContactLocation2::Interior,
        );
        assert_eq!(contact.tangent_cross_sign, RealSign::Positive);
        assert_eq!(
            contact.point.same_point(
                &CurvePoint2::from(Point2::new(&center_x - Real::one(), center_y.clone(),)),
                &policy,
            ),
            Classification::Decided(true),
        );
        let parameter = parameter_map.contact_parameter(contact);
        assert_eq!(
            parameter.order_to_real(&half, &policy).unwrap(),
            Classification::Decided(std::cmp::Ordering::Less),
        );
        let Classification::Decided(Some(mapped_point)) = parameter
            .coincident_point_evidence(&circle, &policy)
            .unwrap()
        else {
            panic!("the mapped rational contact must retain its exact point");
        };
        assert_eq!(
            mapped_point.same_point(&contact.point, &policy),
            Classification::Decided(true),
        );
    }
}

#[test]
fn selected_parallel_normal_circle_keeps_contacts_when_center_refines_to_exact() {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let root_three_half = (Real::from(3_i8).sqrt().unwrap() / Real::from(2_i8)).unwrap();
    let support = QuadraticBezier2::from_line_segment(
        LineSeg2::try_new(Point2::from_values(0, 0), Point2::from_values(1, 0)).unwrap(),
    )
    .parallel_left(Real::zero())
    .unwrap();
    let cutter = RationalBezier2::try_new(
        vec![Point2::from_values(0, -1), Point2::from_values(0, 1)],
        vec![Real::one(), Real::one()],
    )
    .unwrap();
    for (policy, consume_terminal) in [
        (CurveContext::STRICT, false),
        (CurveContext::APPROXIMATE_512, false),
        (CurveContext::APPROXIMATE_512, true),
    ] {
        let Classification::Decided(polynomial) = BezierParameterPolynomial::try_new_power_basis(
            vec![-half.clone(), Real::one()],
            &policy,
        )
        .unwrap() else {
            panic!("the linear center polynomial must construct");
        };
        let Classification::Decided(interval) =
            BezierParameterInterval::try_new(Real::zero(), Real::one(), &policy).unwrap()
        else {
            panic!("the center interval must construct");
        };
        let Classification::Decided(center) =
            BezierAlgebraicParameter2::try_isolate(polynomial, interval, &policy).unwrap()
        else {
            panic!("the center root must isolate");
        };
        let center = BezierParameter2::Algebraic(center);
        assert_eq!(
            center
                .clone()
                .refined_isolating_interval(64, &CurveContext::STRICT),
            BezierParameter2::Exact(half.clone()),
        );
        let Classification::Decided(Some(circle)) =
            BezierAlgebraicCuspSemicircle2::from_selected_parallel_normal(
                support.clone(),
                center.into(),
                Real::one(),
                false,
                &policy,
            )
            .unwrap()
        else {
            panic!("the regular selected circle must construct");
        };
        for circle in [circle.clone(), circle.reversed()] {
            // The circle centered at (1/2, 0) has two irrational contacts
            // with x=0, both in the selected left semicircle.
            let outcome = crate::policy::resolve_certified_value(&policy, |attempt| {
                if consume_terminal {
                    let sine = Real::e().sin();
                    let cosine = Real::e().cos();
                    let zero = &sine * &sine + &cosine * &cosine - Real::one();
                    assert_eq!(real_sign(&zero, attempt), Some(RealSign::Zero));
                }
                circle
                    .rational_intersections(&cutter, &crate::CurveParameterRange2::unit(), attempt)
                    .unwrap()
            });
            assert_eq!(
                outcome.certainty,
                if consume_terminal {
                    CurveCertainty::Approximate512Consumed
                } else {
                    CurveCertainty::Certified
                },
            );
            let Classification::Decided(
                BezierAlgebraicCuspSemicircleRationalIntersections2::SelectedFiber {
                    contacts,
                    overlaps: unexpected_overlaps,
                },
            ) = outcome.value
            else {
                panic!("the exact-center transition must preserve selected-fiber contacts");
            };
            assert!(unexpected_overlaps.is_empty(), "unexpected overlaps");
            assert_eq!(contacts.len(), 2);
            for (contact, (y, cross)) in contacts.iter().zip([
                (-root_three_half.clone(), RealSign::Positive),
                (root_three_half.clone(), RealSign::Negative),
            ]) {
                assert_eq!(
                    contact.location(),
                    BezierAlgebraicCuspSemicircleContactLocation2::Interior,
                );
                assert_eq!(
                    contact.tangent_cross_sign(),
                    if circle.is_clockwise() {
                        product_sign(cross, RealSign::Negative)
                    } else {
                        cross
                    },
                );
                for (axis, coordinate) in [(Axis2::X, Real::zero()), (Axis2::Y, y)] {
                    for replay_policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
                        let replay = contact.point_coordinate_order_to_real(
                            axis,
                            &coordinate,
                            &replay_policy,
                        );
                        if consume_terminal && replay_policy == CurveContext::STRICT {
                            assert!(matches!(replay, Err(CurveError::Topology(_))));
                            continue;
                        }
                        assert_eq!(
                            replay.unwrap(),
                            Classification::Decided(std::cmp::Ordering::Equal),
                        );
                        assert_eq!(
                            contact.tangent_dot_sign(&replay_policy).unwrap(),
                            Classification::Decided(if circle.is_clockwise() {
                                RealSign::Positive
                            } else {
                                RealSign::Negative
                            }),
                        );
                    }
                }
            }
        }
    }
}

#[test]
fn selected_parallel_normal_circle_retains_general_rational_contacts_in_one_fiber() {
    let support = QuadraticBezier2::from_line_segment(
        LineSeg2::try_new(Point2::from_values(0, 0), Point2::from_values(2, 0)).unwrap(),
    )
    .parallel_left(Real::zero())
    .unwrap();
    let cutter = RationalBezier2::try_new(
        vec![
            Point2::from_values(-1, 0),
            Point2::from_values(1, 0),
            Point2::from_values(3, 0),
        ],
        vec![Real::one(), Real::one(), Real::one()],
    )
    .unwrap();
    let independent_parallel = QuadraticBezier2::from_line_segment(
        LineSeg2::try_new(Point2::from_values(0, 0), Point2::from_values(2, 0)).unwrap(),
    )
    .parallel_left(Real::zero())
    .unwrap();
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let quarter = (Real::one() / Real::from(4_i8)).unwrap();

    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let Classification::Decided(polynomial) = BezierParameterPolynomial::try_new_power_basis(
            vec![-half.clone(), Real::zero(), Real::one()],
            &policy,
        )
        .unwrap() else {
            panic!("the selected-center polynomial must construct");
        };
        let Classification::Decided(interval) =
            BezierParameterInterval::try_new(half.clone(), Real::one(), &policy).unwrap()
        else {
            panic!("the selected-center interval must construct");
        };
        let Classification::Decided(center_parameter) =
            BezierAlgebraicParameter2::try_isolate(polynomial, interval, &policy).unwrap()
        else {
            panic!("the selected center must isolate");
        };
        let Classification::Decided(Some(circle)) =
            BezierAlgebraicCuspSemicircle2::from_selected_parallel_normal(
                support.clone(),
                BezierParameter2::Algebraic(center_parameter).into(),
                Real::one(),
                false,
                &policy,
            )
            .unwrap()
        else {
            panic!("the algebraic selected circle must construct");
        };
        let Classification::Decided((
            BezierAlgebraicCuspSemicircleRationalIntersections2::SelectedFiber {
                contacts,
                overlaps: unexpected_overlaps,
            },
            None,
        )) = circle
            .rational_intersections_with_parameter_map(
                &cutter,
                &crate::CurveParameterRange2::unit(),
                &policy,
            )
            .unwrap()
        else {
            panic!("the general rational contact must remain in the selected fiber");
        };
        assert!(unexpected_overlaps.is_empty(), "unexpected overlaps");
        let [contact] = contacts.as_slice() else {
            panic!("the selected half circle must retain exactly its left contact");
        };
        assert_eq!(
            std::mem::size_of::<BezierAlgebraicCuspSemicircleSelectedFiberContact2>(),
            std::mem::size_of::<usize>(),
        );
        assert_eq!(
            contact.location(),
            BezierAlgebraicCuspSemicircleContactLocation2::Interior,
        );
        assert_eq!(contact.tangent_cross_sign(), RealSign::Positive);
        assert_eq!(
            contact
                .other_parameter()
                .order_to_real(&quarter, &policy)
                .unwrap(),
            Classification::Decided(std::cmp::Ordering::Greater),
        );
        assert_eq!(
            contact
                .other_parameter()
                .order_to_real(&half, &policy)
                .unwrap(),
            Classification::Decided(std::cmp::Ordering::Less),
        );
        let cusp_parameter = contact.cusp_parameter();
        assert_eq!(
            cusp_parameter.order_to_real(&half, &policy).unwrap(),
            Classification::Decided(std::cmp::Ordering::Equal),
        );
        assert_eq!(
            contact
                .point_coordinate_order_to_real(Axis2::X, &Real::zero(), &policy)
                .unwrap(),
            Classification::Decided(std::cmp::Ordering::Greater),
        );
        assert_eq!(
            contact
                .point_coordinate_order_to_real(Axis2::Y, &Real::zero(), &policy)
                .unwrap(),
            Classification::Decided(std::cmp::Ordering::Equal),
        );
        let Classification::Decided(bounds) =
            algebraic_chord_endpoint_bounds_refined(&contact.point_evidence(), 8, &policy)
        else {
            panic!("the selected-fiber rational point must refine exactly");
        };
        assert_eq!(
            bounds.contains_point(&Point2::from_values(0, 0), &policy),
            Classification::Decided(false),
        );

        // This independent analytic parallel does not share the
        // intersection map that authored the selected endpoint. The
        // retained-chord authority must still decide their exact tangent
        // relation without adjoining either selected field.
        let fragment = BezierAlgebraicCuspSemicircleFragment2::from_certified_range(
            circle.clone(),
            BezierAlgebraicCuspSemicircleParameter2::Exact(Real::zero()),
            cusp_parameter,
            false,
            &policy,
        );
        assert!(matches!(
            fragment
                .endpoint_tangent_cross_dot_linear_combination_retained_parallel(
                    false,
                    &independent_parallel,
                    &BezierParameter2::Exact(half.clone()),
                    RealSign::Positive,
                    &Real::one(),
                    &Real::zero(),
                    &policy,
                )
                .unwrap(),
            Classification::Decided(Some(RealSign::Positive | RealSign::Negative)),
        ));
    }
}

#[test]
fn selected_center_line_contact_stays_in_recursive_quadratic_solver() {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let support = QuadraticBezier2::from_line_segment(
        LineSeg2::try_new(Point2::from_values(0, 0), Point2::from_values(2, 0)).unwrap(),
    )
    .parallel_left(Real::zero())
    .unwrap();
    let line = LineSeg2::try_new(
        Point2::new(Real::from(-2_i8), half.clone()),
        Point2::new(Real::from(4_i8), half.clone()),
    )
    .unwrap();
    let source = RationalBezier2::try_new(
        vec![
            line.start().translated(Real::zero(), Real::one()),
            line.end().translated(Real::zero(), Real::one()),
        ],
        vec![Real::one(), Real::one()],
    )
    .unwrap();

    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let Classification::Decided(polynomial) = BezierParameterPolynomial::try_new_power_basis(
            vec![-half.clone(), Real::zero(), Real::one()],
            &policy,
        )
        .unwrap() else {
            panic!("the selected center polynomial must construct");
        };
        let Classification::Decided(interval) =
            BezierParameterInterval::try_new(half.clone(), Real::one(), &policy).unwrap()
        else {
            panic!("the selected center interval must construct");
        };
        let Classification::Decided(center_parameter) =
            BezierAlgebraicParameter2::try_isolate(polynomial, interval, &policy).unwrap()
        else {
            panic!("the selected center must isolate");
        };
        let Classification::Decided(Some(circle)) =
            BezierAlgebraicCuspSemicircle2::from_selected_parallel_normal(
                support.clone(),
                BezierParameter2::Algebraic(center_parameter).into(),
                Real::one(),
                false,
                &policy,
            )
            .unwrap()
        else {
            panic!("the selected circle must construct");
        };
        let Classification::Decided(chord) = BezierAlgebraicChord2::try_new(
            CurvePoint2::from(line.start().clone()),
            CurvePoint2::from(line.end().clone()),
            &policy,
        )
        .unwrap() else {
            panic!("the exact cutter chord must construct");
        };
        let Classification::Decided(intersections) = circle
            .recursive_selected_parallel_normal_line_intersections(
                &chord, &line, true, None, &policy,
            )
            .unwrap()
        else {
            panic!("the selected-center circle/line incidence must decide");
        };
        let Classification::Decided(contacts) = circle
            .retain_chord_intersections(&chord, intersections, &policy)
            .unwrap()
        else {
            panic!("the recursive line contacts must retain");
        };
        let contact = contacts
            .iter()
            .find(|contact| {
                matches!(
                    &contact.point,
                    CurvePoint2(CurvePointData2::AlgebraicCuspChord(point))
                        if point.map_contact().0.recursive_quadratic_line_system().is_some()
                )
            })
            .expect("the line contact must retain its recursive quadratic map");
        let CurvePoint2(CurvePointData2::AlgebraicCuspChord(point)) = &contact.point else {
            unreachable!("the recursive contact was matched above")
        };
        let point = CurvePoint2::from(point.translated(&Real::zero(), &Real::one()));

        let parameters = chord.collinear_source_parameters_at_chord_endpoint(
            &source,
            &point,
            &CurveParameterRange2::unit(),
            &policy,
        );
        let Classification::Decided(parameters) = parameters.unwrap() else {
            panic!("the selected-center endpoint must invert recursively");
        };
        let [parameter] = parameters.as_slice() else {
            panic!("the monotone line must retain one source parameter");
        };
        let parameter = parameter
            .as_recursive_projective()
            .expect("the source cut must retain its recursive scalar");
        assert_eq!(
            parameter.order_to_real(&Real::zero(), &policy).unwrap(),
            Classification::Decided(std::cmp::Ordering::Greater),
        );
        assert_eq!(
            parameter.order_to_real(&Real::one(), &policy).unwrap(),
            Classification::Decided(std::cmp::Ordering::Less),
        );
        // Reuse the recursive scalar directly as an incident endpoint on
        // an unrelated nonlinear analytic carrier.  Its source speed is
        // `4 + 4t^2`, so this exercises homogeneous polynomial replay in
        // the retained field rather than a constant-line shortcut or a
        // global scalar projection.
        let incident_parallel = QuadraticBezier2::new(
            Point2::from_values(0, 0),
            Point2::from_values(1, 0),
            Point2::from_values(2, 1),
        )
        .parallel_left(Real::zero())
        .unwrap();
        assert_eq!(
            parameter
                .polynomial_sign(&[Real::from(4_i8), Real::zero(), Real::from(4_i8)], &policy,)
                .unwrap(),
            Classification::Decided(RealSign::Positive),
        );
        assert_eq!(
            parameter
                .polynomial_sign(&[Real::zero(), Real::one(), -Real::one()], &policy)
                .unwrap(),
            Classification::Decided(RealSign::Positive),
        );
        assert_eq!(
            parameter
                .polynomial_sign(&[-Real::one(), Real::one()], &policy)
                .unwrap(),
            Classification::Decided(RealSign::Negative),
        );
        let endpoint = CurveParameter2::from_recursive_projective(parameter.clone());
        let Classification::Decided(anchor_tangent) =
            BezierAlgebraicChord2::from_certified_retained_parallel_unit_tangent(
                incident_parallel.clone(),
                &endpoint,
                &policy,
            )
            .unwrap()
        else {
            panic!("the recursive analytic tangent must construct locally");
        };
        for point in [&anchor_tangent.data.start, &anchor_tangent.data.end] {
            let CurvePoint2(CurvePointData2::AnalyticParallel(point)) = point else {
                panic!("the retained analytic tangent must preserve its point carrier");
            };
            assert!(matches!(
                &point.data.parameter,
                BezierAnalyticParallelPointParameter2::RecursiveProjective(_)
            ));
        }
        let Classification::Decided(incident) = incident_parallel
            .incident_domain_from_parameter(
                &endpoint,
                BezierParameterRayDirection2::Increasing,
                &policy,
            )
            .unwrap()
        else {
            panic!("the recursive endpoint must retain its local incident ray");
        };
        assert!(incident.endpoint().as_recursive_projective().is_some());
        assert!(incident.barrier().is_none());
        assert_eq!(
            incident
                .contains_extension_parameter(
                    &CurveParameter2::from(BezierParameter2::Exact(Real::from(2_i8),)),
                    &policy,
                )
                .unwrap(),
            Classification::Decided(true),
        );
        // Point reconstruction must keep this same recursive scalar in
        // place.  Compare the zero- and unit-left-parallel points inside
        // the resulting tower: their exact squared separation is one.
        let source_point = BezierAnalyticParallelPoint2::new_with_tangent_distance_parameter(
            incident_parallel.clone(),
            BezierAnalyticParallelPointParameter2::RecursiveProjective(parameter.clone()),
            Real::zero(),
            &policy,
        );
        let offset_point = BezierAnalyticParallelPoint2::new_with_tangent_distance_parameter(
            incident_parallel.with_distance(Real::one()),
            BezierAnalyticParallelPointParameter2::RecursiveProjective(parameter.clone()),
            Real::zero(),
            &policy,
        );
        assert!(matches!(
            &offset_point.data.parameter,
            BezierAnalyticParallelPointParameter2::RecursiveProjective(_)
        ));
        let Classification::Decided(Some(source_point)) =
            source_point.recursive_projective_point(&policy).unwrap()
        else {
            panic!("the recursive source point must remain in its retained field");
        };
        let Classification::Decided(Some(offset_point)) =
            offset_point.recursive_projective_point(&policy).unwrap()
        else {
            panic!("the recursive parallel point must adjoin its exact source speed");
        };
        let field = offset_point.denominator.field();
        let source_point = source_point
            .lifted_to(&field)
            .expect("the source point field must be ancestral to its parallel point");
        let (delta_x, delta_y, denominator) = offset_point
            .difference_numerators(&source_point)
            .expect("the retained parallel points must share one field");
        let distance_residual = delta_x
            .square()
            .and_then(|x| delta_y.square().and_then(|y| x.add(&y)))
            .and_then(|distance| {
                denominator
                    .square()
                    .and_then(|unit| distance.subtract(&unit))
            })
            .expect("the unit-distance replay must fit its retained field");
        assert_eq!(
            distance_residual.sign(&policy).unwrap(),
            Classification::Decided(RealSign::Zero),
        );

        // The affine carrier keeps both setback parameters in the same
        // recursive projective scalar instead of globalizing the center.
        // Its source is P(t)=(2t,0), so a half-unit setback translates
        // the parameter by exactly one quarter in each direction.
        let Classification::Decided(affine_cuts) = support
            .fixed_distance_incidence_from_recursive_parameter(
                &support,
                &endpoint,
                &half,
                &CurveParameterRange2::unit(),
                None,
                &policy,
            )
            .unwrap()
        else {
            panic!("the affine recursive setback must decide");
        };
        let [first, second] = affine_cuts.as_slice() else {
            panic!("the affine recursive setback must retain both cuts");
        };
        assert!(first.as_recursive_projective().is_some());
        assert!(second.as_recursive_projective().is_some());
        assert_eq!(
            first.cmp_by_refinement(&endpoint, &policy).unwrap(),
            Classification::Decided(std::cmp::Ordering::Less),
        );
        assert_eq!(
            second.cmp_by_refinement(&endpoint, &policy).unwrap(),
            Classification::Decided(std::cmp::Ordering::Greater),
        );
        let wide_setback = Real::from(2_i8);
        assert!(matches!(
            support
                .fixed_distance_incidence_from_recursive_parameter(
                    &support, &endpoint,
                    &wide_setback,
                    &CurveParameterRange2::unit(),
                    None,
                    &policy,
                )
                .unwrap(),
            Classification::Decided(ref cuts) if cuts.is_empty()
        ));
        for (direction, expected) in [
            (
                BezierParameterRayDirection2::Decreasing,
                std::cmp::Ordering::Less,
            ),
            (
                BezierParameterRayDirection2::Increasing,
                std::cmp::Ordering::Greater,
            ),
        ] {
            let Classification::Decided(cuts) = support
                .fixed_distance_incidence_from_recursive_parameter(
                    &support,
                    &endpoint,
                    &wide_setback,
                    &CurveParameterRange2::unit(),
                    Some(direction),
                    &policy,
                )
                .unwrap()
            else {
                panic!("the affine recursive incident setback must decide");
            };
            let [cut] = cuts.as_slice() else {
                panic!("the affine incident cell must retain exactly its directed cut");
            };
            assert!(cut.as_recursive_projective().is_some());
            let boundary = match direction {
                BezierParameterRayDirection2::Decreasing => Real::zero(),
                BezierParameterRayDirection2::Increasing => Real::one(),
            };
            assert_eq!(
                cut.cmp_by_refinement(&boundary.into(), &policy).unwrap(),
                Classification::Decided(expected),
            );
        }

        // Exercise the public region editor at the recursive start of an
        // affine selected-fiber boundary. The selected side must consume
        // the compact translated cut above and rebuild the boundary
        // without routing through global parameter promotion.
        let start_point = CurvePoint2::from(
            BezierAnalyticParallelPoint2::new_with_tangent_distance_parameter(
                support.clone(),
                BezierAnalyticParallelPointParameter2::RecursiveProjective(parameter.clone()),
                Real::zero(),
                &policy,
            ),
        );
        let end_point = CurvePoint2::from(Point2::from_values(2, 0));
        let apex = CurvePoint2::from(Point2::from_values(2, 1));
        let selected = BezierSplitFragment2::SelectedFiber(
            crate::bezier_split::BezierSelectedFiberFragment2::new(
                crate::bezier_split::BezierSelectedFiberSource2::AnalyticParallel(support.clone()),
                CurveParameterRange2::new_validated(
                    endpoint.clone(),
                    CurveParameter2::from(BezierParameter2::Exact(Real::one())),
                ),
                start_point.clone(),
                end_point.clone(),
            ),
        );
        let vertical = BezierSplitFragment2::Materialized {
            start: BezierParameter2::Exact(Real::zero()),
            end: BezierParameter2::Exact(Real::one()),
            curve: BezierSubcurve2::Quadratic(QuadraticBezier2::from_line_segment(
                LineSeg2::try_new(Point2::from_values(2, 0), Point2::from_values(2, 1)).unwrap(),
            )),
        };
        let Classification::Decided(closing) =
            BezierAlgebraicChord2::try_new(apex, start_point, &policy).unwrap()
        else {
            panic!("the recursive selected-fiber fixture must retain its closing chord");
        };
        let boundary = CurveRegionBoundaryLoop2::new(
            vec![
                selected,
                vertical,
                BezierSplitFragment2::AlgebraicChord(closing),
            ],
            &policy,
        )
        .expect("the recursive selected-fiber triangle must close");
        let region = CurveRegion2::try_new_with_loop_topology(
            vec![boundary],
            vec![CurveRegionLoopRole::Material],
            vec![FillRule::NonZero],
            vec![CurveBoundaryInteriorSide2::Left],
        )
        .unwrap();
        let setback = (Real::one() / Real::from(16_i8)).unwrap();
        let chamfers = region
            .chamfer_loop_vertex_by_setbacks(
                0,
                0,
                setback.clone(),
                setback,
                CurveCornerMode2::TrimOnly,
                &policy,
            )
            .unwrap_or_else(|error| {
                panic!(
                    "the recursive selected-fiber corner must chamfer under {policy:?}: {error:?}"
                )
            });
        assert_eq!(chamfers.certainty, CurveCertainty::Certified);
        let retains_recursive_cut = |region: &CurveRegion2| {
            region.boundary_loops()[0]
                .fragments()
                .iter()
                .any(|fragment| {
                    let BezierSplitFragment2::SelectedFiber(fragment) = fragment else {
                        return false;
                    };
                    fragment.range().start().as_recursive_projective().is_some()
                        || fragment.range().end().as_recursive_projective().is_some()
                })
        };
        assert!(match &chamfers.value {
            CurveCornerSolutions2::Unique(region) => retains_recursive_cut(region),
            CurveCornerSolutions2::Multiple(regions) => regions.iter().any(retains_recursive_cut),
            CurveCornerSolutions2::NoSolution(reason) => {
                panic!("the recursive selected-center corner had no chamfer: {reason:?}")
            }
        });
    }
}

#[test]
fn weighted_selected_center_tangent_line_stays_recursive() {
    let ratio =
        |numerator: i8, denominator: i8| (Real::from(numerator) / Real::from(denominator)).unwrap();
    // In power form, W=1+t, X=(t^2-1/2)(t+1/2), and
    // Y=(t^2-1/2)^2. At alpha=sqrt(1/2), P(alpha)=(0,0)
    // and P'(alpha)=(1,0), while the varying homogeneous weight and
    // genuinely curved source keep both W and the non-square speed
    // polynomial active in the recursive line geometry.
    let source = RationalBezier2::try_new(
        vec![
            Point2::new(ratio(-1, 4), ratio(1, 4)),
            Point2::new(ratio(-3, 10), ratio(1, 5)),
            Point2::new(ratio(-5, 18), ratio(1, 18)),
            Point2::new(ratio(-1, 14), ratio(-1, 7)),
            Point2::new(ratio(3, 8), ratio(1, 8)),
        ],
        vec![
            Real::one(),
            ratio(5, 4),
            ratio(3, 2),
            ratio(7, 4),
            Real::from(2_i8),
        ],
    )
    .unwrap();
    let center_distance = ratio(1, 3);
    let radius = ratio(2, 3);
    let support = source.parallel_left(center_distance).unwrap();
    let tangent_line =
        LineSeg2::try_new(Point2::from_values(-1, 1), Point2::from_values(1, 1)).unwrap();

    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let Classification::Decided(polynomial) = BezierParameterPolynomial::try_new_power_basis(
            vec![ratio(-1, 2), Real::zero(), Real::one()],
            &policy,
        )
        .unwrap() else {
            panic!("the weighted center polynomial must construct");
        };
        let Classification::Decided(interval) =
            BezierParameterInterval::try_new(ratio(1, 2), Real::one(), &policy).unwrap()
        else {
            panic!("the weighted center interval must construct");
        };
        let Classification::Decided(center_parameter) =
            BezierAlgebraicParameter2::try_isolate(polynomial, interval, &policy).unwrap()
        else {
            panic!("the weighted center must isolate");
        };
        assert_eq!(
            crate::tests::decided(
                source
                    .point_at_algebraic_parameter(&center_parameter, &policy)
                    .unwrap()
            )
            .exact_point(&CurveContext::STRICT),
            Some(Point2::from_values(0, 0)),
        );
        let Classification::Decided(Some(circle)) =
            BezierAlgebraicCuspSemicircle2::from_selected_parallel_normal(
                support.clone(),
                BezierParameter2::Algebraic(center_parameter).into(),
                radius.clone(),
                false,
                &policy,
            )
            .unwrap()
        else {
            panic!("the weighted selected circle must construct");
        };
        let Classification::Decided(chord) = BezierAlgebraicChord2::try_new(
            CurvePoint2::from(tangent_line.start().clone()),
            CurvePoint2::from(tangent_line.end().clone()),
            &policy,
        )
        .unwrap() else {
            panic!("the tangent cutter chord must construct");
        };
        let Classification::Decided(intersections) = circle
            .recursive_selected_parallel_normal_line_intersections(
                &chord,
                &tangent_line,
                true,
                None,
                &policy,
            )
            .unwrap()
        else {
            panic!("the weighted tangent incidence must decide");
        };
        let BezierAlgebraicCuspSemicircleChordIntersections2::Contacts {
            contacts: mapped_contacts,
            parameter_map,
        } = &intersections
        else {
            panic!("the tangent line must publish its recursive contact map");
        };
        let [mapped_contact] = mapped_contacts.as_slice() else {
            panic!("a tangent line must publish exactly one mapped contact");
        };
        let retained = parameter_map
            .recursive_quadratic_line_system()
            .expect("the weighted line must use the recursive quadratic system")
            .contact(mapped_contact.branch)
            .unwrap();
        assert_eq!(retained.branch, 0);
        assert_eq!(
            retained
                .parameter
                .order_to_real(&ratio(1, 2), &policy)
                .unwrap(),
            Classification::Decided(std::cmp::Ordering::Equal),
        );
        let Classification::Decided(contacts) = circle
            .retain_chord_intersections(&chord, intersections, &policy)
            .unwrap()
        else {
            panic!("the weighted tangent contact must retain");
        };
        let [contact] = contacts.as_slice() else {
            panic!("a tangent line must retain exactly one contact");
        };
        assert_eq!(contact.tangent_cross_sign, RealSign::Zero);
        assert_eq!(
            contact
                .cusp_parameter
                .order_to_real(&Real::zero(), &policy)
                .unwrap(),
            Classification::Decided(std::cmp::Ordering::Equal),
        );
        assert_eq!(
            contact
                .point
                .same_point(&CurvePoint2::from(Point2::from_values(0, 1),), &policy,),
            Classification::Decided(true),
        );
    }
}

#[test]
fn recursive_projective_center_projects_complete_nonlinear_fixed_distance() {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let center = algebraic_parameter(vec![-half, Real::zero(), Real::one()]);
    let center_source = bezier_parameter_root_representation(&center);
    let one = DenseTensorPolynomial::from_axis_polynomial(1, 0, &[Real::one()])
        .expect("the shallow recursive base must retain its unit");
    let coordinate =
        DenseTensorPolynomial::from_axis_polynomial(1, 0, &[Real::zero(), Real::one()])
            .expect("the shallow recursive base must retain its coordinate");
    let curved_source_parallel = QuadraticBezier2::new(
        Point2::from_values(0, 0),
        Point2::from_values(1, 0),
        Point2::from_values(2, 1),
    )
    .parallel_left(Real::zero())
    .unwrap();
    let setback = (Real::one() / Real::from(16_i8)).unwrap();
    let setback_squared = &setback * &setback;

    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        for parallel in [
            curved_source_parallel.clone(),
            QuadraticBezier2::new(
                Point2::from_values(0, 0),
                Point2::new((Real::one() / Real::from(2_i8)).unwrap(), Real::zero()),
                Point2::from_values(2, 0),
            )
            .parallel_left((Real::one() / Real::from(4_i8)).unwrap())
            .unwrap(),
        ] {
            let field = BezierRecursiveQuadraticField2::base(
                vec![center_source.clone()],
                one.clone(),
                one.clone(),
            )
            .expect("the shallow recursive base must construct");
            let BezierRecursiveQuadraticField2::Base(base) = &field else {
                unreachable!("the shallow recursive field begins at its base")
            };
            let scalar = BezierRecursiveQuadraticProjectiveScalar2 {
                numerator: recursive_quadratic_rational_value(base, coordinate.clone())
                    .expect("the shallow recursive coordinate must embed"),
                denominator: field
                    .constant(Real::one())
                    .expect("the shallow recursive coordinate must retain its denominator"),
            };
            let Classification::Decided(center_parameter) =
                BezierRecursiveProjectiveParameter2::new(scalar, &policy).unwrap()
            else {
                panic!("the shallow recursive center must construct");
            };
            let endpoint = CurveParameter2::from_recursive_projective(center_parameter.clone());
            let Classification::Decided(cuts) = parallel
                .fixed_distance_incidence_from_recursive_parameter(
                    &parallel,
                    &endpoint,
                    &setback,
                    &CurveParameterRange2::unit(),
                    None,
                    &policy,
                )
                .unwrap()
            else {
                panic!(
                    "the nonlinear recursive setback must decide under {policy:?} at distance {}",
                    parallel.distance(),
                );
            };
            assert!(
                !cuts.is_empty(),
                "the interior recursive center must retain a nearby nonlinear cut",
            );
            // Candidate charts Q(v)=P(2v) and Q(v)=P(v-2)
            // retain the center in its own chart. The latter consumes
            // [2,3], so a unit-only scheduler loses every exact contact.
            for (scale, shift, range) in [
                (Real::from(2), Real::zero(), CurveParameterRange2::unit()),
                (
                    Real::one(),
                    Real::from(-2),
                    CurveParameterRange2::new_validated(Real::from(2).into(), Real::from(3).into()),
                ),
            ] {
                let Classification::Decided(candidate_support) = parallel
                    .source()
                    .to_rational_bezier()
                    .unwrap()
                    .subcurve_between_affine_exact(&shift, &(&shift + &scale), &policy)
                    .unwrap()
                else {
                    panic!("the independent polynomial support chart must construct")
                };
                let candidate_support = candidate_support
                    .parallel_left(parallel.distance().clone())
                    .unwrap();
                for center_parameter in [endpoint.clone(), CurveParameter2::from(center.clone())] {
                    let Classification::Decided(reparameterized) = candidate_support
                        .fixed_distance_incidence(
                            &parallel,
                            &center_parameter,
                            &setback,
                            &range,
                            None,
                            &policy,
                        )
                        .unwrap()
                    else {
                        panic!("the center must remain in its own support chart")
                    };
                    assert_eq!(reparameterized.len(), cuts.len());
                    for parameter in &reparameterized {
                        let Classification::Decided(parameter) = parameter
                            .affine_image_unbounded(&scale, &shift, &policy)
                            .unwrap()
                        else {
                            panic!("the candidate chart map must preserve the selected scalar")
                        };
                        assert!(cuts.iter().any(|original| {
                            parameter.cmp_by_refinement(original, &policy).unwrap()
                                == Classification::Decided(std::cmp::Ordering::Equal)
                        }));
                    }
                }
            }
            // A recursive endpoint remains the finite ownership boundary
            // even when the center takes the ordinary algebraic route.
            for reversed in [false, true] {
                let (start, end) = if reversed {
                    (Real::one().into(), endpoint.clone())
                } else {
                    (endpoint.clone(), Real::one().into())
                };
                let range = CurveParameterRange2::new_validated(start, end);
                for center_parameter in [endpoint.clone(), CurveParameter2::from(center.clone())] {
                    let Classification::Decided(selected) = parallel
                        .fixed_distance_incidence(
                            &parallel,
                            &center_parameter,
                            &setback,
                            &range,
                            None,
                            &policy,
                        )
                        .unwrap()
                    else {
                        panic!("recursive range ownership must decide")
                    };
                    assert_eq!(selected.len(), 1);
                    assert_eq!(
                        selected[0].cmp_by_refinement(&endpoint, &policy).unwrap(),
                        Classification::Decided(std::cmp::Ordering::Greater)
                    );
                }
            }
            if parallel.distance().zero_status() != ZeroKnowledge::Zero {
                assert_eq!(cuts.len(), 2);
                for expected in [std::cmp::Ordering::Less, std::cmp::Ordering::Greater] {
                    assert!(cuts.iter().any(|candidate| {
                        let Some(candidate) = candidate.as_bezier_parameter() else {
                            return false;
                        };
                        candidate.cmp_by_refinement(&center, &policy).unwrap()
                            == Classification::Decided(expected)
                    }));
                }
                continue;
            }
            let center_evidence = CurvePoint2::from(
                BezierAnalyticParallelPoint2::new_with_tangent_distance_parameter(
                    parallel.clone(),
                    BezierAnalyticParallelPointParameter2::RecursiveProjective(center_parameter),
                    Real::zero(),
                    &policy,
                ),
            );
            for candidate in cuts {
                let Some(candidate) = candidate.as_bezier_parameter() else {
                    panic!("the nonlinear recursive solve must project only its candidate");
                };
                let candidate_evidence = CurvePoint2::from(BezierAnalyticParallelPoint2::new(
                    parallel.clone(),
                    candidate.clone(),
                    &policy,
                ));
                let Classification::Decided(Some(points)) = recursive_projective_evidence_points(
                    &[&center_evidence, &candidate_evidence],
                    &policy,
                )
                .unwrap() else {
                    panic!("the recursive fixed-distance points must share one tower");
                };
                let [center_point, candidate_point] = points.as_slice() else {
                    unreachable!("the two setback evidences must produce two points")
                };
                let (delta_x, delta_y, denominator) = candidate_point
                    .difference_numerators(center_point)
                    .expect("the recursive fixed-distance points must share one field");
                let residual = delta_x
                    .square()
                    .and_then(|x| delta_y.square().and_then(|y| x.add(&y)))
                    .and_then(|distance| {
                        denominator
                            .square()
                            .and_then(|scale| scale.scale(&setback_squared))
                            .and_then(|radius| distance.subtract(&radius))
                    })
                    .expect("the recursive fixed-distance residual must fit its field");
                assert_eq!(
                    residual.sign(&policy).unwrap(),
                    Classification::Decided(RealSign::Zero),
                );
            }
        }
    }
}

#[test]
fn selected_parallel_normal_circle_retains_general_rational_overlaps_in_one_fiber() {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let one_third = (Real::one() / Real::from(3_i8)).unwrap();
    let quarter = (Real::one() / Real::from(4_i8)).unwrap();
    // x(t)=t+t^2 and alpha^2+alpha=1/2 make the selected
    // algebraic frame's Cartesian center exactly (1/2, 0). The retained
    // alpha remains genuinely algebraic, so the coincident rational
    // quarter circle must be proven in the selected fiber rather than by
    // the rational-frame circle fast path.
    let support = QuadraticBezier2::new(
        Point2::from_values(0, 0),
        Point2::new(half.clone(), Real::zero()),
        Point2::from_values(2, 0),
    )
    .parallel_left(Real::zero())
    .unwrap();
    let quarter_circle = RationalBezier2::from(
        RationalQuadraticBezier2::try_new(
            Point2::new(half.clone(), Real::one()),
            Point2::new(-half.clone(), Real::one()),
            Point2::new(-half.clone(), Real::zero()),
            Real::one(),
            Real::one(),
            Real::from(2_i8),
        )
        .unwrap(),
    );
    // v=4u(1-u) folds the same quarter-circle image at u=1/2.
    // The component replay must retain both monotone cells and their
    // opposite orientations.
    let eleven = Real::from(11_i8);
    let folded_quarter = RationalBezier2::try_new(
        vec![
            Point2::new(half.clone(), Real::one()),
            Point2::new(half.clone() - Real::from(2_i8), Real::one()),
            Point2::new(
                &half - (Real::from(8_i8) / &eleven).unwrap(),
                (Real::from(-5_i8) / &eleven).unwrap(),
            ),
            Point2::new(half.clone() - Real::from(2_i8), Real::one()),
            Point2::new(half.clone(), Real::one()),
        ],
        vec![
            Real::one(),
            Real::one(),
            (&eleven / Real::from(3_i8)).unwrap(),
            Real::one(),
            Real::one(),
        ],
    )
    .unwrap();
    let opposite_quarter = RationalBezier2::from(
        RationalQuadraticBezier2::try_new(
            Point2::new(half.clone(), Real::one()),
            Point2::new(&half + Real::one(), Real::one()),
            Point2::new(&half + Real::one(), Real::zero()),
            Real::one(),
            Real::one(),
            Real::from(2_i8),
        )
        .unwrap(),
    );

    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let Classification::Decided(polynomial) = BezierParameterPolynomial::try_new_power_basis(
            vec![-half.clone(), Real::one(), Real::one()],
            &policy,
        )
        .unwrap() else {
            panic!("the selected-center polynomial must construct");
        };
        let Classification::Decided(interval) =
            BezierParameterInterval::try_new(Real::zero(), half.clone(), &policy).unwrap()
        else {
            panic!("the selected-center interval must construct");
        };
        let Classification::Decided(center_parameter) =
            BezierAlgebraicParameter2::try_isolate(polynomial, interval, &policy).unwrap()
        else {
            panic!("the selected center must isolate");
        };
        let Classification::Decided(Some(circle)) =
            BezierAlgebraicCuspSemicircle2::from_selected_parallel_normal(
                support.clone(),
                BezierParameter2::Algebraic(center_parameter).into(),
                Real::one(),
                false,
                &policy,
            )
            .unwrap()
        else {
            panic!("the algebraic selected circle must construct");
        };
        let Classification::Decided(
            BezierAlgebraicCuspSemicircleRationalIntersections2::SelectedFiber {
                overlaps,
                contacts: unexpected_contacts,
            },
        ) = circle
            .rational_intersections(
                &quarter_circle,
                &crate::CurveParameterRange2::unit(),
                &policy,
            )
            .unwrap()
        else {
            panic!("the rational circle component must remain in the selected fiber");
        };
        assert!(unexpected_contacts.is_empty(), "unexpected contacts");
        let [overlap] = overlaps.as_slice() else {
            panic!("the selected rational quarter must retain one monotone overlap");
        };
        assert_eq!(overlap.orientation(), CurveOverlapOrientation2::Same,);
        assert_eq!(
            overlap
                .other_start_parameter()
                .order_to_real(&Real::zero(), &policy)
                .unwrap(),
            Classification::Decided(std::cmp::Ordering::Equal),
        );
        assert_eq!(
            overlap
                .other_end_parameter()
                .order_to_real(&Real::one(), &policy)
                .unwrap(),
            Classification::Decided(std::cmp::Ordering::Equal),
        );
        assert_eq!(
            overlap
                .cusp_start_parameter()
                .order_to_real(&Real::zero(), &policy)
                .unwrap(),
            Classification::Decided(std::cmp::Ordering::Equal),
        );
        assert_eq!(
            overlap
                .cusp_end_parameter()
                .order_to_real(&half, &policy)
                .unwrap(),
            Classification::Decided(std::cmp::Ordering::Equal),
        );

        let Classification::Decided(other_cut) = overlap
            .other_parameter_for_cusp(
                &BezierAlgebraicCuspSemicircleParameter2::Exact(quarter.clone()),
                &policy,
            )
            .unwrap()
        else {
            panic!("an exact cusp cut must invert into the selected rational fiber");
        };
        assert_eq!(
            other_cut.order_to_real(&one_third, &policy).unwrap(),
            Classification::Decided(std::cmp::Ordering::Equal),
        );
        let Classification::Decided(round_trip) = overlap
            .cusp_parameter_for_other(&other_cut, &policy)
            .unwrap()
        else {
            panic!("the selected rational cut must map back to the cusp domain");
        };
        assert_eq!(
            round_trip.order_to_real(&quarter, &policy).unwrap(),
            Classification::Decided(std::cmp::Ordering::Equal),
        );
        let Classification::Decided(point) = overlap
            .point_evidence_for_other(&other_cut, &policy)
            .unwrap()
        else {
            panic!("the selected rational cut must retain exact point evidence");
        };
        assert_eq!(
            point.same_point(
                &CurvePoint2::from(Point2::new(
                    -(Real::one() / Real::from(10_i8)).unwrap(),
                    (Real::from(4_i8) / Real::from(5_i8)).unwrap(),
                )),
                &policy,
            ),
            Classification::Decided(true),
        );

        let Classification::Decided(
            BezierAlgebraicCuspSemicircleRationalIntersections2::SelectedFiber {
                overlaps: reversed_overlaps,
                contacts: unexpected_contacts,
            },
        ) = circle
            .rational_intersections(
                &quarter_circle.reversed(),
                &crate::CurveParameterRange2::unit(),
                &policy,
            )
            .unwrap()
        else {
            panic!("rational reversal must retain the selected-fiber component");
        };
        assert!(unexpected_contacts.is_empty(), "unexpected contacts");
        let [reversed] = reversed_overlaps.as_slice() else {
            panic!("the reversed quarter must retain one overlap");
        };
        assert_eq!(reversed.orientation(), CurveOverlapOrientation2::Reversed,);
        let Classification::Decided(reversed_cut) = reversed
            .other_parameter_for_cusp(
                &BezierAlgebraicCuspSemicircleParameter2::Exact(quarter.clone()),
                &policy,
            )
            .unwrap()
        else {
            panic!("the reversed selected overlap must invert exactly");
        };
        assert_eq!(
            reversed_cut
                .order_to_real(&(Real::one() - &one_third), &policy)
                .unwrap(),
            Classification::Decided(std::cmp::Ordering::Equal),
        );

        let Classification::Decided(
            BezierAlgebraicCuspSemicircleRationalIntersections2::SelectedFiber {
                overlaps: folded,
                contacts: unexpected_contacts,
            },
        ) = circle
            .rational_intersections(
                &folded_quarter,
                &crate::CurveParameterRange2::unit(),
                &policy,
            )
            .unwrap()
        else {
            panic!("a stationary selected-fiber circle must split into monotone overlaps");
        };
        assert!(unexpected_contacts.is_empty(), "unexpected contacts");
        assert_eq!(folded.len(), 2);
        assert_eq!(folded[0].orientation(), CurveOverlapOrientation2::Same,);
        assert_eq!(folded[1].orientation(), CurveOverlapOrientation2::Reversed,);
        for (overlap, expected_start, expected_end) in [
            (&folded[0], Real::zero(), half.clone()),
            (&folded[1], half.clone(), Real::one()),
        ] {
            assert_eq!(
                overlap
                    .other_start_parameter()
                    .order_to_real(&expected_start, &policy)
                    .unwrap(),
                Classification::Decided(std::cmp::Ordering::Equal),
            );
            assert_eq!(
                overlap
                    .other_end_parameter()
                    .order_to_real(&expected_end, &policy)
                    .unwrap(),
                Classification::Decided(std::cmp::Ordering::Equal),
            );
        }

        let Classification::Decided(
            BezierAlgebraicCuspSemicircleRationalIntersections2::SelectedFiber {
                contacts: opposite_contacts,
                overlaps: unexpected_overlaps,
            },
        ) = circle
            .rational_intersections(
                &opposite_quarter,
                &crate::CurveParameterRange2::unit(),
                &policy,
            )
            .unwrap()
        else {
            panic!("an opposite selected-fiber quarter must retain its shared endpoint");
        };
        assert!(unexpected_overlaps.is_empty(), "unexpected overlaps");
        let [opposite_contact] = opposite_contacts.as_slice() else {
            panic!("the opposite quarter must touch exactly one selected endpoint");
        };
        assert_eq!(
            opposite_contact.location(),
            BezierAlgebraicCuspSemicircleContactLocation2::Start,
        );
        assert_eq!(opposite_contact.tangent_cross_sign(), RealSign::Zero);
    }
}

#[test]
fn genuine_parallel_algebraic_ray_replays_the_unsquared_branch() {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let quarter = (Real::one() / Real::from(4_i8)).unwrap();
    let source = QuadraticBezier2::new(
        Point2::from_values(0, 0),
        Point2::new(half.clone(), Real::zero()),
        Point2::from_values(1, 1),
    );
    let parallel = source.parallel_left(quarter).unwrap();
    let query_curve = RationalBezier2::try_new(
        vec![Point2::from_values(0, 0), Point2::from_values(0, 1)],
        vec![Real::one(), Real::one()],
    )
    .unwrap();

    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        assert!(matches!(
            parallel.exact_rational_parallel_component(&policy).unwrap(),
            Classification::Decided(None)
        ));
        let Classification::Decided(polynomial) = BezierParameterPolynomial::try_new_power_basis(
            vec![-half.clone(), Real::zero(), Real::one()],
            &policy,
        )
        .unwrap() else {
            panic!("the algebraic query polynomial must construct");
        };
        let Classification::Decided(interval) =
            BezierParameterInterval::try_new(half.clone(), Real::one(), &policy).unwrap()
        else {
            panic!("the algebraic query interval must construct");
        };
        let Classification::Decided(parameter) =
            BezierAlgebraicParameter2::try_isolate(polynomial, interval, &policy).unwrap()
        else {
            panic!("the algebraic query parameter must isolate");
        };
        let query = crate::tests::decided(
            query_curve
                .point_at_algebraic_parameter(&parameter, &policy)
                .unwrap(),
        );
        let Classification::Decided(query) = query.predicate_evaluator(&policy).unwrap() else {
            panic!("the algebraic query predicate must construct");
        };
        let range = CurveParameterRange2::from_bezier_range(BezierParameterRange2::new_validated(
            BezierParameter2::Exact(Real::zero()),
            BezierParameter2::Exact(Real::one()),
        ));
        let endpoint = |parameter: Real| {
            let Classification::Decided(point) = parallel.point_at(&parameter, &policy).unwrap()
            else {
                panic!("the represented parallel endpoint must evaluate");
            };
            CurvePoint2::from(point)
        };
        let endpoints = [endpoint(Real::zero()), endpoint(Real::one())];
        let Classification::Decided(forward) = BezierParallelAlgebraicRay2::try_new(
            parallel.clone(),
            range.clone(),
            false,
            endpoints.clone(),
            &policy,
        )
        .unwrap() else {
            panic!("the genuine parallel ray evaluator must construct");
        };
        assert_eq!(
            forward
                .endpoint_side_signs(&query, &Real::zero(), &Real::one(), &policy,)
                .unwrap(),
            Classification::Decided([RealSign::Negative, RealSign::Positive]),
        );
        assert_eq!(
            forward.contains_point(&query, None, &policy).unwrap(),
            Classification::Decided(false),
        );
        assert_eq!(
            forward
                .forward_ray_winding_delta(&query, &Real::one(), &Real::zero(), &policy,)
                .unwrap(),
            Classification::Decided(1),
        );

        let Classification::Decided(reversed) = BezierParallelAlgebraicRay2::try_new(
            parallel.clone(),
            range.clone(),
            true,
            endpoints.clone(),
            &policy,
        )
        .unwrap() else {
            panic!("the reversed genuine parallel ray evaluator must construct");
        };
        assert_eq!(
            reversed
                .forward_ray_winding_delta(&query, &Real::one(), &Real::zero(), &policy,)
                .unwrap(),
            Classification::Decided(-1),
        );
    }
}

#[test]
fn selected_parallel_normal_circle_reuses_rationalized_analytic_parallel_components() {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let support = QuadraticBezier2::new(
        Point2::from_values(0, 0),
        Point2::new(half.clone(), Real::zero()),
        Point2::from_values(2, 0),
    )
    .parallel_left(Real::zero())
    .unwrap();
    let analytic_quarter = RationalBezier2::from(
        RationalQuadraticBezier2::try_new(
            Point2::new(half.clone(), Real::from(2_i8)),
            Point2::new(half.clone() - Real::from(2_i8), Real::from(2_i8)),
            Point2::new(half.clone() - Real::from(2_i8), Real::zero()),
            Real::one(),
            Real::one(),
            Real::from(2_i8),
        )
        .unwrap(),
    )
    .parallel_left(Real::one())
    .unwrap();
    let opposite_analytic_quarter = RationalBezier2::from(
        RationalQuadraticBezier2::try_new(
            Point2::new(half.clone(), Real::from(2_i8)),
            Point2::new(&half + Real::from(2_i8), Real::from(2_i8)),
            Point2::new(&half + Real::from(2_i8), Real::zero()),
            Real::one(),
            Real::one(),
            Real::from(2_i8),
        )
        .unwrap(),
    )
    .parallel_left(Real::from(-1_i8))
    .unwrap();

    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let Classification::Decided(polynomial) = BezierParameterPolynomial::try_new_power_basis(
            vec![-half.clone(), Real::one(), Real::one()],
            &policy,
        )
        .unwrap() else {
            panic!("the selected-center polynomial must construct");
        };
        let Classification::Decided(interval) =
            BezierParameterInterval::try_new(Real::zero(), half.clone(), &policy).unwrap()
        else {
            panic!("the selected-center interval must construct");
        };
        let Classification::Decided(center_parameter) =
            BezierAlgebraicParameter2::try_isolate(polynomial, interval, &policy).unwrap()
        else {
            panic!("the selected center must isolate");
        };
        let Classification::Decided(Some(circle)) =
            BezierAlgebraicCuspSemicircle2::from_selected_parallel_normal(
                support.clone(),
                BezierParameter2::Algebraic(center_parameter).into(),
                Real::one(),
                false,
                &policy,
            )
            .unwrap()
        else {
            panic!("the algebraic selected circle must construct");
        };
        assert!(matches!(
            analytic_quarter
                .exact_rational_parallel_component(&policy)
                .unwrap(),
            Classification::Decided(Some(_))
        ));

        let Classification::Decided(
            BezierAlgebraicCuspSemicircleParallelIntersections2::SelectedFiber {
                overlaps,
                contacts: unexpected_contacts,
            },
        ) = circle
            .parallel_intersections(
                &analytic_quarter,
                &CurveParameterRange2::unit(),
                None,
                &policy,
            )
            .unwrap()
        else {
            panic!("the exact analytic offset must reuse the selected rational fiber");
        };
        assert!(unexpected_contacts.is_empty(), "unexpected contacts");
        let [overlap] = overlaps.as_slice() else {
            panic!("the analytic quarter must retain one monotone overlap");
        };
        assert_eq!(overlap.orientation(), CurveOverlapOrientation2::Same,);
        assert_eq!(
            overlap
                .other_start_parameter()
                .order_to_real(&Real::zero(), &policy)
                .unwrap(),
            Classification::Decided(std::cmp::Ordering::Equal),
        );
        assert_eq!(
            overlap
                .other_end_parameter()
                .order_to_real(&Real::one(), &policy)
                .unwrap(),
            Classification::Decided(std::cmp::Ordering::Equal),
        );

        let Classification::Decided(
            BezierAlgebraicCuspSemicircleParallelIntersections2::SelectedFiber {
                overlaps: reversed,
                contacts: unexpected_contacts,
            },
        ) = circle
            .parallel_intersections(
                &analytic_quarter.reversed(),
                &CurveParameterRange2::unit(),
                None,
                &policy,
            )
            .unwrap()
        else {
            panic!("analytic reversal must retain the selected rational fiber");
        };
        assert!(unexpected_contacts.is_empty(), "unexpected contacts");
        let [reversed] = reversed.as_slice() else {
            panic!("the reversed analytic quarter must retain one overlap");
        };
        assert_eq!(reversed.orientation(), CurveOverlapOrientation2::Reversed,);

        let cusp_overlap_start = overlap.cusp_start_parameter();
        let cusp_overlap_end = overlap.cusp_end_parameter();
        let Classification::Decided(first_cut) = cusp_overlap_start
            .strict_scalar_between(&cusp_overlap_end, &policy)
            .unwrap()
        else {
            panic!("the cusp overlap must expose a represented interior cut");
        };
        let first_cut = BezierAlgebraicCuspSemicircleParameter2::Exact(first_cut);
        let Classification::Decided(second_cut) = first_cut
            .strict_scalar_between(&cusp_overlap_end, &policy)
            .unwrap()
        else {
            panic!("the cusp overlap must expose a second represented interior cut");
        };
        let second_cut = BezierAlgebraicCuspSemicircleParameter2::Exact(second_cut);
        let Classification::Decided(selected_start) = overlap
            .other_parameter_for_cusp(&first_cut, &policy)
            .unwrap()
        else {
            panic!("the first selected analytic cut must map exactly");
        };
        let Classification::Decided(selected_end) = overlap
            .other_parameter_for_cusp(&second_cut, &policy)
            .unwrap()
        else {
            panic!("the second selected analytic cut must map exactly");
        };
        assert!(selected_start.represented_value().is_none());
        assert!(selected_end.represented_value().is_none());
        let selected_carrier_range = crate::CurveParameterRange2::new_validated(
            crate::CurveParameter2::from_selected_fiber(selected_start.clone()),
            crate::CurveParameter2::from_selected_fiber(selected_end.clone()),
        );
        let cusp_range = |start, end| {
            CurveParameterRange2::new_validated(
                CurveParameter2::from_algebraic_cusp(start),
                CurveParameter2::from_algebraic_cusp(end),
            )
        };
        assert_eq!(
            overlap
                .has_positive_overlap(
                    &cusp_range(
                        BezierAlgebraicCuspSemicircleParameter2::Exact(Real::zero()),
                        first_cut.clone(),
                    ),
                    &selected_carrier_range,
                    &policy,
                )
                .unwrap(),
            Classification::Decided(false),
            "independently nonempty trims that correspond only at one endpoint must not become a fillet overlap",
        );
        assert_eq!(
            overlap
                .has_positive_overlap(
                    &cusp_range(first_cut.clone(), second_cut.clone()),
                    &selected_carrier_range,
                    &policy,
                )
                .unwrap(),
            Classification::Decided(true),
        );
        let unit = BezierParameterRange2::new_validated(
            BezierParameter2::Exact(Real::zero()),
            BezierParameter2::Exact(Real::one()),
        );
        let ordinary_carrier_range = crate::CurveParameterRange2::from_bezier_range(unit.clone());
        let (same_first, same_second) = clip_aligned_overlap_for_test(
            &unit,
            &unit,
            false,
            &selected_carrier_range,
            &ordinary_carrier_range,
            &policy,
        )
        .expect("same-oriented selected analytic overlap clipping must complete")
        .expect("the selected analytic carrier lies inside the complete overlap");
        assert_eq!(same_first, selected_carrier_range);
        assert_eq!(same_second, selected_carrier_range);

        let reversed_unit = BezierParameterRange2::new_validated(
            BezierParameter2::Exact(Real::one()),
            BezierParameter2::Exact(Real::zero()),
        );
        let (reversed_first, reversed_second) = clip_aligned_overlap_for_test(
            &unit,
            &reversed_unit,
            true,
            &selected_carrier_range,
            &ordinary_carrier_range,
            &policy,
        )
        .expect("reversed selected analytic overlap clipping must complete")
        .expect("the selected analytic carrier lies inside the reversed overlap");
        assert_eq!(reversed_first, selected_carrier_range);
        assert_eq!(
            reversed_second,
            crate::CurveParameterRange2::new_validated(
                crate::CurveParameter2::from_selected_fiber(selected_start.unit_complement(),),
                crate::CurveParameter2::from_selected_fiber(selected_end.unit_complement(),),
            )
        );
        assert_eq!(
            reversed_second
                .start()
                .as_selected_fiber()
                .unwrap()
                .unit_complement()
                .cmp_by_refinement(
                    selected_carrier_range.start().as_selected_fiber().unwrap(),
                    &policy,
                )
                .unwrap(),
            Classification::Decided(std::cmp::Ordering::Equal),
        );

        let cusp_fragment =
            |start: BezierAlgebraicCuspSemicircleParameter2,
             end: BezierAlgebraicCuspSemicircleParameter2| {
                match start.cmp_by_refinement(&end, &policy).unwrap() {
                    Classification::Decided(std::cmp::Ordering::Less) => {
                        let Classification::Decided(fragment) =
                            BezierAlgebraicCuspSemicircleFragment2::try_new(
                                circle.clone(),
                                start,
                                end,
                                false,
                                &policy,
                            )
                            .unwrap()
                        else {
                            panic!("the retained cusp complement must construct");
                        };
                        Some(BezierSplitFragment2::AlgebraicCuspSemicircle(fragment))
                    }
                    Classification::Decided(std::cmp::Ordering::Equal) => None,
                    Classification::Decided(std::cmp::Ordering::Greater)
                    | Classification::Uncertain(_) => {
                        panic!("the retained cusp complement must be ordered")
                    }
                }
            };
        let selected_before = cusp_fragment(
            BezierAlgebraicCuspSemicircleParameter2::Exact(Real::zero()),
            first_cut.clone(),
        )
        .expect("the first selected cut is strictly interior");
        let selected_after = cusp_fragment(
            second_cut.clone(),
            BezierAlgebraicCuspSemicircleParameter2::Exact(Real::one()),
        )
        .expect("the second selected cut is strictly interior");
        let selected_endpoint = |fragment: &BezierSplitFragment2, start_endpoint| {
            let BezierSplitFragment2::AlgebraicCuspSemicircle(fragment) = fragment else {
                unreachable!("the selected complement retained its cusp carrier")
            };
            let Classification::Decided(Some(point)) = fragment
                .endpoint_point_evidence(start_endpoint, &policy)
                .unwrap()
            else {
                panic!("the selected complement must retain endpoint point evidence");
            };
            point
        };
        let selected_start_point = selected_endpoint(&selected_before, false);
        let selected_end_point = selected_endpoint(&selected_after, true);
        let selected_fragments = vec![
            selected_before,
            BezierSplitFragment2::SelectedFiber(
                crate::bezier_split::BezierSelectedFiberFragment2::new(
                    crate::bezier_split::BezierSelectedFiberSource2::AnalyticParallel(
                        analytic_quarter.clone(),
                    ),
                    selected_carrier_range.clone(),
                    selected_start_point,
                    selected_end_point,
                ),
            ),
            selected_after,
            BezierSplitFragment2::AlgebraicCuspSemicircle(
                BezierAlgebraicCuspSemicircleFragment2::full(circle.complementary_half(), &policy),
            ),
        ];
        let selected_boundary = CurveRegionBoundaryLoop2::new(selected_fragments, &policy)
            .expect("the selected analytic boundary must close exactly");
        let selected_region = CurveRegion2::try_new_with_loop_topology(
            vec![selected_boundary],
            vec![CurveRegionLoopRole::Material],
            vec![FillRule::NonZero],
            vec![CurveBoundaryInteriorSide2::Left],
        )
        .unwrap();
        let reference_boundary = CurveRegionBoundaryLoop2::new(
            vec![
                BezierSplitFragment2::AlgebraicCuspSemicircle(
                    BezierAlgebraicCuspSemicircleFragment2::full(circle.clone(), &policy),
                ),
                BezierSplitFragment2::AlgebraicCuspSemicircle(
                    BezierAlgebraicCuspSemicircleFragment2::full(
                        circle.complementary_half(),
                        &policy,
                    ),
                ),
            ],
            &policy,
        )
        .unwrap();
        let reference_region = CurveRegion2::try_new_with_loop_topology(
            vec![reference_boundary],
            vec![CurveRegionLoopRole::Material],
            vec![FillRule::NonZero],
            vec![CurveBoundaryInteriorSide2::Left],
        )
        .unwrap();
        for style in [
            OffsetCornerStyle2::Round,
            OffsetCornerStyle2::Bevel,
            OffsetCornerStyle2::Miter {
                limit: Real::from(4_i8),
            },
        ] {
            let distance = (Real::one() / Real::from(10_i8)).unwrap();
            let selected_offset = selected_region
                .offset(distance.clone(), &style, &policy)
                .unwrap_or_else(|error| {
                    panic!(
                        "a selected analytic overlap must offset through its true carrier switches: policy={policy:?}, style={style:?}, error={error:?}"
                    )
                });
            let reference_offset = reference_region
                .offset(distance, &style, &policy)
                .expect("the equivalent retained circle must offset");
            assert_eq!(selected_offset.certainty, CurveCertainty::Certified);
            assert_eq!(selected_offset.certainty, reference_offset.certainty);
            for point in [
                Point2::new(half.clone(), Real::zero()),
                Point2::new(&half + Real::from(2_i8), Real::zero()),
                Point2::new(&half - Real::from(2_i8), Real::zero()),
            ] {
                assert_eq!(
                    selected_offset
                        .value
                        .classify_point(&point.clone().into(), &policy)
                        .unwrap()
                        .value,
                    reference_offset
                        .value
                        .classify_point(&point.clone().into(), &policy)
                        .unwrap()
                        .value,
                );
            }
            assert!(
                selected_offset
                    .value
                    .boundary_loops()
                    .iter()
                    .flat_map(CurveRegionBoundaryLoop2::fragments)
                    .all(|fragment| !matches!(fragment, BezierSplitFragment2::SelectedFiber(_)))
            );
        }

        let Classification::Decided(wide_start_cut) = cusp_overlap_start
            .strict_scalar_between(&first_cut, &policy)
            .unwrap()
        else {
            panic!("the analytic overlap must expose a wider first cut");
        };
        let wide_start_cut = BezierAlgebraicCuspSemicircleParameter2::Exact(wide_start_cut);
        let Classification::Decided(wide_end_cut) = second_cut
            .strict_scalar_between(&cusp_overlap_end, &policy)
            .unwrap()
        else {
            panic!("the analytic overlap must expose a wider second cut");
        };
        let wide_end_cut = BezierAlgebraicCuspSemicircleParameter2::Exact(wide_end_cut);
        let Classification::Decided(wide_selected_start) = overlap
            .other_parameter_for_cusp(&wide_start_cut, &policy)
            .unwrap()
        else {
            panic!("the wider first analytic cut must map exactly");
        };
        let Classification::Decided(wide_selected_end) = overlap
            .other_parameter_for_cusp(&wide_end_cut, &policy)
            .unwrap()
        else {
            panic!("the wider second analytic cut must map exactly");
        };
        let analytic_before = cusp_fragment(
            BezierAlgebraicCuspSemicircleParameter2::Exact(Real::zero()),
            wide_start_cut,
        )
        .expect("the wider first selected cut is strictly interior");
        let analytic_after = cusp_fragment(
            wide_end_cut,
            BezierAlgebraicCuspSemicircleParameter2::Exact(Real::one()),
        )
        .expect("the wider second selected cut is strictly interior");
        let analytic_start_point = selected_endpoint(&analytic_before, false);
        let analytic_end_point = selected_endpoint(&analytic_after, true);
        let analytic_fragments = vec![
            analytic_before,
            BezierSplitFragment2::SelectedFiber(
                crate::bezier_split::BezierSelectedFiberFragment2::new(
                    crate::bezier_split::BezierSelectedFiberSource2::AnalyticParallel(
                        analytic_quarter.clone(),
                    ),
                    crate::CurveParameterRange2::new_validated(
                        crate::CurveParameter2::from_selected_fiber(wide_selected_start),
                        crate::CurveParameter2::from_selected_fiber(wide_selected_end),
                    ),
                    analytic_start_point,
                    analytic_end_point,
                ),
            ),
            analytic_after,
            BezierSplitFragment2::AlgebraicCuspSemicircle(
                BezierAlgebraicCuspSemicircleFragment2::full(circle.complementary_half(), &policy),
            ),
        ];
        let analytic_boundary = CurveRegionBoundaryLoop2::new(analytic_fragments, &policy)
            .expect("the complete analytic overlap boundary must close exactly");
        let analytic_region = CurveRegion2::try_new_with_loop_topology(
            vec![analytic_boundary],
            vec![CurveRegionLoopRole::Material],
            vec![FillRule::NonZero],
            vec![CurveBoundaryInteriorSide2::Left],
        )
        .unwrap();
        let evidence = selected_region
            .intersect_region(&analytic_region, &policy)
            .expect("a selected analytic carrier must re-enter overlap clipping")
            .into_value();
        assert!(evidence.blockers().is_empty());
        assert!(evidence.overlaps().iter().any(|overlap| {
            overlap.overlap().first_range().start().is_retained_scalar()
                || overlap
                    .overlap()
                    .second_range()
                    .start()
                    .is_retained_scalar()
        }));
        let booleans = selected_region
            .boolean_regions(&analytic_region, &policy)
            .expect("a selected analytic carrier must re-enter Boolean topology")
            .into_value();
        assert!(!booleans.union().is_empty());
        assert!(!booleans.intersection().is_empty());
        assert!(booleans.difference().is_empty());
        assert!(booleans.xor().is_empty());

        let Classification::Decided(
            BezierAlgebraicCuspSemicircleParallelIntersections2::SelectedFiber {
                contacts,
                overlaps: unexpected_overlaps,
            },
        ) = circle
            .parallel_intersections(
                &opposite_analytic_quarter,
                &CurveParameterRange2::unit(),
                None,
                &policy,
            )
            .unwrap()
        else {
            panic!("the opposite analytic quarter must retain its selected endpoint");
        };
        assert!(unexpected_overlaps.is_empty(), "unexpected overlaps");
        let [contact] = contacts.as_slice() else {
            panic!("the opposite analytic quarter must touch exactly one endpoint");
        };
        assert_eq!(
            contact.location(),
            BezierAlgebraicCuspSemicircleContactLocation2::Start,
        );
        assert_eq!(contact.tangent_cross_sign(), RealSign::Zero);
    }
}

#[test]
fn selected_parallel_normal_incident_circle_selects_the_positive_speed_component() {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    // x(u)=u+u^2 and alpha^2+alpha=1/2 retain a genuinely
    // algebraic selected center at (1/2, 0).
    let support = QuadraticBezier2::new(
        Point2::from_values(0, 0),
        Point2::new(half.clone(), Real::zero()),
        Point2::from_values(2, 0),
    )
    .parallel_left(Real::zero())
    .unwrap();
    let carrier = RationalBezier2::from(
        RationalQuadraticBezier2::try_new(
            Point2::new(half.clone(), Real::from(2_i8)),
            Point2::new(half.clone() - Real::from(2_i8), Real::from(2_i8)),
            Point2::new(half.clone() - Real::from(2_i8), Real::zero()),
            Real::one(),
            Real::one(),
            Real::from(2_i8),
        )
        .unwrap(),
    )
    .parallel_left(Real::one())
    .unwrap();
    let range = BezierParameterRange2::new_validated(
        BezierParameter2::Exact(Real::zero()),
        BezierParameter2::Exact(Real::one()),
    );

    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        assert!(matches!(
            carrier.exact_rational_parallel_component(&policy).unwrap(),
            Classification::Decided(Some(_)),
        ));
        let Classification::Decided(polynomial) = BezierParameterPolynomial::try_new_power_basis(
            vec![-half.clone(), Real::one(), Real::one()],
            &policy,
        )
        .unwrap() else {
            panic!("the selected-center polynomial must construct");
        };
        let Classification::Decided(interval) =
            BezierParameterInterval::try_new(Real::zero(), half.clone(), &policy).unwrap()
        else {
            panic!("the selected-center interval must construct");
        };
        let Classification::Decided(center_parameter) =
            BezierAlgebraicParameter2::try_isolate(polynomial, interval, &policy).unwrap()
        else {
            panic!("the selected center must isolate");
        };
        let Classification::Decided(Some(circle)) =
            BezierAlgebraicCuspSemicircle2::from_selected_parallel_normal(
                support.clone(),
                BezierParameter2::Algebraic(center_parameter).into(),
                Real::one(),
                false,
                &policy,
            )
            .unwrap()
        else {
            panic!("the exact selected-normal circle must construct");
        };
        for analytic in [carrier.clone(), carrier.reversed()] {
            assert!(matches!(
                circle
                    .parallel_intersections(
                        &analytic,
                        &CurveParameterRange2::from_bezier_range((range).clone()),
                        Some(&incident_domain(
                            &analytic,
                            Real::one(),
                            BezierParameterRayDirection2::Increasing,
                            &policy,
                        )),
                        &policy
                    )
                    .unwrap(),
                Classification::Decided(
                    BezierAlgebraicCuspSemicircleParallelIntersections2::CoincidentCircleComponent
                ),
            ));
        }
    }
}

#[test]
fn selected_source_range_retains_incident_endpoint_and_contacts_locally() {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let quarter = (Real::one() / Real::from(4_i8)).unwrap();
    // P(u)=(u,0). The unit circle centered at u=1/4+2s meets
    // [2s,2s+2] once, at u=5/4+2s, including exterior source ranges.
    let support = QuadraticBezier2::new(
        Point2::from_values(0, 0),
        Point2::new(half.clone(), Real::zero()),
        Point2::from_values(1, 0),
    )
    .parallel_left(Real::zero())
    .unwrap();
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        for shift in [-3, 0, 2] {
            let start = Real::from(2 * shift);
            let center_parameter = CurveParameter2::from(&quarter + &start);
            let expected = &start + &quarter + Real::one();
            let end = &start + Real::from(2_i8);
            let Classification::Decided(Some(circle)) =
                BezierAlgebraicCuspSemicircle2::from_selected_parallel_normal(
                    support.clone(),
                    center_parameter,
                    Real::one(),
                    false,
                    &policy,
                )
                .unwrap()
            else {
                panic!("the selected-normal circle must construct")
            };
            let endpoint = CurveParameter2::from_selected_fiber(
                degree_nine_selected_fiber_parameter_for_test(half.clone(), 32_768, &policy),
            );
            let Classification::Decided(endpoint) = endpoint
                .affine_image_unbounded(&Real::from(2_i8), &start, &policy)
                .unwrap()
            else {
                panic!("the finite endpoint must remain in its local fiber")
            };
            assert!(matches!(
                endpoint
                    .as_selected_fiber()
                    .unwrap()
                    .promoted_bezier_parameter(&policy)
                    .unwrap(),
                Classification::Uncertain(_),
            ));
            assert_eq!(
                endpoint
                    .cmp_by_refinement(&expected.clone().into(), &policy)
                    .unwrap(),
                Classification::Decided(std::cmp::Ordering::Less)
            );
            for lower in [CurveParameter2::from(start), endpoint] {
                for reversed in [false, true] {
                    let range = if reversed {
                        CurveParameterRange2::new_validated(end.clone().into(), lower.clone())
                    } else {
                        CurveParameterRange2::new_validated(lower.clone(), end.clone().into())
                    };
                    let mut retained = Vec::new();
                    for half_circle in [circle.clone(), circle.complementary_half()] {
                        let result = half_circle
                            .parallel_intersections(&support, &range, None, &policy)
                            .unwrap();
                        match result {
                            Classification::Decided(
                                BezierAlgebraicCuspSemicircleParallelIntersections2::SelectedFiber {
                                    contacts, overlaps,
                                },
                            ) => {
                                assert!(overlaps.is_empty());
                                retained.extend(contacts.into_iter().map(|contact|
                                    CurveParameter2::from_selected_fiber(contact.other_parameter().clone())
                                ));
                            }
                            Classification::Decided(
                                BezierAlgebraicCuspSemicircleParallelIntersections2::Mapped {
                                    contacts, overlaps,
                                },
                            ) => {
                                assert!(overlaps.is_empty());
                                retained.extend(contacts.into_iter().map(|contact|
                                    CurveParameter2::from(contact.parallel_parameter)
                                ));
                            }
                            Classification::Decided(
                                BezierAlgebraicCuspSemicircleParallelIntersections2::RetainedContacts(contacts),
                            ) => retained.extend(contacts.into_iter().map(|contact|
                                contact.other_parameter().clone()
                            )),
                            Classification::Uncertain(reason) => panic!("finite source contact uncertainty: {reason:?}"),
                            Classification::Decided(_) => panic!("a straight source and circle must have isolated contacts"),
                        }
                    }
                    assert_eq!(retained.len(), 1);
                    assert_eq!(
                        retained[0]
                            .cmp_by_refinement(&CurveParameter2::from(expected.clone()), &policy)
                            .unwrap(),
                        Classification::Decided(std::cmp::Ordering::Equal)
                    );
                }
            }
        }
    }
}

#[test]
fn selected_fiber_interval_supports_exact_and_nonexact_exterior_roots() {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let three_halves = &Real::from(3_i8) * &half;
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        // Retain alpha=1/2 as algebraic construction evidence. Refinement
        // recovers its exact value, which exercises the exterior
        // exact-retained path without changing the selected authority.
        let Classification::Decided(polynomial) = BezierParameterPolynomial::try_new_power_basis(
            vec![-half.clone(), Real::one()],
            &policy,
        )
        .unwrap() else {
            panic!("the rational retained-root polynomial must construct");
        };
        let Classification::Decided(interval) =
            BezierParameterInterval::try_new(Real::zero(), Real::one(), &policy).unwrap()
        else {
            panic!("the retained-root interval must construct");
        };
        let Classification::Decided(retained) =
            BezierAlgebraicParameter2::try_isolate(polynomial, interval, &policy).unwrap()
        else {
            panic!("the retained rational root must isolate");
        };

        // u^2=1+alpha selects sqrt(3/2) strictly between 1 and 2.
        let nonlinear_incidence = BivariatePolynomial::new(vec![
            vec![Real::from(-1_i8), Real::zero(), Real::one()],
            vec![Real::from(-1_i8)],
        ]);
        let outside_unit_predicate =
            BivariatePolynomial::new(vec![vec![Real::from(-1_i8), Real::zero(), Real::one()]]);
        let exterior_range = BezierParameterRange2::from_exact(Real::one(), Real::from(2_i8));
        for exterior_range in [exterior_range.clone(), exterior_range.reversed()] {
            let Classification::Decided(Some(nonlinear)) = selected_fiber_parameters_in_range(
                &nonlinear_incidence,
                &retained,
                &CurveParameterRange2::from_bezier_range(exterior_range.clone()),
                &policy,
            )
            .unwrap() else {
                panic!("the nonlinear exterior fiber must isolate");
            };
            let [nonlinear] = nonlinear.as_slice() else {
                panic!("the positive exterior interval must contain one nonlinear root");
            };
            assert!(nonlinear.represented_value().is_none());
            assert_eq!(
                nonlinear.order_to_real(&Real::one(), &policy).unwrap(),
                Classification::Decided(std::cmp::Ordering::Greater),
            );
            assert_eq!(
                nonlinear.order_to_real(&Real::from(2_i8), &policy).unwrap(),
                Classification::Decided(std::cmp::Ordering::Less),
            );
            assert_eq!(
                nonlinear
                    .predicate_sign(&outside_unit_predicate, &policy)
                    .unwrap(),
                Classification::Decided(RealSign::Positive),
            );
        }

        // u=1+alpha recovers the represented exterior root 3/2. This is
        // valid affine evidence even though it is not a bounded Bezier
        // parameter until the caller maps it back into its target chart.
        let linear_incidence = BivariatePolynomial::new(vec![
            vec![Real::from(-1_i8), Real::one()],
            vec![Real::from(-1_i8)],
        ]);
        let Classification::Decided(Some(linear)) = selected_fiber_parameters_in_range(
            &linear_incidence,
            &retained,
            &CurveParameterRange2::from_bezier_range(exterior_range.clone()),
            &policy,
        )
        .unwrap() else {
            panic!("the linear exterior fiber must isolate");
        };
        let [linear] = linear.as_slice() else {
            panic!("the exterior interval must contain one represented root");
        };
        assert_eq!(linear.represented_value(), Some(&three_halves));
        assert_eq!(
            linear.predicate_sign(&linear_incidence, &policy).unwrap(),
            Classification::Decided(RealSign::Zero),
        );
    }
}

#[test]
fn selected_polynomial_image_saturates_a_foreign_repeated_source_component() {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let image = BivariatePolynomial::new(vec![
        vec![Real::zero(), Real::one()],
        vec![Real::from(-1_i8), Real::one()],
        vec![Real::from(-1_i8)],
    ]);
    let expected_factor =
        BivariatePolynomial::new(vec![vec![Real::one(), Real::from(2_i8), Real::one()]]);
    let expected_relation = BivariatePolynomial::new(vec![
        vec![-half.clone(), Real::one()],
        vec![Real::from(-1_i8), Real::one()],
    ]);

    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let BezierParameter2::Algebraic(alpha) =
            algebraic_parameter(vec![-half.clone(), Real::zero(), Real::one()])
        else {
            unreachable!()
        };
        // F=(u-alpha)(u+1)^2 selects u=alpha. The image
        // G=(u+1)(z-u) is identically zero on the foreign repeated
        // u=-1 component, but its selected residual image is z=alpha.
        let center = BezierAlgebraicSelectedFiberAuthority2::new(
            BivariatePolynomial::new(vec![
                vec![Real::zero(), Real::one(), Real::from(2_i8), Real::one()],
                vec![Real::from(-1_i8), Real::from(-2_i8), Real::from(-1_i8)],
            ]),
            alpha.clone(),
            &policy,
        )
        .parameter(IsolatedRootInterval {
            lower: alpha.interval().start().clone(),
            upper: alpha.interval().end().clone(),
            exact_root: None,
            distinct_root_count: 1,
        });
        let Classification::Decided(Some(image)) = center
            .retained_polynomial_image_relation(&image, &policy)
            .unwrap()
        else {
            panic!("the saturated selected image must remain locally constructible")
        };
        let factor = image
            .identically_zero_source_factor
            .expect("the saturated source factor must be retained");
        let relation = image
            .relation
            .expect("the selected residual image must be retained");
        assert_eq!(factor, expected_factor);
        assert_eq!(relation, expected_relation);
        assert_eq!(
            center.predicate_sign(&factor, &policy).unwrap(),
            Classification::Decided(RealSign::Positive),
        );
    }
}

#[test]
fn selected_parallel_normal_positive_dimensional_projection_rejects_conjugate_components() {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let BezierParameter2::Algebraic(center) =
        algebraic_parameter(vec![-half.clone(), Real::zero(), Real::one()])
    else {
        panic!("sqrt(1/2) must retain its algebraic authority");
    };
    let zero = BivariatePolynomial::new(vec![vec![Real::zero()]]);
    let one = BivariatePolynomial::new(vec![vec![Real::one()]]);
    let target_speed = BivariatePolynomial::new(vec![vec![Real::one(), Real::zero(), Real::one()]]);
    let center_speed = one.clone();
    let circle = BezierParallelTwoNormalExpression2 {
        product: zero.clone(),
        center: one.clone(),
        candidate: zero.clone(),
        rational: one.clone(),
    };
    // The authored expression is 1+sqrt(1)=2, hence never zero. Its
    // once-squared branch is 2+2sqrt(1)=4, but the final norm vanishes
    // identically because its opposite center-speed conjugate is zero.
    let squared_branch = BezierAlgebraicCuspTwoTermExpression2 {
        rational: BivariatePolynomial::new(vec![vec![Real::from(2_i8)]]),
        radical: BivariatePolynomial::new(vec![vec![Real::from(2_i8)]]),
    };
    let exterior_branch = BezierAlgebraicCuspTwoTermExpression2 {
        // u^2=1+alpha has one positive root strictly between 1 and 2.
        rational: BivariatePolynomial::new(vec![
            vec![Real::from(-1_i8), Real::zero(), Real::one()],
            vec![Real::from(-1_i8)],
        ]),
        radical: zero.clone(),
    };
    let exterior_range = BezierParameterRange2::from_exact(Real::one(), Real::from(2_i8));
    let unit_range = BezierParameterRange2::from_exact(Real::zero(), Real::one());
    let square_speed =
        BivariatePolynomial::new(vec![vec![Real::one(), Real::from(-2_i8), Real::one()]]);
    let square_circle = BezierParallelTwoNormalExpression2 {
        product: zero.clone(),
        center: zero.clone(),
        candidate: one.clone(),
        rational: BivariatePolynomial::new(vec![vec![
            -(Real::from(3_i8) / Real::from(2_i8)).unwrap(),
        ]]),
    };
    let square_range = BezierParameterRange2::from_exact(Real::from(2_i8), Real::from(3_i8));
    let square_contact = (Real::from(5_i8) / Real::from(2_i8)).unwrap();

    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        assert!(matches!(
            selected_parallel_normal_positive_dimensional_projection(&circle, &squared_branch, &center_speed, &target_speed, &center, &CurveParameterRange2::unit(), None, &policy)
            .unwrap(),
            Classification::Decided(
                BezierSelectedParallelNormalPositiveProjection2::Candidates(ref candidates)
            ) if candidates.is_empty(),
        ));
        for exterior_range in [exterior_range.clone(), exterior_range.reversed()] {
            let Classification::Decided(
                BezierSelectedParallelNormalPositiveProjection2::Candidates(candidates),
            ) = selected_parallel_normal_positive_dimensional_projection(
                &circle,
                &exterior_branch,
                &center_speed,
                &target_speed,
                &center,
                &CurveParameterRange2::from_bezier_range((exterior_range).clone()),
                None,
                &policy,
            )
            .unwrap()
            else {
                panic!("the positive-dimensional exterior branch must project");
            };
            let [candidate] = candidates.as_slice() else {
                panic!("the exterior branch must retain its one positive root");
            };
            assert_eq!(
                candidate.order_to_real(&Real::one(), &policy).unwrap(),
                Classification::Decided(std::cmp::Ordering::Greater),
            );
            assert_eq!(
                candidate.order_to_real(&Real::from(2_i8), &policy).unwrap(),
                Classification::Decided(std::cmp::Ordering::Less),
            );
        }

        let incident = BezierParallelIncidentDomain2 {
            endpoint: CurveParameter2::from(BezierParameter2::Exact(Real::one())),
            bridge: None,
            anchor: Real::one(),
            direction: BezierParameterRayDirection2::Increasing,
            barrier: None,
        };
        let Classification::Decided(BezierSelectedParallelNormalPositiveProjection2::Candidates(
            candidates,
        )) = selected_parallel_normal_positive_dimensional_projection(
            &circle,
            &exterior_branch,
            &center_speed,
            &target_speed,
            &center,
            &CurveParameterRange2::from_bezier_range((unit_range).clone()),
            Some(&incident),
            &policy,
        )
        .unwrap()
        else {
            panic!("the positive-dimensional incident branch must project");
        };
        assert_eq!(candidates.len(), 1);
        assert_eq!(
            candidates[0].order_to_real(&Real::one(), &policy).unwrap(),
            Classification::Decided(std::cmp::Ordering::Greater),
        );

        // sqrt((u-1)^2)=u-1 on [2,3], although the polynomial square
        // root selected positive at zero is 1-u. The active cell, not
        // parameter zero, must choose the authored positive-speed sheet.
        for square_range in [square_range.clone(), square_range.reversed()] {
            let Classification::Decided(
                BezierSelectedParallelNormalPositiveProjection2::Candidates(candidates),
            ) = selected_parallel_normal_positive_dimensional_projection(
                &square_circle,
                &squared_branch,
                &center_speed,
                &square_speed,
                &center,
                &CurveParameterRange2::from_bezier_range((square_range).clone()),
                None,
                &policy,
            )
            .unwrap()
            else {
                panic!("the exterior square-speed sheet must project");
            };
            let [candidate] = candidates.as_slice() else {
                panic!("the exterior square-speed sheet must retain one root");
            };
            assert_eq!(
                candidate.order_to_real(&square_contact, &policy).unwrap(),
                Classification::Decided(std::cmp::Ordering::Equal),
            );
        }
    }
}

#[test]
fn selected_fiber_positive_dimensional_projection_reports_authored_continuum() {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let zero = BivariatePolynomial::new(vec![vec![Real::zero()]]);
    let one = BivariatePolynomial::new(vec![vec![Real::one()]]);
    let target = QuadraticBezier2::from_line_segment(
        LineSeg2::try_new(Point2::from_values(0, 0), Point2::from_values(1, 0)).unwrap(),
    )
    .parallel_left(Real::zero())
    .unwrap();
    let system = BezierParallelFixedDistanceSystem2 {
        incidence: zero.clone(),
        center_speed_squared: one.clone(),
        candidate_speed_squared: one.clone(),
        squared_branch: BezierAlgebraicCuspTwoTermExpression2 {
            rational: zero.clone(),
            radical: zero.clone(),
        },
        circle: BezierParallelTwoNormalExpression2 {
            product: zero.clone(),
            center: zero.clone(),
            candidate: zero.clone(),
            rational: zero,
        },
    };

    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let BezierParameter2::Algebraic(alpha) =
            algebraic_parameter(vec![-half.clone(), Real::zero(), Real::one()])
        else {
            unreachable!()
        };
        let center = BezierAlgebraicSelectedFiberAuthority2::new(
            BivariatePolynomial::new(vec![
                vec![Real::zero(), Real::one()],
                vec![Real::from(-1_i8)],
            ]),
            alpha.clone(),
            &policy,
        )
        .parameter(IsolatedRootInterval {
            lower: alpha.interval().start().clone(),
            upper: alpha.interval().end().clone(),
            exact_root: None,
            distinct_root_count: 1,
        });
        assert!(matches!(
            target
                .selected_fiber_parallel_normal_positive_dimensional_projection(
                    &center,
                    &system,
                    &CurveParameterRange2::unit(),
                    None,
                    &policy,
                )
                .unwrap(),
            Classification::Decided(
                BezierSelectedParallelNormalPositiveProjection2::CoincidentCircleComponent
            ),
        ));
    }
}

#[test]
fn algebraic_center_fixed_distance_projects_complete_high_degree_fiber() {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let target = RationalBezier2::try_new(
        vec![
            Point2::new(
                (Real::from(-7_i8) / Real::from(10_i8)).unwrap(),
                (Real::from(-13_i8) / Real::from(5_i8)).unwrap(),
            ),
            Point2::new(
                (Real::from(-9_i8) / Real::from(20_i8)).unwrap(),
                (Real::from(-8_i8) / Real::from(5_i8)).unwrap(),
            ),
            Point2::new(
                (Real::from(3_i8) / Real::from(10_i8)).unwrap(),
                (Real::one() / Real::from(15_i8)).unwrap(),
            ),
            Point2::new(
                (Real::from(51_i8) / Real::from(20_i8)).unwrap(),
                (Real::from(12_i8) / Real::from(5_i8)).unwrap(),
            ),
            Point2::new(
                (Real::from(93_i8) / Real::from(10_i8)).unwrap(),
                (Real::from(27_i8) / Real::from(5_i8)).unwrap(),
            ),
        ],
        vec![Real::one(); 5],
    )
    .unwrap()
    .parallel_left(Real::one())
    .unwrap();
    let center = algebraic_parameter(vec![-half, Real::one(), Real::one()]);
    let setback = (Real::one() / Real::from(100_i8)).unwrap();
    let radius_squared = &setback * &setback;
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let incidence = target
            .fixed_distance_incidence_from_parameter_with_domain(
                &target,
                &center,
                &radius_squared,
                &CurveParameterRange2::unit(),
                None,
                &policy,
            )
            .unwrap();
        assert!(
            matches!(incidence, Classification::Decided(ref parameters) if !parameters.is_empty()),
            "the high-degree fixed-distance fiber must project under {policy:?}: {incidence:?}"
        );
    }
}

#[test]
fn fixed_distance_retains_selected_candidates_in_both_range_orientations() {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let quarter = &half * &half;
    let parallel = QuadraticBezier2::new(
        Point2::from_values(0, 0),
        Point2::new(Real::zero(), half),
        Point2::from_values(1, 1),
    )
    .parallel_left(Real::zero())
    .unwrap();
    // P(t)=(t^2,t), with alpha^11=1/4096. The quarter-unit
    // setback has two contacts inside [1/4,3/4]. Degree eleven keeps
    // their selected fibers local, so reversing the search interval
    // must not discard them through an ascending-only scalar filter.
    let mut coefficients = vec![Real::zero(); 12];
    coefficients[0] = -(Real::one() / Real::from(4096_i32)).unwrap();
    coefficients[11] = Real::one();
    let center = CurveParameter2::from(algebraic_parameter(coefficients));
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        for shift in [Real::zero(), Real::from(2)] {
            let Classification::Decided(candidate_support) = parallel
                .source()
                .to_rational_bezier()
                .unwrap()
                .subcurve_between_affine_exact(&(-shift.clone()), &(Real::one() - &shift), &policy)
                .unwrap()
            else {
                panic!("the translated support must construct")
            };
            let candidate_support = candidate_support
                .parallel_left(parallel.distance().clone())
                .unwrap();
            let mut forward = None;
            for reversed in [false, true] {
                let mut bounds = [
                    (&quarter + &shift).into(),
                    (&quarter * Real::from(3) + &shift).into(),
                ];
                if reversed {
                    bounds.reverse();
                }
                let [start, end] = bounds;
                let range = CurveParameterRange2::new_validated(start, end);
                let Classification::Decided(cuts) = candidate_support
                    .fixed_distance_incidence(&parallel, &center, &quarter, &range, None, &policy)
                    .unwrap()
                else {
                    panic!("the selected setback must decide in either range orientation")
                };
                assert_eq!(cuts.len(), 2);
                assert!(cuts.iter().all(|cut| cut.as_selected_fiber().is_some()));
                let Classification::Decided(mapped_center) = center
                    .affine_image_unbounded(&Real::one(), &shift, &policy)
                    .unwrap()
                else {
                    panic!("the translated center must retain its identity")
                };
                for expected in [std::cmp::Ordering::Less, std::cmp::Ordering::Greater] {
                    assert!(cuts.iter().any(|cut| {
                        cut.cmp_by_refinement(&mapped_center, &policy).unwrap()
                            == Classification::Decided(expected)
                    }));
                }
                if let Some(forward) = &forward {
                    for original in forward {
                        assert!(cuts.iter().any(|cut| {
                            cut.cmp_by_refinement(original, &policy).unwrap()
                                == Classification::Decided(std::cmp::Ordering::Equal)
                        }));
                    }
                } else {
                    forward = Some(cuts);
                }
            }
        }
    }
}

#[test]
fn algebraic_center_fixed_distance_covers_adjacent_and_incident_ray() {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    // P(t)=(t^2,t) is regular everywhere. For alpha^2=1/2, the
    // fixed-distance circle centered at P(alpha) with r^2=2 contains
    // P(-alpha), strictly beyond the decreasing endpoint ray.
    let parallel = QuadraticBezier2::new(
        Point2::from_values(0, 0),
        Point2::new(Real::zero(), half.clone()),
        Point2::from_values(1, 1),
    )
    .parallel_left(Real::zero())
    .unwrap();
    let center = algebraic_parameter(vec![-half, Real::zero(), Real::one()]);
    let range = CurveParameterRange2::new_validated(center.clone().into(), Real::one().into());

    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let finite = parallel
            .fixed_distance_incidence_from_parameter_with_domain(
                &parallel,
                &center,
                &Real::from(2_i8),
                &range,
                None,
                &policy,
            )
            .unwrap();
        assert!(matches!(finite, Classification::Decided(ref roots) if roots.is_empty()));

        let extended = parallel
            .fixed_distance_incidence_from_parameter_with_domain(
                &parallel,
                &center,
                &Real::from(2_i8),
                &range,
                Some(BezierParameterRayDirection2::Decreasing),
                &policy,
            )
            .unwrap();
        let Classification::Decided(extended) = extended else {
            panic!("the algebraic endpoint incident ray must decide under {policy:?}");
        };
        assert!(extended.iter().any(|parameter| {
            parameter
                .cmp_by_refinement(&Real::zero().into(), &policy)
                .unwrap()
                == Classification::Decided(std::cmp::Ordering::Less)
        }));
    }
}

#[test]
fn algebraic_center_fixed_distance_stops_before_speed_barrier() {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    // P(t)=(t^2,0) has its first decreasing speed barrier at t=0.
    // The unit-distance mate t=-sqrt(3/2) is therefore on a different
    // regular component and must not leak into endpoint extension.
    let parallel = QuadraticBezier2::new(
        Point2::from_values(0, 0),
        Point2::from_values(0, 0),
        Point2::from_values(1, 0),
    )
    .parallel_left(Real::zero())
    .unwrap();
    let center = algebraic_parameter(vec![-half, Real::zero(), Real::one()]);
    let range = CurveParameterRange2::new_validated(center.clone().into(), Real::one().into());

    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        assert!(matches!(
            parallel
                .fixed_distance_incidence_from_parameter_with_domain(
                    &parallel, &center,
                    &Real::one(),
                    &range,
                    Some(BezierParameterRayDirection2::Decreasing),
                    &policy,
                )
                .unwrap(),
            Classification::Decided(ref parameters) if parameters.is_empty()
        ));
    }
}

#[test]
fn selected_fiber_center_retains_nonlinear_fixed_distance_incident_cut() {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let setback = Real::from(2_i8).sqrt().unwrap();
    let parallel = QuadraticBezier2::new(
        Point2::from_values(0, 0),
        Point2::new(Real::zero(), half.clone()),
        Point2::from_values(1, 1),
    )
    .parallel_left(Real::zero())
    .unwrap();

    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let BezierParameter2::Algebraic(alpha) =
            algebraic_parameter(vec![-half.clone(), Real::zero(), Real::one()])
        else {
            unreachable!()
        };
        let center = BezierAlgebraicSelectedFiberAuthority2::new(
            BivariatePolynomial::new(vec![
                vec![Real::zero(), Real::one()],
                vec![Real::from(-1_i8)],
            ]),
            alpha.clone(),
            &policy,
        )
        .parameter(IsolatedRootInterval {
            lower: alpha.interval().start().clone(),
            upper: alpha.interval().end().clone(),
            exact_root: None,
            distinct_root_count: 1,
        });
        let Classification::Decided(expected) = center
            .affine_image_unbounded(&Real::from(-1_i8), &Real::zero(), &policy)
            .unwrap()
        else {
            panic!("the negative selected root must retain its local authority")
        };
        let outcome = parallel
            .fixed_distance_incidence_from_selected_parameter(
                &parallel,
                &center,
                &setback,
                &CurveParameterRange2::unit(),
                Some(BezierParameterRayDirection2::Decreasing),
                &policy,
            )
            .unwrap();
        let Classification::Decided(candidates) = outcome else {
            panic!("the selected nonlinear fixed-distance fiber must decide: {outcome:?}")
        };
        assert!(
            candidates
                .iter()
                .all(|candidate| candidate.as_selected_fiber().is_some())
        );
        assert!(candidates.iter().any(|candidate| {
            let Some(candidate) = candidate.as_selected_fiber() else {
                return false;
            };
            candidate.cmp_by_refinement(&expected, &policy).unwrap()
                == Classification::Decided(std::cmp::Ordering::Equal)
        }));
    }
}

