#[test]
fn selected_fiber_fixed_distance_descends_from_conjugate_circle_component() {
    // This rational quadratic traverses 270 degrees of the unit circle
    // counterclockwise. Its negative middle weight keeps the denominator
    // positive while placing the selected 45-degree point and its
    // radius-two, chord-two mate on one finite chart.
    let source = RationalBezier2::from(
        RationalQuadraticBezier2::try_new(
            Point2::from_values(1, 0),
            Point2::from_values(1, -1),
            Point2::from_values(0, -1),
            Real::one(),
            Real::from(-1_i8),
            Real::from(2_i8),
        )
        .unwrap(),
    );
    // A right unit parallel of the CCW unit circle has radius two. The
    // opposite center-speed sheet collapses at the origin, so its radius-
    // two circle contains the complete target component and makes the
    // twice-squared projection identically zero. The authored sheet has
    // exactly the authored 60-degree angular cut.
    let parallel = source.parallel_left(Real::from(-1_i8)).unwrap();

    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let parameters =
            algebraic_parameters(vec![Real::one(), Real::from(-6_i8), Real::from(7_i8)]);
        let [BezierParameter2::Algebraic(alpha), _] = parameters.as_slice() else {
            panic!("the two selected chart parameters must remain algebraic")
        };
        let expected_parameters = algebraic_parameters(vec![
            Real::from(-1_i8),
            Real::zero(),
            Real::from(22_i8),
            Real::from(-48_i8),
            Real::from(23_i8),
        ]);
        let expected = expected_parameters
            .first()
            .expect("the 105-degree chart parameter must be in the unit interval");
        let center = BezierAlgebraicSelectedFiberAuthority2::new(
            BivariatePolynomial::new(vec![
                vec![Real::zero(), Real::one()],
                vec![Real::from(-1_i8)],
            ]),
            alpha.clone(),
            &policy,
        )
        .parameter(IsolatedRootInterval {
            lower: alpha.interval().start().clone(),
            upper: alpha.interval().end().clone(),
            exact_root: None,
            distinct_root_count: 1,
        });
        #[cfg(feature = "dispatch-trace")]
        hyperreal::dispatch_trace::reset();
        #[cfg(feature = "dispatch-trace")]
        let outcome = hyperreal::dispatch_trace::with_recording(|| {
            parallel.fixed_distance_incidence_from_selected_parameter(
                &parallel,
                &center,
                &Real::from(2_i8),
                &CurveParameterRange2::unit(),
                None,
                &policy,
            )
        })
        .unwrap();
        #[cfg(not(feature = "dispatch-trace"))]
        let outcome = parallel
            .fixed_distance_incidence_from_selected_parameter(
                &parallel,
                &center,
                &Real::from(2_i8),
                &CurveParameterRange2::unit(),
                None,
                &policy,
            )
            .unwrap();
        #[cfg(feature = "dispatch-trace")]
        let trace = hyperreal::dispatch_trace::take_trace();
        let Classification::Decided(candidates) = outcome else {
            panic!("the selected conjugate circle component must descend exactly: {outcome:?}")
        };
        let [candidate] = candidates.as_slice() else {
            panic!("the authored circle sheet must retain its one 60-degree cut")
        };
        let candidate = candidate
            .as_selected_fiber()
            .expect("the authored circle cut must retain its selected fiber");
        assert_eq!(
            candidate.cmp_bezier_parameter(expected, &policy).unwrap(),
            Classification::Decided(std::cmp::Ordering::Equal),
        );
        #[cfg(feature = "dispatch-trace")]
        assert_eq!(
            trace.path_count(
                "hypercurve",
                "selected-fiber-fixed-distance",
                "retained-positive-polynomial-speed-equation",
            ),
            1,
        );
    }
}

#[test]
fn selected_parallel_normal_circle_intersects_genuinely_analytic_parallel_in_one_fiber() {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let exact_support = QuadraticBezier2::from_line_segment(
        LineSeg2::try_new(Point2::from_values(0, 0), Point2::from_values(1, 0)).unwrap(),
    )
    .parallel_left(Real::zero())
    .unwrap();
    // x(u)=u+u^2 and alpha^2+alpha=1/2 retain a genuinely
    // algebraic center parameter while placing the circle at (1/2, 0).
    let support = QuadraticBezier2::new(
        Point2::from_values(0, 0),
        Point2::new(half.clone(), Real::zero()),
        Point2::from_values(2, 0),
    )
    .parallel_left(Real::zero())
    .unwrap();
    // At t=1/2 this non-PH source is (3/10,-3/5), has tangent
    // (3,4), and therefore has unit left normal (-4/5,3/5). Its unit
    // left parallel meets the selected circle at (-1/2,0) transversely.
    let target = QuadraticBezier2::new(
        Point2::new(
            (Real::from(-7_i8) / Real::from(10_i8)).unwrap(),
            (Real::from(-13_i8) / Real::from(5_i8)).unwrap(),
        ),
        Point2::new(
            (Real::from(-1_i8) / Real::from(5_i8)).unwrap(),
            (Real::from(-3_i8) / Real::from(5_i8)).unwrap(),
        ),
        Point2::new(
            (Real::from(23_i8) / Real::from(10_i8)).unwrap(),
            (Real::from(7_i8) / Real::from(5_i8)).unwrap(),
        ),
    )
    .parallel_left(Real::one())
    .unwrap();
    // Composing the source parameter with s=t+t^2 moves that same
    // transverse contact to the nonrational root t^2+t=1/2 while keeping
    // the source regular on the complete unit interval.
    let reparameterized_target = RationalBezier2::try_new(
        vec![
            Point2::new(
                (Real::from(-7_i8) / Real::from(10_i8)).unwrap(),
                (Real::from(-13_i8) / Real::from(5_i8)).unwrap(),
            ),
            Point2::new(
                (Real::from(-9_i8) / Real::from(20_i8)).unwrap(),
                (Real::from(-8_i8) / Real::from(5_i8)).unwrap(),
            ),
            Point2::new(
                (Real::from(3_i8) / Real::from(10_i8)).unwrap(),
                (Real::one() / Real::from(15_i8)).unwrap(),
            ),
            Point2::new(
                (Real::from(51_i8) / Real::from(20_i8)).unwrap(),
                (Real::from(12_i8) / Real::from(5_i8)).unwrap(),
            ),
            Point2::new(
                (Real::from(93_i8) / Real::from(10_i8)).unwrap(),
                (Real::from(27_i8) / Real::from(5_i8)).unwrap(),
            ),
        ],
        vec![Real::one(); 5],
    )
    .unwrap()
    .parallel_left(Real::one())
    .unwrap();

    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        assert!(matches!(
            target.exact_rational_parallel_component(&policy).unwrap(),
            Classification::Decided(None),
        ));
        let Classification::Decided(polynomial) = BezierParameterPolynomial::try_new_power_basis(
            vec![-half.clone(), Real::one(), Real::one()],
            &policy,
        )
        .unwrap() else {
            panic!("the selected-center polynomial must construct");
        };
        let Classification::Decided(interval) =
            BezierParameterInterval::try_new(Real::zero(), half.clone(), &policy).unwrap()
        else {
            panic!("the selected-center interval must construct");
        };
        let Classification::Decided(center_parameter) =
            BezierAlgebraicParameter2::try_isolate(polynomial, interval, &policy).unwrap()
        else {
            panic!("the selected center must isolate");
        };
        let reparameterized_contact = BezierParameter2::Algebraic(center_parameter.clone());
        let Classification::Decided(Some(circle)) =
            BezierAlgebraicCuspSemicircle2::from_selected_parallel_normal(
                support.clone(),
                BezierParameter2::Algebraic(center_parameter).into(),
                Real::one(),
                false,
                &policy,
            )
            .unwrap()
        else {
            panic!("the selected circle must construct");
        };
        let Classification::Decided(Some(exact_center_circle)) =
            BezierAlgebraicCuspSemicircle2::from_selected_parallel_normal(
                exact_support.clone(),
                BezierParameter2::Exact(half.clone()).into(),
                Real::one(),
                false,
                &policy,
            )
            .unwrap()
        else {
            panic!("the exact-center selected circle must construct");
        };
        let target_range = BezierParameterRange2::new_validated(
            BezierParameter2::Exact(Real::zero()),
            BezierParameter2::Exact(half.clone()),
        );
        let reparameterized_range = BezierParameterRange2::new_validated(
            BezierParameter2::Exact(Real::zero()),
            reparameterized_contact.clone(),
        );
        let outcome = crate::policy::resolve_certified_value(&policy, |attempt| {
            exact_center_circle
                .parallel_intersections(
                    &reparameterized_target,
                    &CurveParameterRange2::from_bezier_range((reparameterized_range).clone()),
                    None,
                    attempt,
                )
                .unwrap()
        });
        assert_eq!(outcome.certainty, CurveCertainty::Certified);
        let Classification::Decided(
            BezierAlgebraicCuspSemicircleParallelIntersections2::SelectedFiber {
                contacts: reparameterized_contacts,
                overlaps: unexpected_overlaps,
            },
        ) = outcome.value
        else {
            panic!("an exact center must retain a nonrational analytic contact");
        };
        assert!(unexpected_overlaps.is_empty(), "unexpected overlaps");
        let [reparameterized_contact_evidence] = reparameterized_contacts.as_slice() else {
            panic!("the restricted reparameterized carrier must have one contact");
        };
        assert_eq!(
            reparameterized_contact_evidence
                .other_parameter()
                .cmp_bezier_parameter(&reparameterized_contact, &policy)
                .unwrap(),
            Classification::Decided(std::cmp::Ordering::Equal),
        );
        for replay_policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            assert_eq!(
                reparameterized_contact_evidence
                    .cusp_parameter()
                    .order_to_real(&half, &replay_policy)
                    .unwrap(),
                Classification::Decided(std::cmp::Ordering::Equal),
            );
            assert_eq!(
                reparameterized_contact_evidence
                    .tangent_dot_sign(&replay_policy)
                    .unwrap(),
                Classification::Decided(RealSign::Negative),
            );
        }
        assert!(
            reparameterized_contact_evidence
                .other_parameter()
                .represented_value()
                .is_none()
        );
        assert!(matches!(
            reparameterized_contact_evidence
                .other_parameter()
                .promoted_bezier_parameter(&policy)
                .unwrap(),
            Classification::Decided(_),
        ));
        let Classification::Decided(Some(recursive_child)) =
            BezierAlgebraicCuspSemicircle2::from_selected_circle_radial(
                &exact_center_circle,
                reparameterized_contact_evidence.cusp_parameter(),
                exact_center_circle.radial_distance().clone(),
                (Real::one() / Real::from(10_i8)).unwrap(),
                false,
                &policy,
            )
            .unwrap()
        else {
            panic!("an analytic selected-fiber contact must author a recursive circle");
        };
        assert!(matches!(
            recursive_child
                .recursive_circle_frame_authority(&policy)
                .unwrap(),
            Classification::Decided(Some(_)),
        ));
        let Classification::Decided(circle_fragment) =
            BezierAlgebraicCuspSemicircleFragment2::try_new(
                exact_center_circle.clone(),
                BezierAlgebraicCuspSemicircleParameter2::Exact(Real::zero()),
                reparameterized_contact_evidence.cusp_parameter(),
                false,
                &policy,
            )
            .unwrap()
        else {
            panic!("the transverse selected-circle fragment must construct");
        };
        let Classification::Decided(circle_start) =
            exact_center_circle.start_point_evidence(&policy).unwrap()
        else {
            panic!("the selected-circle start must be exact");
        };
        let Classification::Decided(target_end) = reparameterized_target
            .point_at(&Real::one(), &policy)
            .unwrap()
        else {
            panic!("the reparameterized analytic endpoint must be exact");
        };
        let Classification::Decided(Some(circle_contact)) = circle_fragment
            .endpoint_point_evidence(false, &policy)
            .unwrap()
        else {
            panic!("the transverse circle cut must retain its contact point");
        };
        let selected_target = BezierSplitFragment2::SelectedFiber(
            crate::bezier_split::BezierSelectedFiberFragment2::new(
                crate::bezier_split::BezierSelectedFiberSource2::AnalyticParallel(
                    reparameterized_target.clone(),
                ),
                crate::CurveParameterRange2::new_validated(
                    crate::CurveParameter2::from_selected_fiber(
                        reparameterized_contact_evidence.other_parameter().clone(),
                    ),
                    crate::CurveParameter2::from(BezierParameter2::Exact(Real::one())),
                ),
                circle_contact,
                CurvePoint2::from(target_end.clone()),
            ),
        );
        let Classification::Decided(closing_chord) =
            BezierAlgebraicChord2::try_new(CurvePoint2::from(target_end), circle_start, &policy)
                .unwrap()
        else {
            panic!("the retained transverse fixture chord must construct");
        };
        let closing_line = BezierSplitFragment2::AlgebraicChord(closing_chord);
        let transverse_region = CurveRegion2::try_new_with_loop_topology(
            vec![
                CurveRegionBoundaryLoop2::new(
                    vec![
                        BezierSplitFragment2::AlgebraicCuspSemicircle(circle_fragment),
                        selected_target,
                        closing_line,
                    ],
                    &policy,
                )
                .unwrap(),
            ],
            vec![CurveRegionLoopRole::Material],
            vec![FillRule::NonZero],
            vec![CurveBoundaryInteriorSide2::Left],
        )
        .unwrap();
        #[cfg(feature = "dispatch-trace")]
        hyperreal::dispatch_trace::reset();
        let transverse_offset_work = || {
            transverse_region.offset(
                (Real::one() / Real::from(10_i8)).unwrap(),
                &OffsetCornerStyle2::Round,
                &policy,
            )
        };
        #[cfg(feature = "dispatch-trace")]
        let transverse_offset = hyperreal::dispatch_trace::with_recording(transverse_offset_work);
        #[cfg(not(feature = "dispatch-trace"))]
        let transverse_offset = transverse_offset_work();
        #[cfg(feature = "dispatch-trace")]
        let transverse_offset_trace = hyperreal::dispatch_trace::take_trace();
        #[cfg(feature = "dispatch-trace")]
        let transverse_offset_trace_entries = transverse_offset_trace
            .dispatch
            .iter()
            .filter(|entry| entry.layer == "hypercurve")
            .collect::<Vec<_>>();
        assert!(
            transverse_offset.is_ok(),
            "a transverse selected-fiber carrier switch must offset: policy={policy:?}, result={transverse_offset:?}{}",
            {
                #[cfg(feature = "dispatch-trace")]
                {
                    format!(", trace={transverse_offset_trace_entries:?}")
                }
                #[cfg(not(feature = "dispatch-trace"))]
                {
                    String::new()
                }
            }
        );
        assert_eq!(
            transverse_offset.as_ref().unwrap().certainty,
            CurveCertainty::Certified
        );
        #[cfg(feature = "dispatch-trace")]
        {
            assert!(
                transverse_offset_trace.path_count(
                    "hypercurve",
                    "algebraic-circle-parallel-kernel",
                    "selected-normal-diagonal-rootless",
                ) > 0,
                "the selected-normal diagonal kernel must discharge the shared contact structurally: {transverse_offset_trace:?}",
            );
            assert!(
                transverse_offset_trace.path_count(
                    "hypercurve",
                    "algebraic-chord-pair",
                    "analytic-parallel-certified-support",
                ) > 0,
                "finite retained-chord clipping must use an exact structural authority: {transverse_offset_trace:?}",
            );
            assert_eq!(
                transverse_offset_trace.path_count(
                    "hypercurve",
                    "algebraic-chord-pair",
                    "represented-endpoint-parallel",
                ),
                0,
                "finite retained-chord clipping must not expand into the global represented endpoint resultant",
            );
            assert!(
                transverse_offset_trace
                    .dispatch
                    .iter()
                    .all(|entry| entry.operation != "represented-chord-normal-frame"),
                "the selected-normal route must not construct the superseded represented chord-normal frame: {transverse_offset_trace:?}",
            );
        }
        let setback = (Real::one() / Real::from(100_i8)).unwrap();
        let fillet = transverse_region
            .fillet_loop_vertex(
                0,
                1,
                &crate::CurveFillet2::new(setback.clone()),
                CurveCornerMode2::TrimOnly,
                &policy,
            )
            .unwrap_or_else(|error| {
                panic!(
                    "a transverse selected-fiber carrier switch must fillet exactly: policy={policy:?}, error={error:?}"
                )
            });
        assert_eq!(fillet.certainty, CurveCertainty::Certified);
        assert_eq!({ fillet.value.solutions().len() }, 3);

        let chamfer = transverse_region
            .chamfer_loop_vertex_by_setbacks(
                0,
                1,
                setback.clone(),
                setback,
                CurveCornerMode2::TrimOnly,
                &policy,
            )
            .unwrap_or_else(|error| {
                panic!(
                    "a transverse selected-fiber carrier switch must chamfer exactly: policy={policy:?}, error={error:?}"
                )
            });
        assert_eq!(chamfer.certainty, CurveCertainty::Certified);
        assert!(matches!(chamfer.value, CurveCornerSolutions2::Unique(_)));
        for circle in [circle, exact_center_circle] {
            let Classification::Decided(
                BezierAlgebraicCuspSemicircleParallelIntersections2::SelectedFiber {
                    contacts,
                    overlaps: unexpected_overlaps,
                },
            ) = circle
                .parallel_intersections(
                    &target,
                    &CurveParameterRange2::from_bezier_range((target_range).clone()),
                    None,
                    &policy,
                )
                .unwrap()
            else {
                panic!("the two-normal kernel must retain analytic contacts locally");
            };
            assert!(unexpected_overlaps.is_empty(), "unexpected overlaps");
            let contact = contacts
                .iter()
                .find(|contact| {
                    contact
                        .other_parameter()
                        .order_to_real(&half, &policy)
                        .unwrap()
                        == Classification::Decided(std::cmp::Ordering::Equal)
                })
                .expect("the authored transverse contact must be retained");
            assert_eq!(
                contact.location(),
                BezierAlgebraicCuspSemicircleContactLocation2::Interior,
            );
            assert_eq!(contact.tangent_cross_sign(), RealSign::Positive);
            assert_eq!(
                contact
                    .cusp_parameter()
                    .order_to_real(&half, &policy)
                    .unwrap(),
                Classification::Decided(std::cmp::Ordering::Equal),
            );
            assert_eq!(
                contact
                    .point_coordinate_order_to_real(Axis2::X, &(-half.clone()), &policy)
                    .unwrap(),
                Classification::Decided(std::cmp::Ordering::Equal),
            );
            assert_eq!(
                contact
                    .point_coordinate_order_to_real(Axis2::Y, &Real::zero(), &policy)
                    .unwrap(),
                Classification::Decided(std::cmp::Ordering::Equal),
            );
            let Classification::Decided(bounds) =
                algebraic_chord_endpoint_bounds_refined(&contact.point_evidence(), 8, &policy)
            else {
                panic!("the retained analytic point must refine without a compositum");
            };
            assert_eq!(
                bounds.contains_point(&Point2::new(-half.clone(), Real::zero()), &policy),
                Classification::Decided(true),
            );
        }
    }
}

#[test]
fn algebraic_selected_fiber_incident_chart_preserves_affine_authority() {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let BezierParameter2::Algebraic(retained_parameter) =
        algebraic_parameter(vec![-half, Real::zero(), Real::one()])
    else {
        panic!("the retained selected parameter must remain algebraic");
    };
    let incidence = BivariatePolynomial::new(vec![vec![Real::from(-2_i8), Real::one()]]);
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let Classification::Decided(Some(parameters)) = selected_fiber_parameters_on_incident_ray(
            &incidence,
            &retained_parameter,
            &Real::one(),
            BezierParameterRayDirection2::Increasing,
            None,
            &policy,
        )
        .unwrap() else {
            panic!("the selected incident chart must isolate exactly");
        };
        let [parameter] = parameters.as_slice() else {
            panic!("the incident chart must retain exactly t=2");
        };
        assert_eq!(
            parameter.order_to_real(&Real::from(2_i8), &policy).unwrap(),
            Classification::Decided(std::cmp::Ordering::Equal),
        );
        assert_eq!(
            parameter.promoted_bezier_parameter(&policy).unwrap(),
            Classification::Decided(BezierParameter2::Exact(Real::from(2_i8))),
        );

        let barrier = BezierParameter2::Exact((Real::from(3_i8) / Real::from(2_i8)).unwrap());
        assert!(matches!(
            selected_fiber_parameters_on_incident_ray(
                &incidence,
                &retained_parameter,
                &Real::one(),
                BezierParameterRayDirection2::Increasing,
                Some(&barrier),
                &policy,
            )
            .unwrap(),
            Classification::Decided(Some(ref parameters)) if parameters.is_empty()
        ));
    }
}

#[test]
#[ignore = "long exact end-to-end benchmark; about 326 seconds in an unoptimized all-feature build"]
fn selected_fiber_genuinely_analytic_contacts_complete_region_booleans() {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let support = QuadraticBezier2::new(
        Point2::from_values(0, 0),
        Point2::new(half.clone(), Real::zero()),
        Point2::from_values(2, 0),
    )
    .parallel_left(Real::zero())
    .unwrap();
    let target = QuadraticBezier2::new(
        Point2::new(
            (Real::from(-7_i8) / Real::from(10_i8)).unwrap(),
            (Real::from(-13_i8) / Real::from(5_i8)).unwrap(),
        ),
        Point2::new(
            (Real::from(-1_i8) / Real::from(5_i8)).unwrap(),
            (Real::from(-3_i8) / Real::from(5_i8)).unwrap(),
        ),
        Point2::new(
            (Real::from(23_i8) / Real::from(10_i8)).unwrap(),
            (Real::from(7_i8) / Real::from(5_i8)).unwrap(),
        ),
    )
    .parallel_left(Real::one())
    .unwrap();

    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        assert!(matches!(
            target.exact_rational_parallel_component(&policy).unwrap(),
            Classification::Decided(None),
        ));
        let Classification::Decided(polynomial) = BezierParameterPolynomial::try_new_power_basis(
            vec![-half.clone(), Real::one(), Real::one()],
            &policy,
        )
        .unwrap() else {
            panic!("the selected-center polynomial must construct");
        };
        let Classification::Decided(interval) =
            BezierParameterInterval::try_new(Real::zero(), half.clone(), &policy).unwrap()
        else {
            panic!("the selected-center interval must construct");
        };
        let Classification::Decided(center_parameter) =
            BezierAlgebraicParameter2::try_isolate(polynomial, interval, &policy).unwrap()
        else {
            panic!("the selected center must isolate");
        };
        let Classification::Decided(Some(first_half)) =
            BezierAlgebraicCuspSemicircle2::from_selected_parallel_normal(
                support.clone(),
                BezierParameter2::Algebraic(center_parameter).into(),
                Real::one(),
                false,
                &policy,
            )
            .unwrap()
        else {
            panic!("the selected circle must construct");
        };
        let selected_boundary = CurveRegionBoundaryLoop2::new(
            vec![
                BezierSplitFragment2::AlgebraicCuspSemicircle(
                    BezierAlgebraicCuspSemicircleFragment2::full(first_half.clone(), &policy),
                ),
                BezierSplitFragment2::AlgebraicCuspSemicircle(
                    BezierAlgebraicCuspSemicircleFragment2::full(
                        first_half.complementary_half(),
                        &policy,
                    ),
                ),
            ],
            &policy,
        )
        .unwrap();
        let selected_region = CurveRegion2::try_new_with_loop_topology(
            vec![selected_boundary],
            vec![CurveRegionLoopRole::Material],
            vec![FillRule::NonZero],
            vec![CurveBoundaryInteriorSide2::Left],
        )
        .unwrap();

        // The rational tangent charts u=10/19 and u=9/19 give exact unit
        // normals at these two nearby parameters. The narrow retained
        // range discards unrelated full-carrier projection roots before
        // their expensive selected-branch replay while keeping t=1/2
        // strictly interior.
        let target_start_parameter = (Real::from(83_i16) / Real::from(190_i16)).unwrap();
        let target_end_parameter = (Real::from(389_i16) / Real::from(684_i16)).unwrap();
        let Classification::Decided(target_fragment) = BezierParallelFragment2::try_new(
            target.clone(),
            BezierParameterRange2::new_validated(
                BezierParameter2::Exact(target_start_parameter.clone()),
                BezierParameter2::Exact(target_end_parameter.clone()),
            ),
            &policy,
        )
        .unwrap() else {
            panic!("the genuinely analytic target must remain regular");
        };
        let Classification::Decided(target_start) =
            target.point_at(&target_start_parameter, &policy).unwrap()
        else {
            panic!("the target start must be represented");
        };
        let Classification::Decided(target_end) =
            target.point_at(&target_end_parameter, &policy).unwrap()
        else {
            panic!("the target end must be represented");
        };
        let line_fragment = |start, end| BezierSplitFragment2::Materialized {
            start: BezierParameter2::Exact(Real::zero()),
            end: BezierParameter2::Exact(Real::one()),
            curve: BezierSubcurve2::Quadratic(QuadraticBezier2::from_line_segment(
                LineSeg2::try_new(start, end).unwrap(),
            )),
        };
        let upper_right = Point2::from_values(4, 3);
        let lower_right = Point2::from_values(4, -3);
        let target_boundary = CurveRegionBoundaryLoop2::new(
            vec![
                BezierSplitFragment2::AnalyticParallel(target_fragment),
                line_fragment(target_end, upper_right.clone()),
                line_fragment(upper_right, lower_right.clone()),
                line_fragment(lower_right, target_start),
            ],
            &policy,
        )
        .unwrap();
        let target_region = CurveRegion2::try_new_with_loop_topology(
            vec![target_boundary],
            vec![CurveRegionLoopRole::Material],
            vec![FillRule::NonZero],
            vec![CurveBoundaryInteriorSide2::Right],
        )
        .unwrap();

        let evidence = selected_region
            .intersect_region(&target_region, &policy)
            .expect("a selected circle must intersect a genuinely analytic region")
            .into_value();
        assert!(evidence.blockers().is_empty());
        assert!(evidence.contacts().iter().any(|contact| {
            contact.first_parameter().is_algebraic_cusp()
                && contact.second_parameter().is_retained_scalar()
        }));

        let booleans = selected_region
            .boolean_regions(&target_region, &policy)
            .expect("selected-fiber analytic contacts must complete Boolean topology")
            .into_value();
        assert!(!booleans.union().is_empty());
        assert!(!booleans.intersection().is_empty());
        assert!(!booleans.difference().is_empty());
        assert!(!booleans.xor().is_empty());
        assert!(
            [
                booleans.union(),
                booleans.intersection(),
                booleans.difference(),
                booleans.xor(),
            ]
            .into_iter()
            .flat_map(|region| region.boundary_loops())
            .flat_map(CurveRegionBoundaryLoop2::fragments)
            .any(|fragment| matches!(
                fragment,
                BezierSplitFragment2::SelectedFiber(fragment)
                    if fragment.analytic_parallel().is_some()
            )),
            "Boolean output must retain the authored analytic selected-fiber carrier"
        );
    }
}

#[test]
fn selected_fiber_rational_circle_overlaps_complete_region_booleans() {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let support = QuadraticBezier2::new(
        Point2::from_values(0, 0),
        Point2::new(half.clone(), Real::zero()),
        Point2::from_values(2, 0),
    )
    .parallel_left(Real::zero())
    .unwrap();
    let rational_quarter = |start: Point2, control: Point2, end: Point2| {
        RationalQuadraticBezier2::try_new(
            start,
            control,
            end,
            Real::one(),
            Real::one(),
            Real::from(2_i8),
        )
        .unwrap()
    };
    let rational_circle = [
        rational_quarter(
            Point2::new(half.clone(), Real::one()),
            Point2::new(-half.clone(), Real::one()),
            Point2::new(-half.clone(), Real::zero()),
        ),
        rational_quarter(
            Point2::new(-half.clone(), Real::zero()),
            Point2::new(-half.clone(), Real::from(-1_i8)),
            Point2::new(half.clone(), Real::from(-1_i8)),
        ),
        rational_quarter(
            Point2::new(half.clone(), Real::from(-1_i8)),
            Point2::new(&half + Real::one(), Real::from(-1_i8)),
            Point2::new(&half + Real::one(), Real::zero()),
        ),
        rational_quarter(
            Point2::new(&half + Real::one(), Real::zero()),
            Point2::new(&half + Real::one(), Real::one()),
            Point2::new(half.clone(), Real::one()),
        ),
    ];

    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let Classification::Decided(polynomial) = BezierParameterPolynomial::try_new_power_basis(
            vec![-half.clone(), Real::one(), Real::one()],
            &policy,
        )
        .unwrap() else {
            panic!("the selected-center polynomial must construct");
        };
        let Classification::Decided(interval) =
            BezierParameterInterval::try_new(Real::zero(), half.clone(), &policy).unwrap()
        else {
            panic!("the selected-center interval must construct");
        };
        let Classification::Decided(center_parameter) =
            BezierAlgebraicParameter2::try_isolate(polynomial, interval, &policy).unwrap()
        else {
            panic!("the selected center must isolate");
        };
        let Classification::Decided(Some(first_half)) =
            BezierAlgebraicCuspSemicircle2::from_selected_parallel_normal(
                support.clone(),
                BezierParameter2::Algebraic(center_parameter).into(),
                Real::one(),
                false,
                &policy,
            )
            .unwrap()
        else {
            panic!("the algebraic selected circle must construct");
        };
        let second_half = first_half.complementary_half();
        let quarter = (Real::one() / Real::from(4_i8)).unwrap();
        let three_quarters = &half + &quarter;
        let partial_first_half = |start: Real, end: Real| {
            let Classification::Decided(fragment) =
                BezierAlgebraicCuspSemicircleFragment2::try_new(
                    first_half.clone(),
                    BezierAlgebraicCuspSemicircleParameter2::Exact(start),
                    BezierAlgebraicCuspSemicircleParameter2::Exact(end),
                    false,
                    &policy,
                )
                .unwrap()
            else {
                panic!("the strict cusp partition must construct");
            };
            BezierSplitFragment2::AlgebraicCuspSemicircle(fragment)
        };
        let selected_boundary = CurveRegionBoundaryLoop2::new(
            vec![
                partial_first_half(Real::zero(), quarter.clone()),
                partial_first_half(quarter, three_quarters.clone()),
                partial_first_half(three_quarters, Real::one()),
                BezierSplitFragment2::AlgebraicCuspSemicircle(
                    BezierAlgebraicCuspSemicircleFragment2::full(second_half, &policy),
                ),
            ],
            &policy,
        )
        .unwrap();
        let selected_region = CurveRegion2::try_new_with_loop_topology(
            vec![selected_boundary],
            vec![CurveRegionLoopRole::Material],
            vec![FillRule::NonZero],
            vec![CurveBoundaryInteriorSide2::Left],
        )
        .unwrap();
        let rational_boundary = CurveRegionBoundaryLoop2::new(
            rational_circle
                .iter()
                .cloned()
                .map(|curve| BezierSplitFragment2::Materialized {
                    start: BezierParameter2::Exact(Real::zero()),
                    end: BezierParameter2::Exact(Real::one()),
                    curve: BezierSubcurve2::RationalQuadratic(curve),
                })
                .collect(),
            &policy,
        )
        .unwrap();
        let rational_region = CurveRegion2::try_new_with_loop_topology(
            vec![rational_boundary],
            vec![CurveRegionLoopRole::Material],
            vec![FillRule::NonZero],
            vec![CurveBoundaryInteriorSide2::Left],
        )
        .unwrap();

        let evidence = selected_region
            .intersect_region(&rational_region, &policy)
            .expect("selected-fiber circle overlaps must publish complete evidence")
            .into_value();
        assert!(evidence.blockers().is_empty());
        assert_eq!(evidence.overlaps().len(), 6);
        assert!(evidence.overlaps().iter().all(|overlap| {
            overlap.overlap().first_range().start().is_algebraic_cusp()
                && overlap
                    .overlap()
                    .second_range()
                    .start()
                    .is_retained_scalar()
                && overlap.overlap().second_range().end().is_retained_scalar()
        }));

        let result = selected_region
            .boolean_regions(&rational_region, &policy)
            .expect("selected-fiber circle overlaps must complete Boolean topology")
            .into_value();
        assert!(!result.union().is_empty());
        assert!(!result.intersection().is_empty());
        assert!(result.difference().is_empty());
        assert!(result.xor().is_empty());
    }
}

#[test]
fn selected_fiber_analytic_circle_overlaps_complete_region_booleans() {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let support = QuadraticBezier2::new(
        Point2::from_values(0, 0),
        Point2::new(half.clone(), Real::zero()),
        Point2::from_values(2, 0),
    )
    .parallel_left(Real::zero())
    .unwrap();
    let analytic_quarter = |start: Point2, control: Point2, end: Point2| {
        RationalBezier2::from(
            RationalQuadraticBezier2::try_new(
                start,
                control,
                end,
                Real::one(),
                Real::one(),
                Real::from(2_i8),
            )
            .unwrap(),
        )
        .parallel_left(Real::one())
        .unwrap()
    };
    let analytic_circle = [
        analytic_quarter(
            Point2::new(half.clone(), Real::from(2_i8)),
            Point2::new(half.clone() - Real::from(2_i8), Real::from(2_i8)),
            Point2::new(half.clone() - Real::from(2_i8), Real::zero()),
        ),
        analytic_quarter(
            Point2::new(half.clone() - Real::from(2_i8), Real::zero()),
            Point2::new(half.clone() - Real::from(2_i8), Real::from(-2_i8)),
            Point2::new(half.clone(), Real::from(-2_i8)),
        ),
        analytic_quarter(
            Point2::new(half.clone(), Real::from(-2_i8)),
            Point2::new(&half + Real::from(2_i8), Real::from(-2_i8)),
            Point2::new(&half + Real::from(2_i8), Real::zero()),
        ),
        analytic_quarter(
            Point2::new(&half + Real::from(2_i8), Real::zero()),
            Point2::new(&half + Real::from(2_i8), Real::from(2_i8)),
            Point2::new(half.clone(), Real::from(2_i8)),
        ),
    ];

    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let Classification::Decided(polynomial) = BezierParameterPolynomial::try_new_power_basis(
            vec![-half.clone(), Real::one(), Real::one()],
            &policy,
        )
        .unwrap() else {
            panic!("the selected-center polynomial must construct");
        };
        let Classification::Decided(interval) =
            BezierParameterInterval::try_new(Real::zero(), half.clone(), &policy).unwrap()
        else {
            panic!("the selected-center interval must construct");
        };
        let Classification::Decided(center_parameter) =
            BezierAlgebraicParameter2::try_isolate(polynomial, interval, &policy).unwrap()
        else {
            panic!("the selected center must isolate");
        };
        let Classification::Decided(Some(first_half)) =
            BezierAlgebraicCuspSemicircle2::from_selected_parallel_normal(
                support.clone(),
                BezierParameter2::Algebraic(center_parameter).into(),
                Real::one(),
                false,
                &policy,
            )
            .unwrap()
        else {
            panic!("the algebraic selected circle must construct");
        };
        let second_half = first_half.complementary_half();
        let quarter = (Real::one() / Real::from(4_i8)).unwrap();
        let three_quarters = &half + &quarter;
        let partial_first_half = |start: Real, end: Real| {
            let Classification::Decided(fragment) =
                BezierAlgebraicCuspSemicircleFragment2::try_new(
                    first_half.clone(),
                    BezierAlgebraicCuspSemicircleParameter2::Exact(start),
                    BezierAlgebraicCuspSemicircleParameter2::Exact(end),
                    false,
                    &policy,
                )
                .unwrap()
            else {
                panic!("the strict cusp partition must construct");
            };
            BezierSplitFragment2::AlgebraicCuspSemicircle(fragment)
        };
        let selected_boundary = CurveRegionBoundaryLoop2::new(
            vec![
                partial_first_half(Real::zero(), quarter.clone()),
                partial_first_half(quarter, three_quarters.clone()),
                partial_first_half(three_quarters, Real::one()),
                BezierSplitFragment2::AlgebraicCuspSemicircle(
                    BezierAlgebraicCuspSemicircleFragment2::full(second_half, &policy),
                ),
            ],
            &policy,
        )
        .unwrap();
        let selected_region = CurveRegion2::try_new_with_loop_topology(
            vec![selected_boundary],
            vec![CurveRegionLoopRole::Material],
            vec![FillRule::NonZero],
            vec![CurveBoundaryInteriorSide2::Left],
        )
        .unwrap();
        let analytic_boundary = CurveRegionBoundaryLoop2::new(
            analytic_circle
                .iter()
                .cloned()
                .map(|parallel| {
                    let Classification::Decided(fragment) = BezierParallelFragment2::try_new(
                        parallel,
                        BezierParameterRange2::new_validated(
                            BezierParameter2::Exact(Real::zero()),
                            BezierParameter2::Exact(Real::one()),
                        ),
                        &policy,
                    )
                    .unwrap() else {
                        panic!("the exact analytic quarter must remain regular");
                    };
                    BezierSplitFragment2::AnalyticParallel(fragment)
                })
                .collect(),
            &policy,
        )
        .unwrap();
        let analytic_region = CurveRegion2::try_new_with_loop_topology(
            vec![analytic_boundary],
            vec![CurveRegionLoopRole::Material],
            vec![FillRule::NonZero],
            vec![CurveBoundaryInteriorSide2::Left],
        )
        .unwrap();

        let evidence = selected_region
            .intersect_region(&analytic_region, &policy)
            .expect("selected-fiber analytic overlaps must publish complete evidence")
            .into_value();
        assert!(evidence.blockers().is_empty());
        assert_eq!(evidence.overlaps().len(), 6);
        assert!(evidence.overlaps().iter().all(|overlap| {
            overlap.overlap().first_range().start().is_algebraic_cusp()
                && overlap
                    .overlap()
                    .second_range()
                    .start()
                    .is_retained_scalar()
                && overlap.overlap().second_range().end().is_retained_scalar()
        }));

        let result = selected_region
            .boolean_regions(&analytic_region, &policy)
            .expect("selected-fiber analytic overlaps must complete Boolean topology")
            .into_value();
        assert!(!result.union().is_empty());
        assert!(!result.intersection().is_empty());
        assert!(result.difference().is_empty());
        assert!(result.xor().is_empty());
    }
}

#[test]
fn exact_parallel_similarity_transports_points_derivatives_and_structure() {
    let source = QuadraticBezier2::new(
        Point2::from_values(0, 0),
        Point2::from_values(1, 2),
        Point2::from_values(3, 1),
    );
    let distance = (Real::one() / Real::from(2_i8)).unwrap();
    let parallel = source.parallel_left(distance).unwrap();
    let transform = Similarity2::try_from_real_affine(
        Real::zero(),
        Real::from(-2_i8),
        Real::from(2_i8),
        Real::zero(),
        Real::from(5_i8),
        Real::from(-7_i8),
    )
    .unwrap();
    let transformed = parallel.transform_similarity(&transform).unwrap();
    assert_eq!(transformed.distance(), &Real::one());
    assert!(matches!(
        transformed.source(),
        BezierParallelSource2::Quadratic(_)
    ));

    let parameter = (Real::one() / Real::from(3_i8)).unwrap();
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let Classification::Decided(source_point) = parallel.point_at(&parameter, &policy).unwrap()
        else {
            panic!("source parallel point became uncertain");
        };
        let Classification::Decided(transformed_point) =
            transformed.point_at(&parameter, &policy).unwrap()
        else {
            panic!("transformed parallel point became uncertain");
        };
        assert_eq!(transformed_point, transform.transform_point(&source_point));

        let Classification::Decided(source_derivative) =
            parallel.derivative_at(&parameter, &policy).unwrap()
        else {
            panic!("source parallel derivative became uncertain");
        };
        let Classification::Decided(transformed_derivative) =
            transformed.derivative_at(&parameter, &policy).unwrap()
        else {
            panic!("transformed parallel derivative became uncertain");
        };
        assert_eq!(
            transformed_derivative.dx(),
            &(Real::from(-2_i8) * source_derivative.dy())
        );
        assert_eq!(
            transformed_derivative.dy(),
            &(Real::from(2_i8) * source_derivative.dx())
        );
    }

    let reconstructed =
        BezierParallel2::from_source(transformed.source().clone(), transformed.distance().clone());
    assert_eq!(reconstructed, transformed);
}

#[test]
fn exact_parallel_reflection_negates_scaled_left_distance() {
    let source = QuadraticBezier2::from_line_segment(
        LineSeg2::try_new(Point2::from_values(0, 0), Point2::from_values(2, 0)).unwrap(),
    );
    let parallel = source.parallel_left(Real::from(2_i8)).unwrap();
    let reflection = Similarity2::try_from_real_affine(
        Real::from(-3_i8),
        Real::zero(),
        Real::zero(),
        Real::from(3_i8),
        Real::zero(),
        Real::zero(),
    )
    .unwrap();
    let transformed = parallel.transform_similarity(&reflection).unwrap();

    assert_eq!(transformed.distance(), &Real::from(-6_i8));
    let BezierParallelSource2::Quadratic(transformed_source) = transformed.source() else {
        panic!("quadratic source family changed under reflection");
    };
    assert!(transformed_source.retained_exact_line_image().is_some());
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        let Classification::Decided(point) = parallel.point_at(&half, &policy).unwrap() else {
            panic!("source line parallel point became uncertain");
        };
        let Classification::Decided(transformed_point) =
            transformed.point_at(&half, &policy).unwrap()
        else {
            panic!("reflected line parallel point became uncertain");
        };
        assert_eq!(transformed_point, reflection.transform_point(&point));
    }
}

fn parameter_lift_map(
    numerator: Vec<Real>,
    denominator: Vec<Real>,
) -> CurveIntersectionParameterLiftMap {
    CurveIntersectionParameterLiftMap {
        cofactor_row: 0,
        numerator_coefficients: numerator,
        denominator_coefficients: denominator,
    }
}

fn rational_component_partition(
    map: &CurveIntersectionParameterLiftMap,
    derivative_numerator: &[Real],
    policy: &CurveContext,
) -> CurveResult<Classification<Option<RationalParameterComponentPartition>>> {
    let mut parameter_image_map = RationalParameterImageMap2::new(
        map.numerator_coefficients.clone(),
        map.denominator_coefficients.clone(),
        policy,
    );
    rational_parameter_component_domains(
        map,
        derivative_numerator,
        &mut parameter_image_map,
        policy,
    )
}

#[test]
fn rational_component_domain_clips_increasing_and_decreasing_maps_exactly() {
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let increasing = parameter_lift_map(
            vec![Real::from(-1_i8), Real::from(4_i8)],
            vec![Real::from(2_i8)],
        );
        let derivative = polynomial_subtract(
            &polynomial_multiply(
                &polynomial_derivative(&increasing.numerator_coefficients),
                &increasing.denominator_coefficients,
            ),
            &polynomial_multiply(
                &increasing.numerator_coefficients,
                &polynomial_derivative(&increasing.denominator_coefficients),
            ),
        );
        let Classification::Decided(Some(increasing)) =
            rational_component_partition(&increasing, &derivative, &policy).unwrap()
        else {
            panic!("increasing rational map did not clip");
        };
        assert!(increasing.isolated_points.is_empty());
        let [(increasing, std::cmp::Ordering::Less)] = increasing.domains.as_slice() else {
            panic!("increasing map did not produce one increasing domain");
        };
        assert_eq!(
            increasing.retained_start.scalar(),
            Some(&(Real::one() / Real::from(4_i8)).unwrap())
        );
        assert_eq!(
            increasing.retained_end.scalar(),
            Some(&(Real::from(3_i8) / Real::from(4_i8)).unwrap())
        );
        assert_eq!(increasing.lifted_start.scalar(), Some(&Real::zero()));
        assert_eq!(increasing.lifted_end.scalar(), Some(&Real::one()));

        let decreasing = parameter_lift_map(
            vec![Real::from(3_i8), Real::from(-4_i8)],
            vec![Real::from(2_i8)],
        );
        let derivative = polynomial_subtract(
            &polynomial_multiply(
                &polynomial_derivative(&decreasing.numerator_coefficients),
                &decreasing.denominator_coefficients,
            ),
            &polynomial_multiply(
                &decreasing.numerator_coefficients,
                &polynomial_derivative(&decreasing.denominator_coefficients),
            ),
        );
        let Classification::Decided(Some(decreasing)) =
            rational_component_partition(&decreasing, &derivative, &policy).unwrap()
        else {
            panic!("decreasing rational map did not clip");
        };
        assert!(decreasing.isolated_points.is_empty());
        let [(decreasing, std::cmp::Ordering::Greater)] = decreasing.domains.as_slice() else {
            panic!("decreasing map did not produce one decreasing domain");
        };
        assert_eq!(
            decreasing.retained_start.scalar(),
            Some(&(Real::one() / Real::from(4_i8)).unwrap())
        );
        assert_eq!(
            decreasing.retained_end.scalar(),
            Some(&(Real::from(3_i8) / Real::from(4_i8)).unwrap())
        );
        assert_eq!(decreasing.lifted_start.scalar(), Some(&Real::one()));
        assert_eq!(decreasing.lifted_end.scalar(), Some(&Real::zero()));
    }
}

#[test]
fn rational_component_monotonicity_allows_stationary_points_without_sign_reversal() {
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        // 8*((s-1/2)^3+1/2) = 3+6s-12s^2+8s^3 has a
        // positive derivative with one double zero at s=1/2.
        let map = parameter_lift_map(
            vec![
                Real::from(3_i8),
                Real::from(6_i8),
                Real::from(-12_i8),
                Real::from(8_i8),
            ],
            vec![Real::from(8_i8)],
        );
        let derivative_numerator = polynomial_subtract(
            &polynomial_multiply(
                &polynomial_derivative(&map.numerator_coefficients),
                &map.denominator_coefficients,
            ),
            &polynomial_multiply(
                &map.numerator_coefficients,
                &polynomial_derivative(&map.denominator_coefficients),
            ),
        );
        let Classification::Decided(Some(domains)) =
            rational_component_partition(&map, &derivative_numerator, &policy).unwrap()
        else {
            panic!("weakly monotone full-domain map was rejected");
        };
        assert!(domains.isolated_points.is_empty());
        let [(domain, std::cmp::Ordering::Less)] = domains.domains.as_slice() else {
            panic!("stationary increasing map was not merged into one domain");
        };
        assert_eq!(domain.retained_start.scalar(), Some(&Real::zero()));
        assert_eq!(domain.retained_end.scalar(), Some(&Real::one()));
    }
}

#[test]
fn rational_component_domains_split_noninjective_and_pole_separated_maps() {
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let noninjective = parameter_lift_map(
            vec![Real::zero(), Real::from(4_i8), Real::from(-4_i8)],
            vec![Real::one()],
        );
        let derivative = polynomial_subtract(
            &polynomial_multiply(
                &polynomial_derivative(&noninjective.numerator_coefficients),
                &noninjective.denominator_coefficients,
            ),
            &polynomial_multiply(
                &noninjective.numerator_coefficients,
                &polynomial_derivative(&noninjective.denominator_coefficients),
            ),
        );
        let Classification::Decided(Some(domains)) =
            rational_component_partition(&noninjective, &derivative, &policy).unwrap()
        else {
            panic!("noninjective finite map did not partition");
        };
        let [
            (ascending, std::cmp::Ordering::Less),
            (descending, std::cmp::Ordering::Greater),
        ] = domains.domains.as_slice()
        else {
            panic!("noninjective map did not produce two oriented domains");
        };
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        assert_eq!(ascending.retained_start.scalar(), Some(&Real::zero()));
        assert_eq!(ascending.retained_end.scalar(), Some(&half));
        assert_eq!(ascending.lifted_start.scalar(), Some(&Real::zero()));
        assert_eq!(ascending.lifted_end.scalar(), Some(&Real::one()));
        assert_eq!(descending.retained_start.scalar(), Some(&half));
        assert_eq!(descending.retained_end.scalar(), Some(&Real::one()));
        assert_eq!(descending.lifted_start.scalar(), Some(&Real::one()));
        assert_eq!(descending.lifted_end.scalar(), Some(&Real::zero()));

        let quarter = (Real::one() / Real::from(4_i8)).unwrap();
        let pole_split = parameter_lift_map(
            vec![-quarter.clone(), Real::one()],
            vec![Real::from(-1_i8), Real::from(2_i8)],
        );
        let derivative = polynomial_subtract(
            &polynomial_multiply(
                &polynomial_derivative(&pole_split.numerator_coefficients),
                &pole_split.denominator_coefficients,
            ),
            &polynomial_multiply(
                &pole_split.numerator_coefficients,
                &polynomial_derivative(&pole_split.denominator_coefficients),
            ),
        );
        let Classification::Decided(Some(domains)) =
            rational_component_partition(&pole_split, &derivative, &policy).unwrap()
        else {
            panic!("pole-separated finite branches did not partition");
        };
        let [
            (first, std::cmp::Ordering::Greater),
            (second, std::cmp::Ordering::Greater),
        ] = domains.domains.as_slice()
        else {
            panic!("pole-separated map did not retain both finite branches");
        };
        let three_quarters = (Real::from(3_i8) / Real::from(4_i8)).unwrap();
        assert_eq!(first.retained_start.scalar(), Some(&Real::zero()));
        assert_eq!(first.retained_end.scalar(), Some(&quarter));
        assert_eq!(first.lifted_start.scalar(), Some(&quarter));
        assert_eq!(first.lifted_end.scalar(), Some(&Real::zero()));
        assert_eq!(second.retained_start.scalar(), Some(&three_quarters));
        assert_eq!(second.retained_end.scalar(), Some(&Real::one()));
        assert_eq!(second.lifted_start.scalar(), Some(&Real::one()));
        assert_eq!(second.lifted_end.scalar(), Some(&three_quarters));
    }
}

#[test]
fn rational_component_domains_retain_isolated_closed_square_touches() {
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let tangent_touch = parameter_lift_map(
            vec![Real::from(-1_i8), Real::from(4_i8), Real::from(-4_i8)],
            vec![Real::one()],
        );
        let derivative = polynomial_subtract(
            &polynomial_multiply(
                &polynomial_derivative(&tangent_touch.numerator_coefficients),
                &tangent_touch.denominator_coefficients,
            ),
            &polynomial_multiply(
                &tangent_touch.numerator_coefficients,
                &polynomial_derivative(&tangent_touch.denominator_coefficients),
            ),
        );
        let Classification::Decided(Some(partition)) =
            rational_component_partition(&tangent_touch, &derivative, &policy).unwrap()
        else {
            panic!("isolated closed-square component touch was not partitioned");
        };
        assert!(partition.domains.is_empty());
        let [point] = partition.isolated_points.as_slice() else {
            panic!("isolated component touch was not retained exactly once");
        };
        assert_eq!(
            point.retained_parameter.scalar(),
            Some(&(Real::one() / Real::from(2_i8)).unwrap())
        );
        assert_eq!(point.lifted_parameter.scalar(), Some(&Real::zero()));
    }
}

#[test]
fn rational_component_range_checks_reject_only_relevant_roots() {
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let quarter = BezierParameter2::Exact((Real::one() / Real::from(4_i8)).unwrap());
        let three_quarters =
            BezierParameter2::Exact((Real::from(3_i8) / Real::from(4_i8)).unwrap());
        assert_eq!(
            polynomial_is_rootless_on_parameter_range(
                &[Real::from(-1_i8), Real::from(10_i8)],
                &quarter,
                &three_quarters,
                &policy,
            )
            .unwrap(),
            Classification::Decided(true)
        );
        assert_eq!(
            polynomial_is_rootless_on_parameter_range(
                &[Real::from(-1_i8), Real::from(2_i8)],
                &quarter,
                &three_quarters,
                &policy,
            )
            .unwrap(),
            Classification::Decided(false)
        );
        let zero = BezierParameter2::Exact(Real::zero());
        let one = BezierParameter2::Exact(Real::one());
        assert_eq!(
            polynomial_is_rootless_on_parameter_range(
                &[Real::from(-1_i8), Real::from(2_i8)],
                &zero,
                &one,
                &policy,
            )
            .unwrap(),
            Classification::Decided(false)
        );
    }
}

#[test]
fn rational_component_certificate_replays_equations_branch_and_poles() {
    let identity_equation = BivariatePolynomial::new(vec![
        vec![Real::zero(), Real::one()],
        vec![Real::from(-1_i8)],
    ]);
    let identity = parameter_lift_map(vec![Real::zero(), Real::one()], vec![Real::one()]);
    let selected_branch = BivariatePolynomial::new(vec![vec![Real::one()]]);
    let opposite_branch = BivariatePolynomial::new(vec![vec![Real::from(-1_i8)]]);
    let vanishing_branch =
        BivariatePolynomial::new(vec![vec![Real::from(-1_i8)], vec![Real::from(2_i8)]]);
    let pole_equation = BivariatePolynomial::new(vec![
        vec![Real::zero(), Real::one()],
        vec![Real::from(-1_i8), Real::from(-2_i8)],
    ]);
    let pole_map = parameter_lift_map(
        vec![Real::zero(), Real::one()],
        vec![Real::one(), Real::from(-2_i8)],
    );

    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let equations = [identity_equation.clone(), identity_equation.clone()];
        let Classification::Decided(Some(evidence)) = certify_rational_parameter_component_map(
            &equations,
            &selected_branch,
            CurveResultantParameter::First,
            &identity,
            &policy,
        )
        .unwrap() else {
            panic!("selected identity component was not certified");
        };
        assert!(evidence.selected_pairs().is_empty());
        let [overlap] = evidence.overlaps.as_ref() else {
            panic!("identity component did not produce exactly one overlap");
        };
        assert_eq!(
            overlap.first_range().scalar_endpoints(),
            Some((&Real::zero(), &Real::one()))
        );
        assert_eq!(
            overlap.second_range().scalar_endpoints(),
            Some((&Real::zero(), &Real::one()))
        );
        assert!(overlap.includes_start());
        assert!(overlap.includes_end());
        let Classification::Decided(Some(opposite)) = certify_rational_parameter_component_map(
            &equations,
            &opposite_branch,
            CurveResultantParameter::First,
            &identity,
            &policy,
        )
        .unwrap() else {
            panic!("opposite component was not decided");
        };
        assert!(opposite.overlaps.is_empty());
        assert!(opposite.selected_pairs().is_empty());
        let Classification::Decided(Some(vanishing)) = certify_rational_parameter_component_map(
            &equations,
            &vanishing_branch,
            CurveResultantParameter::First,
            &identity,
            &policy,
        )
        .unwrap() else {
            panic!("an isolated branch zero did not partition the rational component");
        };
        assert!(vanishing.selected_pairs().is_empty());
        assert_eq!(vanishing.excluded_pairs().len(), 1);
        let [overlap] = vanishing.overlaps.as_ref() else {
            panic!("the positive half of the rational component was not retained");
        };
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        assert_eq!(
            overlap.first_range().scalar_endpoints(),
            Some((&half, &Real::one()))
        );
        assert_eq!(
            overlap.second_range().scalar_endpoints(),
            Some((&half, &Real::one()))
        );
        assert!(!overlap.includes_start());
        assert!(overlap.includes_end());
        let Classification::Decided(Some(zero_branch)) = certify_rational_parameter_component_map(
            &equations,
            &identity_equation,
            CurveResultantParameter::First,
            &identity,
            &policy,
        )
        .unwrap() else {
            panic!("an identically zero selected branch was not decided");
        };
        assert!(zero_branch.overlaps.is_empty());
        assert!(zero_branch.selected_pairs().is_empty());
        assert!(zero_branch.excluded_pairs().is_empty());

        let pole_equations = [pole_equation.clone(), pole_equation.clone()];
        let Classification::Decided(Some(evidence)) = certify_rational_parameter_component_map(
            &pole_equations,
            &selected_branch,
            CurveResultantParameter::First,
            &pole_map,
            &policy,
        )
        .unwrap() else {
            panic!("finite component domain before a pole was not retained");
        };
        assert!(evidence.selected_pairs().is_empty());
        let [overlap] = evidence.overlaps.as_ref() else {
            panic!("pole-split map did not produce one finite overlap");
        };
        assert_eq!(
            overlap.first_range().scalar_endpoints(),
            Some((&Real::zero(), &(Real::one() / Real::from(3_i8)).unwrap()))
        );
        assert_eq!(
            overlap.second_range().scalar_endpoints(),
            Some((&Real::zero(), &Real::one()))
        );
    }
}

#[test]
fn parallel_pair_component_selector_owns_a_selected_tangent_event() {
    let identity = BivariatePolynomial::new(vec![
        vec![Real::zero(), Real::one()],
        vec![Real::from(-1_i8)],
    ]);
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let tangent_cross = BivariatePolynomial::new(vec![vec![-half.clone()], vec![Real::one()]]);
    for (norm_residual, event_is_selected) in [(Real::from(-1_i8), true), (Real::one(), false)] {
        let system = BezierParallelPairEquationSystem2 {
            first_equation: identity.clone(),
            second_equation: identity.clone(),
            norm_equation: identity.clone(),
            first_projection: tangent_cross.clone(),
            second_projection: tangent_cross.clone(),
            tangent_cross: tangent_cross.clone(),
            tangent_dot: BivariatePolynomial::new(vec![vec![Real::one()]]),
            norm_residual: BivariatePolynomial::new(vec![vec![norm_residual]]),
            first_normal_projection: BivariatePolynomial::new(vec![vec![Real::one()]]),
            first_distance: Real::one(),
            second_distance: Real::one(),
            first_distance_sign: RealSign::Positive,
            second_distance_sign: RealSign::Positive,
            weight_product: BivariatePolynomial::new(vec![vec![Real::one()]]),
        };
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let config = CurveIntersectionResultantConfig {
                min_precision: PARALLEL_INTERSECTION_RESULTANT_PRECISION,
                max_resultant_degree: MAX_PARALLEL_INTERSECTION_RESULTANT_DEGREE,
            };
            let Classification::Decided(Some(component)) =
                parameter_component_system_with_selector(
                    &[identity.clone(), identity.clone()],
                    &ParameterComponentSelector2::ParallelPair {
                        normal_constraints: None,
                        system: &system,
                        parameter_filter: None,
                    },
                    &policy,
                    config,
                )
                .unwrap()
            else {
                panic!("the selected pair component was not partitioned");
            };
            assert_eq!(component.overlaps.len(), 2);
            assert_eq!(
                component.selected_pairs().len(),
                usize::from(event_is_selected),
            );
            assert_eq!(
                component.excluded_pairs().len(),
                usize::from(!event_is_selected),
            );
            assert_eq!(component.overlaps[0].includes_end(), event_is_selected);
            assert_eq!(component.overlaps[1].includes_start(), event_is_selected);
            assert_eq!(
                component.overlaps[0].first_range().end().scalar(),
                Some(&half),
            );
            assert_eq!(
                component.overlaps[1].first_range().start().scalar(),
                Some(&half),
            );
        }
    }
}

#[test]
fn parallel_self_component_selector_keeps_one_ordered_half() {
    let complement = BivariatePolynomial::new(vec![
        vec![Real::from(-1_i8), Real::one()],
        vec![Real::one()],
    ]);
    let one = BivariatePolynomial::new(vec![vec![Real::one()]]);
    let system = BezierParallelPairEquationSystem2 {
        first_equation: complement.clone(),
        second_equation: complement.clone(),
        norm_equation: complement.clone(),
        first_projection: one.clone(),
        second_projection: one.clone(),
        tangent_cross: one.clone(),
        tangent_dot: one.clone(),
        norm_residual: one.clone(),
        first_normal_projection: one,
        first_distance: Real::one(),
        second_distance: Real::one(),
        first_distance_sign: RealSign::Positive,
        second_distance_sign: RealSign::Positive,
        weight_product: BivariatePolynomial::new(vec![vec![Real::one()]]),
    };
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let config = CurveIntersectionResultantConfig {
            min_precision: PARALLEL_INTERSECTION_RESULTANT_PRECISION,
            max_resultant_degree: MAX_PARALLEL_INTERSECTION_RESULTANT_DEGREE,
        };
        let Classification::Decided(Some(component)) = parameter_component_system_with_selector(
            &[complement.clone(), complement.clone()],
            &ParameterComponentSelector2::ParallelPair {
                normal_constraints: None,
                system: &system,
                parameter_filter: Some(&BivariatePolynomial::new(vec![
                    vec![Real::zero(), Real::one()],
                    vec![-Real::one()],
                ])),
            },
            &policy,
            config,
        )
        .unwrap() else {
            panic!("the symmetric self component was not ordered");
        };
        let [overlap] = component.overlaps.as_ref() else {
            panic!("one strict half of the self component must remain");
        };
        assert_eq!(
            overlap.first_range().scalar_endpoints(),
            Some((&Real::zero(), &half)),
        );
        assert_eq!(
            overlap.second_range().scalar_endpoints(),
            Some((&Real::one(), &half)),
        );
        assert_eq!(overlap.orientation(), CurveOverlapOrientation2::Reversed,);
        assert!(overlap.includes_start());
        assert!(!overlap.includes_end());
        assert!(component.selected_pairs().is_empty());
        assert_eq!(component.excluded_pairs().len(), 1);
    }
}

#[test]
fn parallel_pair_selector_splits_a_reducible_boundary_factor() {
    // The first support 4u-t=0 is also the tangent/projection boundary.
    // The second support 4u+t-4=0 never meets that boundary on the
    // authored square. The remaining tangent-parallel predicates must be
    // allowed to select or reject the first support without preventing the
    // transverse second support from being certified.
    let boundary_component = BivariatePolynomial::new(vec![
        vec![Real::zero(), Real::from(4_i8)],
        vec![Real::from(-1_i8)],
    ]);
    let transverse_component = BivariatePolynomial::new(vec![
        vec![Real::from(-4_i8), Real::from(4_i8)],
        vec![Real::one()],
    ]);
    let component = bivariate_multiply(&boundary_component, &transverse_component);
    let one = BivariatePolynomial::new(vec![vec![Real::one()]]);
    let negative_one = BivariatePolynomial::new(vec![vec![Real::from(-1_i8)]]);
    let config = CurveIntersectionResultantConfig {
        min_precision: PARALLEL_INTERSECTION_RESULTANT_PRECISION,
        max_resultant_degree: MAX_PARALLEL_INTERSECTION_RESULTANT_DEGREE,
    };

    for (second_distance, expected_overlaps) in [(Real::one(), 2), (Real::from(2_i8), 1)] {
        let system = BezierParallelPairEquationSystem2 {
            first_equation: component.clone(),
            second_equation: component.clone(),
            norm_equation: component.clone(),
            first_projection: boundary_component.clone(),
            second_projection: boundary_component.clone(),
            tangent_cross: boundary_component.clone(),
            tangent_dot: one.clone(),
            norm_residual: negative_one.clone(),
            first_normal_projection: one.clone(),
            first_distance: Real::one(),
            second_distance,
            first_distance_sign: RealSign::Positive,
            second_distance_sign: RealSign::Positive,
            weight_product: BivariatePolynomial::new(vec![vec![Real::one()]]),
        };
        for retained_parameter in [
            CurveResultantParameter::First,
            CurveResultantParameter::Second,
        ] {
            for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
                let Classification::Decided(Some(evidence)) =
                    certify_regular_implicit_parameter_component_with_selector(
                        &component,
                        &ParameterComponentSelector2::ParallelPair {
                            normal_constraints: None,
                            system: &system,
                            parameter_filter: None,
                        },
                        retained_parameter,
                        &policy,
                        config,
                    )
                    .unwrap()
                else {
                    panic!("the selector-boundary factor was not split exactly");
                };
                assert_eq!(evidence.overlaps.len(), expected_overlaps);
                assert_eq!(evidence.component_overlaps.len(), expected_overlaps);
                assert!(evidence.overlaps.iter().any(|overlap| {
                    overlap.orientation() == CurveOverlapOrientation2::Reversed
                        && overlap.second_range().scalar_endpoints()
                            == Some((
                                &Real::one(),
                                &(Real::from(3_i8) / Real::from(4_i8)).unwrap(),
                            ))
                }));
                if expected_overlaps == 2 {
                    assert!(evidence.overlaps.iter().any(|overlap| {
                        overlap.orientation() == CurveOverlapOrientation2::Same
                            && overlap.second_range().scalar_endpoints()
                                == Some((&Real::zero(), &(Real::one() / Real::from(4_i8)).unwrap()))
                    }));
                }
            }
        }
    }
}

#[test]
fn parameter_domains_limit_component_charts() {
    let zero = Real::zero();
    let one = Real::one();
    let half = (one.clone() / Real::from(2_i8)).unwrap();
    let quarter = &half * &half;
    let first_barrier = BezierParameter2::Exact(&one + &half);
    let second_barrier = BezierParameter2::Exact(-(&half + &quarter));
    let rays = [
        BezierParameterRay2 {
            anchor: &one,
            direction: BezierParameterRayDirection2::Increasing,
            barrier: Some(&first_barrier),
        },
        BezierParameterRay2 {
            anchor: &zero,
            direction: BezierParameterRayDirection2::Decreasing,
            barrier: Some(&second_barrier),
        },
    ];
    let config = CurveIntersectionResultantConfig {
        min_precision: PARALLEL_INTERSECTION_RESULTANT_PRECISION,
        max_resultant_degree: MAX_PARALLEL_INTERSECTION_RESULTANT_DEGREE,
    };
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        for extend_first in [false, true] {
            for extend_second in [false, true] {
                let extensions = [
                    extend_first.then_some(rays[0]),
                    extend_second.then_some(rays[1]),
                ];
                // t=u, t=u+2, t=5/4, u=-1/2, t=3/2 and u=-3/4.
                // The last two lie exactly on excluded regularity barriers.
                for (support, expected) in [
                    (
                        BivariatePolynomial::new(vec![
                            vec![zero.clone(), one.clone()],
                            vec![-&one],
                        ]),
                        true,
                    ),
                    (
                        BivariatePolynomial::new(vec![
                            vec![Real::from(2_i8), one.clone()],
                            vec![-&one],
                        ]),
                        extend_first && extend_second,
                    ),
                    (
                        BivariatePolynomial::new(vec![vec![-(&one + &quarter)], vec![one.clone()]]),
                        extend_first,
                    ),
                    (
                        BivariatePolynomial::new(vec![vec![half.clone(), one.clone()]]),
                        extend_second,
                    ),
                    (
                        BivariatePolynomial::new(vec![vec![-(&one + &half)], vec![one.clone()]]),
                        false,
                    ),
                    (
                        BivariatePolynomial::new(vec![vec![&half + &quarter, one.clone()]]),
                        false,
                    ),
                ] {
                    let system = positive_component_selector_system(&support);
                    let Classification::Decided(selection) = select_parameter_component_in_domain(
                        &support,
                        &ParameterComponentSelector2::ParallelPair {
                            normal_constraints: None,
                            system: &system,
                            parameter_filter: None,
                        },
                        [
                            CurveParameterDomain2::new(
                                &CurveParameterRange2::unit(),
                                extensions[0],
                            ),
                            CurveParameterDomain2::new(
                                &CurveParameterRange2::unit(),
                                extensions[1],
                            ),
                        ],
                        ParameterComponentQuery2::FirstComponent(None),
                        &policy,
                        config,
                    )
                    .unwrap() else {
                        panic!("component selection must decide each exact domain")
                    };
                    assert_eq!(
                        selection.has_components(),
                        expected,
                        "first={extend_first}, second={extend_second}, support={support:?}"
                    );
                    if !expected {
                        assert!(selection.selected_pairs.is_empty());
                    }
                }
            }
        }
    }
}

fn positive_component_selector_system(
    support: &BivariatePolynomial,
) -> BezierParallelPairEquationSystem2 {
    let one = BivariatePolynomial::new(vec![vec![Real::one()]]);
    BezierParallelPairEquationSystem2 {
        first_equation: support.clone(),
        second_equation: support.clone(),
        norm_equation: support.clone(),
        first_projection: one.clone(),
        second_projection: one.clone(),
        tangent_cross: one.clone(),
        tangent_dot: one.clone(),
        norm_residual: one.clone(),
        first_normal_projection: one,
        first_distance: Real::one(),
        second_distance: Real::one(),
        first_distance_sign: RealSign::Positive,
        second_distance_sign: RealSign::Positive,
        weight_product: BivariatePolynomial::new(vec![vec![Real::one()]]),
    }
}

#[test]
fn parameter_domains_retain_isolated_constraints() {
    let zero = Real::zero();
    let one = Real::one();
    let half = (one.clone() / Real::from(2_i8)).unwrap();
    let quarter = &half * &half;
    let first_parameter = &one + &quarter;
    let first_barrier = BezierParameter2::Exact(&one + &half);
    let second_barrier = BezierParameter2::Exact(-(&half + &quarter));
    let rays = [
        BezierParameterRay2 {
            anchor: &one,
            direction: BezierParameterRayDirection2::Increasing,
            barrier: Some(&first_barrier),
        },
        BezierParameterRay2 {
            anchor: &zero,
            direction: BezierParameterRayDirection2::Decreasing,
            barrier: Some(&second_barrier),
        },
    ];
    let config = CurveIntersectionResultantConfig {
        min_precision: PARALLEL_INTERSECTION_RESULTANT_PRECISION,
        max_resultant_degree: MAX_PARALLEL_INTERSECTION_RESULTANT_DEGREE,
    };
    // h=t-u-2 is a component only when both sides extend. The independent
    // residual (t,u)=(5/4,1/2) needs only the first extension.
    let component =
        BivariatePolynomial::new(vec![vec![Real::from(-2_i8), -&one], vec![one.clone()]]);
    let support = bivariate_multiply(
        &component,
        &BivariatePolynomial::new(vec![vec![-&first_parameter], vec![one.clone()]]),
    );
    let constraint = bivariate_multiply(
        &component,
        &BivariatePolynomial::new(vec![vec![-&half, one.clone()]]),
    );
    let system = positive_component_selector_system(&component);
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        for extend_first in [false, true] {
            for extend_second in [false, true] {
                let extensions = [
                    extend_first.then_some(rays[0]),
                    extend_second.then_some(rays[1]),
                ];
                let Classification::Decided(result) = parameter_domain_constraint(
                    support.clone(),
                    &constraint,
                    [
                        CurveParameterDomain2::new(&CurveParameterRange2::unit(), extensions[0]),
                        CurveParameterDomain2::new(&CurveParameterRange2::unit(), extensions[1]),
                    ],
                    &policy,
                    config,
                )
                .unwrap() else {
                    panic!("component saturation and residual projection must decide")
                };
                let component = result
                    .component_support
                    .expect("the common polynomial factor survives");
                let Classification::Decided(selection) = select_parameter_component_in_domain(
                    &component,
                    &ParameterComponentSelector2::ParallelPair {
                        normal_constraints: None,
                        system: &system,
                        parameter_filter: None,
                    },
                    [
                        CurveParameterDomain2::new(&CurveParameterRange2::unit(), extensions[0]),
                        CurveParameterDomain2::new(&CurveParameterRange2::unit(), extensions[1]),
                    ],
                    ParameterComponentQuery2::FirstComponent(None),
                    &policy,
                    config,
                )
                .unwrap() else {
                    panic!("the shared component must retain its requested domain")
                };
                assert_eq!(selection.has_components(), extend_first && extend_second);
                assert_eq!(result.isolated_projection.is_some(), extend_first);
                if let Some(projection) = result.isolated_projection {
                    let CurveIntersectionCandidates2::Candidates {
                        first_parameters: parallel_parameters,
                        second_parameters: other_parameters,
                    } = projection.candidates
                    else {
                        panic!("the isolated pair must survive saturation")
                    };
                    assert_eq!(parallel_parameters.len(), 1);
                    assert_eq!(other_parameters.len(), 1);
                    for (parameter, expected) in [
                        (&parallel_parameters[0], &first_parameter),
                        (&other_parameters[0], &half),
                    ] {
                        assert_eq!(
                            parameter
                                .cmp_by_refinement(
                                    &BezierParameter2::Exact(expected.clone()),
                                    &policy
                                )
                                .unwrap(),
                            Classification::Decided(std::cmp::Ordering::Equal)
                        );
                    }
                }
            }
        }
    }
}

#[test]
fn parameter_domains_retain_finite_residuals_without_unowned_components() {
    let ratio = |n: i32, d: i32| (Real::from(n) / Real::from(d)).unwrap();
    let one = Real::one();
    let component = BivariatePolynomial::new(vec![vec![Real::zero(), -&one], vec![one.clone()]]);
    let system = positive_component_selector_system(&component);
    let config = CurveIntersectionResultantConfig {
        min_precision: PARALLEL_INTERSECTION_RESULTANT_PRECISION,
        max_resultant_degree: MAX_PARALLEL_INTERSECTION_RESULTANT_DEGREE,
    };
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let selected = degree_nine_selected_fiber_parameter_for_test(ratio(1, 2), 32_768, &policy);
        assert!(matches!(
            selected.promoted_bezier_parameter(&policy).unwrap(),
            Classification::Uncertain(_)
        ));
        for origin in [
            CurveParameter2::from(ratio(1, 2)),
            CurveParameter2::from_selected_fiber(selected),
        ] {
            for shift in [-2_i32, 0, 2].map(Real::from) {
                let first_parameter = &shift + ratio(1, 4);
                let second_parameter = &shift + ratio(3, 4);
                // The component t=u misses these disjoint domains, but
                // the isolated residual pair belongs to both finite spans.
                let support = bivariate_multiply(
                    &component,
                    &BivariatePolynomial::new(vec![vec![-&first_parameter], vec![one.clone()]]),
                );
                let constraint = bivariate_multiply(
                    &component,
                    &BivariatePolynomial::new(vec![vec![-&second_parameter, one.clone()]]),
                );
                let boundaries = [-3, -1, 1, 3].map(|numerator| {
                    let Classification::Decided(parameter) = origin
                        .affine_image_unbounded(&one, &(&shift + ratio(numerator, 8)), &policy)
                        .unwrap()
                    else {
                        panic!("finite boundaries must retain their native authority")
                    };
                    parameter
                });
                for reverse_first in [false, true] {
                    for reverse_second in [false, true] {
                        let range = |axis: usize, reverse| {
                            let mut pair = [
                                boundaries[2 * axis].clone(),
                                boundaries[2 * axis + 1].clone(),
                            ];
                            if reverse {
                                pair.swap(0, 1);
                            }
                            let [start, end] = pair;
                            CurveParameterRange2::new_validated(start, end)
                        };
                        let first_range = range(0, reverse_first);
                        let second_range = range(1, reverse_second);
                        let domains = [
                            CurveParameterDomain2::new(&first_range, None),
                            CurveParameterDomain2::new(&second_range, None),
                        ];
                        let Classification::Decided(result) = parameter_domain_constraint(
                            support.clone(),
                            &constraint,
                            domains,
                            &policy,
                            config,
                        )
                        .unwrap() else {
                            panic!("finite residual projection must decide")
                        };
                        let component = result.component_support.unwrap();
                        let Classification::Decided(selection) =
                            select_parameter_component_in_domain(
                                &component,
                                &ParameterComponentSelector2::ParallelPair {
                                    normal_constraints: None,
                                    system: &system,
                                    parameter_filter: None,
                                },
                                domains,
                                ParameterComponentQuery2::FirstComponent(None),
                                &policy,
                                config,
                            )
                            .unwrap()
                        else {
                            panic!("finite component clipping must decide")
                        };
                        assert!(!selection.has_components());
                        assert!(selection.selected_pairs.is_empty());
                        let CurveIntersectionCandidates2::Candidates {
                            first_parameters: parallel_parameters,
                            second_parameters: other_parameters,
                        } = result.isolated_projection.unwrap().candidates
                        else {
                            panic!("the exact residual pair must survive saturation")
                        };
                        for (parameters, expected) in [
                            (parallel_parameters, &first_parameter),
                            (other_parameters, &second_parameter),
                        ] {
                            assert_eq!(parameters.len(), 1);
                            assert_eq!(
                                parameters[0]
                                    .cmp_by_refinement(
                                        &BezierParameter2::Exact(expected.clone()),
                                        &policy,
                                    )
                                    .unwrap(),
                                Classification::Decided(std::cmp::Ordering::Equal),
                            );
                        }
                        // Translating the same diagonal by half a unit
                        // gives a true overlap on these exact domains.
                        let overlapping = BivariatePolynomial::new(vec![
                            vec![ratio(1, 2), -&one],
                            vec![one.clone()],
                        ]);
                        let Classification::Decided(selection) =
                            select_parameter_component_in_domain(
                                &overlapping,
                                &ParameterComponentSelector2::ParallelPair {
                                    normal_constraints: None,
                                    system: &positive_component_selector_system(&overlapping),
                                    parameter_filter: None,
                                },
                                domains,
                                ParameterComponentQuery2::FirstComponent(None),
                                &policy,
                                config,
                            )
                            .unwrap()
                        else {
                            panic!("an owned finite overlap must remain representable")
                        };
                        assert!(selection.has_components());
                    }
                }
            }
        }
    }
}

#[test]
fn parameter_domains_retain_chart_events_and_closed_finite_boundaries() {
    let ratio = |n: i32, d: i32| (Real::from(n) / Real::from(d)).unwrap();
    let one = Real::one();
    let half = ratio(1, 2);
    let quarter = ratio(1, 4);
    let alpha = half.clone().sqrt().unwrap();
    let barrier = BezierParameter2::Exact(one.clone());
    let config = CurveIntersectionResultantConfig {
        min_precision: PARALLEL_INTERSECTION_RESULTANT_PRECISION,
        max_resultant_degree: MAX_PARALLEL_INTERSECTION_RESULTANT_DEGREE,
    };
    let support = BivariatePolynomial::new(vec![vec![Real::zero(), -&one], vec![one.clone()]]);
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        for shift in [-2_i32, 0, 2].map(Real::from) {
            // Select only (t-shift)^2=1/2 on the diagonal. Its positive
            // root survives chart transport; every open cell is excluded.
            let event = BivariatePolynomial::new(vec![
                vec![&shift * &shift - &half],
                vec![-(Real::from(2_i8) * &shift)],
                vec![one.clone()],
            ]);
            let opposite = bivariate_scale(event.clone(), &-&one);
            let system = BezierParallelPairEquationSystem2 {
                first_projection: opposite.clone(),
                second_projection: opposite,
                tangent_cross: event,
                norm_residual: BivariatePolynomial::new(vec![vec![-&one]]),
                ..positive_component_selector_system(&support)
            };
            let finite = CurveParameterRange2::new_validated(
                (&shift + ratio(5, 8)).into(),
                (&shift + ratio(7, 8)).into(),
            );
            let Classification::Decided(selection) = select_parameter_component_in_domain(
                &support,
                &ParameterComponentSelector2::ParallelPair {
                    normal_constraints: None,
                    system: &system,
                    parameter_filter: None,
                },
                [CurveParameterDomain2::new(&finite, None); 2],
                ParameterComponentQuery2::FirstComponent(None),
                &policy,
                config,
            )
            .unwrap() else {
                panic!("an isolated selected event must survive its finite chart")
            };
            assert!(!selection.has_components());
            assert_eq!(selection.selected_pairs.len(), 1);
            let pair = &selection.selected_pairs[0];
            for parameter in [&pair.parallel_parameter, &pair.other_parameter] {
                assert_eq!(
                    parameter
                        .cmp_by_refinement(&BezierParameter2::Exact(&shift + &alpha), &policy,)
                        .unwrap(),
                    Classification::Decided(std::cmp::Ordering::Equal),
                );
            }
            for boundary in [ratio(5, 8), ratio(7, 8)] {
                let axis =
                    BivariatePolynomial::new(vec![vec![-(&shift + boundary)], vec![one.clone()]]);
                let Classification::Decided(selection) = select_parameter_component_in_domain(
                    &axis,
                    &ParameterComponentSelector2::ParallelPair {
                        normal_constraints: None,
                        system: &positive_component_selector_system(&axis),
                        parameter_filter: None,
                    },
                    [CurveParameterDomain2::new(&finite, None); 2],
                    ParameterComponentQuery2::FirstComponent(None),
                    &policy,
                    config,
                )
                .unwrap() else {
                    panic!("finite component boundaries are closed")
                };
                assert!(selection.has_components());
            }
            if shift != Real::zero() {
                continue;
            }
            let short =
                CurveParameterRange2::new_validated(Real::zero().into(), quarter.clone().into());
            // The event is inside the original unit span but outside the
            // first finite span. Only its optional incident ray owns it.
            for extend in [false, true] {
                let Classification::Decided(selection) = select_parameter_component_in_domain(
                    &support,
                    &ParameterComponentSelector2::ParallelPair {
                        normal_constraints: None,
                        system: &system,
                        parameter_filter: None,
                    },
                    [
                        CurveParameterDomain2::new(
                            &short,
                            extend.then_some(BezierParameterRay2 {
                                anchor: &quarter,
                                direction: BezierParameterRayDirection2::Increasing,
                                barrier: Some(&barrier),
                            }),
                        ),
                        CurveParameterDomain2::new(&finite, None),
                    ],
                    ParameterComponentQuery2::FirstComponent(None),
                    &policy,
                    config,
                )
                .unwrap() else {
                    panic!("ray ownership must follow the actual finite range")
                };
                assert!(!selection.has_components());
                assert_eq!(selection.selected_pairs.len(), usize::from(extend));
            }
        }
    }
}

#[test]
fn finite_component_charts_accept_nonrational_exact_scalar_bounds() {
    let one = Real::one();
    let half = (&one / Real::from(2_i8)).unwrap();
    let lower = Real::from(2_i8).sqrt().unwrap();
    let upper = Real::from(3_i8).sqrt().unwrap();
    let root = (Real::from(2_i8) + &half).sqrt().unwrap();
    let support = BivariatePolynomial::new(vec![vec![Real::zero(), -&one], vec![one.clone()]]);
    let event = BivariatePolynomial::new(vec![
        vec![-(Real::from(2_i8) + &half)],
        vec![Real::zero()],
        vec![one.clone()],
    ]);
    let opposite = bivariate_scale(event.clone(), &-&one);
    let isolated = BezierParallelPairEquationSystem2 {
        first_projection: opposite.clone(),
        second_projection: opposite,
        tangent_cross: event,
        norm_residual: BivariatePolynomial::new(vec![vec![-&one]]),
        ..positive_component_selector_system(&support)
    };
    let config = CurveIntersectionResultantConfig {
        min_precision: PARALLEL_INTERSECTION_RESULTANT_PRECISION,
        max_resultant_degree: MAX_PARALLEL_INTERSECTION_RESULTANT_DEGREE,
    };
    // These endpoints make the finite chart's coefficients irrational.
    // A represented Real is not a rational-payload precondition for the
    // shared component or selected-event authority.
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        for [start, end] in [
            [lower.clone(), upper.clone()],
            [upper.clone(), lower.clone()],
        ] {
            let range = CurveParameterRange2::new_validated(start.into(), end.into());
            for (system, positive) in [
                (&positive_component_selector_system(&support), true),
                (&isolated, false),
            ] {
                let Classification::Decided(selection) = select_parameter_component_in_domain(
                    &support,
                    &ParameterComponentSelector2::ParallelPair {
                        normal_constraints: None,
                        system,
                        parameter_filter: None,
                    },
                    [CurveParameterDomain2::new(&range, None); 2],
                    ParameterComponentQuery2::FirstComponent(None),
                    &policy,
                    config,
                )
                .unwrap() else {
                    panic!("irrational finite bounds must preserve the exact component")
                };
                assert_eq!(selection.has_components(), positive);
                if !positive {
                    assert_eq!(selection.selected_pairs.len(), 1);
                    let pair = &selection.selected_pairs[0];
                    for parameter in [&pair.parallel_parameter, &pair.other_parameter] {
                        assert_eq!(
                            parameter
                                .cmp_by_refinement(&BezierParameter2::Exact(root.clone()), &policy,)
                                .unwrap(),
                            Classification::Decided(std::cmp::Ordering::Equal),
                        );
                    }
                }
            }
        }
    }
}

#[test]
fn incident_component_charts_clip_exact_regular_barriers() {
    let support_before_barriers = BivariatePolynomial::new(vec![
        vec![Real::one(), Real::one()],
        vec![Real::from(-1_i8)],
    ]);
    let support_beyond_barriers = BivariatePolynomial::new(vec![
        vec![Real::from(2_i8), Real::one()],
        vec![Real::from(-1_i8)],
    ]);
    let system = positive_component_selector_system(&support_before_barriers);
    let first_barrier = BezierParameter2::Exact((Real::from(3_i8) / Real::from(2_i8)).unwrap());
    let second_barrier = BezierParameter2::Exact((Real::from(-1_i8) / Real::from(2_i8)).unwrap());
    let config = CurveIntersectionResultantConfig {
        min_precision: PARALLEL_INTERSECTION_RESULTANT_PRECISION,
        max_resultant_degree: MAX_PARALLEL_INTERSECTION_RESULTANT_DEGREE,
    };

    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let selected = select_parameter_component_in_domain(
            &support_before_barriers,
            &ParameterComponentSelector2::ParallelPair {
                normal_constraints: None,
                system: &system,
                parameter_filter: None,
            },
            [
                CurveParameterDomain2::new(
                    &CurveParameterRange2::unit(),
                    Some(BezierParameterRay2 {
                        anchor: &Real::one(),
                        direction: BezierParameterRayDirection2::Increasing,
                        barrier: Some(&first_barrier),
                    }),
                ),
                CurveParameterDomain2::new(
                    &CurveParameterRange2::unit(),
                    Some(BezierParameterRay2 {
                        anchor: &Real::zero(),
                        direction: BezierParameterRayDirection2::Decreasing,
                        barrier: Some(&second_barrier),
                    }),
                ),
            ],
            ParameterComponentQuery2::FirstComponent(None),
            &policy,
            config,
        )
        .unwrap();
        let Classification::Decided(selected) = selected else {
            panic!("the pre-barrier component was uncertain")
        };
        assert!(selected.has_components());
        let excluded = select_parameter_component_in_domain(
            &support_beyond_barriers,
            &ParameterComponentSelector2::ParallelPair {
                normal_constraints: None,
                system: &system,
                parameter_filter: None,
            },
            [
                CurveParameterDomain2::new(
                    &CurveParameterRange2::unit(),
                    Some(BezierParameterRay2 {
                        anchor: &Real::one(),
                        direction: BezierParameterRayDirection2::Increasing,
                        barrier: Some(&first_barrier),
                    }),
                ),
                CurveParameterDomain2::new(
                    &CurveParameterRange2::unit(),
                    Some(BezierParameterRay2 {
                        anchor: &Real::zero(),
                        direction: BezierParameterRayDirection2::Decreasing,
                        barrier: Some(&second_barrier),
                    }),
                ),
            ],
            ParameterComponentQuery2::FirstComponent(None),
            &policy,
            config,
        )
        .unwrap();
        let Classification::Decided(excluded) = excluded else {
            panic!("the post-barrier component was uncertain")
        };
        assert!(!excluded.has_components());
        assert!(excluded.selected_pairs.is_empty());

        let half = (Real::one() / Real::from(2_i8)).unwrap();
        for axis_support in [
            BivariatePolynomial::new(vec![vec![-half.clone()], vec![Real::one()]]),
            BivariatePolynomial::new(vec![vec![-half, Real::one()]]),
        ] {
            let axis_system = BezierParallelPairEquationSystem2 {
                first_equation: axis_support.clone(),
                second_equation: axis_support.clone(),
                norm_equation: axis_support.clone(),
                ..system.clone()
            };
            let axis_selection = select_parameter_component_in_domain(
                &axis_support,
                &ParameterComponentSelector2::ParallelPair {
                    normal_constraints: None,
                    system: &axis_system,
                    parameter_filter: None,
                },
                [
                    CurveParameterDomain2::new(
                        &CurveParameterRange2::unit(),
                        Some(BezierParameterRay2 {
                            anchor: &Real::one(),
                            direction: BezierParameterRayDirection2::Increasing,
                            barrier: Some(&first_barrier),
                        }),
                    ),
                    CurveParameterDomain2::new(
                        &CurveParameterRange2::unit(),
                        Some(BezierParameterRay2 {
                            anchor: &Real::zero(),
                            direction: BezierParameterRayDirection2::Decreasing,
                            barrier: Some(&second_barrier),
                        }),
                    ),
                ],
                ParameterComponentQuery2::FirstComponent(None),
                &policy,
                config,
            )
            .unwrap();
            let Classification::Decided(axis_selection) = axis_selection else {
                panic!("the axis-wide component was uncertain")
            };
            assert!(axis_selection.has_components());

            let axis_constraint = parameter_domain_constraint(
                axis_support.clone(),
                &axis_support,
                [
                    CurveParameterDomain2::new(
                        &CurveParameterRange2::unit(),
                        Some(BezierParameterRay2 {
                            anchor: &Real::one(),
                            direction: BezierParameterRayDirection2::Increasing,
                            barrier: Some(&first_barrier),
                        }),
                    ),
                    CurveParameterDomain2::new(
                        &CurveParameterRange2::unit(),
                        Some(BezierParameterRay2 {
                            anchor: &Real::zero(),
                            direction: BezierParameterRayDirection2::Decreasing,
                            barrier: Some(&second_barrier),
                        }),
                    ),
                ],
                &policy,
                config,
            )
            .unwrap();
            let Classification::Decided(axis_constraint) = axis_constraint else {
                panic!("the axis-wide constraint was uncertain")
            };
            assert!(axis_constraint.component_support.is_some());
            assert!(axis_constraint.isolated_projection.is_none());
        }
    }
}

#[test]
fn parameter_component_domains_own_selected_events_once() {
    let one = Real::one();
    let half = (&one / Real::from(2_i8)).unwrap();
    let quarter = &half * &half;
    let fixed = &half + &quarter;
    let exterior = &one + &half;
    let alpha = half.clone().sqrt().unwrap();
    let barrier = BezierParameter2::Exact(alpha.clone());
    // Opposite tangent/projection signs exclude every open component
    // cell. Only the isolated zeros of (v^2-1/2)(v-3/2) are selected.
    let event_coefficients = vec![fixed.clone(), -&half, -&exterior, one.clone()];
    let event_on_first = BivariatePolynomial::new(
        event_coefficients
            .iter()
            .cloned()
            .map(|coefficient| vec![coefficient])
            .collect(),
    );
    let event_on_second = BivariatePolynomial::new(vec![event_coefficients]);
    let config = CurveIntersectionResultantConfig {
        min_precision: PARALLEL_INTERSECTION_RESULTANT_PRECISION,
        max_resultant_degree: MAX_PARALLEL_INTERSECTION_RESULTANT_DEGREE,
    };
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        for (case, support) in [
            BivariatePolynomial::new(vec![vec![Real::zero(), one.clone()], vec![-&one]]),
            BivariatePolynomial::new(vec![vec![-&fixed], vec![one.clone()]]),
            BivariatePolynomial::new(vec![vec![-&fixed, one.clone()]]),
        ]
        .into_iter()
        .enumerate()
        {
            let event = if case == 1 {
                &event_on_second
            } else {
                &event_on_first
            };
            let opposite = bivariate_scale(event.clone(), &-&one);
            let system = BezierParallelPairEquationSystem2 {
                first_projection: opposite.clone(),
                second_projection: opposite,
                tangent_cross: event.clone(),
                norm_residual: BivariatePolynomial::new(vec![vec![-&one]]),
                ..positive_component_selector_system(&support)
            };
            for clip in [false, true] {
                let ray = BezierParameterRay2 {
                    anchor: &half,
                    direction: BezierParameterRayDirection2::Increasing,
                    barrier: clip.then_some(&barrier),
                };
                for extend_first in [false, true] {
                    for extend_second in [false, true] {
                        let Classification::Decided(selection) =
                            select_parameter_component_in_domain(
                                &support,
                                &ParameterComponentSelector2::ParallelPair {
                                    normal_constraints: None,
                                    system: &system,
                                    parameter_filter: None,
                                },
                                [
                                    CurveParameterDomain2::new(
                                        &CurveParameterRange2::unit(),
                                        extend_first.then_some(ray),
                                    ),
                                    CurveParameterDomain2::new(
                                        &CurveParameterRange2::unit(),
                                        extend_second.then_some(ray),
                                    ),
                                ],
                                ParameterComponentQuery2::FirstComponent(None),
                                &policy,
                                config,
                            )
                            .unwrap()
                        else {
                            panic!("overlapping component charts must retain exact selected events")
                        };
                        assert!(!selection.has_components());
                        let has_exterior = !clip
                            && match case {
                                0 => extend_first && extend_second,
                                1 => extend_second,
                                2 => extend_first,
                                _ => unreachable!(),
                            };
                        assert_eq!(
                            selection.selected_pairs.len(),
                            1 + usize::from(has_exterior),
                            "case {case}, extensions {extend_first}, {extend_second}, clip {clip}"
                        );
                        for parameter in
                            std::iter::once(&alpha).chain(has_exterior.then_some(&exterior))
                        {
                            let expected = match case {
                                0 => [parameter, parameter],
                                1 => [&fixed, parameter],
                                2 => [parameter, &fixed],
                                _ => unreachable!(),
                            };
                            assert_eq!(
                                selection
                                    .selected_pairs
                                    .iter()
                                    .filter(|pair| {
                                        [&pair.parallel_parameter, &pair.other_parameter]
                                            .into_iter()
                                            .zip(expected)
                                            .all(|(actual, expected)| {
                                                actual
                                                    .cmp_by_refinement(
                                                        &BezierParameter2::Exact(expected.clone()),
                                                        &policy,
                                                    )
                                                    .unwrap()
                                                    == Classification::Decided(
                                                        std::cmp::Ordering::Equal,
                                                    )
                                            })
                                    })
                                    .count(),
                                1
                            );
                        }
                    }
                }
            }
        }
    }
}

#[test]
fn incident_component_charts_transport_an_isolated_selected_event() {
    let support = BivariatePolynomial::new(vec![
        vec![Real::one(), Real::one()],
        vec![Real::from(-1_i8)],
    ]);
    let tangent_cross = BivariatePolynomial::new(vec![
        vec![Real::from(-2_i8)],
        vec![Real::zero()],
        vec![Real::one()],
    ]);
    let opposite_projection = bivariate_scale(tangent_cross.clone(), &Real::from(-1_i8));
    let one = BivariatePolynomial::new(vec![vec![Real::one()]]);
    let system = BezierParallelPairEquationSystem2 {
        first_equation: support.clone(),
        second_equation: support.clone(),
        norm_equation: support.clone(),
        first_projection: opposite_projection.clone(),
        second_projection: opposite_projection,
        tangent_cross: tangent_cross.clone(),
        tangent_dot: one.clone(),
        norm_residual: BivariatePolynomial::new(vec![vec![Real::from(-1_i8)]]),
        first_normal_projection: one,
        first_distance: Real::one(),
        second_distance: Real::one(),
        first_distance_sign: RealSign::Positive,
        second_distance_sign: RealSign::Positive,
        weight_product: BivariatePolynomial::new(vec![vec![Real::one()]]),
    };
    let first_barrier = BezierParameter2::Exact((Real::from(3_i8) / Real::from(2_i8)).unwrap());
    let config = CurveIntersectionResultantConfig {
        min_precision: PARALLEL_INTERSECTION_RESULTANT_PRECISION,
        max_resultant_degree: MAX_PARALLEL_INTERSECTION_RESULTANT_DEGREE,
    };

    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let Classification::Decided(selection) = select_parameter_component_in_domain(
            &support,
            &ParameterComponentSelector2::ParallelPair {
                normal_constraints: None,
                system: &system,
                parameter_filter: None,
            },
            [
                CurveParameterDomain2::new(
                    &CurveParameterRange2::unit(),
                    Some(BezierParameterRay2 {
                        anchor: &Real::one(),
                        direction: BezierParameterRayDirection2::Increasing,
                        barrier: Some(&first_barrier),
                    }),
                ),
                CurveParameterDomain2::new(
                    &CurveParameterRange2::unit(),
                    Some(BezierParameterRay2 {
                        anchor: &Real::zero(),
                        direction: BezierParameterRayDirection2::Decreasing,
                        barrier: None,
                    }),
                ),
            ],
            ParameterComponentQuery2::FirstComponent(None),
            &policy,
            config,
        )
        .unwrap() else {
            panic!("the isolated exterior selector event was uncertain")
        };
        assert!(!selection.has_components());
        let [pair] = selection.selected_pairs.as_slice() else {
            panic!("the isolated exterior selector event was not retained once")
        };
        assert_eq!(
            signed_bivariate_at_parameter_pair(
                &support,
                &pair.parallel_parameter,
                &pair.other_parameter,
                &policy,
            )
            .unwrap(),
            Classification::Decided(RealSign::Zero),
        );
        assert_eq!(
            signed_bivariate_at_parameter_pair(
                &tangent_cross,
                &pair.parallel_parameter,
                &pair.other_parameter,
                &policy,
            )
            .unwrap(),
            Classification::Decided(RealSign::Zero),
        );
        assert_eq!(
            pair.parallel_parameter
                .cmp_by_refinement(&first_barrier, &policy)
                .unwrap(),
            Classification::Decided(std::cmp::Ordering::Less),
        );
    }
}

#[test]
fn complete_component_queries_keep_split_cells_and_residual_contacts() {
    let q = |n: i32, d: i32| (Real::from(n) / Real::from(d)).unwrap();
    let component =
        BivariatePolynomial::new(vec![vec![Real::zero(), -Real::one()], vec![Real::one()]]);
    let branch =
        BivariatePolynomial::new(vec![vec![q(1, 4)], vec![-Real::one()], vec![Real::one()]]);
    let config = CurveIntersectionResultantConfig {
        min_precision: PARALLEL_INTERSECTION_RESULTANT_PRECISION,
        max_resultant_degree: MAX_PARALLEL_INTERSECTION_RESULTANT_DEGREE,
    };
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let Classification::Decided(selection) = select_parameter_component_in_domain(
            &component,
            &ParameterComponentSelector2::Positive(&branch, None),
            [CurveParameterDomain2::new(&CurveParameterRange2::unit(), None); 2],
            ParameterComponentQuery2::AllComponents(None),
            &policy,
            config,
        )
        .unwrap() else {
            panic!("complete split component query was uncertain");
        };
        assert_eq!(selection.components.len(), 2);
        for (value, expected) in [(q(1, 4), true), (q(1, 2), false), (q(3, 4), true)] {
            let parameter = CurveParameter2::from(value);
            let count = selection
                .components
                .iter()
                .filter(|component| {
                    component
                        .contains_pair(&parameter, &parameter, &policy)
                        .unwrap()
                        == Classification::Decided(true)
                })
                .count();
            assert_eq!(count, usize::from(expected));
        }
        let source = QuadraticBezier2::from_line_segment(
            LineSeg2::try_new(
                Point2::new(Real::zero(), Real::zero()),
                Point2::new(Real::one(), Real::zero()),
            )
            .unwrap(),
        )
        .parallel_left(Real::one())
        .unwrap();
        // The domain kernel removes the known source diagonal before
        // residual projection, so use an independent component here.
        let component =
            BivariatePolynomial::new(vec![vec![-Real::one(), Real::one()], vec![Real::one()]]);
        let first_residual = BivariatePolynomial::new(vec![vec![-q(1, 4)], vec![Real::one()]]);
        let second_residual = BivariatePolynomial::new(vec![vec![-q(2, 3), Real::one()]]);
        let system = BezierParallelPairEquationSystem2 {
            first_equation: bivariate_multiply(&component, &first_residual),
            second_equation: bivariate_multiply(&component, &second_residual),
            norm_equation: BivariatePolynomial::new(vec![vec![Real::zero()]]),
            ..positive_component_selector_system(&component)
        };
        let excluded = Classification::Decided(CertifiedParallelSourceOverlap2::without_contacts(
            CertifiedParallelSourceOverlapKind2::Excluded,
        ));
        let Some(BezierParallelPairDomainProjection2::Enumerated {
            projection,
            components,
            ..
        }) = project_parallel_pair_without_components_in_domain(
            &system,
            &source,
            &source,
            &excluded,
            [CurveParameterDomain2::new(&CurveParameterRange2::unit(), None); 2],
            ParameterComponentQuery2::AllComponents(None),
            None,
            &policy,
        )
        .unwrap()
        else {
            panic!("complete query must keep the component and the isolated projection");
        };
        assert!(!components.is_empty());
        let CurveIntersectionCandidates2::Candidates {
            first_parameters,
            second_parameters,
        } = projection.candidates
        else {
            panic!("the residual candidate was discarded");
        };
        assert_eq!(first_parameters, vec![BezierParameter2::Exact(q(1, 4))]);
        assert_eq!(second_parameters, vec![BezierParameter2::Exact(q(2, 3))]);
    }
}

#[test]
fn axis_components_keep_exact_clipped_ends_and_open_selector_events() {
    let q = |n: i32, d: i32| (Real::from(n) / Real::from(d)).unwrap();
    let support = BivariatePolynomial::new(vec![vec![-q(1, 2)], vec![Real::one()]]);
    let branch = BivariatePolynomial::new(vec![vec![q(1, 4), -Real::one(), Real::one()]]);
    let alpha = q(1, 8).sqrt().unwrap();
    let range =
        CurveParameterRange2::new_validated(alpha.clone().into(), (Real::one() - &alpha).into());
    let config = CurveIntersectionResultantConfig {
        min_precision: PARALLEL_INTERSECTION_RESULTANT_PRECISION,
        max_resultant_degree: MAX_PARALLEL_INTERSECTION_RESULTANT_DEGREE,
    };
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let Classification::Decided(selection) = select_parameter_component_in_domain(
            &support,
            &ParameterComponentSelector2::Positive(&branch, None),
            [
                CurveParameterDomain2::new(&CurveParameterRange2::unit(), None),
                CurveParameterDomain2::new(&range, None),
            ],
            ParameterComponentQuery2::AllComponents(None),
            &policy,
            config,
        )
        .unwrap() else {
            panic!("exact axis-domain clipping was uncertain");
        };
        assert_eq!(selection.components.len(), 2);
        for (value, expected) in [
            (alpha.clone(), true),
            (q(1, 2), false),
            (Real::one() - &alpha, true),
            (q(1, 4), false),
            (q(3, 4), false),
        ] {
            let first = CurveParameter2::from(q(1, 2));
            let second = CurveParameter2::from(value);
            let count = selection
                .components
                .iter()
                .filter(|component| {
                    component.contains_pair(&first, &second, &policy).unwrap()
                        == Classification::Decided(true)
                })
                .count();
            assert_eq!(count, usize::from(expected));
        }
    }
}

#[test]
fn incident_constraint_retains_isolated_roots_after_component_analysis() {
    let support = BivariatePolynomial::new(vec![
        vec![Real::one(), Real::one()],
        vec![Real::from(-1_i8)],
    ]);
    let five_quarters = (Real::from(5_i8) / Real::from(4_i8)).unwrap();
    let constraint =
        BivariatePolynomial::new(vec![vec![-five_quarters.clone()], vec![Real::one()]]);
    let first_barrier = BezierParameter2::Exact((Real::from(3_i8) / Real::from(2_i8)).unwrap());
    let config = CurveIntersectionResultantConfig {
        min_precision: PARALLEL_INTERSECTION_RESULTANT_PRECISION,
        max_resultant_degree: MAX_PARALLEL_INTERSECTION_RESULTANT_DEGREE,
    };

    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let Classification::Decided(constraint) = parameter_domain_constraint(
            support.clone(),
            &constraint,
            [
                CurveParameterDomain2::new(
                    &CurveParameterRange2::unit(),
                    Some(BezierParameterRay2 {
                        anchor: &Real::one(),
                        direction: BezierParameterRayDirection2::Increasing,
                        barrier: Some(&first_barrier),
                    }),
                ),
                CurveParameterDomain2::new(
                    &CurveParameterRange2::unit(),
                    Some(BezierParameterRay2 {
                        anchor: &Real::zero(),
                        direction: BezierParameterRayDirection2::Decreasing,
                        barrier: None,
                    }),
                ),
            ],
            &policy,
            config,
        )
        .unwrap() else {
            panic!("the isolated incident constraint was uncertain");
        };
        assert!(constraint.component_support.is_none());
        let Some(projection) = constraint.isolated_projection else {
            panic!("the isolated source/component constraint was discarded");
        };
        let CurveIntersectionCandidates2::Candidates {
            first_parameters: parallel_parameters,
            second_parameters: other_parameters,
        } = projection.candidates
        else {
            panic!("the isolated incident constraint was not projected");
        };
        assert_eq!(
            parallel_parameters,
            vec![BezierParameter2::Exact(five_quarters.clone())],
        );
        assert_eq!(
            other_parameters,
            vec![BezierParameter2::Exact(
                (Real::one() / Real::from(4_i8)).unwrap(),
            )],
        );
    }
}

#[test]
fn incident_pair_projection_accepts_a_non_source_radical_component() {
    let source = |height| {
        QuadraticBezier2::from_line_segment(
            LineSeg2::try_new(
                Point2::new(Real::zero(), Real::from(height)),
                Point2::new(Real::one(), Real::from(height)),
            )
            .unwrap(),
        )
        .parallel_left(Real::one())
        .unwrap()
    };
    let first = source(0);
    let second = source(4);
    let support = BivariatePolynomial::new(vec![
        vec![Real::one(), Real::one()],
        vec![Real::from(-1_i8)],
    ]);
    let one = BivariatePolynomial::new(vec![vec![Real::one()]]);
    let system = BezierParallelPairEquationSystem2 {
        first_equation: support.clone(),
        second_equation: support.clone(),
        norm_equation: support,
        first_projection: one.clone(),
        second_projection: one.clone(),
        tangent_cross: one.clone(),
        tangent_dot: one.clone(),
        norm_residual: one.clone(),
        first_normal_projection: one,
        first_distance: Real::one(),
        second_distance: Real::one(),
        first_distance_sign: RealSign::Positive,
        second_distance_sign: RealSign::Positive,
        weight_product: BivariatePolynomial::new(vec![vec![Real::one()]]),
    };
    let excluded = Classification::Decided(CertifiedParallelSourceOverlap2::without_contacts(
        CertifiedParallelSourceOverlapKind2::Excluded,
    ));

    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let projection = project_parallel_pair_without_components_in_domain(
            &system,
            &first,
            &second,
            &excluded,
            [
                CurveParameterDomain2::new(
                    &CurveParameterRange2::unit(),
                    Some(BezierParameterRay2 {
                        anchor: &Real::one(),
                        direction: BezierParameterRayDirection2::Increasing,
                        barrier: None,
                    }),
                ),
                CurveParameterDomain2::new(
                    &CurveParameterRange2::unit(),
                    Some(BezierParameterRay2 {
                        anchor: &Real::zero(),
                        direction: BezierParameterRayDirection2::Decreasing,
                        barrier: None,
                    }),
                ),
            ],
            ParameterComponentQuery2::FirstComponent(None),
            None,
            &policy,
        )
        .unwrap();
        assert!(matches!(
            projection,
            Some(BezierParallelPairDomainProjection2::Components(components)) if !components.is_empty(),
        ));

        let fixed_first = BivariatePolynomial::new(vec![
            vec![-(Real::one() / Real::from(2_i8)).unwrap()],
            vec![Real::one()],
        ]);
        let axis_system = BezierParallelPairEquationSystem2 {
            first_equation: fixed_first.clone(),
            second_equation: fixed_first.clone(),
            norm_equation: fixed_first,
            ..system.clone()
        };
        let axis_projection = project_parallel_pair_without_components_in_domain(
            &axis_system,
            &first,
            &second,
            &excluded,
            [
                CurveParameterDomain2::new(
                    &CurveParameterRange2::unit(),
                    Some(BezierParameterRay2 {
                        anchor: &Real::one(),
                        direction: BezierParameterRayDirection2::Increasing,
                        barrier: None,
                    }),
                ),
                CurveParameterDomain2::new(
                    &CurveParameterRange2::unit(),
                    Some(BezierParameterRay2 {
                        anchor: &Real::zero(),
                        direction: BezierParameterRayDirection2::Decreasing,
                        barrier: None,
                    }),
                ),
            ],
            ParameterComponentQuery2::FirstComponent(None),
            None,
            &policy,
        )
        .unwrap();
        assert!(matches!(
            axis_projection,
            Some(BezierParallelPairDomainProjection2::Components(components)) if !components.is_empty(),
        ));

        let tangent_cross = BivariatePolynomial::new(vec![
            vec![Real::from(-2_i8)],
            vec![Real::zero()],
            vec![Real::one()],
        ]);
        let opposite_projection = bivariate_scale(tangent_cross.clone(), &Real::from(-1_i8));
        let isolated_system = BezierParallelPairEquationSystem2 {
            first_projection: opposite_projection.clone(),
            second_projection: opposite_projection,
            tangent_cross,
            norm_residual: BivariatePolynomial::new(vec![vec![Real::from(-1_i8)]]),
            ..system.clone()
        };
        let first_barrier = BezierParameter2::Exact((Real::from(3_i8) / Real::from(2_i8)).unwrap());
        let Some(BezierParallelPairDomainProjection2::Enumerated { projection, .. }) =
            project_parallel_pair_without_components_in_domain(
                &isolated_system,
                &first,
                &second,
                &excluded,
                [
                    CurveParameterDomain2::new(
                        &CurveParameterRange2::unit(),
                        Some(BezierParameterRay2 {
                            anchor: &Real::one(),
                            direction: BezierParameterRayDirection2::Increasing,
                            barrier: Some(&first_barrier),
                        }),
                    ),
                    CurveParameterDomain2::new(
                        &CurveParameterRange2::unit(),
                        Some(BezierParameterRay2 {
                            anchor: &Real::zero(),
                            direction: BezierParameterRayDirection2::Decreasing,
                            barrier: None,
                        }),
                    ),
                ],
                ParameterComponentQuery2::FirstComponent(None),
                None,
                &policy,
            )
            .unwrap()
        else {
            panic!("the isolated selected component event was not projected")
        };
        let Some(component_projection) = projection.radical_component_projection else {
            panic!("the isolated component event lost its projection")
        };
        let [pair] = component_projection.component_pairs.as_ref() else {
            panic!("the isolated component event was not retained once")
        };
        assert_eq!(
            signed_bivariate_at_parameter_pair(
                &isolated_system.tangent_cross,
                &pair.parallel_parameter,
                &pair.other_parameter,
                &policy,
            )
            .unwrap(),
            Classification::Decided(RealSign::Zero),
        );
    }
}

#[test]
fn incident_non_source_parallel_overlap_reaches_the_common_projection() {
    let line = |start_x: i8, height: i8, distance: i8| {
        QuadraticBezier2::from_line_segment(
            LineSeg2::try_new(
                Point2::new(Real::from(start_x), Real::from(height)),
                Point2::new(Real::from(start_x + 1), Real::from(height)),
            )
            .unwrap(),
        )
        .parallel_left(Real::from(distance))
        .unwrap()
    };
    // The sources are disjoint parallel lines, but their selected
    // parallels are the same line with exterior correspondence u=t-1.
    // This is a radical component, not a source-coordinate component.
    let first = line(0, 0, 1);
    let second = line(1, 2, -1);
    let excluded = Classification::Decided(CertifiedParallelSourceOverlap2::without_contacts(
        CertifiedParallelSourceOverlapKind2::Excluded,
    ));
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let Classification::Decided(Some(system)) =
            parallel_pair_equation_system(&first, &second, false, &policy).unwrap()
        else {
            panic!("the incident non-source overlap lacked a pair system")
        };
        let projection = project_parallel_pair_without_components_in_domain(
            &system,
            &first,
            &second,
            &excluded,
            [
                CurveParameterDomain2::new(
                    &CurveParameterRange2::unit(),
                    Some(BezierParameterRay2 {
                        anchor: &Real::one(),
                        direction: BezierParameterRayDirection2::Increasing,
                        barrier: None,
                    }),
                ),
                CurveParameterDomain2::new(
                    &CurveParameterRange2::unit(),
                    Some(BezierParameterRay2 {
                        anchor: &Real::zero(),
                        direction: BezierParameterRayDirection2::Decreasing,
                        barrier: None,
                    }),
                ),
            ],
            ParameterComponentQuery2::FirstComponent(None),
            None,
            &policy,
        )
        .unwrap();
        assert!(matches!(
            projection,
            Some(BezierParallelPairDomainProjection2::Components(components)) if !components.is_empty(),
        ));
        let Classification::Decided(incident) = first
            .parallel_intersections_in_domain(
                &second,
                [
                    CurveParameterDomain2::new(
                        &CurveParameterRange2::unit(),
                        Some(
                            incident_domain(
                                &first,
                                Real::one(),
                                BezierParameterRayDirection2::Increasing,
                                &policy,
                            )
                            .parameter_ray(),
                        ),
                    ),
                    CurveParameterDomain2::new(
                        &CurveParameterRange2::unit(),
                        Some(
                            incident_domain(
                                &second,
                                Real::zero(),
                                BezierParameterRayDirection2::Decreasing,
                                &policy,
                            )
                            .parameter_ray(),
                        ),
                    ),
                ],
                ParameterComponentQuery2::FirstComponent(None),
                &policy,
            )
            .unwrap()
        else {
            panic!("the complete incident pair result was uncertain")
        };
        let (intersections, retained_components) = incident.into_parts();
        let positive_dimensional = !retained_components.is_empty();
        assert!(intersections.is_complete());
        assert!(positive_dimensional);
    }
}

#[test]
fn algebraic_incident_barrier_retains_its_exact_compact_root() {
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let irrational = (Real::from(2_i8)).sqrt().unwrap();
        for (case_index, (constant, compact_polynomial)) in [
            (
                Real::from(2_i8),
                vec![Real::one(), Real::from(-4_i8), Real::from(2_i8)],
            ),
            (
                irrational.clone(),
                vec![
                    Real::one() - &irrational,
                    Real::from(2_i8) * &irrational,
                    -irrational.clone(),
                ],
            ),
        ]
        .into_iter()
        .enumerate()
        {
            let polynomial = match BezierParameterPolynomial::try_new_power_basis(
                vec![-constant, Real::zero(), Real::one()],
                &policy,
            )
            .unwrap()
            {
                Classification::Decided(polynomial) => polynomial,
                Classification::Uncertain(reason) => {
                    panic!("the barrier polynomial was uncertain: {reason:?}")
                }
            };
            let barriers = match polynomial
                .isolate_incident_ray_roots(
                    &Real::one(),
                    BezierParameterRayDirection2::Increasing,
                    &policy,
                )
                .unwrap()
            {
                Classification::Decided(barriers) => barriers,
                Classification::Uncertain(reason) => {
                    panic!("incident barrier isolation was uncertain: {reason:?}")
                }
            };
            let [barrier] = barriers.as_slice() else {
                panic!("the positive square root has one increasing incident root")
            };
            let compact = match barrier
                .incident_ray_compact_parameter(
                    &Real::one(),
                    BezierParameterRayDirection2::Increasing,
                    &policy,
                )
                .unwrap()
            {
                Classification::Decided(compact) => compact,
                Classification::Uncertain(reason) => {
                    panic!("the compact barrier was uncertain: {reason:?}")
                }
            };
            assert_eq!(
                signed_coefficients_at_parameter(&compact_polynomial, &compact, &policy).unwrap(),
                Classification::Decided(RealSign::Zero),
                "incident compact case {case_index} under {policy:?}",
            );
            let restored = match compact
                .incident_ray_parameter(
                    &Real::one(),
                    BezierParameterRayDirection2::Increasing,
                    &policy,
                )
                .unwrap()
            {
                Classification::Decided(restored) => restored,
                Classification::Uncertain(reason) => {
                    panic!("the restored incident barrier was uncertain: {reason:?}")
                }
            };
            assert_eq!(
                restored.same_value(barrier, &policy).unwrap(),
                Classification::Decided(true),
            );
        }
    }
}

#[test]
fn nonlinear_parameter_component_maps_and_clips_its_exact_branch() {
    // u=t^2 is monotone on the authored square but is not an affine or
    // projective parameter correspondence.  Independent axis clipping
    // would therefore retain false overlaps.
    let fraction =
        |numerator: i8, denominator: i8| (Real::from(numerator) / Real::from(denominator)).unwrap();
    let mut square_root_parameters =
        algebraic_parameters(vec![-fraction(1, 2), Real::zero(), Real::one()]);
    let square_root_half = square_root_parameters
        .pop()
        .expect("sqrt(1/2) has one authored-domain root");
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let overlap = nonlinear_parameter_component_overlap_for_test(&policy);
        let Classification::Decided(Some(mapped)) = overlap
            .map_parameter(
                CurveResultantParameter::First,
                &BezierParameter2::Exact(fraction(1, 2)),
                &policy,
            )
            .unwrap()
        else {
            panic!("the exact nonlinear forward map was not decided");
        };
        assert_eq!(mapped.scalar(), Some(&fraction(1, 4)));
        let Classification::Decided(Some(mapped)) = overlap
            .map_parameter(
                CurveResultantParameter::Second,
                &BezierParameter2::Exact(fraction(1, 4)),
                &policy,
            )
            .unwrap()
        else {
            panic!("the exact nonlinear inverse map was not decided");
        };
        assert_eq!(mapped.scalar(), Some(&fraction(1, 2)));
        let Classification::Decided(Some(mapped)) = overlap
            .map_parameter(CurveResultantParameter::First, &square_root_half, &policy)
            .unwrap()
        else {
            panic!("the algebraic nonlinear forward map was not decided");
        };
        assert_eq!(mapped.scalar(), Some(&fraction(1, 2)));

        let first = CurveParameterRange2::from_bezier_range(BezierParameterRange2::from_exact(
            fraction(1, 5),
            fraction(2, 5),
        ));
        let disjoint_second = CurveParameterRange2::from_bezier_range(
            BezierParameterRange2::from_exact(fraction(1, 2), fraction(7, 10)),
        );
        assert_eq!(
            overlap
                .has_positive_overlap(&first, &disjoint_second, &policy)
                .unwrap(),
            Classification::Decided(false),
        );
        assert_eq!(
            overlap
                .clipped_ranges(&first, &disjoint_second, &policy)
                .unwrap(),
            Classification::Decided(None),
        );

        let first = CurveParameterRange2::from_bezier_range(BezierParameterRange2::from_exact(
            fraction(1, 4),
            fraction(3, 4),
        ));
        let second = CurveParameterRange2::from_bezier_range(BezierParameterRange2::from_exact(
            fraction(1, 16),
            fraction(1, 4),
        ));
        assert_eq!(
            overlap
                .has_positive_overlap(&first, &second, &policy)
                .unwrap(),
            Classification::Decided(true),
        );
        let Classification::Decided(Some((first, second))) =
            overlap.clipped_ranges(&first, &second, &policy).unwrap()
        else {
            panic!("the paired nonlinear subrange was not retained");
        };
        assert_eq!(
            first.scalar_endpoints(),
            Some((&fraction(1, 4), &fraction(1, 2))),
        );
        assert_eq!(
            second.scalar_endpoints(),
            Some((&fraction(1, 16), &fraction(1, 4))),
        );

        let BezierParameter2::Algebraic(retained_parameter) = square_root_half.clone() else {
            panic!("sqrt(1/2) was not retained algebraically")
        };
        let selected_parameter = |value: Real| {
            CurveParameter2::from_selected_fiber(
                BezierAlgebraicSelectedFiberAuthority2::exact_parameter(
                    retained_parameter.clone(),
                    value,
                    &policy,
                ),
            )
        };
        let first = CurveParameterRange2::new_validated(
            selected_parameter(fraction(1, 4)),
            selected_parameter(fraction(3, 4)),
        );
        let second = CurveParameterRange2::from_bezier_range(BezierParameterRange2::from_exact(
            fraction(1, 16),
            fraction(1, 4),
        ));
        assert_eq!(
            overlap
                .has_positive_overlap(&first, &second, &policy)
                .unwrap(),
            Classification::Decided(true),
        );
        let Classification::Decided(Some((first, second))) =
            overlap.clipped_ranges(&first, &second, &policy).unwrap()
        else {
            panic!("the selected first-axis nonlinear subrange was not retained");
        };
        let first_start = first
            .start()
            .as_selected_fiber()
            .expect("an unchanged selected first bound must remain local");
        assert_eq!(
            first_start.order_to_real(&fraction(1, 4), &policy).unwrap(),
            Classification::Decided(std::cmp::Ordering::Equal),
        );
        assert_eq!(first.end().scalar(), Some(&fraction(1, 2)));
        assert_eq!(
            second.scalar_endpoints(),
            Some((&fraction(1, 16), &fraction(1, 4))),
        );

        let first = CurveParameterRange2::from_bezier_range(BezierParameterRange2::from_exact(
            fraction(1, 4),
            fraction(3, 4),
        ));
        let second = CurveParameterRange2::new_validated(
            selected_parameter(fraction(1, 16)),
            selected_parameter(fraction(1, 4)),
        );
        assert_eq!(
            overlap
                .has_positive_overlap(&first, &second, &policy)
                .unwrap(),
            Classification::Decided(true),
        );
        let Classification::Decided(Some((first, second))) =
            overlap.clipped_ranges(&first, &second, &policy).unwrap()
        else {
            panic!("the selected second-axis nonlinear subrange was not retained");
        };
        assert_eq!(first.start().scalar(), Some(&fraction(1, 4)));
        assert_eq!(first.end().scalar(), Some(&fraction(1, 2)));
        for (parameter, expected) in [
            (second.start(), fraction(1, 16)),
            (second.end(), fraction(1, 4)),
        ] {
            let selected = parameter
                .as_selected_fiber()
                .expect("an unchanged selected second bound must remain local");
            assert_eq!(
                selected.order_to_real(&expected, &policy).unwrap(),
                Classification::Decided(std::cmp::Ordering::Equal),
            );
        }
    }
}

#[test]
fn nonlinear_parameter_component_maps_a_degree_135_selected_scalar_locally() {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        // alpha^9 = 1/2 and u^15 = alpha make the ordinary projection of
        // u degree 135.  The component v=u^2 must keep both scalars over
        // the selected alpha root instead of constructing that norm.
        let source = degree_nine_selected_fiber_parameter_for_test(half.clone(), 1, &policy);
        let overlap = nonlinear_parameter_component_overlap_for_test(&policy);
        let mapped = match overlap
            .map_curve_parameter(
                CurveResultantParameter::First,
                &CurveParameter2::from_selected_fiber(source.clone()),
                &policy,
            )
            .unwrap()
        {
            Classification::Decided(Some(parameter)) => parameter,
            outcome => panic!("the selected nonlinear component map failed: {outcome:?}"),
        };
        let mapped = mapped
            .as_selected_fiber()
            .expect("a nonrepresented component image must remain in the selected fiber");
        assert_eq!(
            mapped.data.authority.data.retained_parameter,
            source.data.authority.data.retained_parameter,
        );
        assert_eq!(
            mapped.data.authority.data.policy,
            CurveContext::STRICT,
            "component construction must not consume APPROXIMATE_512",
        );
        assert_eq!(
            algebraic_selected_fiber_pair_predicate_sign(
                &source,
                mapped,
                &overlap.support,
                &policy,
            )
            .unwrap(),
            Classification::Decided(RealSign::Zero),
        );
        let round_trip = match overlap
            .map_curve_parameter(
                CurveResultantParameter::Second,
                &CurveParameter2::from_selected_fiber(mapped.clone()),
                &policy,
            )
            .unwrap()
        {
            Classification::Decided(Some(parameter)) => parameter,
            outcome => panic!("the reverse selected component map failed: {outcome:?}"),
        };
        let round_trip = round_trip
            .as_selected_fiber()
            .expect("the reverse nonrepresented image must remain in the selected fiber");
        assert_eq!(
            round_trip.cmp_by_refinement(&source, &policy).unwrap(),
            Classification::Decided(std::cmp::Ordering::Equal),
        );
    }
}

#[test]
fn finite_component_transport_composes_maps_without_rebasing_its_proof() {
    let policy = CurveContext::STRICT;
    let half = (Real::one() / Real::from(2)).unwrap();
    let parameter = |value: Real| BezierParameter2::Exact(value);
    // Both v=u and v=1-u lie in the unit square. The upper branch is
    // rank one: clipping its bounds alone does not carry that identity.
    let original = BezierParameterComponentOverlap2 {
        parameter_charts: None,
        overlap: RationalBezierIntersectionOverlap2::from_certified_parameters(
            parameter(half.clone()),
            parameter(Real::one()),
            parameter(half.clone()),
            parameter(Real::one()),
            CurveOverlapOrientation2::Same,
            [true, true],
        ),
        support: Arc::new(BivariatePolynomial::new(vec![
            vec![Real::zero(), -Real::one(), Real::one()],
            vec![Real::one()],
            vec![-Real::one()],
        ])),
        fiber_root_ranks: [1, 1],
        witness: BezierParallelIntersectionParameterPair2 {
            parallel_parameter: parameter((Real::from(3) / Real::from(4)).unwrap()),
            other_parameter: parameter((Real::from(3) / Real::from(4)).unwrap()),
        },
    };
    let Classification::Decided(mut transported) = original
        .clone()
        .in_parameter_charts(
            [
                ParameterComponentAffineMap2 {
                    scale: 3.into(),
                    offset: 2.into(),
                },
                ParameterComponentAffineMap2 {
                    scale: 5.into(),
                    offset: (-4).into(),
                },
            ],
            &policy,
        )
        .unwrap()
    else {
        panic!("finite affine maps must retain the branch")
    };
    for _ in 0..16 {
        let Classification::Decided(next) = transported
            .in_parameter_charts(
                std::array::from_fn(|_| ParameterComponentAffineMap2 {
                    scale: Real::one(),
                    offset: Real::one(),
                }),
                &policy,
            )
            .unwrap()
        else {
            panic!("translations must compose")
        };
        transported = next;
        assert!(Arc::ptr_eq(&original.support, &transported.support));
        assert_eq!(original.fiber_root_ranks, transported.fiber_root_ranks);
        assert_eq!(original.witness, transported.witness);
        assert_eq!(original.overlap, transported.overlap);
    }
    let alpha = algebraic_parameter(vec![-half, Real::zero(), Real::one()]);
    let Classification::Decided(source) = alpha
        .affine_image_unbounded(&3.into(), &18.into(), &policy)
        .unwrap()
    else {
        panic!("the source parameter transports")
    };
    let Classification::Decided(expected) = alpha
        .affine_image_unbounded(&5.into(), &12.into(), &policy)
        .unwrap()
    else {
        panic!("the target parameter transports")
    };
    let Classification::Decided(Some(mapped)) = transported
        .map_curve_parameter(
            CurveResultantParameter::First,
            &source.clone().into(),
            &policy,
        )
        .unwrap()
    else {
        panic!("the rank-one branch maps")
    };
    assert_eq!(
        mapped.same_value(&expected.into(), &policy).unwrap(),
        Classification::Decided(true)
    );
    let Classification::Decided(Some(restored)) = transported
        .map_curve_parameter(CurveResultantParameter::Second, &mapped, &policy)
        .unwrap()
    else {
        panic!("the branch maps back")
    };
    assert_eq!(
        restored.same_value(&source.into(), &policy).unwrap(),
        Classification::Decided(true)
    );
    let swapped = swapped_parameter_component_overlap(&transported);
    assert_eq!(
        swapped
            .map_curve_parameter(CurveResultantParameter::First, &mapped, &policy)
            .unwrap(),
        Classification::Decided(Some(restored))
    );
}

#[test]
fn nonlinear_parameter_component_maps_recursive_projective_scalars_locally() {
    let fraction =
        |numerator: i8, denominator: i8| (Real::from(numerator) / Real::from(denominator)).unwrap();
    let half = fraction(1, 2);
    let eighth = fraction(1, 8);
    let source_parameter = algebraic_parameter(vec![-half.clone(), Real::zero(), Real::one()]);
    let source_representation = bezier_parameter_root_representation(&source_parameter);
    let one = DenseTensorPolynomial::from_axis_polynomial(1, 0, &[Real::one()])
        .expect("the recursive component base must retain its unit");
    let coordinate =
        DenseTensorPolynomial::from_axis_polynomial(1, 0, &[Real::zero(), Real::one()])
            .expect("the recursive component base must retain its coordinate");
    let parameter = |value: Real| BezierParameter2::Exact(value);
    let witness = BezierParallelIntersectionParameterPair2 {
        parallel_parameter: parameter(Real::zero()),
        other_parameter: parameter(Real::zero()),
    };
    let affine = BezierParameterComponentOverlap2 {
        parameter_charts: None,
        overlap: RationalBezierIntersectionOverlap2::from_certified_parameters(
            parameter(Real::zero()),
            parameter(Real::one()),
            parameter(Real::zero()),
            parameter(half.clone()),
            CurveOverlapOrientation2::Same,
            [true, true],
        ),
        // 2v-u=0 maps alpha to alpha/2 without leaving its recursive
        // coefficient tower.
        support: Arc::new(BivariatePolynomial::new(vec![
            vec![Real::zero(), Real::from(2_i8)],
            vec![Real::from(-1_i8)],
        ])),
        fiber_root_ranks: [0, 0],
        witness: witness.clone(),
    };
    let cubic = BezierParameterComponentOverlap2 {
        parameter_charts: None,
        overlap: RationalBezierIntersectionOverlap2::from_certified_parameters(
            parameter(Real::zero()),
            parameter(Real::one()),
            parameter(Real::zero()),
            parameter(Real::one()),
            CurveOverlapOrientation2::Same,
            [true, true],
        ),
        // v-u^3=0 forces the reverse map through the complete projected
        // enumerator while authored-sheet replay selects u=alpha from
        // v=alpha/2=alpha^3.
        support: Arc::new(BivariatePolynomial::new(vec![
            vec![Real::zero(), Real::one()],
            vec![Real::zero()],
            vec![Real::zero()],
            vec![Real::from(-1_i8)],
        ])),
        fiber_root_ranks: [0, 0],
        witness: witness.clone(),
    };
    let upper_quadratic_branch = BezierParameterComponentOverlap2 {
        parameter_charts: None,
        overlap: RationalBezierIntersectionOverlap2::from_certified_parameters(
            parameter(half.clone()),
            parameter(Real::one()),
            parameter(half.clone()),
            parameter(Real::one()),
            CurveOverlapOrientation2::Same,
            [true, true],
        ),
        // (v-u)(v-(1-u))=0 has two ordered unit roots. The authored
        // upper branch is rank one in both directions on [1/2,1].
        support: Arc::new(BivariatePolynomial::new(vec![
            vec![Real::zero(), Real::from(-1_i8), Real::one()],
            vec![Real::one()],
            vec![Real::from(-1_i8)],
        ])),
        fiber_root_ranks: [1, 1],
        witness: witness.clone(),
    };
    let degree_drop = BezierParameterComponentOverlap2 {
        parameter_charts: None,
        overlap: RationalBezierIntersectionOverlap2::from_certified_parameters(
            parameter(Real::zero()),
            parameter(Real::one()),
            parameter(Real::zero()),
            parameter(Real::one()),
            CurveOverlapOrientation2::Same,
            [true, true],
        ),
        // v-u+(u^2-1/2)v^3=0 specializes to v=u at the selected
        // alpha^2=1/2 source. The global cubic leading coefficient drops
        // only on the authored retained tuple.
        support: Arc::new(BivariatePolynomial::new(vec![
            vec![Real::zero(), Real::one(), Real::zero(), -half.clone()],
            vec![Real::from(-1_i8)],
            vec![Real::zero(), Real::zero(), Real::zero(), Real::one()],
        ])),
        fiber_root_ranks: [0, 0],
        witness,
    };

    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let field = BezierRecursiveQuadraticField2::base(
            vec![source_representation.clone()],
            one.clone(),
            one.clone(),
        )
        .expect("the recursive component field must construct");
        let BezierRecursiveQuadraticField2::Base(base) = &field else {
            unreachable!("the recursive component field begins at its base")
        };
        let scalar = BezierRecursiveQuadraticProjectiveScalar2 {
            numerator: recursive_quadratic_rational_value(base, coordinate.clone())
                .expect("the selected source coordinate must embed"),
            denominator: field
                .constant(Real::one())
                .expect("the selected source coordinate must retain its denominator"),
        };
        let Classification::Decided(source) =
            BezierRecursiveProjectiveParameter2::new(scalar, &policy).unwrap()
        else {
            panic!("the recursive component source must construct");
        };
        let source = CurveParameter2::from_recursive_projective(source);

        let direct = crate::policy::resolve_certified_operation(&policy, |attempt| {
            affine.map_curve_parameter(CurveResultantParameter::First, &source, attempt)
        })
        .unwrap();
        assert_eq!(direct.certainty, CurveCertainty::Certified);
        let Classification::Decided(Some(direct)) = direct.value else {
            panic!("the affine recursive component image must decide");
        };
        let direct_parameter = direct
            .as_recursive_projective()
            .expect("a nonrepresented affine image must remain recursive");
        assert_eq!(direct_parameter.data.policy, CurveContext::STRICT);
        assert_eq!(
            direct_parameter
                .polynomial_sign(&[-eighth.clone(), Real::zero(), Real::one()], &policy)
                .unwrap(),
            Classification::Decided(RealSign::Zero),
        );

        let ranked = crate::policy::resolve_certified_operation(&policy, |attempt| {
            upper_quadratic_branch.map_curve_parameter(
                CurveResultantParameter::First,
                &source,
                attempt,
            )
        })
        .unwrap();
        assert_eq!(ranked.certainty, CurveCertainty::Certified);
        let Classification::Decided(Some(ranked)) = ranked.value else {
            panic!("the rank-one recursive component image must decide");
        };
        let ranked = ranked
            .as_recursive_projective()
            .expect("a quadratic recursive image must remain in its extended tower");
        assert_eq!(
            ranked.order_to_real(&half, &policy).unwrap(),
            Classification::Decided(std::cmp::Ordering::Greater),
        );
        assert_eq!(
            ranked
                .polynomial_sign(&[-half.clone(), Real::zero(), Real::one()], &policy)
                .unwrap(),
            Classification::Decided(RealSign::Zero),
        );

        let dropped = crate::policy::resolve_certified_operation(&policy, |attempt| {
            degree_drop.map_curve_parameter(CurveResultantParameter::First, &source, attempt)
        })
        .unwrap();
        assert_eq!(dropped.certainty, CurveCertainty::Certified);
        let Classification::Decided(Some(dropped)) = dropped.value else {
            panic!("the recursive component degree drop must decide");
        };
        let dropped = dropped
            .as_recursive_projective()
            .expect("an exact selected degree drop must stay in the recursive tower");
        assert_eq!(
            dropped
                .polynomial_sign(&[-half.clone(), Real::zero(), Real::one()], &policy)
                .unwrap(),
            Classification::Decided(RealSign::Zero),
        );

        let projected = crate::policy::resolve_certified_operation(&policy, |attempt| {
            cubic.map_curve_parameter(CurveResultantParameter::Second, &direct, attempt)
        })
        .unwrap();
        assert_eq!(projected.certainty, CurveCertainty::Certified);
        let Classification::Decided(Some(projected)) = projected.value else {
            panic!("the cubic recursive component image must decide");
        };
        let projected = projected
            .as_recursive_projective()
            .expect("a higher-degree recursive image must remain in its local field");
        assert_eq!(projected.data.policy, CurveContext::STRICT);
        assert_eq!(
            projected
                .polynomial_sign(&[-half.clone(), Real::zero(), Real::one()], &policy)
                .unwrap(),
            Classification::Decided(RealSign::Zero),
        );
        assert_eq!(
            projected
                .cmp_bezier_parameter(&source_parameter, &policy)
                .unwrap(),
            Classification::Decided(std::cmp::Ordering::Equal),
        );
    }
}

#[test]
fn non_source_parallel_overlap_replays_the_radical_component() {
    let line = |height: i8| {
        QuadraticBezier2::from_line_segment(
            LineSeg2::try_new(
                Point2::new(Real::zero(), Real::from(height)),
                Point2::new(Real::one(), Real::from(height)),
            )
            .unwrap(),
        )
    };
    let first = line(0).parallel_left(Real::one()).unwrap();
    let second = line(2).parallel_left(Real::from(-1_i8)).unwrap();
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let Classification::Decided(Some(system)) =
            parallel_pair_equation_system(&first, &second, true, &policy).unwrap()
        else {
            panic!("the coincident parallel lines must reach their exact pair system");
        };
        let Classification::Decided(BezierParallelPairDomainProjection2::Enumerated {
            projection,
            retained_contacts,
            components,
        }) = project_unit_parallel_pair_intersection_system(&system, &first, &second, &policy)
            .unwrap()
        else {
            panic!("the non-source radical component was not projected");
        };
        assert!(components.is_empty());
        let result = first
            .replay_parallel_pair_projection(
                &second,
                &system,
                projection,
                BezierParallelPairParameterSelection2::All,
                &policy,
            )
            .unwrap();
        let Classification::Decided(intersections) =
            extend_parallel_pair_contacts(result, retained_contacts, &policy).unwrap()
        else {
            panic!("the non-source radical component was not replayed");
        };
        assert!(intersections.is_complete());
        assert!(intersections.contacts().is_empty());
        let [overlap] = intersections.overlaps() else {
            panic!("the coincident selected lines must publish one overlap");
        };
        assert_eq!(
            overlap.first_range().scalar_endpoints(),
            Some((&Real::zero(), &Real::one())),
        );
        assert_eq!(
            overlap.second_range().scalar_endpoints(),
            Some((&Real::zero(), &Real::one())),
        );
        assert!(overlap.includes_start());
        assert!(overlap.includes_end());
        assert_eq!(intersections.component_overlaps().len(), 1);
    }
}

#[test]
fn rational_component_partitions_odd_even_and_endpoint_branch_zeros() {
    let identity_equation = BivariatePolynomial::new(vec![
        vec![Real::zero(), Real::one()],
        vec![Real::from(-1_i8)],
    ]);
    let identity = parameter_lift_map(vec![Real::zero(), Real::one()], vec![Real::one()]);
    let punctured_branch =
        BivariatePolynomial::new(vec![vec![Real::one(), Real::from(-4_i8), Real::from(4_i8)]]);
    let start_branch = BivariatePolynomial::new(vec![vec![Real::zero(), Real::one()]]);
    let end_branch = BivariatePolynomial::new(vec![vec![Real::one(), Real::from(-1_i8)]]);
    let negative_punctured_branch = BivariatePolynomial::new(vec![vec![
        Real::from(-1_i8),
        Real::from(4_i8),
        Real::from(-4_i8),
    ]]);
    let reversed_equation = BivariatePolynomial::new(vec![
        vec![Real::from(-1_i8), Real::one()],
        vec![Real::one()],
    ]);
    let reversed = parameter_lift_map(vec![Real::one(), Real::from(-1_i8)], vec![Real::one()]);
    let crossing_branch = BivariatePolynomial::new(vec![vec![
        (Real::from(-1_i8) / Real::from(2_i8)).unwrap(),
        Real::one(),
    ]]);
    let zero = Real::zero();
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let one = Real::one();

    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let equations = [identity_equation.clone(), identity_equation.clone()];
        let Classification::Decided(Some(punctured)) = certify_rational_parameter_component_map(
            &equations,
            &punctured_branch,
            CurveResultantParameter::First,
            &identity,
            &policy,
        )
        .unwrap() else {
            panic!("an even branch zero did not partition the rational component");
        };
        assert!(punctured.selected_pairs().is_empty());
        assert_eq!(punctured.excluded_pairs().len(), 1);
        let [before, after] = punctured.overlaps.as_ref() else {
            panic!("an interior puncture must produce two open-sided overlaps");
        };
        assert_eq!(
            before.first_range().scalar_endpoints(),
            Some((&zero, &half))
        );
        assert_eq!(after.first_range().scalar_endpoints(), Some((&half, &one)));
        assert!(before.includes_start());
        assert!(!before.includes_end());
        assert!(!after.includes_start());
        assert!(after.includes_end());

        for (branch, expected_inclusion) in
            [(&start_branch, [false, true]), (&end_branch, [true, false])]
        {
            let Classification::Decided(Some(endpoint)) = certify_rational_parameter_component_map(
                &equations,
                branch,
                CurveResultantParameter::First,
                &identity,
                &policy,
            )
            .unwrap() else {
                panic!("an endpoint branch zero was not retained as an open boundary");
            };
            assert_eq!(endpoint.excluded_pairs().len(), 1);
            let [overlap] = endpoint.overlaps.as_ref() else {
                panic!("an endpoint branch zero must retain one positive-length overlap");
            };
            assert_eq!(
                [overlap.includes_start(), overlap.includes_end()],
                expected_inclusion
            );
        }

        let Classification::Decided(Some(negative)) = certify_rational_parameter_component_map(
            &equations,
            &negative_punctured_branch,
            CurveResultantParameter::First,
            &identity,
            &policy,
        )
        .unwrap() else {
            panic!("the negative punctured branch was not decided");
        };
        assert!(negative.overlaps.is_empty());
        assert!(negative.selected_pairs().is_empty());
        assert_eq!(negative.excluded_pairs().len(), 1);

        let reversed_equations = [reversed_equation.clone(), reversed_equation.clone()];
        let Classification::Decided(Some(reversed_evidence)) =
            certify_rational_parameter_component_map(
                &reversed_equations,
                &crossing_branch,
                CurveResultantParameter::Second,
                &reversed,
                &policy,
            )
            .unwrap()
        else {
            panic!("the reversed branch-zero domain was not certified");
        };
        assert_eq!(reversed_evidence.excluded_pairs().len(), 1);
        let [overlap] = reversed_evidence.overlaps.as_ref() else {
            panic!("the reversed branch-zero domain must produce one overlap");
        };
        assert_eq!(
            overlap.first_range().scalar_endpoints(),
            Some((&zero, &half))
        );
        assert_eq!(
            overlap.second_range().scalar_endpoints(),
            Some((&one, &half))
        );
        assert_eq!(overlap.orientation(), CurveOverlapOrientation2::Reversed);
        assert!(overlap.includes_start());
        assert!(!overlap.includes_end());
    }
}

#[test]
fn bounded_component_extraction_rejoins_the_uncapped_authority() {
    let t = BivariatePolynomial::new(vec![vec![Real::zero()], vec![Real::one()]]);
    let u = BivariatePolynomial::new(vec![vec![Real::zero(), Real::one()]]);
    let component = bivariate_subtract(&u, &t);
    let quadratic = bivariate_add(&bivariate_multiply(&t, &t), &bivariate_multiply(&u, &u));
    let first_residual = bivariate_add(
        &quadratic,
        &BivariatePolynomial::new(vec![vec![Real::one()]]),
    );
    let second_residual = bivariate_add(
        &quadratic,
        &BivariatePolynomial::new(vec![vec![Real::from(2_i8)]]),
    );
    let equations = [
        bivariate_multiply(&component, &first_residual),
        bivariate_multiply(&component, &second_residual),
    ];
    let bounded = CurveIntersectionResultantConfig {
        min_precision: PARALLEL_INTERSECTION_RESULTANT_PRECISION,
        max_resultant_degree: 2,
    };
    assert_eq!(
        parameter_component_bivariate_polynomial_system(
            &equations[0],
            &equations[1],
            CurveResultantParameter::First,
            bounded,
        )
        .status,
        BivariatePolynomialComponentStatus::DegreeBoundExceeded,
    );

    let complete = parameter_component_bivariate_polynomial_system_complete(
        &equations[0],
        &equations[1],
        CurveResultantParameter::First,
        bounded,
    );
    assert_eq!(
        complete.status,
        BivariatePolynomialComponentStatus::Rational
    );
    let support = rational_parameter_component_support(
        CurveResultantParameter::First,
        &complete.numerator_coefficients,
        &complete.denominator_coefficients,
    )
    .expect("the exact identity component must have a rational support");
    assert!(
        equations
            .iter()
            .all(|equation| divide_bivariate_polynomial_exact(equation, &support).is_some())
    );

    let positive_branch = BivariatePolynomial::new(vec![vec![Real::one()]]);
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        #[cfg(feature = "dispatch-trace")]
        hyperreal::dispatch_trace::reset();
        let work = || {
            crate::policy::resolve_certified_value(&policy, |attempt| {
                parameter_component_system(&equations, &positive_branch, attempt, bounded).unwrap()
            })
        };
        #[cfg(feature = "dispatch-trace")]
        let outcome = hyperreal::dispatch_trace::with_recording(work);
        #[cfg(not(feature = "dispatch-trace"))]
        let outcome = work();
        #[cfg(feature = "dispatch-trace")]
        let trace = hyperreal::dispatch_trace::take_trace();
        let Classification::Decided(Some(system)) = outcome.value else {
            panic!("the bounded schedule did not transport the complete component");
        };
        assert_eq!(outcome.certainty, crate::CurveCertainty::Certified);
        let [overlap] = system.overlaps.as_ref() else {
            panic!("the identity component must produce one complete overlap");
        };
        assert_eq!(
            overlap.first_range().scalar_endpoints(),
            Some((&Real::zero(), &Real::one()))
        );
        assert_eq!(
            overlap.second_range().scalar_endpoints(),
            Some((&Real::zero(), &Real::one()))
        );
        assert_eq!(overlap.orientation(), CurveOverlapOrientation2::Same);
        assert!(system.selected_pairs().is_empty());
        assert!(system.excluded_pairs().is_empty());
        #[cfg(feature = "dispatch-trace")]
        assert!(
            trace.path_count(
                "hypercurve",
                "bivariate-component",
                "unbounded-cold-continuation",
            ) >= 1,
            "the bounded component schedule must enter its exact continuation: {trace:?}",
        );
    }
}

#[test]
fn rational_component_system_discards_only_the_identically_zero_branch() {
    let zero_branch = BivariatePolynomial::new(vec![
        vec![Real::zero(), Real::one()],
        vec![Real::from(-1_i8)],
    ]);
    let quarter = (Real::one() / Real::from(4_i8)).unwrap();
    let selected = BivariatePolynomial::new(vec![
        vec![-quarter.clone(), Real::one()],
        vec![Real::from(-1_i8)],
    ]);
    let component = bivariate_multiply(&zero_branch, &selected);
    let equations = [
        bivariate_multiply(
            &component,
            &BivariatePolynomial::new(vec![vec![Real::from(2_i8)], vec![Real::one()]]),
        ),
        bivariate_multiply(
            &component,
            &BivariatePolynomial::new(vec![vec![Real::from(3_i8), Real::one()]]),
        ),
    ];
    let config = CurveIntersectionResultantConfig {
        min_precision: PARALLEL_INTERSECTION_RESULTANT_PRECISION,
        max_resultant_degree: MAX_PARALLEL_INTERSECTION_RESULTANT_DEGREE,
    };
    let three_quarters = (Real::from(3_i8) / Real::from(4_i8)).unwrap();

    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let Classification::Decided(Some(system)) =
            parameter_component_system(&equations, &zero_branch, &policy, config).unwrap()
        else {
            panic!("the residual selected component was not transported");
        };
        assert!(system.selected_pairs().is_empty());
        let [overlap] = system.overlaps.as_ref() else {
            panic!("only the positive shifted component may survive");
        };
        assert_eq!(
            overlap.first_range().scalar_endpoints(),
            Some((&Real::zero(), &three_quarters))
        );
        assert_eq!(
            overlap.second_range().scalar_endpoints(),
            Some((&quarter, &Real::one()))
        );
        assert_eq!(overlap.orientation(), CurveOverlapOrientation2::Same);
    }
}

#[test]
fn rational_component_system_retains_residual_isolated_candidates() {
    let quarter = (Real::one() / Real::from(4_i8)).unwrap();
    let three_quarters = (Real::from(3_i8) / Real::from(4_i8)).unwrap();
    let component = BivariatePolynomial::new(vec![
        vec![Real::zero(), Real::from(-1_i8)],
        vec![Real::one()],
    ]);
    let first_residual = BivariatePolynomial::new(vec![vec![-quarter.clone()], vec![Real::one()]]);
    let second_residual =
        BivariatePolynomial::new(vec![vec![-three_quarters.clone(), Real::one()]]);
    let equations = [
        bivariate_multiply(&component, &first_residual),
        bivariate_multiply(&component, &second_residual),
    ];
    let branch = BivariatePolynomial::new(vec![vec![Real::one()]]);
    let config = CurveIntersectionResultantConfig {
        min_precision: PARALLEL_INTERSECTION_RESULTANT_PRECISION,
        max_resultant_degree: MAX_PARALLEL_INTERSECTION_RESULTANT_DEGREE,
    };

    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let Classification::Decided(Some(system)) =
            parameter_component_system(&equations, &branch, &policy, config).unwrap()
        else {
            panic!("shared component plus residual point was not decomposed");
        };
        assert_eq!(system.overlaps.len(), 1);
        let Classification::Decided(CurveIntersectionCandidates2::Candidates {
            first_parameters: parallel_parameters,
            second_parameters: other_parameters,
        }) = project_parallel_intersection_system(
            &system.residual_equations[0],
            &system.residual_equations[1],
            [CurveParameterDomain2::new(&CurveParameterRange2::unit(), None); 2],
            &policy,
        )
        .unwrap()
        else {
            panic!("residual isolated solution was discarded");
        };
        assert_eq!(
            parallel_parameters,
            vec![BezierParameter2::Exact(quarter.clone())]
        );
        assert_eq!(
            other_parameters,
            vec![BezierParameter2::Exact(three_quarters.clone())]
        );
    }
}

#[test]
fn branch_zero_component_pair_suppresses_the_same_residual_candidate() {
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let component = BivariatePolynomial::new(vec![
        vec![Real::zero(), Real::from(-1_i8)],
        vec![Real::one()],
    ]);
    let first_residual = BivariatePolynomial::new(vec![vec![-half.clone()], vec![Real::one()]]);
    let second_residual = BivariatePolynomial::new(vec![vec![-half.clone(), Real::one()]]);
    let equations = [
        bivariate_multiply(&component, &first_residual),
        bivariate_multiply(&component, &second_residual),
    ];
    let branch = BivariatePolynomial::new(vec![vec![
        Real::from(-1_i8),
        Real::from(4_i8),
        Real::from(-4_i8),
    ]]);
    let config = CurveIntersectionResultantConfig {
        min_precision: PARALLEL_INTERSECTION_RESULTANT_PRECISION,
        max_resultant_degree: MAX_PARALLEL_INTERSECTION_RESULTANT_DEGREE,
    };

    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let Classification::Decided(Some(system)) =
            parameter_component_system(&equations, &branch, &policy, config).unwrap()
        else {
            panic!("the branch-zero residual coincidence was not decomposed");
        };
        assert!(system.overlaps.is_empty());
        assert!(system.selected_pairs().is_empty());
        let [excluded] = system.excluded_pairs() else {
            panic!("the strict branch zero was not retained as exclusion evidence");
        };
        assert!(
            excluded
                == &BezierParallelIntersectionParameterPair2 {
                    parallel_parameter: BezierParameter2::Exact(half.clone()),
                    other_parameter: BezierParameter2::Exact(half.clone()),
                },
            "the excluded component pair changed"
        );

        let Classification::Decided(candidate_system) =
            parallel_candidate_system_from_parameter_components(system, &policy).unwrap()
        else {
            panic!("the residual candidate projection was undecidable");
        };
        let CurveIntersectionCandidates2::Candidates {
            first_parameters: parallel_parameters,
            second_parameters: other_parameters,
        } = &candidate_system.candidates
        else {
            panic!("the residual branch-zero pair was not projected");
        };
        assert_eq!(
            parallel_parameters,
            &[BezierParameter2::Exact(half.clone())]
        );
        assert_eq!(other_parameters, &[BezierParameter2::Exact(half.clone())]);
        assert!(matches!(
            parallel_parameter_pair_is_excluded(
                &candidate_system.component_pairs[candidate_system.selected_component_pair_count..],
                &parallel_parameters[0],
                &other_parameters[0],
                &policy,
            )
            .unwrap(),
            Classification::Decided(true)
        ));
    }
}

#[test]
fn nonrational_rational_parameter_component_uses_exact_real_coefficients() {
    let alpha = (Real::one() / Real::from(2_i8)).unwrap().sqrt().unwrap();
    let component =
        BivariatePolynomial::new(vec![vec![Real::zero(), Real::one()], vec![-alpha.clone()]]);
    let equations = [
        bivariate_multiply(
            &component,
            &BivariatePolynomial::new(vec![vec![Real::from(2_i8)], vec![Real::one()]]),
        ),
        bivariate_multiply(
            &component,
            &BivariatePolynomial::new(vec![vec![Real::from(3_i8), Real::one()]]),
        ),
    ];
    let branch = BivariatePolynomial::new(vec![vec![Real::one()]]);
    let config = CurveIntersectionResultantConfig {
        min_precision: PARALLEL_INTERSECTION_RESULTANT_PRECISION,
        max_resultant_degree: MAX_PARALLEL_INTERSECTION_RESULTANT_DEGREE,
    };

    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let Classification::Decided(Some(system)) =
            parameter_component_system(&equations, &branch, &policy, config).unwrap()
        else {
            panic!("the non-rational rational component was not transported");
        };
        let [overlap] = system.overlaps.as_ref() else {
            panic!("the non-rational rational component must publish once");
        };
        assert_eq!(
            overlap.first_range().scalar_endpoints(),
            Some((&Real::zero(), &Real::one()))
        );
        let Some(second_end) = overlap.second_range().end().scalar() else {
            panic!("the represented non-rational image endpoint was discarded");
        };
        assert_eq!(
            real_sign(&(second_end - &alpha), &policy),
            Some(RealSign::Zero)
        );
        assert_eq!(overlap.orientation(), CurveOverlapOrientation2::Same);
    }
}

#[test]
fn nonrational_implicit_parameter_component_uses_exact_real_coefficients() {
    // u^2 + u - sqrt(1/2)t = 0 has one smooth branch in the authored
    // square. Its endpoint and defining component are non-rational, but
    // all topology remains exact Real arithmetic.
    let alpha = (Real::one() / Real::from(2_i8)).unwrap().sqrt().unwrap();
    let component = BivariatePolynomial::new(vec![
        vec![Real::zero(), Real::one(), Real::one()],
        vec![-alpha.clone()],
    ]);
    let equations = [
        bivariate_multiply(
            &component,
            &BivariatePolynomial::new(vec![vec![Real::from(2_i8)], vec![Real::one()]]),
        ),
        bivariate_multiply(
            &component,
            &BivariatePolynomial::new(vec![vec![Real::from(3_i8), Real::one()]]),
        ),
    ];
    let branch = BivariatePolynomial::new(vec![vec![Real::one()]]);
    let crossing_branch = BivariatePolynomial::new(vec![vec![-alpha.clone()], vec![Real::one()]]);
    let config = CurveIntersectionResultantConfig {
        min_precision: PARALLEL_INTERSECTION_RESULTANT_PRECISION,
        max_resultant_degree: MAX_PARALLEL_INTERSECTION_RESULTANT_DEGREE,
    };

    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let Classification::Decided(Some(system)) =
            parameter_component_system(&equations, &branch, &policy, config).unwrap()
        else {
            panic!("the non-rational implicit component was not transported");
        };
        let [overlap] = system.overlaps.as_ref() else {
            panic!("the non-rational implicit graph must publish once");
        };
        assert_eq!(
            overlap.first_range().scalar_endpoints(),
            Some((&Real::zero(), &Real::one()))
        );
        assert_eq!(
            signed_bivariate_at_parameter_pair(
                &component,
                overlap.first_range().end(),
                overlap.second_range().end(),
                &policy,
            )
            .unwrap(),
            Classification::Decided(RealSign::Zero)
        );
        assert_eq!(overlap.orientation(), CurveOverlapOrientation2::Same);

        let Classification::Decided(Some(partitioned)) =
            parameter_component_system(&equations, &crossing_branch, &policy, config).unwrap()
        else {
            panic!("the exact non-rational branch zero was not partitioned");
        };
        assert!(partitioned.selected_pairs().is_empty());
        assert_eq!(partitioned.excluded_pairs().len(), 1);
        let [overlap] = partitioned.overlaps.as_ref() else {
            panic!("the positive non-rational tail was not retained");
        };
        assert!(matches!(
            overlap
                .first_range()
                .start()
                .same_value(&BezierParameter2::Exact(alpha.clone()), &policy)
                .unwrap(),
            Classification::Decided(true)
        ));
        assert!(!overlap.includes_start());
        assert!(overlap.includes_end());
        assert_eq!(
            signed_bivariate_at_parameter_pair(
                &component,
                overlap.first_range().start(),
                overlap.second_range().start(),
                &policy,
            )
            .unwrap(),
            Classification::Decided(RealSign::Zero)
        );
    }
}

#[test]
fn rational_component_system_enumerates_split_quadratic_components() {
    let first_component = BivariatePolynomial::new(vec![
        vec![Real::zero(), Real::one()],
        vec![Real::from(-1_i8)],
    ]);
    let second_component = BivariatePolynomial::new(vec![
        vec![Real::from(-1_i8), Real::one()],
        vec![Real::one()],
    ]);
    let common = bivariate_multiply(&first_component, &second_component);
    let quarter = (Real::one() / Real::from(4_i8)).unwrap();
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let first_residual = BivariatePolynomial::new(vec![vec![-quarter.clone()], vec![Real::one()]]);
    let second_residual = BivariatePolynomial::new(vec![vec![-half.clone(), Real::one()]]);
    let equations = [
        bivariate_multiply(&common, &first_residual),
        bivariate_multiply(&common, &second_residual),
    ];
    let branch = BivariatePolynomial::new(vec![vec![Real::one()]]);
    let config = CurveIntersectionResultantConfig {
        min_precision: PARALLEL_INTERSECTION_RESULTANT_PRECISION,
        max_resultant_degree: MAX_PARALLEL_INTERSECTION_RESULTANT_DEGREE,
    };

    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let Classification::Decided(Some(system)) =
            parameter_component_system(&equations, &branch, &policy, config).unwrap()
        else {
            panic!("two rational components were not enumerated");
        };
        assert_eq!(system.overlaps.len(), 2);
        assert!(system.selected_pairs().is_empty());
        assert!(
            system
                .overlaps
                .iter()
                .any(|overlap| { overlap.orientation() == CurveOverlapOrientation2::Same })
        );
        assert!(
            system
                .overlaps
                .iter()
                .any(|overlap| { overlap.orientation() == CurveOverlapOrientation2::Reversed })
        );
        let Classification::Decided(candidate_system) =
            parallel_candidate_system_from_parameter_components(system, &policy).unwrap()
        else {
            panic!("multiple component residual projection was uncertain");
        };
        assert_eq!(candidate_system.overlaps.len(), 2);
        let CurveIntersectionCandidates2::Candidates {
            first_parameters: parallel_parameters,
            second_parameters: other_parameters,
        } = candidate_system.candidates
        else {
            panic!("isolated residual beside two components was discarded");
        };
        assert_eq!(
            parallel_parameters,
            vec![BezierParameter2::Exact(quarter.clone())]
        );
        assert_eq!(
            other_parameters,
            vec![BezierParameter2::Exact(half.clone())]
        );
    }
}

