#[test]
fn bounded_parameter_lifts_rejoin_the_uncapped_authority() {
    // The common solution is `t^3 = 1/2`, `u = 1/2`. The cubic retained
    // dependence exceeds the artificial hot budget while the authored
    // nullity-one fiber still has an exact constant lift.
    let half = (Real::one() / Real::from(2_i8)).unwrap();
    let first = BivariatePolynomial::new(vec![
        vec![Real::zero(), Real::one()],
        vec![],
        vec![],
        vec![Real::from(-1_i8)],
    ]);
    let second = BivariatePolynomial::new(vec![vec![-half.clone(), Real::one()]]);
    let retained = algebraic_parameter(vec![
        Real::from(-1_i8),
        Real::zero(),
        Real::zero(),
        Real::from(2_i8),
    ]);
    let lifted = BezierParameter2::Exact(half);
    let bounded = CurveIntersectionResultantConfig {
        min_precision: PARALLEL_INTERSECTION_RESULTANT_PRECISION,
        max_resultant_degree: 2,
    };
    assert_eq!(
        linear_parameter_lifts_bivariate_polynomial_system(
            &first,
            &second,
            CurveResultantParameter::First,
            bounded,
        )
        .status,
        CurveIntersectionParameterLiftStatus::DegreeBoundExceeded,
    );

    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        #[cfg(feature = "dispatch-trace")]
        hyperreal::dispatch_trace::reset();
        let work = || {
            crate::policy::resolve_certified_value(&policy, |attempt| {
                let report = linear_parameter_lifts_bivariate_polynomial_system_complete(
                    &first,
                    &second,
                    CurveResultantParameter::First,
                    bounded,
                );
                parameter_pair_matches_linear_lift(&report, &retained, &lifted, attempt).unwrap()
            })
        };
        #[cfg(feature = "dispatch-trace")]
        let outcome = hyperreal::dispatch_trace::with_recording(work);
        #[cfg(not(feature = "dispatch-trace"))]
        let outcome = work();
        #[cfg(feature = "dispatch-trace")]
        let trace = hyperreal::dispatch_trace::take_trace();
        assert!(matches!(
            outcome.value,
            Classification::Decided(BivariateParameterPairReplay::LinearLift(
                CurveResultantParameter::First,
                _
            ))
        ));
        assert_eq!(outcome.certainty, crate::CurveCertainty::Certified);
        #[cfg(feature = "dispatch-trace")]
        assert!(
            trace.path_count(
                "hypercurve",
                "bivariate-parameter-lift",
                "unbounded-cold-continuation",
            ) >= 1,
            "the bounded lift schedule must enter its exact continuation: {trace:?}",
        );
    }
}

#[test]
fn specialized_common_fiber_counts_even_multiplicity_in_a_coupled_system() {
    // alpha = cbrt(1/2), beta = alpha^2 = cbrt(1/4). The two equations
    // differ by A(alpha)=2*alpha^3-1 and specialize to
    // (beta-alpha^2)^2, so the selected fiber root has even multiplicity
    // and cannot be recovered from endpoint sign change.
    let alpha = algebraic_parameter(vec![
        Real::from(-1_i8),
        Real::zero(),
        Real::zero(),
        Real::from(2_i8),
    ]);
    let beta = algebraic_parameter(vec![
        Real::from(-1_i8),
        Real::zero(),
        Real::zero(),
        Real::from(4_i8),
    ]);
    let first = BivariatePolynomial::new(vec![
        vec![Real::from(-1_i8), Real::zero(), Real::one()],
        vec![],
        vec![Real::zero(), Real::from(-2_i8)],
        vec![Real::from(2_i8)],
        vec![Real::one()],
    ]);
    let second = BivariatePolynomial::new(vec![
        vec![Real::from(-2_i8), Real::zero(), Real::one()],
        vec![],
        vec![Real::zero(), Real::from(-2_i8)],
        vec![Real::from(4_i8)],
        vec![Real::one()],
    ]);
    let config = CurveIntersectionResultantConfig {
        min_precision: PARALLEL_INTERSECTION_RESULTANT_PRECISION,
        max_resultant_degree: MAX_PARALLEL_INTERSECTION_RESULTANT_DEGREE,
    };
    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        let mut parameter_lifts = [None, None];
        assert_eq!(
            replay_bivariate_parameter_pair(
                &first,
                &second,
                &alpha,
                &beta,
                &policy,
                config,
                &mut parameter_lifts,
            )
            .unwrap(),
            Classification::Decided(BivariateParameterPairReplay::Direct)
        );
    }
}

#[test]
fn specialized_common_fiber_replays_degree_drops_in_either_orientation() {
    let alpha = algebraic_parameter(vec![
        Real::from(-1_i8),
        Real::zero(),
        Real::zero(),
        Real::from(2_i8),
    ]);
    let beta = algebraic_parameter(vec![
        Real::from(-1_i8),
        Real::zero(),
        Real::zero(),
        Real::from(4_i8),
    ]);
    // A=2*a^3-1 and B=4*b^3-1 vanish at the represented pair. The A*B
    // term supplies generic degree three in both orientations, then drops
    // out exactly. Both specialized equations retain b-a^2 as their GCD.
    let first = BivariatePolynomial::new(vec![
        vec![Real::one(), Real::one(), Real::zero(), Real::from(-4_i8)],
        vec![],
        vec![Real::from(-1_i8)],
        vec![
            Real::from(-2_i8),
            Real::zero(),
            Real::zero(),
            Real::from(8_i8),
        ],
    ]);
    let second = BivariatePolynomial::new(vec![
        vec![
            Real::one(),
            Real::from(2_i8),
            Real::zero(),
            Real::from(-4_i8),
        ],
        vec![],
        vec![Real::from(-2_i8)],
        vec![
            Real::from(-2_i8),
            Real::zero(),
            Real::zero(),
            Real::from(8_i8),
        ],
    ]);
    let rootless_after_drop = BivariatePolynomial::new(vec![
        vec![Real::one(), Real::zero(), Real::from(-1_i8)],
        vec![],
        vec![],
        vec![Real::zero(), Real::zero(), Real::from(2_i8)],
    ]);
    let beta_defining = BivariatePolynomial::new(vec![vec![
        Real::from(-1_i8),
        Real::zero(),
        Real::zero(),
        Real::from(4_i8),
    ]]);
    let alpha_defining = BivariatePolynomial::new(vec![
        vec![Real::from(-1_i8)],
        vec![],
        vec![],
        vec![Real::from(2_i8)],
    ]);

    for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
        for (retained_axis, retained, fiber) in [
            (CurveResultantParameter::First, &alpha, &beta),
            (CurveResultantParameter::Second, &beta, &alpha),
        ] {
            assert_eq!(
                parameter_pair_matches_specialized_fiber(
                    &first,
                    &second,
                    retained_axis,
                    retained,
                    fiber,
                    &policy,
                )
                .unwrap(),
                Classification::Decided(BivariateParameterPairReplay::Direct)
            );
        }
        assert_eq!(
            parameter_pair_matches_specialized_fiber(
                &rootless_after_drop,
                &beta_defining,
                CurveResultantParameter::First,
                &alpha,
                &beta,
                &policy,
            )
            .unwrap(),
            Classification::Decided(BivariateParameterPairReplay::Rejected)
        );
        assert_eq!(
            parameter_pair_matches_specialized_fiber(
                &alpha_defining,
                &alpha_defining,
                CurveResultantParameter::First,
                &alpha,
                &beta,
                &policy,
            )
            .unwrap(),
            Classification::Uncertain(UncertaintyReason::Boundary)
        );
    }
}
